remove_action('wp_head', 'wlwmanifest_link');
remove_action('wp_head', 'wp_shortlink_wp_head');
remove_action('wp_head', 'wp_oembed_add_discovery_links');
remove_action('wp_head', 'rest_output_link_wp_head');
remove_action('wp_head', 'wp_block_editor_styles', 10);
// Matikan semua output plugin yang ngasal (Yoast, Rank Math, dsb) dari head
add_action('wp_head', function() { ob_start(); }, 0);
add_action('wp_head', function() { ob_get_clean(); }, 999);

header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
header('Cache-Control: post-check=0, pre-check=0', false);
header('Pragma: no-cache');

if (function_exists('ptv_dashboard_session_boot')) {
    ptv_dashboard_session_boot();
} else {
    if (PHP_VERSION_ID >= 70300) {
        session_set_cookie_params([
            'lifetime' => 259200,
            'path' => '/',
            'domain' => '',
            'secure' => is_ssl(),
            'httponly' => true,
            'samesite' => 'Lax',
        ]);
    } else {
        session_set_cookie_params(259200, '/; samesite=Lax', '', is_ssl(), true);
    }
    session_start();
}

if (function_exists('ptv_auth_safe_log')) {
    $sess_status = 'NONE';
    if (function_exists('session_status')) {
        if (session_status() === PHP_SESSION_ACTIVE) $sess_status = 'ACTIVE';
        elseif (session_status() === PHP_SESSION_DISABLED) $sess_status = 'DISABLED';
    }
    ptv_auth_safe_log('AUTH_FORENSIC_DASHBOARD', [
        'incoming_php_session_cookie' => !empty($_COOKIE[session_name()]) ? 'YES' : 'NO',
        'incoming_ptv_auth_cookie'    => !empty($_COOKIE['ptv_kru_auth']) ? 'YES' : 'NO',
        'session_id'                  => session_id() ?: 'NONE',
        'save_path'                   => session_save_path() ?: ini_get('session.save_path'),
        'session_status'              => $sess_status,
        'crew_logged_in'              => !empty($_SESSION['ptv_crew_logged_in']) ? 'YES' : 'NO',
        'crew_id'                     => $_SESSION['ptv_crew_id'] ?? 'NONE',
    ]);
    ptv_auth_safe_log('DASBOR_PAGE_START');
}

if (isset($_SESSION['ptv_admin_logged_in']) && isset($_SESSION['ptv_login_time'])) {
    if (time() - $_SESSION['ptv_login_time'] > 259200) {
        session_unset(); session_destroy();
        wp_redirect(strtok($_SERVER["REQUEST_URI"], '?')); exit;
    }
}

// Logout Action
if (isset($_GET['logout'])) {
    session_unset(); 
    session_destroy();
    if (ini_get("session.use_cookies")) {
        $params = session_get_cookie_params();
        setcookie(session_name(), '', time() - 42000, $params["path"], '', is_ssl(), true);
    }
    setcookie('ptv_kru_auth', '', time() - 42000, '/', '', is_ssl(), true);
    if (function_exists('wp_logout')) {
        wp_logout();
    }
    wp_redirect(home_url('/dasbor/')); exit;
}

// CPT + Supabase + WP User Authentication
$login_error = '';
$oauth_error = sanitize_text_field($_GET['oauth_error'] ?? '');
if (!empty($oauth_error)) {
    $_SESSION = [];
    if (ini_get("session.use_cookies")) {
        $params = session_get_cookie_params();
        setcookie(session_name(), '', time() - 42000, $params["path"], '', is_ssl(), true);
    }
    setcookie('ptv_kru_auth', '', time() - 42000, '/', '', is_ssl(), true);
}
if (isset($_POST['ptv_login']) || isset($_POST['ptv_user']) || (isset($_SERVER['REQUEST_METHOD']) && strtoupper($_SERVER['REQUEST_METHOD']) === 'POST' && isset($_POST['ptv_pass']))) {
    $username_input = trim(wp_unslash($_POST['ptv_user'] ?? ''));
    $pass_input     = wp_unslash($_POST['ptv_pass'] ?? '');

    $kru_row = function_exists('ptv_get_kru_by_username')
        ? ptv_get_kru_by_username($username_input)
        : null;

    $is_valid = false;
    if ($kru_row) {
        $role       = $kru_row['role'] ?? '';
        $pass_hash  = $kru_row['password_hash'] ?? '';
        $sb_uuid    = $kru_row['id'] ?? '';

        // Status Akun independen dari Status Kru (Kru nonaktif tetap bisa login jika status akun aktif)
        $acc_status = strtolower(trim((string)($kru_row['status_akun'] ?? '')));
        if (empty($acc_status)) {
            $acc_map = get_option('ptv_kru_account_status_map', []);
            $cid_key = (string)($sb_uuid ?: '');
            $un_key  = strtolower(trim((string)($kru_row['username'] ?? $username_input)));
            if ($cid_key && isset($acc_map[$cid_key])) {
                $acc_status = strtolower($acc_map[$cid_key]);
            } elseif ($un_key && isset($acc_map[$un_key])) {
                $acc_status = strtolower($acc_map[$un_key]);
            } else {
                $cpt_pid = $kru_row['cpt_post_id'] ?? 0;
                if ($cpt_pid) {
                    $acc_status = strtolower(trim((string)get_post_meta($cpt_pid, 'ptv_kru_status_akun', true)));
                }
            }
        }
        if (empty($acc_status)) {
            $acc_status = 'aktif'; // Default aktif untuk akun terdaftar
        }

        if ($acc_status === 'nonaktif' || empty($role) || $role === '-') {
            $login_error = 'Akun tidak ditemukan!';
        } else {
            // Verifikasi ketat HANYA dari password_hash asli di database (standar bcrypt $2y$ / $2a$)
            // DILARANG menggunakan password fallback, default nama kru, ataupun perbandingan plaintext
            if (!empty($pass_hash) && (strpos((string)$pass_hash, '$2y$') === 0 || strpos((string)$pass_hash, '$2a$') === 0)) {
                $is_valid = password_verify($pass_input, $pass_hash);
            }

            if (!$is_valid) {
                $login_error = 'Akun tidak ditemukan!';
            }
        }
    } else {
        $login_error = 'Akun tidak ditemukan!';
    }

    if ($is_valid) {
        $is_supabase = isset($kru_row['id']) && strpos($kru_row['id'], 'cpt:') !== 0 && strpos($kru_row['id'], 'wp:') !== 0;
        $cpt_post_id = $kru_row['cpt_post_id'] ?? 0;

        $_SESSION['ptv_admin_logged_in'] = true;
        $_SESSION['ptv_admin_role']      = $kru_row['role'] ?? 'member';
        $_SESSION['ptv_admin_name']      = $kru_row['nama'] ?? '';
        $_SESSION['ptv_login_time']      = time();
        $_SESSION['ptv_admin_nonce']     = bin2hex(random_bytes(16));
        $_SESSION['ptv_fresh_login']     = true;
        $_SESSION['ptv_kru_sb_id']       = $is_supabase ? $kru_row['id'] : '';
        $_SESSION['ptv_kru_post_id']     = $cpt_post_id;
        $_SESSION['ptv_crew_logged_in']  = true;
        $_SESSION['ptv_crew_post_id']    = $cpt_post_id;
        $_SESSION['ptv_crew_name']       = $kru_row['nama'] ?? '';
        $_SESSION['ptv_crew_id']         = $kru_row['crew_id'] ?? '';
        $_SESSION['ptv_crew_divisi']     = $kru_row['divisi'] ?? '';
        $_SESSION['ptv_crew_foto']       = $kru_row['foto_url'] ?? '';
        $resolved_identifier = !empty($kru_row['username']) ? $kru_row['username'] : (!empty($kru_row['crew_id']) ? $kru_row['crew_id'] : $username_input);
        $_SESSION['ptv_crew_username']   = $resolved_identifier;
        $_SESSION['ptv_crew_login_time'] = time();

        $secret = defined('AUTH_KEY') ? AUTH_KEY : 'ptv_secret_key_2026';
        $now = time();
        $sig = hash_hmac('sha256', $resolved_identifier . '|' . $now, $secret);
        $cookie_val = $resolved_identifier . '|' . $now . '|' . $sig;
        if (PHP_VERSION_ID >= 70300) {
            setcookie('ptv_kru_auth', $cookie_val, [
                'expires'  => $now + 259200,
                'path'     => '/',
                'domain'   => '',
                'secure'   => is_ssl(),
                'httponly' => true,
                'samesite' => 'Lax',
            ]);
        } else {
            setcookie('ptv_kru_auth', $cookie_val, $now + 259200, '/; samesite=Lax', '', is_ssl(), true);
        }

        // Cookie sesi PHPSESSID dipancarkan secara native oleh session_start() via session_set_cookie_params
        // Pemanggilan manual duplicate setcookie(session_name()) dihapus agar tidak memancarkan Set-Cookie ganda

        if (function_exists('ptv_record_login_history')) {
            ptv_record_login_history($kru_row, $username_input);
        }

        if (function_exists('session_write_close')) {
            session_write_close();
        }
        wp_safe_redirect(home_url('/dasbor/')); exit;
    } else {
        $login_error = 'Akun tidak ditemukan!';
        // Bersihkan hanya flag sesi login, JANGAN hapus session cookie browser
        unset($_SESSION['ptv_admin_logged_in'], $_SESSION['ptv_crew_logged_in']);
        if (PHP_VERSION_ID >= 70300) {
            setcookie('ptv_kru_auth', '', [
                'expires'  => time() - 42000,
                'path'     => '/',
                'domain'   => '',
                'secure'   => is_ssl(),
                'httponly' => true,
                'samesite' => 'Lax',
            ]);
        } else {
            setcookie('ptv_kru_auth', '', time() - 42000, '/; samesite=Lax', '', is_ssl(), true);
        }
    }
}

// CATATAN KEAMANAN: Auto-bridge user WordPress dihapus total agar akun administrator WP tidak bypass ke portal dasbor.

// Pastikan jika sesi kosong namun cookie ptv_kru_auth ada di header request, pulihkan sesi sekali lagi
if (empty($_SESSION['ptv_admin_logged_in']) && !empty($_COOKIE['ptv_kru_auth'])) {
    if (function_exists('ptv_dashboard_session_boot')) {
        ptv_dashboard_session_boot();
    }
}

$is_logged_in = isset($_SESSION['ptv_admin_logged_in']) && $_SESSION['ptv_admin_logged_in'] === true;

if (function_exists('ptv_auth_safe_log')) {
    ptv_auth_safe_log('DASBOR_AUTH_CHECK', [
        'is_logged_in' => $is_logged_in ? 'YES' : 'NO',
        'crew_user'    => $_SESSION['ptv_crew_username'] ?? '-',
    ]);
    if (!$is_logged_in) {
        $reject_reason = 'NO_SESSION_COOKIE';
        if (!empty($_COOKIE[session_name()])) {
            $reject_reason = 'SESSION_DATA_EMPTY';
        } elseif (!empty($_COOKIE['ptv_kru_auth'])) {
            $reject_reason = 'INVALID_PTV_AUTH';
        }
        ptv_auth_safe_log('AUTH_REJECT_REASON', [
            'reason'               => $reject_reason,
            'incoming_sess_cookie' => !empty($_COOKIE[session_name()]) ? 'YES' : 'NO',
            'incoming_auth_cookie' => !empty($_COOKIE['ptv_kru_auth']) ? 'YES' : 'NO',
        ]);
    }
}

