      <script>
        function togglePassVisibility() {
          var inp = document.getElementById('ptvPassInput');
          var btn = document.getElementById('passToggleBtn');
          if (!inp) return;
          var isPass = inp.type === 'password';
          inp.type = isPass ? 'text' : 'password';
          var eyeOpen = btn.querySelector('.eye-open');
          var eyeClosed = btn.querySelector('.eye-closed');
          if (eyeOpen && eyeClosed) {
            eyeOpen.style.display = isPass ? 'none' : 'block';
            eyeClosed.style.display = isPass ? 'block' : 'none';
          }
        }

        function handleGoogleLogin() {
          var form = document.createElement('form');
          form.method = 'POST';
          form.action = '<?php echo esc_url(admin_url("admin-ajax.php")); ?>';
          var actInp = document.createElement('input');
          actInp.type = 'hidden';
          actInp.name = 'action';
          actInp.value = 'ptv_google_oauth_start';
          form.appendChild(actInp);
          var retInp = document.createElement('input');
          retInp.type = 'hidden';
          retInp.name = 'return_url';
          retInp.value = window.location.href;
          form.appendChild(retInp);
          document.body.appendChild(form);
          form.submit();
        }

        function openHelpModal() {
          var s = document.getElementById('helpModalScrim');
          var m = document.getElementById('helpModal');
          if (s) s.classList.add('active');
          if (m) m.classList.add('active');
          document.documentElement.classList.add('modal-open');
          document.body.classList.add('modal-open');
        }
        function closeHelpModal() {
          var s = document.getElementById('helpModalScrim');
          var m = document.getElementById('helpModal');
          if (s) s.classList.remove('active');
          if (m) m.classList.remove('active');
          document.documentElement.classList.remove('modal-open');
          document.body.classList.remove('modal-open');
        }
        document.addEventListener('keydown', function(e) {
          if (e.key === 'Escape') closeHelpModal();
        });

        var loginForm = document.getElementById('ptvLoginForm');
        if (loginForm) {
          loginForm.addEventListener('submit', function(e) {
            e.preventDefault();
            var btn = loginForm.querySelector('.lk-btn-login');
            var origText = btn ? btn.textContent : 'Login';
            if (btn) {
              btn.disabled = true;
              btn.textContent = 'Memverifikasi...';
              btn.style.opacity = '0.7';
            }

            var userInput = loginForm.querySelector('[name="ptv_user"]');
            var passInput = loginForm.querySelector('[name="ptv_pass"]');
            var userVal = userInput ? userInput.value.trim() : '';
            var passVal = passInput ? passInput.value : '';

            var oldErr = document.querySelector('.lk-error:not(.oauth-error)');
            if (oldErr) oldErr.remove();

            var formData = new FormData();
            formData.append('action', 'ptv_crew_login');
            formData.append('username', userVal);
            formData.append('password', passVal);

            fetch('<?php echo esc_url(admin_url("admin-ajax.php")); ?>', {
              method: 'POST',
              body: formData,
              credentials: 'include'
            })
            .then(function(res) {
              return res.json().then(function(data) {
                return { status: res.status, ok: res.ok, data: data };
              });
            })
            .then(function(result) {
              if (result.ok && result.data && result.data.success) {
                console.info('[AUTH] login success');
                var redirectUrl = (result.data.data && result.data.data.redirect) ? result.data.data.redirect : '<?php echo esc_url(home_url("/dasbor/")); ?>';
                var sep = redirectUrl.indexOf('?') === -1 ? '?' : '&';
                var targetUrl = redirectUrl + sep + 't=' + Date.now();
                window.location.replace(targetUrl);
              } else {
                if (btn) {
                  btn.disabled = false;
                  btn.textContent = origText;
                  btn.style.opacity = '1';
                }
                var errMsg = (result.data && result.data.data) ? result.data.data : 'Akun tidak ditemukan!';
                showLoginError(typeof errMsg === 'string' ? errMsg : 'Akun tidak ditemukan!');
              }
            })
            .catch(function(err) {
              console.warn('[AUTH] AJAX login error:', err);
              if (btn) {
                btn.disabled = false;
                btn.textContent = origText;
                btn.style.opacity = '1';
              }
              showLoginError('Gagal terhubung ke server. Periksa koneksi dan coba lagi.');
            });
          });
        }

        function showLoginError(msg) {
          var oldErr = document.querySelector('.lk-error:not(.oauth-error)');
          if (oldErr) oldErr.remove();
          var errDiv = document.createElement('div');
          errDiv.className = 'lk-error';
          errDiv.innerHTML = '<svg stroke="currentColor" fill="none" stroke-width="2" viewBox="0 0 24 24" height="16" width="16"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="8" x2="12" y2="12"></line><line x1="12" y1="16" x2="12.01" y2="16"></line></svg><span>' + escapeHtml(msg) + '</span>';
          var form = document.getElementById('ptvLoginForm');
          if (form && form.parentNode) {
            form.parentNode.insertBefore(errDiv, form);
          }
        }

        function escapeHtml(text) {
          var div = document.createElement('div');
          div.textContent = text;
          return div.innerHTML;
        }
      </script>
    </body>
    </html>
    <?php
    if (ob_get_level()) ob_end_flush();
    exit;
}

