    console.warn('[PAGE] reload requested', new Error().stack);
    return _origReload.apply(window.location, arguments);
  };
} catch(e) {}
if (window.history && window.history.replaceState && window.location.search.indexOf('t=') !== -1) {
  var cleanSearch = window.location.search.replace(/([?&])t=\d+(&|$)/, '$1').replace(/[?&]$/, '');
  window.history.replaceState(null, '', window.location.pathname + cleanSearch + window.location.hash);
}
