<body>
<div id="app"></div>
<div id="toasts"></div>
<button id="ptvScrollTopBtn" type="button" aria-label="Scroll to Top" title="Scroll ke atas" class="ptv-scroll-top-btn"><i class="fa-solid fa-arrow-up"></i></button>

<script>
/* ============================================================
   PTV OPERATIONS — APP (Hydrated from WordPress & Supabase)
   ============================================================ */
(function(){
"use strict";

const BOOT_ME = (typeof window !== 'undefined' && window.BOOT_ME) ? window.BOOT_ME : <?php echo wp_json_encode($boot_data['ME']); ?>;
if (typeof window !== 'undefined' && !window.BOOT_ME) { window.BOOT_ME = BOOT_ME; }

/* ── PTV Client Identification & Sender Isolation ── */
function getPtvClientId() {
  try {
    let cid = sessionStorage.getItem('ptv_client_id');
    if (!cid) {
      cid = 'ptv_cli_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 9);
      sessionStorage.setItem('ptv_client_id', cid);
    }
    return cid;
  } catch (_) {
    return 'ptv_cli_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 9);
  }
}
window.PTV_CLIENT_ID = window.PTV_CLIENT_ID || getPtvClientId();
window._recentLocalMutations = window._recentLocalMutations || new Map();
window._markLocalMutation = function(key) {
  if (!key) return;
  const k = String(key);
  window._recentLocalMutations.set(k, Date.now());
  setTimeout(() => {
    window._recentLocalMutations.delete(k);
  }, 15000);
};

// Daftarkan PTV_CLIENT_ID ke Service Worker untuk push suppression
(function registerPtvClientWithSW() {
  if (typeof navigator !== 'undefined' && navigator.serviceWorker) {
    if (navigator.serviceWorker.controller) {
      try {
        navigator.serviceWorker.controller.postMessage({
          type: 'REGISTER_CLIENT_ID',
          client_id: window.PTV_CLIENT_ID
        });
      } catch (_) {}
    }
    navigator.serviceWorker.ready.then((reg) => {
      if (reg && reg.active) {
        try {
          reg.active.postMessage({
            type: 'REGISTER_CLIENT_ID',
            client_id: window.PTV_CLIENT_ID
          });
        } catch (_) {}
      }
    }).catch(() => {});
  }
})();

// Interceptor global window.fetch untuk menyematkan client_id & actor_id ke semua AJAX request
(function setupPtvFetchInterceptor() {
  if (window._ptvFetchInterceptorInstalled) return;
  window._ptvFetchInterceptorInstalled = true;
  const originalFetch = window.fetch;
  window.fetch = function(input, init) {
    try {
      const url = typeof input === 'string' ? input : (input && input.url ? input.url : '');
      const isAjax = url.includes('admin-ajax.php') || (typeof AJAX_URL !== 'undefined' && url.includes(AJAX_URL));
      if (isAjax) {
        init = init || {};
        let headers = init.headers;
        if (!headers) {
          headers = new Headers();
          init.headers = headers;
        } else if (!(headers instanceof Headers)) {
          headers = new Headers(headers);
          init.headers = headers;
        }
        if (!headers.has('X-PTV-Client-Id') && window.PTV_CLIENT_ID) {
          headers.set('X-PTV-Client-Id', window.PTV_CLIENT_ID);
        }
        const mySbId = (typeof BOOT_ME !== 'undefined' && BOOT_ME) ? (BOOT_ME.sb_id || BOOT_ME.id || '') : '';
        const myName = (typeof BOOT_ME !== 'undefined' && BOOT_ME) ? (BOOT_ME.name || '') : '';
        if (!headers.has('X-PTV-Actor-Id') && mySbId) {
          headers.set('X-PTV-Actor-Id', String(mySbId));
        }
        if (!headers.has('X-PTV-Actor-Name') && myName) {
          headers.set('X-PTV-Actor-Name', String(myName));
        }

        if (init.body instanceof FormData) {
          if (!init.body.has('client_id') && window.PTV_CLIENT_ID) {
            init.body.append('client_id', window.PTV_CLIENT_ID);
          }
          if (!init.body.has('actor_id') && mySbId) {
            init.body.append('actor_id', String(mySbId));
          }
          if (!init.body.has('actor_name') && myName) {
            init.body.append('actor_name', String(myName));
          }

          const entityId = init.body.get('id') || init.body.get('uuid') || init.body.get('code') || init.body.get('crew_id') || '';
          if (entityId) {
            window._markLocalMutation(entityId);
          }
        }
      }
    } catch (_) {}
    return originalFetch.apply(this, arguments);
  };
})();

const BOOT_DB = <?php echo wp_json_encode($boot_data['DB']); ?>;
const AJAX_URL = <?php echo wp_json_encode(admin_url('admin-ajax.php')); ?>;
const LOGOUT_URL = <?php echo wp_json_encode(add_query_arg('logout', '1', home_url('/dasbor/'))); ?>;
const PTV_LOGO_URL = <?php echo wp_json_encode(esc_url($ptv_dashboard_logo_url)); ?>;
const VERIFIKASI_SURAT_BASE_URL = <?php echo wp_json_encode(home_url('/verifikasi-surat/')); ?>;
const VERIFIKASI_IDENTITAS_BASE_URL = <?php echo wp_json_encode(home_url('/verifikasi-identitas/')); ?>;
<?php
$ptv_nonresmi_file = WP_CONTENT_DIR . '/uploads/2026/09/LOGO-NON-RESMI.webp';
if (!file_exists($ptv_nonresmi_file)) {
    $ptv_nonresmi_file = WP_CONTENT_DIR . '/uploads/LOGO-NON-RESMI.webp';
}
$ptv_id_card_logo_url = file_exists($ptv_nonresmi_file)
    ? (strpos($ptv_nonresmi_file, '2026/09') !== false ? '/wp-content/uploads/2026/09/LOGO-NON-RESMI.webp' : '/wp-content/uploads/LOGO-NON-RESMI.webp')
    : '/wp-content/uploads/2026/09/LOGO-NON-RESMI.webp';
$ptv_id_card_logo_data = file_exists($ptv_nonresmi_file)
    ? ('data:image/webp;base64,' . base64_encode(file_get_contents($ptv_nonresmi_file)))
    : '';

$bs_file = WP_CONTENT_DIR . '/uploads/BS-X-PTV.webp';
$bs_logo_data = file_exists($bs_file) ? ('data:image/webp;base64,' . base64_encode(file_get_contents($bs_file))) : '';
?>
const BS_X_PTV_LOGO_DATA = <?php echo wp_json_encode($bs_logo_data); ?>;
const BS_X_PTV_LOGO_URL = <?php echo wp_json_encode('/wp-content/uploads/BS-X-PTV.webp'); ?>;
const PTV_ID_CARD_LOGO_URL = <?php echo wp_json_encode($ptv_id_card_logo_url); ?>;
const PTV_ID_CARD_LOGO_BASE64 = <?php echo wp_json_encode($ptv_id_card_logo_data); ?>;
const HERO_BG_IMAGES = <?php echo wp_json_encode($hero_bg_pool); ?>;
function getRandomHeroBg(){
  if(!Array.isArray(HERO_BG_IMAGES) || !HERO_BG_IMAGES.length) return '';
  const idx = Math.floor(Math.random() * HERO_BG_IMAGES.length);
  return HERO_BG_IMAGES[idx];
}

/* ---------------- Icons (Font Awesome 6) ---------------- */
const FA = {
  home:'fa-solid fa-house', event:'fa-solid fa-calendar-day', cal:'fa-solid fa-calendar-days',
  camera:'fa-solid fa-camera-retro', more:'fa-solid fa-ellipsis', plus:'fa-solid fa-plus',
  bell:'fa-solid fa-bell', search:'fa-solid fa-magnifying-glass',
  chev:'fa-solid fa-chevron-right', chevL:'fa-solid fa-chevron-left', chevD:'fa-solid fa-chevron-down',
  x:'fa-solid fa-xmark', check:'fa-solid fa-check', clock:'fa-regular fa-clock',
  pin:'fa-solid fa-location-dot', users:'fa-solid fa-users', box:'fa-solid fa-boxes-stacked',
  handoff:'fa-solid fa-right-left', wrench:'fa-solid fa-screwdriver-wrench',
  alert:'fa-solid fa-triangle-exclamation', lost:'fa-solid fa-magnifying-glass-location',
  doc:'fa-solid fa-file-lines', id:'fa-solid fa-id-card', phone:'fa-solid fa-phone',
  mobile:'fa-solid fa-mobile-screen-button', tablet:'fa-solid fa-tablet-screen-button',
  shield:'fa-solid fa-shield-halved', money:'fa-solid fa-receipt', megaphone:'fa-solid fa-bullhorn',
  chart:'fa-solid fa-chart-simple', settings:'fa-solid fa-gear', qr:'fa-solid fa-qrcode',
  scan:'fa-solid fa-qrcode', download:'fa-solid fa-arrow-down-to-bracket',
  eye:'fa-solid fa-eye', send:'fa-solid fa-paper-plane', photo:'fa-solid fa-image',
  filter:'fa-solid fa-sliders', logout:'fa-solid fa-arrow-right-from-bracket',
  moon:'fa-solid fa-moon', info:'fa-solid fa-circle-info', archive:'fa-solid fa-box-archive',
  refresh:'fa-solid fa-arrows-rotate', wa:'fa-brands fa-whatsapp', book:'fa-solid fa-book-open',
  sparkle:'fa-solid fa-wand-magic-sparkles', tag:'fa-solid fa-tag', gear2:'fa-solid fa-sliders',
  note:'fa-solid fa-note-sticky', sticky:'fa-solid fa-note-sticky',
};
FA.download = 'fa-solid fa-download';
const ic = new Proxy({}, { get:(_,k)=> FA[k] ? `<i class="${FA[k]}"></i>` : '' });
const icBig = (k,px)=> FA[k] ? `<i class="${FA[k]}" style="font-size:${px}px"></i>` : '';

/* ---------------- Utils ---------------- */
const $ = (s,r)=> (r||document).querySelector(s);
const el = (h)=>{const t=document.createElement('template');t.innerHTML=h.trim();return t.content.firstElementChild;};
const esc = (s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials = (n)=>String(n||'').split(/\s+/).filter(w=>/^[A-Za-z]/.test(w)).slice(0,2).map(w=>w[0]).join('').toUpperCase()||'P';
function normRole(r){
  const s = String(r || '').trim().toLowerCase();
  if (s === 'admin' || s === 'administrasi') return 'administrasi';
  if (s === 'eksekutif' || s === 'executive') return 'eksekutif';
  if (s === 'pengarah') return 'pengarah';
  if (s === 'pembina') return 'pembina';
  return 'crew';
}
function roleLabel(r){return {eksekutif:'Eksekutif',administrasi:'Administrasi',pengarah:'Pengarah',pembina:'Pembina',crew:'Crew'}[normRole(r)]||'Crew'}
function avatarHTML(name, photoUrl, sizeClass = '', extraStyle = '') {
  const cleanPhoto = String(photoUrl || '').trim();
  const cls = ['avatar', sizeClass].filter(Boolean).join(' ');
  const styleAttr = extraStyle ? ` style="${extraStyle}"` : '';
  const init = initials(name);
  if (cleanPhoto) {
    return `<span class="${cls}"${styleAttr}><img src="${esc(cleanPhoto)}" alt="${esc(name || '')}" onerror="this.onerror=null;this.parentElement.innerHTML='${init}';"></span>`;
  }
  return `<span class="${cls}"${styleAttr}>${init}</span>`;
}
function catIcon(cat){
  const c = String(cat||'').toLowerCase();
  if(c.includes('smartphone')||c.includes('tablet')||c.includes('ipad')||c.includes('iphone')||c.includes('android')||c.includes('mobile')||c.includes('hp')||c.includes('phone')||c.includes('tab')) return 'mobile';
  if(c.includes('kamera')||c.includes('camera')||c.includes('lens')||c.includes('tripod')||c.includes('gimbal')) return 'camera';
  if(c.includes('audio')||c.includes('mic')||c.includes('sound')||c.includes('headphone')||c.includes('speaker')) return 'megaphone';
  if(c.includes('komputer')||c.includes('ram')||c.includes('pc')||c.includes('laptop')||c.includes('storage')||c.includes('ssd')||c.includes('harddisk')) return 'chart';
  if(c.includes('kabel')||c.includes('cable')||c.includes('otg')||c.includes('adapter')||c.includes('hub')||c.includes('hdmi')) return 'box';
  if(c.includes('streaming')||c.includes('broadcast')||c.includes('capture')) return 'box';
  return 'box';
}
function itemThumbHTML(x, extraClass = '') {
  const photo = String(x?.photo || x?.foto_url || x?.gambar || x?.foto || '').trim();
  const iconKey = catIcon(x?.cat);
  const fallbackSvg = ic[iconKey] || ic.box;
  const cls = ['li-ic', extraClass].filter(Boolean).join(' ');

  if (photo) {
    return `<span class="${cls} has-img"><img src="${esc(photo)}" alt="${esc(x?.name || 'Alat')}" class="li-img" loading="lazy" onerror="this.style.display='none';this.parentElement.classList.remove('has-img');if(this.nextElementSibling)this.nextElementSibling.style.display='contents';" /><span class="li-fb" style="display:none">${fallbackSvg}</span></span>`;
  }
  return `<span class="${cls}">${fallbackSvg}</span>`;
}
function itemHeroHTML(x) {
  const photo = String(x?.photo || x?.foto_url || x?.gambar || x?.foto || '').trim();
  const iconKey = catIcon(x?.cat);
  const fallbackSvg = icBig(iconKey, 46);

  if (photo) {
    return `<div class="dt-hero has-img"><img src="${esc(photo)}" alt="${esc(x?.name || 'Alat')}" class="dt-hero-img" loading="lazy" onerror="this.style.display='none';this.parentElement.classList.remove('has-img');if(this.nextElementSibling)this.nextElementSibling.style.display='contents';" /><span class="dt-hero-fb" style="display:none">${fallbackSvg}</span></div>`;
  }
  return `<div class="dt-hero">${fallbackSvg}</div>`;
}
const ID = ()=>Math.random().toString(36).slice(2,9);
const pad = n=>String(n).padStart(2,'0');
const MONTHS=['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
const MON=['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'];
const DOW=['Min','Sen','Sel','Rab','Kam','Jum','Sab'];
const DOW_FULL=['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'];
const HIJRI_MONTHS = [
  'Muharram', 'Shafar', 'Rabiul Awal', 'Rabiul Akhir',
  'Jumadil Awal', 'Jumadil Akhir', 'Rajab', 'Sya\'ban',
  'Ramadhan', 'Syawal', 'Dzulqo\'dah', 'Dzulhijjah'
];

function normalizeHijriMonth(name) {
  if (!name) return '';
  const s = String(name).toLowerCase().replace(/[^a-z0-9]/g, '');
  if (s.includes('muhar')) return 'Muharram';
  if (s.includes('shaf') || s.includes('safar')) return 'Shafar';
  if (s.includes('rabi') && (s.includes('awal') || s.includes('ula') || s.includes('1') || s.includes('awwal'))) return 'Rabiul Awal';
  if (s.includes('rabi') && (s.includes('akhir') || s.includes('tsani') || s.includes('2') || s.includes('sani'))) return 'Rabiul Akhir';
  if (s.includes('jumad') && (s.includes('awal') || s.includes('ula') || s.includes('1'))) return 'Jumadil Awal';
  if (s.includes('jumad') && (s.includes('akhir') || s.includes('tsani') || s.includes('2') || s.includes('sani'))) return 'Jumadil Akhir';
  if (s.includes('rajab')) return 'Rajab';
  if (s.includes('syab') || s.includes('sha\'b') || s.includes('shab')) return 'Sya\'ban';
  if (s.includes('ramad')) return 'Ramadhan';
  if (s.includes('syaw') || s.includes('shaw')) return 'Syawal';
  if (s.includes('dzulq') || s.includes('zulka') || s.includes('dhuqi')) return 'Dzulqo\'dah';
  if (s.includes('dzulh') || s.includes('zulhij') || s.includes('dhuhij')) return 'Dzulhijjah';
  return String(name).trim();
}
const PASARAN_NAMES=['Wage','Kliwon','Legi','Pahing','Pon'];

const today = new Date();
const iso = d=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
const dOff = n=>{const d=new Date(today);d.setDate(d.getDate()+n);return iso(d);};

function getWetonInfo(s){
  if(!s) return { day: '', pasaran: '', full: '' };
  const d = new Date(s.includes('T') ? s : s + 'T00:00:00');
  if(isNaN(d)) return { day: '', pasaran: '', full: '' };
  const dayName = DOW_FULL[d.getDay()];
  const epochDays = Math.floor(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) / 86400000);
  const pasaranName = PASARAN_NAMES[((epochDays % 5) + 5) % 5];
  return {
    day: dayName,
    pasaran: pasaranName,
    full: `${dayName} ${pasaranName}`
  };
}

function getHijriInfo(s){
  if(!s) return { day: 1, month: 1, monthName: 'Muharram', year: 1448, full: '', short: '' };
  const d = new Date(s.includes('T') ? s : s + 'T00:00:00');
  if(isNaN(d)) return { day: 1, month: 1, monthName: 'Muharram', year: 1448, full: '', short: '' };

  if(typeof Intl !== 'undefined' && Intl.DateTimeFormat){
    try {
      const f = new Intl.DateTimeFormat('id-ID-u-ca-islamic-umalqura', {
        day: 'numeric',
        month: 'numeric',
        year: 'numeric'
      });
      const parts = f.formatToParts(d);
      let day, month, year;
      for(const p of parts){
        if(p.type === 'day') day = parseInt(p.value, 10);
        if(p.type === 'month') month = parseInt(p.value, 10);
        if(p.type === 'year') year = parseInt(p.value, 10);
      }
      if(day && month && year){
        const mName = HIJRI_MONTHS[(month - 1) % 12] || `Bulan ${month}`;
        return {
          day,
          month,
          monthName: mName,
          year,
          full: `${day} ${mName} ${year} H`,
          short: `${day} ${mName.slice(0, 4)}`
        };
      }
    } catch(e){}
  }

  // Pure Algorithmic Fallback (Indonesian MABIMS / Kuwaiti Astronomical Criteria)
  let gY = d.getFullYear(), gM = d.getMonth() + 1, gD = d.getDate();
  if(gM < 3){ gY -= 1; gM += 12; }
  const a = Math.floor(gY / 100);
  const b = 2 - a + Math.floor(a / 4);
  const jd = Math.floor(365.25 * (gY + 4716)) + Math.floor(30.6001 * (gM + 1)) + gD + b - 1524;
  const l = jd - 1948440 + 10632;
  const n = Math.floor((l - 1) / 10631);
  const l2 = l - 10631 * n + 354;
  const j = (Math.floor((10985 - l2) / 5316)) * (Math.floor((50 * l2) / 17719)) + (Math.floor(l2 / 5670)) * (Math.floor((43 * l2) / 15238));
  const l3 = l2 - (Math.floor((30 - j) / 15)) * (Math.floor((17719 * j) / 50)) - (Math.floor(j / 16)) * (Math.floor((15238 * j) / 43)) + 29;
  const hm = Math.floor((24 * l3) / 709);
  const hd = l3 - Math.floor((709 * hm) / 24);
  const hy = 30 * n + j - 30;

  const mName = HIJRI_MONTHS[(hm - 1) % 12] || `Bulan ${hm}`;
  return {
    day: hd,
    month: hm,
    monthName: mName,
    year: hy,
    full: `${hd} ${mName} ${hy} H`,
    short: `${hd} ${mName.slice(0, 4)}`
  };
}

