  'konten harian': 'Konten Harian'
};

function normalizePlannerCategory(cat) {
  if (!cat) return 'Event Hijriyah';
  const clean = String(cat).trim();
  const lower = clean.toLowerCase();
  return PLANNER_CATEGORY_MAP[lower] || clean;
}

function getPlannerCategoryLabel(cat) {
  return normalizePlannerCategory(cat);
}

function normalizePlannerRecurrenceType(type) {
  if (!type) return 'sekali_tayang';
  const t = String(type).trim().toLowerCase();
  switch (t) {
    case 'none':
    case 'sekali':
    case 'sekali_tayang':
    case 'single':
      return 'sekali_tayang';

    case 'tanggal_hijriah':
    case 'tanggal_hijriyah':
      return 'tanggal_hijriah';

    case 'bulan_hijriah':
    case 'bulan_hijriyah':
      return 'bulan_hijriah';

    case 'bagian_bulan_hijriah':
    case 'month_segment':
    case 'segment_hijriah':
    case 'segment':
      return 'bagian_bulan_hijriah';

    case 'tanggal_masehi':
    case 'tanggal_masehi_tahunan':
      return 'tanggal_masehi_tahunan';

    case 'bulan_masehi':
      return 'bulan_masehi';

    case 'setiap_bulan':
    case 'bulanan':
      return 'setiap_bulan';

    case 'hari_mingguan':
    case 'mingguan':
      return 'hari_mingguan';

    case 'hari_weton':
    case 'hari_pasaran':
    case 'weton':
    case 'pasaran':
      return 'hari_weton';

    case 'minggu_ke_n':
      return 'minggu_ke_n';

    case 'hari_ke_n':
      return 'hari_ke_n';

    case 'custom_periode':
    case 'custom':
    case 'periode':
      return 'custom_periode';

    default:
      return t;
  }
}

