];

function getPlannerRecurrenceLabel(rawType) {
  if (!rawType) return PLANNER_RECURRENCE_MAP['sekali_tayang'];
  const norm = normalizePlannerRecurrenceType(rawType);
  if (PLANNER_RECURRENCE_MAP[norm]) {
    return PLANNER_RECURRENCE_MAP[norm];
  }
  console.warn('[Planner Audit] Pola waktu tidak dikenal:', rawType);
  return 'Pola waktu tidak dikenal';
}

function renderPlannerSelect(id, options, selectedVal) {
  const normSelected = String(selectedVal || '').trim().toLowerCase();
  const optionsHtml = options.map(opt => {
    const val = Array.isArray(opt) ? opt[0] : (opt.value !== undefined ? opt.value : opt);
    const lbl = Array.isArray(opt) ? opt[1] : (opt.label !== undefined ? opt.label : opt);
    const isSelected = String(val).trim().toLowerCase() === normSelected;
    return `<option value="${esc(val)}"${isSelected ? ' selected' : ''}>${esc(lbl)}</option>`;
  }).join('');
  return `<select class="input" id="${id}">${optionsHtml}</select>`;
}

function renderPlannerCategorySelect(id, selectedVal) {
  const norm = normalizePlannerCategory(selectedVal || 'Event Hijriyah');
  const list = [...PLANNER_CANONICAL_CATEGORIES];
  if (norm && !list.includes(norm)) {
    list.push(norm);
  }
  const opts = list.map(c => [c, getPlannerCategoryLabel(c)]);
  return renderPlannerSelect(id, opts, norm);
}

function renderPlannerRecurrenceSelect(id, selectedVal) {
  const norm = normalizePlannerRecurrenceType(selectedVal || 'sekali_tayang');
  return renderPlannerSelect(id, PLANNER_RECURRENCE_OPTIONS, norm);
}

/* ---------------- Content Planner Recurring Engine (Semantic Architecture) ---------------- */
function getPlannerRecurrence(p) {
  if (!p) return { type: 'sekali_tayang', rule: {}, precision: 'EXACT' };
  if (p._recParsed) return p._recParsed;

  let type = normalizePlannerRecurrenceType(p.recurrence_type || '');
  let rule = p.recurrence_rule || {};
  if (typeof rule === 'string') {
    try { rule = JSON.parse(rule); } catch(e){ rule = {}; }
  }

  // Parse from deskripsi comment if available
  if ((!type || type === 'sekali_tayang') && p.deskripsi && p.deskripsi.includes('<!-- PTV_RECURRENCE:')) {
    const m = p.deskripsi.match(/<!-- PTV_RECURRENCE:\s*({.*?})\s*-->/);
    if (m && m[1]) {
      try {
        const parsed = JSON.parse(m[1]);
        if (parsed.type) {
          type = normalizePlannerRecurrenceType(parsed.type);
          rule = parsed.rule || parsed;
        } else {
          rule = parsed;
        }
      } catch(e){}
    }
  }

  // Semantic inference from fields if type is still empty/sekali_tayang
  if (!type || type === 'sekali_tayang') {
    if (rule.segment || (p.subkategori && /^(awal|pertengahan|akhir|menjelang)/i.test(p.subkategori))) {
      type = 'bagian_bulan_hijriah';
      if (!rule.segment) {
        const sub = (p.subkategori || '').toLowerCase();
        if (sub.includes('awal')) rule.segment = 'awal';
        else if (sub.includes('pertengahan')) rule.segment = 'pertengahan';
        else if (sub.includes('akhir')) rule.segment = 'akhir';
        else if (sub.includes('menjelang')) rule.segment = 'menjelang';
      }
      if (!rule.month && p.bulan_hijriah) rule.month = p.bulan_hijriah;
    } else if (p.bulan_hijriah) {
      if (p.tanggal_hijriah !== null && p.tanggal_hijriah !== undefined && p.tanggal_hijriah !== '') {
        type = 'tanggal_hijriah';
        rule.day = Number(p.tanggal_hijriah);
        rule.month = p.bulan_hijriah;
      } else {
        type = 'bulan_hijriah';
        rule.month = p.bulan_hijriah;
      }
    } else if (rule.day && rule.month) {
      type = typeof rule.month === 'number' ? 'tanggal_masehi_tahunan' : 'tanggal_hijriah';
    } else if (rule.month) {
      type = typeof rule.month === 'number' ? 'bulan_masehi' : 'bulan_hijriah';
    } else if (rule.pasaran) {
      type = 'hari_weton';
    } else if (rule.dayOfWeek) {
      type = 'hari_mingguan';
    } else if (rule.repeat === 'every_month') {
      type = 'setiap_bulan';
    } else if (p.tanggal_mulai) {
      type = 'sekali_tayang';
    }
  }

  type = normalizePlannerRecurrenceType(type);

  // Determine Precision Semantic:
  // - EXACT: Bound to a specific date (Masehi date, Hijri exact date, weton, weekday, etc.)
  // - MONTH: Broad month-level event where specific date is undetermined (tanggal belum ditentukan / fleksibel)
  // - MONTH_SEGMENT: Broad 10-day period of a month (Awal, Pertengahan, Akhir)
  // - CUSTOM_PERIOD: Date range period
  let precision = 'EXACT';
  if (type === 'bulan_hijriah' || type === 'bulan_masehi') {
    const hasExactDay = Number(rule.day || p.tanggal_hijriah || 0) > 0;
    precision = hasExactDay ? 'EXACT' : 'MONTH';
  } else if (type === 'bagian_bulan_hijriah' || type === 'month_segment') {
    precision = 'MONTH_SEGMENT';
  } else if (type === 'custom_periode') {
    precision = 'CUSTOM_PERIOD';
  }

  p._recParsed = { type: type || 'sekali_tayang', rule: rule || {}, precision };
  return p._recParsed;
}

function matchPlannerRule(p, isoDate, hInfo, wInfo) {
  if (!p || !isoDate) return false;
  const { type: rawType, rule } = getPlannerRecurrence(p);
  const type = normalizePlannerRecurrenceType(rawType);
  const dObj = new Date(isoDate.includes('T') ? isoDate : isoDate + 'T00:00:00');
  if (isNaN(dObj.getTime())) return false;
  const h = hInfo || getHijriInfo(isoDate);
  const w = wInfo || getWetonInfo(isoDate);
  const curM = dObj.getMonth() + 1;
  const curD = dObj.getDate();

  switch (type) {
    case 'tanggal_hijriah': {
      const targetDay = Number(rule.day || p.tanggal_hijriah || 0);
      const targetMonth = normalizeHijriMonth(rule.month || p.bulan_hijriah);
      const curMonth = normalizeHijriMonth(h.monthName);
      return (Number(h.day) === targetDay && curMonth === targetMonth);
    }
    case 'bulan_hijriah': {
      // PENTING: Jika tanggal_hijriah belum ditentukan (NULL), JANGAN paksa cocok pada tanggal 1!
      // Event tingkat bulan ditampilkan melalui section periode bulan / overlap, bukan sebagai exact date.
      const targetDay = Number(rule.day || p.tanggal_hijriah || 0);
      if (targetDay > 0) {
        const targetMonth = normalizeHijriMonth(rule.month || p.bulan_hijriah);
        return (Number(h.day) === targetDay && normalizeHijriMonth(h.monthName) === targetMonth);
      }
      return false;
    }
    case 'bagian_bulan_hijriah':
    case 'month_segment': {
      const targetMonth = normalizeHijriMonth(rule.month || p.bulan_hijriah);
      const curMonth = normalizeHijriMonth(h.monthName);
      if (targetMonth && curMonth !== targetMonth) return false;
      const seg = (rule.segment || 'awal').toLowerCase();
      const hDay = Number(h.day);
      if (seg === 'awal') return hDay >= 1 && hDay <= 10;
      if (seg === 'pertengahan') return hDay >= 11 && hDay <= 20;
      if (seg === 'akhir') return hDay >= 21 && hDay <= 30;
      if (seg === 'menjelang') return hDay >= 25 && hDay <= 30;
      return false;
    }
    case 'tanggal_masehi_tahunan':
    case 'tanggal_masehi': {
      const targetDay = Number(rule.day || (p.tanggal_mulai ? parseInt(p.tanggal_mulai.split('-')[2], 10) : 0));
      const targetMonth = Number(rule.month || (p.tanggal_mulai ? parseInt(p.tanggal_mulai.split('-')[1], 10) : 0));
      return (curD === targetDay && curM === targetMonth);
    }
    case 'bulan_masehi': {
      const targetDay = Number(rule.day || (p.tanggal_mulai ? parseInt(p.tanggal_mulai.split('-')[2], 10) : 0));
      if (targetDay > 0) return (curM === Number(rule.month) && curD === targetDay);
      return false; // Month-level masehi ditampilkan via isPlannerActiveInMonth
    }
    case 'setiap_bulan':
    case 'bulanan': {
      let targetDay = Number(rule.day);
      if (!targetDay && p.tanggal_mulai) {
        targetDay = parseInt(p.tanggal_mulai.split('-')[2], 10);
      }
      if (!targetDay) targetDay = 15;
      return curD === targetDay;
    }
    case 'hari_mingguan': {
      const targetDow = String(rule.dayOfWeek || '').trim().toLowerCase();
      return (w.day || '').trim().toLowerCase() === targetDow;
    }
    case 'hari_weton':
    case 'hari_pasaran': {
      const targetDow = String(rule.dayOfWeek || '').trim().toLowerCase();
      const targetPasaran = String(rule.pasaran || '').trim().toLowerCase();
      return (w.day || '').trim().toLowerCase() === targetDow && (w.pasaran || '').trim().toLowerCase() === targetPasaran;
    }
    case 'minggu_ke_n':
    case 'hari_ke_n': {
      const targetNth = Number(rule.nth || 1);
      const targetDow = String(rule.dayOfWeek || 'Minggu').trim().toLowerCase();
      const targetMonth = Number(rule.month || 0);
      if (targetMonth > 0 && curM !== targetMonth) return false;
      if ((w.day || '').trim().toLowerCase() !== targetDow) return false;
      const currentNth = Math.floor((curD - 1) / 7) + 1;
      return currentNth === targetNth;
    }
    case 'custom_periode': {
      if (p.tanggal_mulai && p.tanggal_selesai) {
        return isoDate >= p.tanggal_mulai && isoDate <= p.tanggal_selesai;
      }
      if (p.tanggal_mulai) return p.tanggal_mulai === isoDate;
      return false;
    }
    case 'sekali_tayang':
    case 'none':
    default: {
      if (p.tanggal_mulai) return p.tanggal_mulai === isoDate;
      if (p.bulan_hijriah && p.tanggal_hijriah && h.monthName) {
        return normalizeHijriMonth(p.bulan_hijriah) === normalizeHijriMonth(h.monthName) && Number(p.tanggal_hijriah) === Number(h.day);
      }
      return false;
    }
  }
}

// Cek apakah suatu momentum planner aktif / overlap pada bulan kalender Masehi (y, m)
function isPlannerActiveInMonth(p, y, m) {
  if (!p) return false;
  const { type: rawType, rule, precision } = getPlannerRecurrence(p);
  const type = normalizePlannerRecurrenceType(rawType);
  const daysInMonth = new Date(y, m + 1, 0).getDate();

  if (precision === 'MONTH') {
    if (type === 'bulan_hijriah') {
      const targetMonth = normalizeHijriMonth(rule.month || p.bulan_hijriah);
      for (let d = 1; d <= daysInMonth; d++) {
        const iso = `${y}-${pad(m+1)}-${pad(d)}`;
        const h = getHijriInfo(iso);
        if (normalizeHijriMonth(h.monthName) === targetMonth) return true;
      }
      return false;
    }
    if (type === 'bulan_masehi') {
      return Number(rule.month || (p.tanggal_mulai ? parseInt(p.tanggal_mulai.split('-')[1], 10) : 0)) === (m + 1);
    }
  }

  if (precision === 'MONTH_SEGMENT' || type === 'bagian_bulan_hijriah' || type === 'month_segment') {
    const targetMonth = normalizeHijriMonth(rule.month || p.bulan_hijriah);
    const seg = (rule.segment || 'awal').toLowerCase();
    for (let d = 1; d <= daysInMonth; d++) {
      const iso = `${y}-${pad(m+1)}-${pad(d)}`;
      const h = getHijriInfo(iso);
      if (normalizeHijriMonth(h.monthName) === targetMonth) {
        const hd = Number(h.day);
        if (seg === 'awal' && hd >= 1 && hd <= 10) return true;
        if (seg === 'pertengahan' && hd >= 11 && hd <= 20) return true;
        if (seg === 'akhir' && hd >= 21 && hd <= 30) return true;
        if (seg === 'menjelang' && hd >= 25 && hd <= 30) return true;
      }
    }
    return false;
  }

  if (precision === 'CUSTOM_PERIOD') {
    const firstIso = `${y}-${pad(m+1)}-01`;
    const lastIso = `${y}-${pad(m+1)}-${pad(daysInMonth)}`;
    const start = p.tanggal_mulai || rule.start || '';
    const end = p.tanggal_selesai || rule.end || start;
    if (start && end) {
      return (start <= lastIso && end >= firstIso);
    }
    if (start) return (start >= firstIso && start <= lastIso);
    return false;
  }

  // Exact items: cek apakah ada hari di bulan ini yang cocok
  for (let d = 1; d <= daysInMonth; d++) {
    const iso = `${y}-${pad(m+1)}-${pad(d)}`;
    if (matchPlannerRule(p, iso)) return true;
  }
  return false;
}

function getPlannerScheduleBadge(p) {
  if (!p) return { label: 'Momentum', icon: 'fa-regular fa-calendar', isSpecific: false, precision: 'EXACT' };
  const { type: rawType, rule, precision } = getPlannerRecurrence(p);
  const type = normalizePlannerRecurrenceType(rawType);
  const MONTHS_SHORT = ['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'];
  
  if (type === 'bulan_hijriah') {
    const m = normalizeHijriMonth(rule.month || p.bulan_hijriah || 'Bulan');
    return {
      label: `○ ${m} (Tgl Belum Ditentukan)`,
      shortLabel: `○ ${m}`,
      icon: 'fa-regular fa-circle-dot',
      isSpecific: false,
      precision: 'MONTH'
    };
  }
  if (type === 'bagian_bulan_hijriah' || type === 'month_segment') {
    const segMap = { awal: 'Awal', pertengahan: 'Pertengahan', akhir: 'Akhir', menjelang: 'Menjelang' };
    const seg = segMap[(rule.segment || 'awal').toLowerCase()] || 'Awal';
    const m = normalizeHijriMonth(rule.month || p.bulan_hijriah || '');
    return {
      label: `○ ${seg} ${m} (Periode)`,
      shortLabel: `○ ${seg} ${m}`,
      icon: 'fa-solid fa-layer-group',
      isSpecific: false,
      precision: 'MONTH_SEGMENT'
    };
  }
  if (type === 'bulan_masehi') {
    const mIdx = Number(rule.month || 1) - 1;
    return {
      label: `○ Sepanjang ${MONTHS[mIdx] || ''}`,
      shortLabel: `○ ${MONTHS_SHORT[mIdx] || ''}`,
      icon: 'fa-regular fa-calendar',
      isSpecific: false,
      precision: 'MONTH'
    };
  }
  if (type === 'tanggal_hijriah') {
    const d = rule.day || p.tanggal_hijriah || '';
    const m = normalizeHijriMonth(rule.month || p.bulan_hijriah || '');
    return {
      label: `● ${d} ${m} H`,
      shortLabel: `${d} ${m}`,
      icon: 'fa-solid fa-moon',
      isSpecific: true,
      precision: 'EXACT'
    };
  }
  if (type === 'tanggal_masehi_tahunan' || type === 'tanggal_masehi') {
    const d = rule.day || (p.tanggal_mulai ? parseInt(p.tanggal_mulai.split('-')[2], 10) : 0);
    const mIdx = (rule.month || (p.tanggal_mulai ? parseInt(p.tanggal_mulai.split('-')[1], 10) : 1)) - 1;
    return {
      label: `● ${d} ${MONTHS_SHORT[mIdx] || ''}`,
      shortLabel: `${d} ${MONTHS_SHORT[mIdx] || ''}`,
      icon: 'fa-regular fa-calendar-check',
      isSpecific: true,
      precision: 'EXACT'
    };
  }
  if (type === 'hari_weton' || type === 'hari_pasaran') {
    return {
      label: `● Tiap ${rule.dayOfWeek || ''} ${rule.pasaran || ''}`.trim(),
      shortLabel: `${rule.dayOfWeek || ''} ${rule.pasaran || ''}`.trim(),
      icon: 'fa-solid fa-arrows-rotate',
      isSpecific: true,
      precision: 'EXACT'
    };
  }
  if (type === 'hari_mingguan') {
    return {
      label: `● Tiap ${rule.dayOfWeek || 'Hari'}`,
      shortLabel: `Tiap ${rule.dayOfWeek || 'Hari'}`,
      icon: 'fa-solid fa-arrows-rotate',
      isSpecific: true,
      precision: 'EXACT'
    };
  }
  if (type === 'setiap_bulan' || type === 'bulanan') {
    const d = rule.day || (p.tanggal_mulai ? parseInt(p.tanggal_mulai.split('-')[2], 10) : 15);
    return {
      label: `● Tiap Tgl ${d}`,
      shortLabel: `Tgl ${d}`,
      icon: 'fa-solid fa-arrows-rotate',
      isSpecific: true,
      precision: 'EXACT'
    };
  }
  if (type === 'minggu_ke_n' || type === 'hari_ke_n') {
    return {
      label: `● ${rule.dayOfWeek || ''} Ke-${rule.nth || 1}`,
      shortLabel: `${rule.dayOfWeek || ''} Ke-${rule.nth || 1}`,
      icon: 'fa-regular fa-clock',
      isSpecific: true,
      precision: 'EXACT'
    };
  }
  if (type === 'custom_periode') {
    return {
      label: `○ Periode Khusus`,
      shortLabel: `Periode`,
      icon: 'fa-solid fa-calendar-week',
      isSpecific: false,
      precision: 'CUSTOM_PERIOD'
    };
  }
  if (p.tanggal_mulai) {
    const parts = p.tanggal_mulai.split('-');
    if (parts.length === 3) {
      const d = parseInt(parts[2], 10);
      const mIdx = parseInt(parts[1], 10) - 1;
      return {
        label: `● ${d} ${MONTHS_SHORT[mIdx] || ''}`,
        shortLabel: `${d} ${MONTHS_SHORT[mIdx] || ''}`,
        icon: 'fa-regular fa-calendar-check',
        isSpecific: true,
        precision: 'EXACT'
      };
    }
  }
  if (p.bulan_hijriah) {
    return {
      label: `○ Bulan ${normalizeHijriMonth(p.bulan_hijriah)}`,
      shortLabel: `○ ${normalizeHijriMonth(p.bulan_hijriah)}`,
      icon: 'fa-regular fa-circle-dot',
      isSpecific: false,
      precision: 'MONTH'
    };
  }
  return { label: 'Momentum', icon: 'fa-solid fa-lightbulb', isSpecific: false, precision: 'EXACT' };
}

function fmtDate(s,long){
  if(!s) return '—';
  const d=new Date(s.includes('T')?s:s+'T00:00:00');
  if(isNaN(d))return s;
  return long?`${DOW_FULL[d.getDay()]}, ${d.getDate()} ${MONTHS[d.getMonth()]} ${d.getFullYear()}`:`${d.getDate()} ${MON[d.getMonth()]} ${d.getFullYear()}`;
}
function fmtDateTimeWIB(s){
  if(!s) return '—';
  const d = new Date(s.includes('T') ? s : (s.includes(' ') ? s.replace(' ', 'T') : s + 'T00:00:00'));
  if(isNaN(d)) return s;
  const day = d.getDate();
  const month = MONTHS[d.getMonth()];
  const year = d.getFullYear();
  const hh = String(d.getHours()).padStart(2, '0');
  const mm = String(d.getMinutes()).padStart(2, '0');
  return `${day} ${month} ${year}\n${hh}:${mm} WIB`;
}

function cleanEscapedText(val){
  if(val === null || val === undefined) return '';
  if(Array.isArray(val)) {
    const arr = val.map(cleanEscapedText).filter(Boolean);
    return arr;
  }
  let s = String(val).trim();
  if(!s || s === '[]' || s === 'null' || s === 'undefined' || s === '""') return '';

  for(let i = 0; i < 3; i++){
    const t = s.trim();
    if((t.startsWith('[') && t.endsWith(']')) || (t.startsWith('"') && t.endsWith('"'))){
      try {
        const parsed = JSON.parse(t);
        if(typeof parsed === 'string') { s = parsed; continue; }
        if(Array.isArray(parsed)) return parsed.map(cleanEscapedText).filter(Boolean);
      } catch(e){}
    }
    break;
  }
  s = s.replace(/\\+/g, '').replace(/^["'\[]+|["'\]]+$/g, '').trim();
  return s;
}

function normalizeContentList(val){
  if(val === null || val === undefined) return [];
  let items = [];
  if(typeof val === 'string'){
    let s = val.trim();
    if(!s || s === '[]' || s === 'null' || s === 'undefined' || s === '""') return [];
    if(s.startsWith('[') && s.endsWith(']')){
      try {
        const parsed = JSON.parse(s);
        if(Array.isArray(parsed)) items = parsed;
        else items = [s];
      } catch(e){
        items = s.split(/[\r\n,]+/);
      }
    } else {
      items = s.split(/[\r\n]+/);
    }
  } else if(Array.isArray(val)){
    items = val;
  } else if(val){
    items = [val];
  }

  const result = [];
  items.forEach(it => {
    const cleaned = cleanEscapedText(it);
    if(Array.isArray(cleaned)){
      cleaned.forEach(c => { if(c && c !== '[]' && c !== 'null') result.push(c); });
    } else if(cleaned && cleaned !== '[]' && cleaned !== 'null'){
      result.push(cleaned);
    }
  });
  return result;
}

function formatContentListText(val, sep = ' · '){
  const list = normalizeContentList(val);
  if(!list.length) return '';
  return list.join(sep);
}
function parseDateRobust(s){
  if(!s) return null;
  if(s instanceof Date) return isNaN(s.getTime()) ? null : s;
  let str = String(s).trim();
  if(/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}/.test(str)){
    str = str.replace(' ', 'T');
  }
  const d = new Date(str);
  return isNaN(d.getTime()) ? null : d;
}

function relDay(s){
  if(!s) return '—';
  const a = parseDateRobust(s);
  if(!a) return String(s);
  const now = new Date();
  const d1 = new Date(a.getFullYear(), a.getMonth(), a.getDate());
  const d2 = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const n = Math.round((d1 - d2) / 864e5);
  if(n === 0) return 'Hari ini';
  if(n === 1) return 'Besok';
  if(n === -1) return 'Kemarin';
  if(n > 1 && n < 7) return `${n} hari lagi`;
  if(n < 0 && n >= -6) return `${Math.abs(n)} hari lalu`;
  return fmtDate(s);
}

function formatNoteTimeAgo(s){
  if(!s) return 'Baru saja';
  const d = parseDateRobust(s);
  if(!d) return 'Baru saja';

  const now = new Date();
  const diffMs = now.getTime() - d.getTime();

  // If created very recently or slight server clock drift
  if(diffMs < 60000 && diffMs > -60000) return 'Baru saja';

  const diffSec = Math.floor(diffMs / 1000);
  const diffMin = Math.floor(diffSec / 60);

  const d1 = new Date(d.getFullYear(), d.getMonth(), d.getDate());
  const d2 = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const dayDiff = Math.round((d2 - d1) / 864e5);

  if(dayDiff === 0){
    if(diffMin < 1) return 'Baru saja';
    if(diffMin < 60) return `${diffMin} menit lalu`;
    return 'Hari ini';
  }
  if(dayDiff === 1) return '1 hari lalu';
  if(dayDiff >= 2 && dayDiff < 7) return `${dayDiff} hari lalu`;
  if(dayDiff >= 7 && dayDiff < 30){
    const w = Math.floor(dayDiff / 7);
    return `${w} minggu lalu`;
  }
  if(dayDiff >= 30 && dayDiff < 365){
    const m = Math.floor(dayDiff / 30);
    return `${m} bulan lalu`;
  }
  if(dayDiff >= 365){
    const y = Math.floor(dayDiff / 365);
    return `${y} tahun lalu`;
  }
  return fmtDate(s);
}
