function normalizeInventoryCategory(cat){
  if(!cat) return 'Lainnya';
  const c = String(cat).trim().toLowerCase();
  if(c === 'kamera' || c === 'camera' || c.startsWith('kamera')) return 'Kamera';
  if(c === 'lensa' || c === 'lens' || c.startsWith('lensa')) return 'Lensa';
  if(c.includes('tripod') || c.includes('rig') || c.includes('gimbal') || c.includes('monopod') || c.includes('support') || c.includes('stabilizer')) return 'Tripod & Rig';
  if(c.includes('baterai') || c.includes('battery') || c.includes('batere') || c.startsWith('baterai') || c.startsWith('battery') || c.includes('v-mount') || c.includes('vmount') || c.includes('powerbank') || c.includes('accu')) return 'Baterai & Power';
  if(c.includes('smartphone') || c.includes('tablet') || c.includes('ipad') || c.includes('iphone') || c.includes('android') || c.includes('mobile') || c.includes('hp') || c.includes('phone') || c.includes('tab')) return 'Smartphone / Tablet';
  if(c.includes('komputer') || c.includes('laptop') || c.includes('pc') || c.includes('macbook')) return 'Komputer / Laptop';
  if(c === 'audio' || c === 'mic' || c === 'sound' || c.startsWith('audio') || c.startsWith('mic') || c.includes('microphone') || c.includes('headphone') || c.includes('earphone')) return 'Audio';
  if(c.includes('light') || c.includes('lampu') || c.includes('lighting') || c.includes('softbox') || c.includes('led')) return 'Lighting';
  if(c.includes('stream') || c.includes('live') || c.includes('switcher') || c.includes('atem') || c.includes('capture')) return 'Streaming / Live Production';
  if(c.includes('jaringan') || c.includes('network') || c.includes('router') || c.includes('mikrotik') || c.includes('switch hub') || c.includes('access point') || c.includes('wifi') || c.includes('ethernet') || c.includes('lan ') || c === 'lan' || c.includes('rj45') || c.includes('crimp') || c.includes('ont') || c.includes('modem') || c.includes('access_point')) return 'Pengaturan Jaringan';
  if(c.includes('kabel') || c.includes('adapter') || c.includes('cable') || c.includes('hdmi') || c.includes('type c') || c.includes('charger')) return 'Kabel & Adapter';
  if(c.includes('dry cabinet') || c.includes('cabinet') || c.includes('dry box')) return 'Dry Cabinet';
  if(c.includes('smart tv') || c.includes('tv') || c.includes('televisi') || c.includes('monitor tv')) return 'TV / Smart TV';
  if(c.includes('storage') || c.includes('ssd') || c.includes('hdd') || c.includes('harddisk') || c.includes('sd card') || c.includes('cfexpress') || c.includes('memory') || c.includes('flashdisk') || c.includes('microsd')) return 'Storage';
  if(c.includes('peralatan') || c.includes('perkakas') || c.includes('tool') || c.includes('obeng') || c.includes('tang') || c.includes('solder') || c.includes('teknis')) return 'Peralatan & Perkakas';
  if(c.includes('atk') || c.includes('kertas') || c.includes('alat tulis') || c.includes('spidol') || c.includes('pulpen')) return 'ATK';
  return 'Lainnya';
}

function cleanMojibake(str, fallback = '') {
  if (str === null || str === undefined) return fallback;
  let s = String(str).trim();
  if (!s || s === 'null' || s === '[]') return fallback;

  // Pembersihan karakter mojibake akibat double/triple encoding UTF-8 / Windows-1252
  s = s.replace(/\u00C3\u0192\u00C2\u00A2\u00C3\u00A2\u201A\u00AC\u00C2\u009D/g, '—')
       .replace(/\u00C3\u0192\u00C2\u00A2\u00C3\u00A2\u201A\u00AC\u0153/g, '–')
       .replace(/Ã¢â‚¬â€œ/g, '–')
       .replace(/Ã¢â‚¬â€”/g, '—')
       .replace(/Ã¢â‚¬â—/g, '—')
       .replace(/Ã¢â‚¬â/g, '—')
       .replace(/Ã¢â‚¬/g, '—')
       .replace(/Ã¢,¬â€œ/g, '–')
       .replace(/Ã¢,¬â€”/g, '—')
       .replace(/Ã¢,¬/g, '—')
       .replace(/â‚¬â€œ/g, '–')
       .replace(/â‚¬â€”/g, '—')
       .replace(/â‚¬â—/g, '—')
       .replace(/â€“/g, '–')
       .replace(/â€”/g, '—')
       .replace(/Ã¢â€ â€™/g, '→')
       .replace(/Ã¢â€ â€™/g, '→')
       .replace(/â†’/g, '→')
       .replace(/Ã¢â€ Â /g, '←')
       .replace(/â† /g, '←')
       .replace(/Ã¢â‚¬Â¢/g, '•')
       .replace(/â€¢/g, '•')
       .replace(/Ã‚Â·/g, '·')
       .replace(/Â·/g, '·')
       .replace(/Ã¢â‚¬Â¦/g, '…')
       .replace(/â€¦/g, '…')
       .replace(/Ã¢â‚¬Å“/g, '“')
       .replace(/Ã¢â‚¬Â /g, '”')
       .replace(/Ã¢â‚¬â„¢/g, '’')
       .replace(/Ã¢â‚¬Ëœ/g, '‘')
       .replace(/â€œ/g, '"')
       .replace(/â€ /g, '"')
       .replace(/â€™/g, "'")
       .replace(/â€˜/g, "'")
       .replace(/Ã‚ /g, ' ')
       .replace(/Ã‚/g, '')
       .replace(/Â /g, ' ')
       .trim();

  if (!s || s === 'null') return fallback;
  if ((s === '-' || s === '—') && fallback !== '') return fallback;
  return s;
}

function getUnitBarcode(invCode, unitIndex) {
  const code = String(invCode || 'INV').trim().toUpperCase();
  const uIdx = String(unitIndex || 1).padStart(2, '0');
  return `${code}-${uIdx}`;
}

function isNiksanUnit(unitInput) {
  if (!unitInput) return false;
  let str = '';
  if (typeof unitInput === 'string') {
    str = unitInput;
  } else if (typeof unitInput === 'object') {
    str = unitInput.nama_unit || unitInput.name || unitInput.unit_name || unitInput.unitName || '';
  }
  return String(str || '').toLowerCase().includes('niksan');
}

function getUnitDisplayName(unitObj, fallbackIndex) {
  if (!unitObj && !fallbackIndex) return '';
  const idx = Number(unitObj?.unit || unitObj?.nomor_unit || unitObj?.unit_no || fallbackIndex || 1);
  const raw = String(unitObj?.nama_unit || unitObj?.name || unitObj?.unit_name || unitObj?.unitName || (typeof unitObj === 'string' ? unitObj : '')).trim();
  if (raw && !/^unit\s+\d+$/i.test(raw)) {
    return raw;
  }
  if (raw && /^unit\s+\d+$/i.test(raw)) {
    const m = raw.match(/\d+/);
    if (m) {
      return `Unit ${String(parseInt(m[0], 10)).padStart(2, '0')}`;
    }
  }
  return `Unit ${String(idx).padStart(2, '0')}`;
}

function renderUnitBranding(unitInput, options = {}) {
