}

window.handleUnitNameInput = function(inputEl) {
  if (!inputEl) return;
  const isNiksan = isNiksanUnit(inputEl.value);
  const wrap = inputEl.parentElement || inputEl.closest('.unit-cond-row, .field, div');
  const badge = wrap ? wrap.querySelector('.unit-niksan-indicator') : null;
  if (badge) {
    if (isNiksan) {
      badge.classList.add('active');
      badge.style.display = 'inline-flex';
    } else {
      badge.classList.remove('active');
      badge.style.display = 'none';
    }
  }
};

function getAssetUnitSummary(it){
  if(!it) return { total:0, available:0, borrowed:0, damaged:0, lost:0, service:0, units:[], summaryText:'0 Unit', masterStatus:'Tersedia' };
  const total = Math.max(1, Number(it.qty_total || it.qty || 1));
  const invCode = String(it.code || ('INV-' + String(it.id).slice(0,5).toUpperCase())).trim();
  const rawUnits = Array.isArray(it.unit_conditions) ? it.unit_conditions : [];

  // Cari laporan kerusakan aktif (status bukan 'Selesai')
  const activeDamages = (DB.damages || []).filter(d => String(d.item) === String(it.id) && String(d.status).toLowerCase() !== 'selesai');

  // Cari peminjaman aktif (status bukan kembali)
  const activeLoans = (DB.loans || []).filter(l => String(l.item) === String(it.id) && !l.back);

  const units = [];
  let availableCount = 0;
  let borrowedCount = 0;
  let damagedCount = 0;
  let lostCount = 0;
  let serviceCount = 0;

  // Track borrowed unit allocations (for loans with or without explicit unit_no)
  const borrowedUnitNos = new Set();
  let unassignedLoanCount = 0;
  activeLoans.forEach(l => {
    const uNo = parseInt(l.unit_no, 10);
    if(uNo && uNo >= 1 && uNo <= total){
      borrowedUnitNos.add(uNo);
    } else {
      unassignedLoanCount += Number(l.qty || 1);
    }
  });

  for(let i = 1; i <= total; i++){
    const cur = rawUnits.find(u => Number(u.unit) === i) || {};
    const uName = getUnitDisplayName(cur, i);
    let uCond = cur.cond || 'Baik';
    const uSn = cur.sn || (it.sn && it.sn !== '—' ? (total > 1 ? `${it.sn}-${i}` : it.sn) : '');
    const uCode = cur.code || cur.kode_unit || getUnitBarcode(invCode, i);
    const uNotes = cur.notes || '';

    // Cek laporan kerusakan aktif
    const activeDmg = activeDamages.find(d => Number(d.unit_no) === i || (d.unit_code && d.unit_code.toUpperCase() === uCode.toUpperCase()) || (total === 1 && !d.unit_no));
    if(activeDmg){
      uCond = 'Rusak';
    }

    const isDamaged = (uCond === 'Rusak' || uCond === 'Bermasalah' || !!activeDmg);
    const isLost = (uCond === 'Hilang');
    const isService = (uCond === 'Butuh Servis');

    // Cek status peminjaman
    let isBorrowed = false;
    let borrowerName = '';
    if(!isDamaged && !isLost){
      if(borrowedUnitNos.has(i)){
        isBorrowed = true;
        const matchingLoan = activeLoans.find(l => parseInt(l.unit_no, 10) === i || (l.unit_code && l.unit_code.toUpperCase() === uCode.toUpperCase()));
        borrowerName = matchingLoan ? matchingLoan.by : (it.holder || 'Kru');
      } else if(unassignedLoanCount > 0){
        isBorrowed = true;
        unassignedLoanCount--;
        borrowerName = it.holder || (activeLoans[0]?.by || 'Kru');
      }
    }

    let uStatus = 'Tersedia';
    if(isLost){
      uStatus = 'Hilang';
      lostCount++;
    } else if(isDamaged){
      uStatus = 'Rusak';
      damagedCount++;
    } else if(isBorrowed){
      uStatus = 'Dipinjam';
      borrowedCount++;
    } else {
      uStatus = 'Tersedia';
      availableCount++;
      if(isService) serviceCount++;
    }

    units.push({
      unit: i,
      unit_id: cur.unit_id || cur.id || null,
      name: uName,
      nama_unit: uName,
      code: uCode,
      cond: uCond,
      status: uStatus,
      sn: uSn,
      notes: uNotes,
      is_available: uStatus === 'Tersedia',
      is_borrowed: isBorrowed,
      is_damaged: isDamaged,
      is_lost: isLost,
      borrower: borrowerName,
      damage_report: activeDmg || null
    });
  }

  // Tentukan ringkasan teks sesuai spesifikasi audit
  let summaryText = '';
  if(total === 1){
    if(lostCount === 1) summaryText = '1 Hilang';
    else if(damagedCount === 1) summaryText = '1 Rusak';
    else if(borrowedCount === 1) summaryText = '1 Dipinjam';
    else summaryText = '1 Tersedia';
  } else {
    const parts = [];
    if(availableCount > 0) parts.push(`${availableCount} Tersedia`);
    if(borrowedCount > 0) parts.push(`${borrowedCount} Dipinjam`);
    if(damagedCount > 0) parts.push(`${damagedCount} Rusak`);
    if(lostCount > 0) parts.push(`${lostCount} Hilang`);
    summaryText = parts.length ? parts.join(' · ') : `${availableCount} Tersedia`;
  }

  // Tentukan status master
  let masterStatus = 'Tersedia';
  if(lostCount >= total) masterStatus = 'Hilang';
  else if(damagedCount >= total) masterStatus = 'Rusak / Servis';
  else if(availableCount === 0 && borrowedCount > 0) masterStatus = 'Dipinjam';
  else masterStatus = 'Tersedia';

  // Perbarui properti cache pada objek alat
  it.qty_total = total;
  it.qty_available = availableCount;
  it.qty_borrowed = borrowedCount;
  it.qty_damaged = damagedCount;
  it.qty_lost = lostCount;
  it.status = masterStatus;

  return {
    total,
    available: availableCount,
    borrowed: borrowedCount,
    damaged: damagedCount,
    lost: lostCount,
    service: serviceCount,
    units,
    summaryText,
    masterStatus
  };
}

function sortInventoryItems(items){
  if(!Array.isArray(items)) return [];
  const catOrder = {};
  INVENTORY_CATEGORIES.forEach((cat, idx) => { catOrder[cat] = idx + 1; });

  return items.slice().sort((a, b) => {
    if (!a && !b) return 0;
    if (!a) return 1;
    if (!b) return -1;

    // LEVEL 1: Category Order
    const catA = normalizeInventoryCategory(a.cat);
    const catB = normalizeInventoryCategory(b.cat);
    const ordA = catOrder[catA] ?? 999;
    const ordB = catOrder[catB] ?? 999;
    if (ordA !== ordB) return ordA - ordB;

    // Fallback if both categories are unmapped or equal rank
    if (catA !== catB) {
      const cmpCat = String(catA || '').localeCompare(String(catB || ''), 'id', { sensitivity: 'base', numeric: true });
      if (cmpCat !== 0) return cmpCat;
    }

    // LEVEL 2: Name A-Z within Category (case-insensitive & natural numeric sort)
    const nameA = String(a.name || '').trim();
    const nameB = String(b.name || '').trim();
    const cmpName = nameA.localeCompare(nameB, 'id', { sensitivity: 'base', numeric: true });
    if (cmpName !== 0) return cmpName;

    // Secondary tie-breaker: Inventory Code A-Z
    const codeA = String(a.code || '').trim();
    const codeB = String(b.code || '').trim();
    return codeA.localeCompare(codeB, 'id', { sensitivity: 'base', numeric: true });
  });
}

