const DB = Object.assign({
  announcements:[], events:[], inventory:[], inventory_sources:['Yayasan','Hibah Kementerian','Dana Perusahaan','Kas Organisasi','Hibah Pribadi'], loans:[], damages:[], lost:[], docs:[], crew:[], kontak_eksternal:[], finance:[], contents:[], content_planner:[], keuangan:{ pemasukan:[], pengeluaran:[], kas_kru:[], periode:[] }, notifs:[]
}, BOOT_DB);

function sanitizeDB(db){
  if(!db) return;
  const keys = ['announcements','events','inventory','inventory_sources','loans','damages','lost','docs','crew','kontak_eksternal','finance','contents','content_planner','notes','notifs'];
  keys.forEach(k=>{ if(!Array.isArray(db[k])) db[k] = []; });
  if(!db.keuangan || typeof db.keuangan !== 'object') db.keuangan = { pemasukan:[], pengeluaran:[], kas_kru:[], periode:[] };
  if(!Array.isArray(db.keuangan.pemasukan)) db.keuangan.pemasukan = [];
  if(!Array.isArray(db.keuangan.pengeluaran)) db.keuangan.pengeluaran = [];
  if(!Array.isArray(db.keuangan.kas_kru)) db.keuangan.kas_kru = [];
  if(!Array.isArray(db.keuangan.periode)) db.keuangan.periode = [];
  if(!db.inventory_sources.length){
    db.inventory_sources = ['Yayasan','Hibah Kementerian','Dana Perusahaan','Kas Organisasi','Hibah Pribadi'];
  }
  db.events.forEach(e=>{
    if(!Array.isArray(e.crew)) e.crew = (typeof e.crew === 'string' && e.crew.trim()) ? e.crew.split(/,\s*/).map(s=>s.trim()).filter(Boolean) : [];
    if(!Array.isArray(e.gear)) e.gear = (typeof e.gear === 'string' && e.gear.trim()) ? e.gear.split(/,\s*/).map(s=>s.trim()).filter(Boolean) : [];
    e.crew = e.crew.map(c => {
      if (typeof c === 'object' && c !== null) {
        const cname = cleanMojibake(c.name || c.nama || c.full_name || c.nama_lengkap || '', '');
        if (cname === '[object Object]') return null;
        const cid = cleanMojibake(c.id || c.crew_id || c.kru_id || '', '');
        const cjob = cleanMojibake(c.job || c.tugas || c.jabatan_acara || '', '');
        return {
          id: cid,
          name: cname,
          job: cjob,
          tugas: cjob
        };
      }
      const s = cleanMojibake(c, '');
      if (!s || s === '[object Object]') return null;
      return s;
    }).filter(Boolean);
    e.gear = e.gear.map(g => {
      if (typeof g === 'object' && g !== null) {
        const gid = cleanMojibake(g.id || g.item_id || '', '');
        if (!gid || gid === '[object Object]' || gid === 'Array') return null;
        return {
          id: gid,
          qty: Math.max(1, parseInt(g.qty, 10) || 1),
          name: cleanMojibake(g.name || '', ''),
          code: cleanMojibake(g.code || '', ''),
          photo: cleanMojibake(g.photo || g.foto_url || g.gambar || g.foto || '', ''),
          cat: cleanMojibake(g.cat || '', '')
        };
      }
      const gid = cleanMojibake(g, '');
      if (!gid || gid === '[object Object]' || gid === 'Array') return null;
      return {
        id: gid,
        qty: 1,
        name: '',
        code: '',
        photo: '',
        cat: ''
      };
    }).filter(Boolean);
    e.name = cleanMojibake(e.name, 'Kegiatan PTV');
    e.loc = cleanMojibake(e.loc, 'Pesantren');
    e.time = cleanMojibake(e.time, '08:00 – Selesai');
    e.notes = cleanMojibake(e.notes, '—');
    e.type = cleanMojibake(e.type, 'internal');
    e.dresscode = cleanMojibake(e.dresscode, '');
    if(!e.date) e.date = iso(today);
    if (!Array.isArray(e.rundown)) {
      if (typeof e.rundown === 'string' && e.rundown.trim()) {
        try { e.rundown = JSON.parse(e.rundown); } catch (_) { e.rundown = []; }
      } else {
        e.rundown = [];
      }
    }
  });
  db.crew.forEach(c=>{
    if(!c) return;
    if(!c.name) c.name = 'Kru';
    if(!c.div) c.div = 'Technical';
  });
  db.kontak_eksternal.forEach(k=>{
    if(!k || typeof k !== 'object') return;
    if(!k.nama) k.nama = 'Tanpa Nama';
    if(!k.kategori) k.kategori = 'Lainnya';
    if(!k.status) k.status = 'Aktif';
    k.nomor_telepon = String(k.nomor_telepon || '').trim();
    k.whatsapp = String(k.whatsapp || k.nomor_telepon || '').trim();
    k.jabatan = String(k.jabatan || '').trim();
    k.organisasi = String(k.organisasi || '').trim();
    k.email = String(k.email || '').trim();
    k.alamat = String(k.alamat || '').trim();
    k.catatan = String(k.catatan || '').trim();
    k.foto_url = String(k.foto_url || k.photo || '').trim();
  });
  db.content_planner.forEach(p=>{
    if(!p || typeof p !== 'object') return;
    p.judul_momentum = cleanEscapedText(p.judul_momentum);
    p.subkategori = cleanEscapedText(p.subkategori);
    p.kategori = normalizePlannerCategory(cleanEscapedText(p.kategori) || 'Event Hijriyah');
    p.daftar_konten = normalizeContentList(p.daftar_konten);
    if(p.jenis_konten) {
      const jk = cleanEscapedText(p.jenis_konten);
      p.jenis_konten = Array.isArray(jk) ? jk.join(' · ') : jk;
    }
    if(p.deskripsi) {
      p.deskripsi = cleanEscapedText(p.deskripsi);
    }
  });
  db.inventory.forEach(x=>{
    if(!x) return;
    if(!x.photo && x.foto_url) x.photo = x.foto_url;
    if(!x.photo && x.gambar) x.photo = x.gambar;
    if(!x.photo && x.foto) x.photo = x.foto;
    if(!x.sumber_perolehan && x.sumber) x.sumber_perolehan = x.sumber;
    if(!x.sumber_perolehan) x.sumber_perolehan = 'Yayasan';
    if(!x.sumber) x.sumber = x.sumber_perolehan;
  });
  if(typeof sortInventoryItems === 'function'){
    db.inventory = sortInventoryItems(db.inventory);
  }
  if(Array.isArray(db.docs)){
    db.docs.forEach(d=>{
      if(!d) return;
      if(d.no) d.no = cleanMojibake(d.no);
      if(d.subject) d.subject = cleanMojibake(d.subject);
      if(d.owner) d.owner = cleanMojibake(d.owner);
      if(d.type) d.type = cleanMojibake(d.type);
    });
  }
  if(Array.isArray(db.damages)){
    db.damages.forEach(dmg=>{
      if(!dmg) return;
      if(dmg.title) dmg.title = cleanMojibake(dmg.title);
      if(dmg.desc) dmg.desc = cleanMojibake(dmg.desc);
      if(dmg.by) dmg.by = cleanMojibake(dmg.by);
    });
  }
  db.loans.forEach(l=>{
    if(!l) return;
    if(l.by) l.by = cleanMojibake(l.by);
    if(l.purpose) l.purpose = cleanMojibake(l.purpose);
    if(l.unit_name) l.unit_name = cleanMojibake(l.unit_name);
    if(l.by && /\s+[—–-]\s+/.test(l.by)){
      const parts = l.by.split(/\s+[—–-]\s+/);
      if(parts.length >= 2){
        l.by = parts[0].trim();
        if(!l.purpose || l.purpose === 'Operasional PTV' || l.purpose === 'Operasional'){
          l.purpose = parts.slice(1).join(' — ').trim();
        }
      }
    }
    if(!l.purpose) l.purpose = 'Operasional PTV';
  });
  if(typeof ME !== 'undefined' && ME){
    if(!ME.name) ME.name = 'Kru PTV';
    if(!ME.short) ME.short = (ME.name||'').split(' ')[0] || 'Kru';
    if(!ME.role) ME.role = 'crew';
  }
}
sanitizeDB(DB);

/* ============================================================
   PTV SCOPED REALTIME STATE, SECTION SKELETONS & BADGES
   Separates Initial Load (Skeleton) vs Background Refresh (In-place)
   ============================================================ */
function initScopeState(initialArray) {
  const has = Array.isArray(initialArray) && initialArray.length > 0;
  return {
    isInitialLoading: !has,
    isRefreshing: false,
    hasData: has,
    error: null,
    lastSyncAt: has ? new Date().toISOString() : null
  };
}

window.PTV_SCOPES_STATE = {
  inventory:     initScopeState(typeof BOOT_DB !== 'undefined' ? BOOT_DB.inventory : null),
  loans:         initScopeState(typeof BOOT_DB !== 'undefined' ? BOOT_DB.loans : null),
  events:        initScopeState(typeof BOOT_DB !== 'undefined' ? BOOT_DB.events : null),
  docs:          initScopeState(typeof BOOT_DB !== 'undefined' ? BOOT_DB.docs : null),
  damages:       initScopeState(typeof BOOT_DB !== 'undefined' ? BOOT_DB.damages : null),
  announcements: initScopeState(typeof BOOT_DB !== 'undefined' ? BOOT_DB.announcements : null),
  lost:          initScopeState(typeof BOOT_DB !== 'undefined' ? BOOT_DB.lost : null),
  finance:       initScopeState(typeof BOOT_DB !== 'undefined' ? BOOT_DB.finance : null),
  crew:          initScopeState(typeof BOOT_DB !== 'undefined' ? BOOT_DB.crew : null),
  notes:         initScopeState(typeof BOOT_DB !== 'undefined' ? BOOT_DB.notes : null)
};

function getSectionSyncStatusHTML(scope) {
  if (typeof navigator !== 'undefined' && navigator.onLine === false) {
    return `<span class="ptv-sec-status ptv-sec-offline"><i class="fa-solid fa-wifi-slash"></i> Offline — data terakhir</span>`;
  }
  const rtStatus = window.PTV_REALTIME_STATE ? window.PTV_REALTIME_STATE.status : 'connected';
  if (rtStatus === 'reconnecting' || rtStatus === 'connecting') {
    return `<span class="ptv-sec-status ptv-sec-syncing"><i class="fa-solid fa-arrows-rotate fa-spin"></i> Menyinkronkan...</span>`;
  }
  const sc = window.PTV_SCOPES_STATE && window.PTV_SCOPES_STATE[scope];
  if (sc) {
    if (sc.isRefreshing) {
      return `<span class="ptv-sec-status ptv-sec-syncing"><i class="fa-solid fa-arrows-rotate fa-spin"></i> Memperbarui...</span>`;
    }
    if (sc.error) {
      return `<span class="ptv-sec-status ptv-sec-error"><i class="fa-solid fa-cloud-arrow-down"></i> ${esc(sc.error)}</span>`;
    }
  }
  return '';
}

function updateScopeStatusBadge(scope) {
  const badgeHTML = getSectionSyncStatusHTML(scope);
  const badgeMap = {
    inventory: ['#invScopeStatusBadge', '#berandaLoansBadge'],
    loans: ['#loanScopeStatusBadge', '#berandaLoansBadge'],
    damages: ['#damageScopeStatusBadge'],
    docs: ['#docScopeStatusBadge', '#berandaDocsBadge'],
    events: ['#eventScopeStatusBadge', '#berandaEventsBadge'],
    announcements: ['#berandaAnnounceBadge']
  };
  const selectors = badgeMap[scope] || [];
  selectors.forEach(sel => {
    const el = document.querySelector(sel);
    if (el) el.innerHTML = badgeHTML;
  });
}

function updateAllScopeStatusBadges() {
  if (!window.PTV_SCOPES_STATE) return;
  Object.keys(window.PTV_SCOPES_STATE).forEach(sc => updateScopeStatusBadge(sc));
}

