function canAccessKeuangan() {
  if (typeof ME === 'undefined' || !ME) return false;
  
  // Ambil role & status murni langsung dari data record Supabase ptv_kru
  const role = String(ME.role || state.role || '').toLowerCase().trim();
  const rawStatus = String(ME.status || '').toLowerCase().trim();
  const div = String(ME.div || ME.divisi || '').toLowerCase().trim();
  const pos = String(ME.pos || ME.jabatan || '').toLowerCase().trim();
  const ptvId = String(ME.ptvId || ME.crew_id || '').toUpperCase().trim();
  const username = String(ME.username || '').toLowerCase().trim();
  const name = String(ME.name || '').toLowerCase().trim();

  // FAIL-CLOSED: Jika status kru eksplisit nonaktif di Supabase, tolak total
  const isNonaktif = ['nonaktif', 'non-aktif', 'non aktif', 'pasif', 'alumni', 'inactive'].includes(rawStatus);
  if (isNonaktif) return false;

  // Pengarah, Pembina, Penasihat, Dewan Pendiri/Pengasuh, Member non-operasional: DITOLAK
  if (['pembina', 'pengarah', 'penasihat', 'member', 'non-operasional', 'tamu'].includes(role)) return false;
  if (['pengarah', 'pembina', 'penasihat'].includes(div)) return false;
  if (/pembina|pengarah|penasihat|pendiri|pengasuh/i.test(pos)) return false;

  // 1. Eksekutif Aktif murni dari ptv_kru.role = 'eksekutif' atau administrator
  if (role === 'eksekutif' || role === 'executive' || role === 'admin' || role === 'administrator') {
    return true;
  }

  // 2. Farsya Aktif (PTV-023, username farsya, atau nama Farsya)
  if (ptvId === 'PTV-023' || username === 'farsya' || name.includes('farsya')) {
    return true;
  }

  // 3. Kru Operasional Aktif murni dari ptv_kru.role ('kru' atau 'administrasi')
  if (role === 'kru' || role === 'crew' || role === 'administrasi') {
    return true;
  }

  // FAIL-CLOSED: Role lain di luar data existing ditolak
  return false;
}

function canAccessNilaiInventaris() {
  if (typeof ME === 'undefined' || !ME) return false;
  const role = normRole(ME.role || state.role || '');
  const rawStatus = String(ME.status || '').toLowerCase().trim();
  const div = String(ME.div || ME.divisi || '').toLowerCase().trim();
  const pos = String(ME.pos || ME.jabatan || '').toLowerCase().trim();

  // Nonaktif ditolak
  const isNonaktif = ['nonaktif', 'non-aktif', 'non aktif', 'pasif', 'alumni', 'inactive'].includes(rawStatus);
  if (isNonaktif) return false;

  // Pengarah & Pembina DITOLAK total dari Nilai Inventaris
  if (['pembina', 'pengarah', 'penasihat', 'tamu'].includes(role)) return false;
  if (['pengarah', 'pembina', 'penasihat'].includes(div)) return false;
  if (/pembina|pengarah|penasihat/i.test(pos)) return false;

  // Kru, Administrasi, Eksekutif diperbolehkan
  return ['eksekutif', 'administrasi', 'crew'].includes(role);
}

const can = p => {
  if (p === 'keuangan') return canAccessKeuangan();
  if (p === 'nilaiInventaris' || p === 'nilaiInventarisDetail') return canAccessNilaiInventaris();
  if (p.startsWith('/')) return true;
  const pageRoles = PAGES[p]?.roles || [];
  const curRole = normRole(state.role || ME.role || '');
  const rawRole = String(state.role || ME.role || '').toLowerCase().trim();
  return pageRoles.includes(curRole) || pageRoles.includes(rawRole) || (curRole === 'crew' && pageRoles.includes('kru'));
};

