/* ============================================================
   ACTION REQUIRED SYSTEM (EKSEKUTIF ROLE)
   Shared single source of truth across Sidebar and More Switcher
   ============================================================ */
window.actionRequiredCounts = {
  documents: 0,
  loans: 0,
  damageReports: 0,
  damages: 0,
  perizinan: 0,
};

function getActionRequiredCounts() {
  const curRole = typeof normRole === 'function' ? normRole(state.role || ME.role) : String(state.role || ME.role || '').toLowerCase().trim();
  const isExec = (curRole === 'eksekutif' || curRole === 'executive');

  // Strict permission: Action Required approval badges ONLY for Eksekutif
  if (!isExec) {
    const zeroCounts = {
      documents: 0,
      loans: 0,
      damageReports: 0,
      damages: 0,
      perizinan: 0,
    };
    window.actionRequiredCounts = zeroCounts;
    return zeroCounts;
  }

  // 1. Pengajuan Dokumen (ST, SBB, SI pending executive approval)
  const pendingDocs = (DB.docs || []).filter(d => {
    if (!d) return false;
    const st = String(d.status || '').toLowerCase().trim();
    return st === 'menunggu' || st === 'pending' || st.includes('menunggu');
  }).length;

  // 2. Lapor Kerusakan yang memerlukan Quality Check / tindakan Eksekutif
  const pendingDamages = (DB.damages || []).filter(d => {
    if (!d) return false;
    const st = String(d.status || '').toLowerCase().trim();
    const isDone = st === 'selesai' || !!d.qc_by || !!d.qc_date;
    return !isDone && (st === 'baru' || st === 'sedang dicek');
  }).length;

  // 3. Peminjaman yang membutuhkan approval (jika ada)
  const pendingLoans = (DB.loans || []).filter(l => {
    if (!l) return false;
    const st = String(l.status || '').toLowerCase().trim();
    return st === 'menunggu' || st === 'pending';
  }).length;

  const counts = {
    documents: pendingDocs,
    loans: pendingLoans,
    damageReports: pendingDamages,
    damages: pendingDamages,
    perizinan: pendingDocs,
  };

  window.actionRequiredCounts = counts;
  return counts;
}
window.getActionRequiredCounts = getActionRequiredCounts;

function getActionBadgeHTML(menuKey) {
  const counts = getActionRequiredCounts();
  let cnt = 0;
  if (menuKey === 'perizinan') cnt = counts.documents || counts.perizinan || 0;
  else if (menuKey === 'kerusakan') cnt = counts.damages || counts.damageReports || 0;
  else if (menuKey === 'peminjaman') cnt = counts.loans || 0;
  else if (counts[menuKey] !== undefined) cnt = counts[menuKey];

  if (!cnt || cnt <= 0) return '';
  return `<span class="action-cnt" data-action-badge="${menuKey}">${cnt > 99 ? '99+' : cnt}</span>`;
}
window.getActionBadgeHTML = getActionBadgeHTML;

function updateActionBadges() {
  const counts = getActionRequiredCounts();
  renderSidebar();

  const total = (counts.documents || 0) + (counts.damages || 0) + (counts.loans || 0);
  const moreDot = $('#moreActionDot');
  if (moreDot) {
    moreDot.style.display = total > 0 ? 'block' : 'none';
  }

  // Update More page if open
  if (typeof state !== 'undefined' && state.route && state.route.page === 'more') {
    const view = $('#view');
    if (view && typeof pgMore === 'function') {
      view.innerHTML = pgMore();
    }
  }
}
window.ptvUpdateActionBadges = updateActionBadges;

function renderSidebar(){
  const nav = $('#sideNav'); if(!nav) return;
  const sideRole = $('#sideRole');
  if(sideRole) sideRole.textContent = ME.name.split(' ').slice(0,2).join(' ') + ' · ' + roleLabel(state.role);
  const cur = state.route.page, parent = PAGES[cur]?.parent;
  nav.innerHTML = SIDEBAR.map(grp=>{
    const items = grp.items.filter(([k])=>k.startsWith('/') || can(k));
    if(!items.length) return '';
    return `<div class="side-grp"><p>${grp.g}</p>${items.map(([k,label,i])=>{
      if(k.startsWith('/')){
        return `<a href="${k}" target="_blank" rel="noopener noreferrer" class="snav" style="text-decoration:none">${ic[i]}<span>${label}</span><i class="fa-solid fa-arrow-up-right-from-square" style="font-size:10px;margin-left:auto;opacity:0.6"></i></a>`;
      }
      const on = (k===cur||k===parent)?' on':'';
      const cnt = getActionBadgeHTML(k);
      return `<button class="snav${on}" data-go="${k}">${ic[i]}<span>${label}</span>${cnt}</button>`;
    }).join('')}</div>`;
  }).join('');
}

function syncChrome(){
  const p = PAGES[state.route.page]||PAGES.beranda;
  const pt = $('#pageTitle'); if (pt) pt.textContent = p.title;
  const parent = p.parent?PAGES[p.parent]:null;
  const cr = $('#crumb');
  if (cr) {
    cr.innerHTML = parent
      ? `<span>${esc(parent.crumb)}</span>${ic.chev}<b>${esc(p.crumb)}</b>`
      : `<b>${esc(p.crumb)}</b>`;
  }
  const tab = TAB_OF[state.route.page]|| (state.route.page==='more'?'more':null);
  document.querySelectorAll('.bitem').forEach(b=>b.classList.toggle('on', b.dataset.tab===tab));
  const u = unreadCount();
  const d = $('#notifDot'); d.textContent = u>9?'9+':u; d.style.display = u?'grid':'none';
  const counts = getActionRequiredCounts();
  const totalAction = (counts.documents || 0) + (counts.damages || 0) + (counts.loans || 0);
  const moreDot = $('#moreActionDot');
  if (moreDot) moreDot.style.display = totalAction > 0 ? 'block' : 'none';
  renderSidebar();
  document.title = (state.route.page==='beranda' ? 'Dashboard — Progresif TV' : p.title + ' · Progresif TV');
  if (state.route.page === 'pengaturan' && typeof syncPushSettingsUI === 'function') setTimeout(syncPushSettingsUI, 50);
}

/* ---------------- Global Modal & Sheet State Manager ---------------- */
window._modalStack = window._modalStack || [];

function registerModalOpen(modalId, info) {
  if (!modalId) return;
  const id = typeof modalId === 'string' ? modalId : (info?.id || 'modal_' + Date.now());
  const entry = typeof info === 'object' && info !== null ? { id, ...info } : { id };
  const idx = window._modalStack.findIndex(m => (typeof m === 'object' ? m.id : m) === id);
  if (idx !== -1) {
    window._modalStack.splice(idx, 1);
  }
  window._modalStack.push(entry);
}

function registerModalClose(modalId) {
  if (!modalId) {
    window._modalStack.pop();
    return;
  }
  const idStr = String(modalId);
  if (idStr === 'sheet') {
    // Cari dan hapus entri sheet terakhir dari stack (mendukung nested modal/sheet jika ada)
    let foundIdx = -1;
    for (let i = window._modalStack.length - 1; i >= 0; i--) {
      const item = window._modalStack[i];
      const mId = typeof item === 'object' ? item.id : String(item);
      if (mId.startsWith('sheet_') || mId === 'sheet') {
        foundIdx = i;
        break;
      }
    }
    if (foundIdx !== -1) {
      window._modalStack.splice(foundIdx, 1);
    } else {
      window._modalStack = window._modalStack.filter(m => {
        const mId = typeof m === 'object' ? m.id : String(m);
        return !mId.startsWith('sheet_') && mId !== 'sheet';
      });
    }
  } else {
    window._modalStack = window._modalStack.filter(m => {
      const mId = typeof m === 'object' ? m.id : String(m);
      return mId !== idStr;
    });
  }
}

function isAnyModalOpen(options) {
  const opts = options || {};

  // 1. Periksa Modal Stack
  if (Array.isArray(window._modalStack) && window._modalStack.length > 0) {
    const activeNonSearchModals = window._modalStack.filter(item => {
      const type = typeof item === 'object' ? item.type : '';
      const id = typeof item === 'object' ? item.id : String(item);
      if (type === 'search' || id === 'sheet_search' || id === 'sheet_Pencarian' || id === 'mobileSearch') {
        return false;
      }
      return true;
    });

    if (opts.ignoreSearchSelf) {
      if (activeNonSearchModals.length > 0) return true;
    } else {
      if (window._modalStack.length > 0) return true;
    }
  }

  // 2. Direct DOM Check: Sheet Utama (#sheet) & Scrim (#scrim)
  const sh = document.getElementById('sheet');
  const sc = document.getElementById('scrim');
  const isSheetOn = !!(sh && (sh.classList.contains('on') || sh.classList.contains('active')));
  const isScrimOn = !!(sc && (sc.classList.contains('on') || sc.classList.contains('active')));

  if (isSheetOn || isScrimOn) {
    const isSearchSheet = !!(
      document.getElementById('sheetTitle')?.textContent?.trim() === 'Pencarian' ||
      (sh && sh.querySelector('#gq') !== null)
    );
    if (opts.ignoreSearchSelf) {
      if (!isSearchSheet) return true;
    } else {
      return true;
    }
  }

  // 3. Direct DOM Check: Mobile Search Overlay (#mobileSearchOverlay)
  const mso = document.getElementById('mobileSearchOverlay');
  if (mso && (mso.classList.contains('on') || mso.classList.contains('active') || mso.style.display === 'block')) {
    if (!opts.ignoreSearchSelf) return true;
  }

  // 4. Direct DOM Check: Loan Mobile Drawer Overlay (#loanMobileDrawerOverlay)
  const loanDrawer = document.getElementById('loanMobileDrawerOverlay');
  if (loanDrawer && (loanDrawer.classList.contains('open') || loanDrawer.classList.contains('active') || loanDrawer.style.display === 'block')) {
    return true;
  }

  // 5. Direct DOM Check: Help Modal (#helpModal / #helpModalScrim)
  const helpModal = document.getElementById('helpModal');
  const helpScrim = document.getElementById('helpModalScrim');
  if ((helpModal && (helpModal.classList.contains('active') || helpModal.classList.contains('on'))) ||
      (helpScrim && (helpScrim.classList.contains('active') || helpScrim.classList.contains('on')))) {
    return true;
  }

  // 6. Direct DOM Check: Body/HTML modal-open class
  const hasModalClass = document.body.classList.contains('modal-open') ||
                        document.documentElement.classList.contains('modal-open');
  if (hasModalClass) {
    const isSearchSheet = !!(sh && (sh.classList.contains('on') || sh.classList.contains('active')) && (
      document.getElementById('sheetTitle')?.textContent?.trim() === 'Pencarian' ||
      sh.querySelector('#gq') !== null
    ));
    const isSearchMso = !!(mso && (mso.classList.contains('on') || mso.classList.contains('active') || mso.style.display === 'block'));
    if (opts.ignoreSearchSelf) {
      if (!isSearchSheet && !isSearchMso) return true;
    } else {
      return true;
    }
  }

  // 7. Generic DOM Check: Dialog, modal, drawer, popup, swal2
  const genericModals = document.querySelectorAll(`
    [role="dialog"].on,
    [role="dialog"].active,
    [role="dialog"].open,
    [role="dialog"].show,
    .lk-modal.active,
    .modal.show,
    .modal.active,
    .modal.open,
    .modal.on,
    .drawer.open,
    .drawer.active,
    .drawer.on,
    .popup.open,
    .popup.active,
    .popup.on,
    .swal2-container,
    .modal-backdrop
  `);

  for (let i = 0; i < genericModals.length; i++) {
    const el = genericModals[i];
    if (el.id === 'mobileSearchOverlay') {
      if (!opts.ignoreSearchSelf) return true;
      continue;
    }
    if (el.id === 'sheet') {
      const isSearchSheet = !!(
        document.getElementById('sheetTitle')?.textContent?.trim() === 'Pencarian' ||
        el.querySelector('#gq') !== null
      );
      if (!opts.ignoreSearchSelf || !isSearchSheet) return true;
      continue;
    }
    return true;
  }

  // 8. Active Focus Check: Jika cursor / fokus berada di dalam modal / editor / container modal
  const activeEl = document.activeElement;
  if (activeEl && activeEl !== document.body && activeEl !== document.documentElement) {
    const parentModal = activeEl.closest('#sheet, #mobileSearchOverlay, #helpModal, #loanMobileDrawerOverlay, [role="dialog"], .modal, .drawer, .popup, .note-editor-wrapper');
    if (parentModal) {
      if (parentModal.id === 'mobileSearchOverlay') {
        if (!opts.ignoreSearchSelf) return true;
      } else if (parentModal.id === 'sheet') {
        const isSearchSheet = !!(
          document.getElementById('sheetTitle')?.textContent?.trim() === 'Pencarian' ||
          parentModal.querySelector('#gq') !== null
        );
        if (!opts.ignoreSearchSelf || !isSearchSheet) return true;
      } else {
        return true;
      }
    }
  }

  return false;
}
window.isAnyModalOpen = isAnyModalOpen;
window.registerModalOpen = registerModalOpen;
window.registerModalClose = registerModalClose;

/* ---------------- Overlays ---------------- */
let sheetCloser = null;
let savedScrollY = 0;
let isScrollLocked = false;

function lockBodyScroll(){
  if(isScrollLocked) return;
  savedScrollY = window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop || 0;
  isScrollLocked = true;
  document.documentElement.classList.add('modal-open');
  document.body.classList.add('modal-open');
}

function unlockBodyScroll(){
  if(!isScrollLocked) return;
  isScrollLocked = false;
  document.documentElement.classList.remove('modal-open');
  document.body.classList.remove('modal-open');
  document.body.style.position = '';
  document.body.style.top = '';
  document.body.style.left = '';
  document.body.style.right = '';
  document.body.style.width = '';
  document.body.style.overflow = '';
}

function openSheet(title, body, opts){
  opts = opts||{};
  if (typeof registerModalOpen === 'function') {
    registerModalOpen('sheet_' + (title || 'modal'), {
      type: title === 'Pencarian' ? 'search' : 'sheet',
      title: title || ''
    });
  }
  $('#sheetTitle').textContent = title;
  $('#sheetBody').innerHTML = body;
  const foot = $('#sheetFoot');
  if(opts.foot){foot.classList.remove('hide');foot.innerHTML=opts.foot}else{foot.classList.add('hide');foot.innerHTML=''}
  $('#sheet').classList.toggle('wide', !!opts.wide);
  if(opts.className){
    opts.className.split(' ').forEach(cls => { if(cls) $('#sheet').classList.add(cls); });
  }
  $('#scrim').classList.add('on'); $('#sheet').classList.add('on');
  lockBodyScroll();
  sheetCloser = opts.onClose||null;
  if(opts.then) requestAnimationFrame(()=>opts.then($('#sheetBody')));
}
function closeSheet(){
  if (typeof window.noteAutoSaveManager !== 'undefined') {
    window.noteAutoSaveManager.clearTimer();
    window.noteAutoSaveManager.isDirty = false;
    window.noteAutoSaveManager.activeNoteId = null;
  }
  if (typeof registerModalClose === 'function') {
    registerModalClose('sheet');
  }
  window._currentOpenDocId = null;
  window._currentOpenDamageId = null;
  if(typeof stopActiveScanner === 'function') stopActiveScanner();
  const sc = $('#scrim'), sh = $('#sheet');
  if(sc) sc.classList.remove('on');
  if(sh) {
    sh.classList.remove('on');
    setTimeout(()=>{
      if(!sh.classList.contains('on')){
        sh.className = 'sheet';
        const b = $('#sheetBody'), t = $('#sheetTitle'), f = $('#sheetFoot');
        if(b) b.innerHTML = '';
        if(t) t.textContent = '';
        if(f) { f.innerHTML = ''; f.classList.add('hide'); }
      }
    }, 280);
  }
  unlockBodyScroll();
  if(sheetCloser){const f=sheetCloser;sheetCloser=null;f()}
}
window.closeSheet = closeSheet;
function toast(titleOrObj, descOrIcon, iconKey){
  let title = '', desc = '', icon = 'check';

  if(typeof titleOrObj === 'object' && titleOrObj !== null){
    title = titleOrObj.title || titleOrObj.msg || 'Notifikasi';
    desc = titleOrObj.desc || titleOrObj.sub || '';
    icon = titleOrObj.icon || 'check';
  } else if(typeof descOrIcon === 'string' && typeof iconKey === 'string'){
    title = String(titleOrObj || '');
    desc = String(descOrIcon || '');
    icon = iconKey;
  } else if(typeof descOrIcon === 'string' && (FA[descOrIcon] || ['check','scan','moon','info','alert','download','refresh','wrench','lost','doc','box','megaphone','event','shield'].includes(descOrIcon))){
    title = String(titleOrObj || '');
    icon = descOrIcon;
    desc = '';
  } else if(typeof descOrIcon === 'string' && descOrIcon.length > 0){
    title = String(titleOrObj || '');
    desc = descOrIcon;
    icon = 'check';
  } else {
    title = String(titleOrObj || '');
    icon = descOrIcon || 'check';
    desc = '';
  }

  const container = document.getElementById('toasts');
  if(!container) return;

  // 1. Cek duplikasi pesan yang persis sama (misal user klik tombol ganti peran berkali-kali)
  const existing = Array.from(container.querySelectorAll('.toast:not(.out)')).find(el => {
    return el.querySelector('.toast-title')?.textContent === title &&
           (el.querySelector('.toast-desc')?.textContent || '') === desc;
  });

  if(existing){
    existing.classList.remove('pulse');
    void existing.offsetWidth; // trigger reflow for smooth animation restart
    existing.classList.add('pulse');
    if(existing._timer) clearTimeout(existing._timer);
    existing._timer = setTimeout(() => {
      existing.classList.add('out');
      setTimeout(() => existing.remove(), 280);
    }, 3200);
    haptic(6);
    return;
  }

  // 2. Batasi maksimal 3 notifikasi bersamaan secara mulus (animasikan keluar yang paling lama)
  const activeToasts = Array.from(container.querySelectorAll('.toast:not(.out)'));
  if(activeToasts.length >= 3){
    const oldest = activeToasts[0];
    if(oldest){
      oldest.classList.add('out');
      setTimeout(() => oldest.remove(), 280);
    }
  }

  const iconClass = FA[icon] || FA.check;
  const icTone = ['scan','refresh','cal','event'].includes(icon) ? 'info' :
                 ['wrench','alert','box'].includes(icon) ? 'warn' :
                 ['lost','x'].includes(icon) ? 'dang' :
                 ['doc','megaphone','send','note'].includes(icon) ? 'purple' :
                 ['shield'].includes(icon) ? 'purple' :
                 ['moon'].includes(icon) ? 'moon' :
                 ['download'].includes(icon) ? 'download' : 'ok';

  const t = el(`
    <div class="toast">
      <div class="toast-ic ${icTone}"><i class="${iconClass}"></i></div>
      <div class="toast-body">
        <div class="toast-title">${esc(title)}</div>
        ${desc ? `<div class="toast-desc">${esc(desc)}</div>` : ''}
      </div>
    </div>
  `);

  // Dismiss saat diklik/diketuk
  t.addEventListener('click', () => {
    if(t._timer) clearTimeout(t._timer);
    t.classList.add('out');
    setTimeout(() => t.remove(), 280);
  });

  // Swipe dismiss gesture di layar sentuh
  let touchStartY = 0, touchStartX = 0;
  t.addEventListener('touchstart', (e) => {
    if(e.touches.length === 1){
      touchStartY = e.touches[0].clientY;
      touchStartX = e.touches[0].clientX;
    }
  }, { passive: true });

  t.addEventListener('touchend', (e) => {
    if(e.changedTouches.length === 1){
      const dy = e.changedTouches[0].clientY - touchStartY;
      const dx = Math.abs(e.changedTouches[0].clientX - touchStartX);
      if(dy < -20 || dx > 60){ // Swipe up or swipe sideways
        if(t._timer) clearTimeout(t._timer);
        t.classList.add('out');
        setTimeout(() => t.remove(), 280);
      }
    }
  }, { passive: true });

  container.appendChild(t);
  haptic(10);

  t._timer = setTimeout(() => {
    if(t.parentElement){
      t.classList.add('out');
      setTimeout(() => t.remove(), 280);
    }
  }, 3400);
}
function confirmToast(msg){toast(msg)}

