/* ---------------- Global search & Universal Search Gate ---------------- */
function openUniversalSearch(opts){
  // 1. GLOBAL MODAL LOCK GATE: Jika ADA MODAL / POPUP / DRAWER AKTIF (selain search itu sendiri),
  // Universal Search TERKUNCI TOTAL & TIDAK BOLEH DIBUKA.
  if (typeof isAnyModalOpen === 'function' && isAnyModalOpen({ ignoreSearchSelf: true })) {
    return;
  }

  if (window.innerWidth < 992) {
    openMobileSearchOverlay();
    return;
  }
  openSheet('Pencarian', `
    <div class="searchbar">${ic.search}<input id="gq" placeholder="Acara, alat, kru, surat, catatan…" autocomplete="off"></div>
    <div id="gres"><p class="hint mt12">Ketik minimal 2 huruf. Hasil dikelompokkan per kategori.</p></div>`,
    {then:(b)=>{const i=$('#gq',b); setTimeout(()=>i.focus(),120);
      i.addEventListener('input',()=>runSearch(i.value, '#gres'));}});
}

function openSearch(opts){
  return openUniversalSearch(opts);
}
window.openSearch = openSearch;
window.openUniversalSearch = openUniversalSearch;

function openMobileSearchOverlay(){
  let el = document.getElementById('mobileSearchOverlay');
  if(!el){
    el = document.createElement('div');
    el.id = 'mobileSearchOverlay';
    el.className = 'mobile-search-overlay';
    el.setAttribute('role', 'dialog');
    el.setAttribute('aria-modal', 'true');
    el.innerHTML = `
      <div class="mso-container">
        <div class="mso-header">
          <div class="mso-search-box">
            ${ic.search}
            <input type="search" id="msoInput" class="mso-input" placeholder="Cari kru, alat, acara, catatan, surat..." autocomplete="off" autocapitalize="none">
            <button type="button" id="msoClear" class="mso-clear-btn" aria-label="Hapus">&times;</button>
          </div>
          <button type="button" id="msoClose" class="mso-close-btn">Tutup</button>
        </div>
        <div class="mso-body" id="msoResults">
          <p class="hint mt12" style="text-align:center;">Ketik minimal 2 huruf untuk mulai mencari.<br>Hasil pencarian live dikelompokkan per kategori.</p>
        </div>
      </div>
    `;
    document.body.appendChild(el);

    const input = document.getElementById('msoInput');
    const clearBtn = document.getElementById('msoClear');
    const closeBtn = document.getElementById('msoClose');
    const resBox = document.getElementById('msoResults');

    input.addEventListener('input', () => {
      const q = input.value.trim();
      clearBtn.style.display = q ? 'inline-flex' : 'none';
      runSearch(input.value, '#msoResults', true);
    });

    clearBtn.addEventListener('click', () => {
      input.value = '';
      clearBtn.style.display = 'none';
      runSearch('', '#msoResults', true);
      input.focus();
    });

    closeBtn.addEventListener('click', () => {
      closeMobileSearchOverlay();
    });

    el.addEventListener('click', (e) => {
      if(e.target === el){
        closeMobileSearchOverlay();
      }
    });

    resBox.addEventListener('click', (e) => {
      const item = e.target.closest('[data-search-go]');
      if(item){
        closeMobileSearchOverlay();
        const go = item.dataset.searchGo;
        if(go.startsWith('catatanDetail:') || go.startsWith('openNoteDetail:')){
          openNoteDetail(go.split(':')[1]);
        } else if(go.startsWith('alatDetail:')){
          navigate('alatDetail', go.split(':')[1]);
        } else if(go.startsWith('acaraDetail:')){
          navigate('acaraDetail', go.split(':')[1]);
        } else {
          navigate(go);
        }
      }
    });
  }

  if (typeof registerModalOpen === 'function') {
    registerModalOpen('mobileSearch', { type: 'search', title: 'Pencarian' });
  }
  el.classList.add('on');
  document.body.style.overflow = 'hidden';
  const input = document.getElementById('msoInput');
  if(input){
    input.value = '';
    const clearBtn = document.getElementById('msoClear');
    if(clearBtn) clearBtn.style.display = 'none';
    const resBox = document.getElementById('msoResults');
    if(resBox) resBox.innerHTML = '<p class="hint mt12" style="text-align:center;">Ketik minimal 2 huruf untuk mulai mencari.<br>Hasil pencarian live dikelompokkan per kategori.</p>';
    setTimeout(() => {
      input.focus();
    }, 100);
  }
}

function closeMobileSearchOverlay(){
  if (typeof registerModalClose === 'function') {
    registerModalClose('mobileSearch');
  }
  const el = document.getElementById('mobileSearchOverlay');
  if(el){
    el.classList.remove('on');
  }
  document.body.style.overflow = '';
}
/* ---------------- Search Clear Helper ---------------- */
function initSearchClearButtons(rootEl){
  const container = rootEl || document;
  container.querySelectorAll(".searchbar").forEach(bar => {
    const input = bar.querySelector("input");
    if(!input) return;
    let clearBtn = bar.querySelector(".search-clear-btn");
    if(!clearBtn){
      clearBtn = document.createElement("button");
      clearBtn.type = "button";
      clearBtn.className = "search-clear-btn";
      clearBtn.innerHTML = "&times;";
      clearBtn.setAttribute("aria-label", "Hapus pencarian");
      bar.appendChild(clearBtn);
    }
    
    const updateClearBtn = () => {
      const hasVal = Boolean(input.value && input.value.trim().length > 0);
      bar.classList.toggle("has-value", hasVal);
      clearBtn.style.display = hasVal ? "grid" : "none";
    };

    updateClearBtn();
    
    if(!input._clearBound){
      input._clearBound = true;
      input.addEventListener("input", updateClearBtn);
      input.addEventListener("focus", updateClearBtn);
    }
    
    if(!clearBtn._clickBound){
      clearBtn._clickBound = true;
      clearBtn.addEventListener("click", (e) => {
        e.preventDefault();
        e.stopPropagation();
        input.value = "";
        updateClearBtn();
        input.dispatchEvent(new Event("input", { bubbles: true }));
        input.focus();
        haptic(6);
      });
    }
  });
}

/* ---------------- Universal Photo Upload Widget (Kamera + Galeri) ---------------- */
function renderPhotoUploadWidget(inputId, previewUrl, labelText, customOpts){
  const opts = Object.assign({
    camLabel: 'Kamera',
    galLabel: 'Galeri / File',
    camIcon: 'fa-solid fa-camera',
    galIcon: 'fa-regular fa-images',
    capture: 'environment',
    accept: 'image/jpeg,image/png,image/webp,image/gif,image/heic,image/heif',
    pageContext: ''
  }, customOpts || {});

  const ctxPrefix = opts.pageContext ? `${opts.pageContext}_` : '';
  const camId = `cam_${ctxPrefix}${inputId}`;
  const galId = `gal_${ctxPrefix}${inputId}`;
  const captureAttr = opts.capture ? `capture="${opts.capture}"` : 'capture="environment"';
  const hiddenStyle = 'position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);border:0;opacity:0;pointer-events:none;';

  return `
    <div class="photo-upload-widget" id="${inputId}_widget" data-context="${esc(opts.pageContext || 'default')}" style="margin-top:4px;position:relative">
      <input type="hidden" id="${inputId}" value="${esc(previewUrl || "")}">
      <!-- Input Kamera Langsung (Membuka Kamera Sesuai Konteks) -->
      <input type="file" id="${camId}" data-role="cam-input" accept="image/*" ${captureAttr} style="${hiddenStyle}">
      <!-- Input Galeri / File Picker (Membuka File Picker / Galeri Perangkat tanpa Memaksa Kamera) -->
      <input type="file" id="${galId}" data-role="gal-input" accept="${opts.accept}" style="${hiddenStyle}">

      <!-- Box Preview jika foto sudah ada / dipilih -->
      <div id="${inputId}_preview" style="display:${previewUrl ? "flex" : "none"};align-items:center;gap:12px;padding:10px 12px;background:var(--bg-2);border:1.5px solid var(--line);border-radius:var(--r-m);margin-bottom:8px">
        <div style="width:54px;height:54px;border-radius:10px;overflow:hidden;background:#f1f5f9;flex-shrink:0;border:1px solid var(--line-2);display:grid;place-items:center">
          <img id="${inputId}_img" src="${esc(previewUrl || "")}" style="width:100%;height:100%;object-fit:cover" alt="Preview Foto">
        </div>
        <div style="flex:1;min-width:0">
          <div class="t-xs trunc" id="${inputId}_name" style="font-weight:700;color:var(--ink)">Foto terpilih</div>
          <div class="t-xs" style="color:var(--ok);font-weight:600">✓ Foto tersimpan</div>
        </div>
        <div style="display:flex;align-items:center;gap:6px;flex-shrink:0">
          <button type="button" class="btn sm" data-upload-trigger="${camId}" data-source="camera" title="Ambil Ulang via ${opts.camLabel}" style="padding:5px 8px;font-size:11.5px;display:inline-flex;align-items:center;gap:4px">
            <i class="${opts.camIcon}"></i><span class="only-desktop">${opts.camLabel}</span>
          </button>
          <button type="button" class="btn sm" data-upload-trigger="${galId}" data-source="gallery" title="Pilih dari ${opts.galLabel}" style="padding:5px 8px;font-size:11.5px;display:inline-flex;align-items:center;gap:4px">
            <i class="${opts.galIcon}"></i><span class="only-desktop">${opts.galLabel}</span>
          </button>
          <button type="button" class="btn sm dang" data-upload-remove="${inputId}" title="Hapus Foto" style="padding:5px 8px;font-size:11.5px">
            <i class="fa-solid fa-trash"></i>
          </button>
        </div>
      </div>

      <!-- Box Pilihan Dua Tombol: [ 📷 Kamera ] [ 🖼 Galeri / File ] jika belum ada foto -->
      <div id="${inputId}_btn_wrap" style="display:${previewUrl ? "none" : "block"}">
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">
          <button type="button" class="upload" data-upload-trigger="${camId}" data-source="camera" style="display:flex;align-items:center;justify-content:center;gap:8px;padding:12px;border:1.5px dashed var(--b-300, #93c5fd);border-radius:var(--r-m);background:var(--surface);color:var(--b-700, #1d4ed8);font-size:13px;font-weight:650;cursor:pointer;transition:all .15s">
            <i class="${opts.camIcon}" style="font-size:15px;color:var(--b-600)"></i>
            <span>${opts.camLabel}</span>
          </button>
          <button type="button" class="upload" data-upload-trigger="${galId}" data-source="gallery" style="display:flex;align-items:center;justify-content:center;gap:8px;padding:12px;border:1.5px dashed var(--line);border-radius:var(--r-m);background:var(--surface);color:var(--ink);font-size:13px;font-weight:650;cursor:pointer;transition:all .15s">
            <i class="${opts.galIcon}" style="font-size:15px;color:var(--b-600)"></i>
            <span>${opts.galLabel}</span>
          </button>
        </div>
        <div class="t-xs muted" style="text-align:center;margin-top:6px;font-size:11px">
          ${labelText || "Pilih foto dari kamera langsung atau galeri perangkat"}
        </div>
      </div>

      <!-- Indikator Loading Saat Upload Berlangsung -->
      <div id="${inputId}_loading" style="display:none;padding:10px;text-align:center;font-size:12px;color:var(--b-600);background:var(--b-050);border-radius:var(--r-m);border:1px solid var(--b-200);margin-top:6px">
        <i class="fa-solid fa-spinner fa-spin" style="margin-right:6px"></i>Mengunggah foto ke server...
      </div>
    </div>
  `;
}

function bindPhotoUploadWidget(rootEl, inputId){
  const widget = rootEl ? rootEl.querySelector(`#${inputId}_widget`) : document.querySelector(`#${inputId}_widget`);
  if (!widget) return;
  if (widget.dataset.bound === 'true') return;
  widget.dataset.bound = 'true';

  const camIn = widget.querySelector('[data-role="cam-input"]') || widget.querySelector(`[id^="cam_"]`);
  const galIn = widget.querySelector('[data-role="gal-input"]') || widget.querySelector(`[id^="gal_"]`);
  const hiddenIn = widget.querySelector(`#${inputId}`);
  const previewBox = widget.querySelector(`#${inputId}_preview`);
  const imgEl = widget.querySelector(`#${inputId}_img`);
  const btnWrap = widget.querySelector(`#${inputId}_btn_wrap`);
  const loadingBox = widget.querySelector(`#${inputId}_loading`);
  const nameEl = widget.querySelector(`#${inputId}_name`);

  widget.addEventListener("click", (e) => {
    const trigger = e.target.closest(`[data-upload-trigger]`);
    if (trigger) {
      e.preventDefault();
      e.stopPropagation();
      const source = trigger.getAttribute('data-source');
      const targetInputId = trigger.getAttribute('data-upload-trigger');
      let inputEl = null;
      if (targetInputId) {
        inputEl = widget.querySelector(`#${targetInputId}`);
      }
      if (!inputEl) {
        inputEl = (source === 'camera') ? camIn : galIn;
      }
      if (inputEl) {
        inputEl.value = '';
        inputEl.click();
      }
      return;
    }
    const removeBtn = e.target.closest(`[data-upload-remove="${inputId}"]`);
    if (removeBtn) {
      e.preventDefault();
      e.stopPropagation();
      if (hiddenIn) hiddenIn.value = "";
      if (camIn) camIn.value = "";
      if (galIn) galIn.value = "";
      if (previewBox) previewBox.style.display = "none";
      if (btnWrap) btnWrap.style.display = "block";
      if (imgEl) imgEl.src = "";
      haptic(6);
    }
  });

  const handleSelectedFile = (file, srcType) => {
    if (!file) return;

    // Validasi ekstensi & format gambar (JPG, PNG, WEBP, HEIC, GIF)
    const validExtensions = /\.(jpe?g|png|webp|gif|heic|heif)$/i;
    const isImageMime = file.type ? file.type.startsWith('image/') : validExtensions.test(file.name);
    if (!isImageMime && !validExtensions.test(file.name)) {
      toast('Format file tidak didukung. Harap pilih foto (JPG, PNG, WEBP, atau HEIC).', 'alert');
      return;
    }

    // Validasi batas ukuran file (Maksimal 15MB)
    if (file.size > 15 * 1024 * 1024) {
      toast('Ukuran file foto terlalu besar (Maksimal 15MB).', 'alert');
      return;
    }

    if (nameEl) nameEl.textContent = file.name || (srcType === 'camera' ? 'Foto kamera' : 'Foto terpilih');

    const reader = new FileReader();
    reader.onload = (re) => {
      if (imgEl) imgEl.src = re.target.result;
      if (previewBox) previewBox.style.display = "flex";
      if (btnWrap) btnWrap.style.display = "none";
    };
    reader.readAsDataURL(file);

    if (loadingBox) loadingBox.style.display = "block";
    const fd = new FormData();
    fd.append("action", "ptv_dashboard_action_upload_image");
    fd.append("image", file);

    fetch(AJAX_URL, { method: "POST", body: fd })
      .then(r => r.json())
      .then(res => {
        if (res.success && res.data?.url) {
          if (hiddenIn) hiddenIn.value = res.data.url;
          if (imgEl) imgEl.src = res.data.url;
          toast("Foto berhasil diunggah ke server.", "check");
        } else {
          toast(res.data?.message || res.data || "Gagal mengunggah foto ke server.", "alert");
        }
      })
      .catch(() => {
        toast("Terjadi kendala jaringan saat mengunggah foto.", "alert");
      })
      .finally(() => {
        if (loadingBox) loadingBox.style.display = "none";
      });
  };

  if (camIn) {
    camIn.addEventListener("change", () => {
      const file = camIn.files && camIn.files[0];
      handleSelectedFile(file, 'camera');
    });
  }

  if (galIn) {
    galIn.addEventListener("change", () => {
      const file = galIn.files && galIn.files[0];
      handleSelectedFile(file, 'gallery');
    });
  }
}

function runSearch(q, targetSelector = '#gres', isMobile = false){
  const box = $(targetSelector);
  if(!box) return;
  q = q.trim().toLowerCase();
  if(q.length < 2){
    box.innerHTML = '<p class="hint mt12" style="text-align:center;">Ketik minimal 2 huruf. Hasil dikelompokkan per kategori.</p>';
    return;
  }
  const hit = (s) => String(s || '').toLowerCase().includes(q);
  const groups = [
    ['Kru', (DB.crew||[]).filter(c=>hit(c.name)||hit(c.div)||hit(c.ptvId)).map(c=>({t:c.name,s:`${c.div||'Kru'} · ${c.ptvId||''}`,go:'kru',i:'users'}))],
    ['Inventaris Alat', (DB.inventory||[]).filter(x=>hit(x.name)||hit(x.brand)||hit(x.sn)||hit(x.cat)).map(x=>({t:x.name,s:`${x.cat} · ${x.status}`,go:`alatDetail:${x.id}`,i:'box',item:x}))],
    ['Acara', (DB.events||[]).filter(e=>hit(e.name)||hit(e.loc)).map(e=>({t:e.name,s:`${fmtDate(e.date)} · ${e.loc}`,go:`acaraDetail:${e.id}`,i:'event'}))],
    ['Catatan & Notulensi', (DB.notes||[]).filter(n=>hit(n.judul||n.title)||hit(n.isi||n.body)||(Array.isArray(n.tags)?n.tags.some(hit):hit(n.tags||n.tag))).map(n=>({t:n.judul||n.title,s:`${(n.tipe==='meeting_minutes'||(Array.isArray(n.tags)&&n.tags.includes('notulensi')))?'Notulensi Rapat':'Catatan Bersama'} · ${(Array.isArray(n.tags)?n.tags.join(', '):n.tags)||'Umum'}`,go:`openNoteDetail:${n.id}`,i:'note'}))],
    ['Surat & Dokumen', (DB.docs||[]).filter(d=>hit(d.subject)||hit(d.no)||hit(d.type)).map(d=>({t:d.subject,s:`${d.no} · ${d.status}`,go:'dokumen',i:'doc'}))],
    ['Pengumuman', (DB.announcements||[]).filter(a=>hit(a.title)||hit(a.body)).map(a=>({t:a.title,s:a.by,go:'broadcast',i:'megaphone'}))],
    ['Laporan Kerusakan', (DB.damages||[]).filter(d=>hit(d.title)||hit(itemById(d.item)?.name)).map(d=>({t:`${itemById(d.item)?.name || 'Alat'} — ${d.title}`,s:d.status,go:'kerusakan',i:'wrench'}))],
    ['Lost & Found', (DB.lost||[]).filter(l=>hit(l.name)||hit(l.loc)).map(l=>({t:l.name,s:`${l.loc} · ${l.status}`,go:'lostfound',i:'lost'}))]
  ].filter(g => g[1].length);

  if(!groups.length){
    box.innerHTML = `<div class="empty" style="text-align:center;padding:32px 0;">${ic.search}<p>Tidak ada hasil untuk "${esc(q)}".<br>Coba kata kunci lain.</p></div>`;
    return;
  }

  box.innerHTML = groups.map(([g, rows]) => `
    <p class="sgroup-t" style="margin:14px 0 6px;font-size:11.5px;font-weight:750;letter-spacing:.05em;color:var(--muted);">${g.toUpperCase()}</p>
    <div class="list">${rows.slice(0, 5).map(r => `
      <button class="li" data-search-go="${r.go}" style="text-align:left;cursor:pointer;">
        ${r.item ? itemThumbHTML(r.item) : `<span class="li-ic">${ic[r.i]||ic.search}</span>`}
        <span class="li-body"><span class="li-t trunc" style="font-weight:650">${esc(r.t)}</span><span class="li-s trunc">${esc(r.s)}</span></span>
        <span class="chev">${ic.chev}</span>
      </button>`).join('')}</div>
  `).join('');
}

/* ---------------- Notifications ---------------- */
function renderNotifItemsHTML(rows) {
  if (!rows || !rows.length) {
    return '<div class="empty" style="padding:36px 16px;text-align:center;"><i class="fa-regular fa-bell-slash" style="font-size:32px;opacity:0.35;margin-bottom:10px;display:block;"></i><p style="margin:0;font-size:13.5px;color:var(--ink-2);font-weight:550;">Tidak ada notifikasi baru.</p></div>';
  }
  return rows.map(n => {
    const isProt = !!n.is_protected;
    return `
    <div class="li notif-card-row ${n.unread ? 'is-unread' : ''}" style="display:flex;align-items:flex-start;padding:11px 12px;border-radius:14px;margin-bottom:6px;gap:8px;background:var(--card-bg, rgba(255,255,255,0.03));border:1px solid var(--line, rgba(255,255,255,0.07));">
      <div data-notif="${esc(n.id)}" style="display:flex;align-items:flex-start;gap:10px;flex:1;min-width:0;cursor:pointer;background:none;border:none;padding:0;text-align:left;color:inherit;" title="Klik untuk membuka detail">
        <span class="li-ic" style="${n.unread ? 'color:var(--b-500,#2563eb);' : 'opacity:.45;'}margin-top:2px;flex-shrink:0;">${ic[n.kind] || ic.bell}</span>
        <span class="li-body" style="min-width:0;flex:1;">
          <span class="li-t" style="font-size:13px;font-weight:${n.unread ? '700' : '550'};display:flex;align-items:center;gap:6px;color:var(--ink);flex-wrap:wrap;">
            <span class="trunc" style="max-width:calc(100% - 75px);">${esc(n.t)}</span>
            ${n.unread ? '<span style="display:inline-block;width:6.5px;height:6.5px;border-radius:50%;background:var(--b-500,#2563eb);flex-shrink:0;"></span>' : ''}
            ${isProt ? '<span class="chip notif-locked-chip" style="font-size:9.5px;padding:2px 7px;background:rgba(197,163,90,0.15);color:var(--ptv-gold,#c5a35a);border:1px solid rgba(197,163,90,0.3);"><i class="fa-solid fa-lock" style="font-size:9px;"></i> Terkunci</span>' : ''}
          </span>
          <span class="li-s" style="font-size:12px;color:var(--ink-2);line-height:1.38;margin-top:2px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;">${esc(n.s)}</span>
          <span style="font-size:10.5px;color:var(--ink3);margin-top:4px;display:inline-block;font-weight:500;">${esc(n.when || 'Baru saja')}</span>
        </span>
      </div>
      <div style="display:flex;align-items:center;gap:3px;flex-shrink:0;margin-top:1px;">
        <button type="button" class="btn-icon notif-lock-btn" data-act="toggleNotifLock:${esc(n.id)}" title="${isProt ? 'Terkunci (dilindungi dari Hapus Semua & Auto-Delete). Klik untuk buka kunci' : 'Kunci notifikasi agar tidak terhapus otomatis / oleh Hapus Semua'}" style="width:28px;height:28px;border-radius:8px;border:none;background:${isProt ? 'rgba(197,163,90,0.18)' : 'rgba(255,255,255,0.04)'};color:${isProt ? 'var(--ptv-gold,#c5a35a)' : 'var(--ink3,#888)'};cursor:pointer;display:inline-flex;align-items:center;justify-content:center;font-size:12px;">
          <i class="fa-solid ${isProt ? 'fa-lock' : 'fa-lock-open'}" style="${isProt ? '' : 'opacity:0.45;'}"></i>
        </button>
        <button type="button" class="btn-icon notif-del-btn" data-act="deleteSingleNotif:${esc(n.id)}" title="Hapus notifikasi ini" style="width:28px;height:28px;border-radius:8px;border:none;background:rgba(255,255,255,0.04);color:var(--ink3,#888);cursor:pointer;display:inline-flex;align-items:center;justify-content:center;font-size:12px;" onmouseover="this.style.color='#ef4444';this.style.background='rgba(239,68,68,0.1)';" onmouseout="this.style.color='var(--ink3,#888)';this.style.background='rgba(255,255,255,0.04)';">
          <i class="fa-regular fa-trash-can"></i>
        </button>
      </div>
    </div>`;
  }).join('');
}

function openNotif(){
  const rows = (DB.notifs || []);
  const permState = (typeof window.PTVNotificationManager !== 'undefined')
    ? window.PTVNotificationManager.getNotificationPermissionState()
    : (('Notification' in window) ? window.Notification.permission : 'unsupported');

  let bannerHtml = '';
  if (permState === 'default') {
    bannerHtml = `
      <div class="notif-push-banner" id="notifPushPromptBanner">
        <div style="display:flex;align-items:center;gap:10px;min-width:0;">
          <span style="width:32px;height:32px;border-radius:50%;background:#2563eb;color:#ffffff;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;">
            <i class="fa-solid fa-bell" style="font-size:13px;"></i>
          </span>
          <div style="min-width:0;">
            <div style="font-size:12px;font-weight:700;color:var(--ink);">Izin Notifikasi Browser</div>
            <div style="font-size:11px;color:var(--ink-2);line-height:1.25;">Aktifkan notifikasi pop-up Chrome & Safari</div>
          </div>
        </div>
        <button type="button" class="btn sm" data-act="enablePush" style="flex-shrink:0;padding:5px 13px;font-size:11.5px;font-weight:650;border-radius:var(--r-full);background:#2563eb;color:#ffffff;border:none;cursor:pointer;">
          Aktifkan
        </button>
      </div>`;
  } else if (permState === 'denied') {
    bannerHtml = `
      <div class="notif-push-banner" style="background:rgba(239,68,68,0.08);border-color:rgba(239,68,68,0.25);">
        <div style="display:flex;align-items:center;gap:10px;min-width:0;">
          <span style="width:32px;height:32px;border-radius:50%;background:#ef4444;color:#ffffff;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;">
            <i class="fa-solid fa-bell-slash" style="font-size:13px;"></i>
          </span>
          <div style="min-width:0;">
            <div style="font-size:12px;font-weight:700;color:var(--ink);">Notifikasi Diblokir</div>
            <div style="font-size:11px;color:var(--ink-2);line-height:1.25;">Klik untuk petunjuk membuka blokir</div>
          </div>
        </div>
        <button type="button" class="btn sm" data-act="openDeniedModal" style="flex-shrink:0;padding:5px 12px;font-size:11.5px;font-weight:650;border-radius:var(--r-full);background:#ef4444;color:#ffffff;border:none;cursor:pointer;">
          Buka Blokir
        </button>
      </div>`;
  } else if (permState === 'insecure_http') {
    bannerHtml = `
      <div class="notif-push-banner" style="background:rgba(245,158,11,0.08);border-color:rgba(245,158,11,0.25);">
        <div style="display:flex;align-items:center;gap:10px;min-width:0;">
          <span style="width:32px;height:32px;border-radius:50%;background:#f59e0b;color:#ffffff;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;">
            <i class="fa-solid fa-lock-open" style="font-size:13px;"></i>
          </span>
          <div style="min-width:0;">
            <div style="font-size:12px;font-weight:700;color:var(--ink);">Gunakan HTTPS</div>
            <div style="font-size:11px;color:var(--ink-2);line-height:1.25;">Web Push membutuhkan koneksi aman</div>
          </div>
        </div>
        <button type="button" class="btn sm" data-act="openInsecureModal" style="flex-shrink:0;padding:5px 12px;font-size:11.5px;font-weight:650;border-radius:var(--r-full);background:#f59e0b;color:#ffffff;border:none;cursor:pointer;">
          Info HTTPS
        </button>
      </div>`;
  } else if (permState === 'ios_safari_browser') {
    bannerHtml = `
      <div class="notif-push-banner" style="background:rgba(37,99,235,0.08);border-color:rgba(37,99,235,0.25);">
        <div style="display:flex;align-items:center;gap:10px;min-width:0;">
          <span style="width:32px;height:32px;border-radius:50%;background:#2563eb;color:#ffffff;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;">
            <i class="fa-brands fa-apple" style="font-size:14px;"></i>
          </span>
          <div style="min-width:0;">
            <div style="font-size:12px;font-weight:700;color:var(--ink);">Khusus iPhone/iPad</div>
            <div style="font-size:11px;color:var(--ink-2);line-height:1.25;">Perlu ditambahkan ke Layar Utama</div>
          </div>
        </div>
        <button type="button" class="btn sm" data-act="openIOSModal" style="flex-shrink:0;padding:5px 12px;font-size:11.5px;font-weight:650;border-radius:var(--r-full);background:#2563eb;color:#ffffff;border:none;cursor:pointer;">
          Petunjuk
        </button>
      </div>`;
  }

  const bodyHtml = `
    ${bannerHtml}
    <div id="notifListContainer" class="list">
      ${renderNotifItemsHTML(rows)}
    </div>`;

  const footHtml = `
    <div style="display:flex;gap:8px;align-items:center;width:100%;">
      <button type="button" class="btn" data-act="readAll" style="flex:1;font-size:12px;font-weight:600;padding:8px 12px;border-radius:var(--r-full);display:inline-flex;align-items:center;justify-content:center;gap:6px;">
        <i class="fa-regular fa-envelope-open" style="font-size:12px;"></i>
        <span>Tandai dibaca</span>
      </button>
      <button type="button" class="btn dang" data-act="deleteAllUnlockedNotifs" style="flex:1.2;font-size:12px;font-weight:600;padding:8px 14px;border-radius:var(--r-full);background:rgba(239,68,68,0.08);color:#dc2626;border:1px solid rgba(239,68,68,0.22);display:inline-flex;align-items:center;justify-content:center;gap:6px;cursor:pointer;" title="Hapus semua notifikasi yang tidak dikunci">
        <i class="fa-regular fa-trash-can" style="font-size:12px;"></i>
        <span>Hapus Semua</span>
      </button>
      <button type="button" class="btn" data-act="openDeleteNotifModal" style="flex:0 0 auto;font-size:12px;font-weight:600;padding:8px 10px;border-radius:var(--r-full);display:inline-flex;align-items:center;justify-content:center;" title="Opsi Pembersihan Rentang Waktu">
        <i class="fa-solid fa-clock-rotate-left" style="font-size:12px;"></i>
      </button>
    </div>`;

  // BUKA MODAL SECARA INSTAN TANPA MENUNGGU JARINGAN (0ms delay)
  openSheet('Notifikasi', bodyHtml, { foot: footHtml });

  // Sinkronisasi data terbaru di background secara asynchronous
  if (typeof AJAX_URL !== 'undefined') {
    (async () => {
      try {
        const fd = new FormData();
        fd.append('action', 'ptv_get_notifications');
        fd.append('nonce', typeof PTV_NONCE !== 'undefined' ? PTV_NONCE : '');
        const r = await fetch(AJAX_URL, { method: 'POST', body: fd, credentials: 'same-origin' });
        const j = await r.json();
        if (j.success && Array.isArray(j.data)) {
          DB.notifs = j.data;
          syncChrome();
          const listEl = document.getElementById('notifListContainer');
          const titleEl = document.getElementById('sheetTitle');
          if (listEl && titleEl && titleEl.textContent === 'Notifikasi') {
            listEl.innerHTML = renderNotifItemsHTML(DB.notifs);
          }
        }
      } catch(_) {}
    })();
  }
}
