function qrDataURL(text, size, margin) {
  size = size || 512;
  margin = (typeof margin === 'number') ? margin : 3;
  try {
    if (typeof qrcode === 'function') {
      const qr = qrcode(0, 'M');
      qr.addData(String(text || ''), 'Byte');
      qr.make();
      const count = qr.getModuleCount();
      const totalModules = count + margin * 2;
      const canvas = document.createElement('canvas');
      canvas.width = size;
      canvas.height = size;
      const ctx = canvas.getContext('2d');

      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, size, size);

      ctx.fillStyle = '#000000';
      const cellSize = size / totalModules;
      for (let r = 0; r < count; r++) {
        for (let c = 0; c < count; c++) {
          if (qr.isDark(r, c)) {
            const x = Math.round((c + margin) * cellSize);
            const y = Math.round((r + margin) * cellSize);
            const w = Math.ceil(cellSize);
            const h = Math.ceil(cellSize);
            ctx.fillRect(x, y, w, h);
          }
        }
      }
      return canvas.toDataURL('image/png');
    }
  } catch (err) {
    console.error('Failed to generate QR DataURL:', err);
  }
  return '';
}

function qrImgHTML(text, displaySize, opts) {
  displaySize = displaySize || 64;
  const margin = (opts && typeof opts.margin === 'number') ? opts.margin : 3;
  const dataUrl = qrDataURL(text, 512, margin);
  if (dataUrl) {
    return `<img src="${dataUrl}" class="qr-img" width="${displaySize}" height="${displaySize}" alt="Kode QR Resmi" style="display:block; margin:0 auto; width:${displaySize}px; height:${displaySize}px; max-width:100%; max-height:100%; image-rendering:pixelated; image-rendering:-webkit-optimize-contrast; background:#ffffff; box-sizing:border-box; border-radius:3px;" />`;
  }
  return qrSVG(text, displaySize, opts);
}

function qrSVG(text, size, opts){
  size = size || 110;
  const margin = (opts && typeof opts.margin === 'number') ? opts.margin : 2;
  try {
    if (typeof qrcode === 'function') {
      const qr = qrcode(0, 'M');
      qr.addData(String(text || ''), 'Byte');
      qr.make();
      const count = qr.getModuleCount();
      const cellSize = 4;
      const totalDim = (count + margin * 2) * cellSize;
      let d = '';
      for (let r = 0; r < count; r++) {
        for (let c = 0; c < count; c++) {
          if (qr.isDark(r, c)) {
            const x = (c + margin) * cellSize;
            const y = (r + margin) * cellSize;
            d += `M${x} ${y}h${cellSize}v${cellSize}h-${cellSize}z `;
          }
        }
      }
      return `<svg class="qr" width="${size}" height="${size}" viewBox="0 0 ${totalDim} ${totalDim}" preserveAspectRatio="xMidYMid meet" shape-rendering="crispEdges" aria-label="Kode QR Resmi" style="display:block; margin:0 auto; width:${size}px; height:${size}px; max-width:100%; max-height:100%; background:#ffffff; box-sizing:border-box;"><rect x="0" y="0" width="${totalDim}" height="${totalDim}" fill="#ffffff"/><path d="${d.trim()}" fill="#000000"/></svg>`;
    }
  } catch(err) {
    console.error('Failed to generate standard QR Code:', err);
  }
  return `<div style="width:${size}px;height:${size}px;background:#fff;border:1px solid #cbd5e1;display:flex;align-items:center;justify-content:center;font-size:9px;color:#64748b;">QR Error</div>`;
}

function downloadQRPNG(text, filename) {
  if (!text) {
    toast('Data QR tidak tersedia untuk diunduh.', 'alert');
    return;
  }
  try {
    const size = 1024;
    const canvas = document.createElement('canvas');
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');

    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, size, size);

    if (typeof qrcode === 'function') {
      const qr = qrcode(0, 'M');
      qr.addData(String(text), 'Byte');
      qr.make();
      const count = qr.getModuleCount();
      const margin = 4;
      const totalModules = count + margin * 2;
      const cellSize = size / totalModules;

      ctx.fillStyle = '#000000';
      for (let r = 0; r < count; r++) {
        for (let c = 0; c < count; c++) {
          if (qr.isDark(r, c)) {
            const x = Math.round((c + margin) * cellSize);
            const y = Math.round((r + margin) * cellSize);
            const w = Math.ceil(cellSize);
            const h = Math.ceil(cellSize);
            ctx.fillRect(x, y, w, h);
          }
        }
      }

      const link = document.createElement('a');
      link.download = (filename || 'PTV-QR') + '.png';
      link.href = canvas.toDataURL('image/png');
      link.click();
      toast('QR Code berhasil diunduh (PNG 1024x1024).', 'check');
    }
  } catch(e) {
    console.error('Download QR error:', e);
    toast('Gagal mengunduh QR Code.', 'alert');
  }
}

async function ptvUrlToBase64(url) {
  if (!url) return '';
  if (url.startsWith('data:')) return url;
  
  // 1. Coba direct fetch (CORS/Same-Origin)
  try {
    const res = await fetch(url, { mode: 'cors' });
    if (res.ok) {
      const blob = await res.blob();
      const b64 = await new Promise((resolve) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve(reader.result);
        reader.onerror = () => resolve('');
        reader.readAsDataURL(blob);
      });
      if (b64 && b64.startsWith('data:image')) return b64;
    }
  } catch (e) {
    // Network/CORS block -> lanjut ke server proxy
  }

  // 2. Server-side proxy melalui WordPress data bridge
  try {
    const proxyUrl = AJAX_URL + (AJAX_URL.includes('?') ? '&' : '?') + 'action=ptv_dashboard_action_proxy_base64&url=' + encodeURIComponent(url);
    const pRes = await fetch(proxyUrl);
    const pJson = await pRes.json();
    if (pJson.success && pJson.data?.data_uri) {
      return pJson.data.data_uri;
    }
  } catch (e) {
    console.warn('Proxy conversion failed for:', url, e);
  }

  return url;
}

async function downloadIdCardImage(filename, btnElement) {
  const card = document.querySelector('.idcard');
  if (!card) {
    toast('Elemen ID Card tidak ditemukan.', 'alert');
    return;
  }

  const originalBtnContent = btnElement ? btnElement.innerHTML : null;
  if (btnElement) {
    btnElement.disabled = true;
    btnElement.innerHTML = '<i class="fa-solid fa-spinner fa-spin" style="margin-right:6px"></i>Menyiapkan ID...';
  }

  try {
    toast('Memproses pembuatan gambar ID Card HD...', 'info');

    // 1. Library html2canvas
    let h2c = window.html2canvas;
    if (!h2c && typeof html2pdf !== 'undefined') {
      h2c = window.html2canvas;
    }
    if (!h2c) {
      await new Promise((resolve, reject) => {
        const s = document.createElement('script');
        s.src = 'https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js';
        s.onload = resolve;
        s.onerror = reject;
        document.head.appendChild(s);
      });
      h2c = window.html2canvas;
    }

    if (!h2c) {
      throw new Error('Library html2canvas tidak dapat dimuat.');
    }

    // 2. Konversi foto profil ke Base64 (mengatasi CORS cross-origin dari webp/Supabase/progresiftv.id)
    const photoImg = card.querySelector('.idcard-photo-img');
    let photoBase64 = '';
    if (photoImg && photoImg.src) {
      photoBase64 = await ptvUrlToBase64(photoImg.src);
      // Pre-crop image ke rasio presisi 1 / 1.08 agar html2canvas tidak pernah mendistorsi/memenyetkan foto
      if (photoBase64) {
        try {
          photoBase64 = await new Promise((resolve) => {
            const tempImg = new Image();
            tempImg.crossOrigin = 'anonymous';
            tempImg.onload = () => {
              const nw = tempImg.naturalWidth || tempImg.width;
              const nh = tempImg.naturalHeight || tempImg.height;
              if (!nw || !nh) return resolve(photoBase64);
              const targetRatio = 1 / 1.08;
              const sourceRatio = nw / nh;
              let sw, sh, sx, sy;
              if (sourceRatio > targetRatio) {
                sh = nh;
                sw = nh * targetRatio;
                sx = (nw - sw) / 2;
                sy = 0;
              } else {
                sw = nw;
                sh = nw / targetRatio;
                sx = 0;
                sy = Math.max(0, (nh - sh) * 0.2);
              }
              const c = document.createElement('canvas');
              c.width = 640;
              c.height = Math.round(640 / targetRatio);
              const ctx = c.getContext('2d');
              ctx.drawImage(tempImg, sx, sy, sw, sh, 0, 0, c.width, c.height);
              resolve(c.toDataURL('image/png'));
            };
            tempImg.onerror = () => resolve(photoBase64);
            tempImg.src = photoBase64;
          });
        } catch(eCrop) {
          console.warn('Pre-crop ID Card photo error:', eCrop);
        }
      }
    }

    // 3. Render Canvas dengan html2canvas
    const canvas = await h2c(card, {
      scale: 3,
      useCORS: true,
      allowTaint: false,
      backgroundColor: null,
      logging: false,
      onclone: (clonedDoc) => {
        const clonedCard = clonedDoc.querySelector('.idcard');
        if (clonedCard) {
          clonedCard.style.transform = 'none';
          clonedCard.style.boxShadow = 'none';
        }

        // Terapkan foto profil Base64 ke dalam DOM tiruan
        const clonedPhoto = clonedDoc.querySelector('.idcard-photo-img');
        if (clonedPhoto && photoBase64) {
          clonedPhoto.src = photoBase64;
          clonedPhoto.crossOrigin = 'anonymous';
        }

        // Render logo resmi putih murni di top-bar
        const clonedBrandBox = clonedDoc.querySelector('.idcard-brand-box');
        if (clonedBrandBox) {
          const oldLogo = clonedBrandBox.querySelector('.idcard-logo-white, .idcard-logo-img');
          if (oldLogo) oldLogo.remove();

          const logoImg = clonedDoc.createElement('img');
          logoImg.src = (typeof PTV_ID_CARD_LOGO_BASE64 !== 'undefined' && PTV_ID_CARD_LOGO_BASE64) ? PTV_ID_CARD_LOGO_BASE64 : (typeof PTV_ID_CARD_LOGO_URL !== 'undefined' ? PTV_ID_CARD_LOGO_URL : '/wp-content/uploads/2026/09/LOGO-NON-RESMI.webp');
          logoImg.className = 'idcard-logo-img';
          logoImg.style.cssText = 'height:26px;width:auto;max-width:145px;object-fit:contain;display:block;margin-bottom:2px;';
          clonedBrandBox.insertBefore(logoImg, clonedBrandBox.firstChild);
        }
      }
    });

    const outFilename = (filename || ('ID-Card-' + (ME.ptvId || 'PTV'))).replace(/[^a-zA-Z0-9_-]/g, '_') + '.png';
    const link = document.createElement('a');
    link.download = outFilename;
    link.href = canvas.toDataURL('image/png');
    link.click();

    toast('ID Card berhasil diunduh sebagai gambar PNG HD.', 'check');
  } catch(e) {
    console.error('Download ID Card error:', e);
    toast('Gagal mengunduh gambar ID: ' + (e?.message || e), 'alert');
  } finally {
    if (btnElement) {
      btnElement.disabled = false;
      if (originalBtnContent) btnElement.innerHTML = originalBtnContent;
    }
  }
}
