function togglePassEye(inputId, btn) {
  const inp = document.getElementById(inputId);
  if (!inp) return;
  const isPass = inp.type === 'password';
  inp.type = isPass ? 'text' : 'password';
  const targetBtn = btn || document.querySelector(`[data-toggle-pass="${inputId}"]`);
  if (targetBtn) {
    targetBtn.innerHTML = isPass ? '<i class="fa-regular fa-eye-slash"></i>' : '<i class="fa-regular fa-eye"></i>';
    targetBtn.setAttribute('aria-label', isPass ? 'Sembunyikan password' : 'Lihat password');
  }
}
