/* ---------------- Linear Barcode 1D (Code 128 Generator) ---------------- */
const C128_PATTERNS = [
  "212222","222122","222221","121223","121322","131222","122213","122312","132212","221213",
  "221312","231212","112232","122132","122231","113222","123122","123221","223211","221132",
  "221231","213212","223112","312131","311222","321122","321221","312212","322112","322211",
  "212123","212321","232121","111323","131123","131321","112313","132113","132311","211313",
  "231113","231311","112133","112331","132131","113123","113321","133121","313121","211331",
  "231131","213113","213311","213131","311123","311321","331121","312113","312311","332111",
  "314111","221411","431111","111224","111422","121124","121421","141122","141221","112214",
  "112412","122114","122411","142112","142211","241211","221114","413111","241112","134111",
  "111242","121142","121241","114212","124112","124211","411212","421112","421211","212141",
  "214121","412121","111143","111341","131141","114113","114311","411113","411311","113141",
  "114131","311141","411131","211412","211214","211232","2331112"
];

function barcode128SVG(code, opts = {}) {
  const text = String(code || 'INV-000').trim().toUpperCase();
  const width = opts.width || 240;
  const showText = opts.showText !== false;
  const fontSize = opts.fontSize || 11;
  
  let checkSum = 104;
  const codes = [104]; // Start B
  for (let i = 0; i < text.length; i++) {
    const charCode = text.charCodeAt(i);
    const val = charCode >= 32 && charCode <= 126 ? charCode - 32 : 0;
    codes.push(val);
    checkSum += val * (i + 1);
  }
  codes.push(checkSum % 103);
  codes.push(106); // Stop

  let barStr = '';
  for (const c of codes) {
    barStr += C128_PATTERNS[c] || '212222';
  }

  let totalModules = 0;
  for (let i = 0; i < barStr.length; i++) {
    totalModules += parseInt(barStr[i], 10);
  }

  const quietZone = 14;
  const totalWidth = totalModules + (quietZone * 2);
  
  // Height calculation with guaranteed vertical separation
  const topPad = 4;
  let barHeight = opts.barHeight || 36;
  if (opts.height) {
    barHeight = showText ? Math.max(22, opts.height - (fontSize + 18)) : Math.max(24, opts.height - 8);
  }
  
  let x = quietZone;
  let rects = '';
  for (let i = 0; i < barStr.length; i++) {
    const w = parseInt(barStr[i], 10);
    const isBar = (i % 2 === 0);
    if (isBar) {
      rects += `<rect x="${x}" y="${topPad}" width="${w}" height="${barHeight}" fill="currentColor"/>`;
    }
    x += w;
  }

  // Clear vertical gap between barcode lines and text (min 8px separation)
  const gap = 8;
  const textBaselineY = topPad + barHeight + gap + (fontSize * 0.9);
  const totalHeight = showText ? Math.ceil(textBaselineY + 4) : (topPad + barHeight + topPad);

  const textSvg = showText 
    ? `<text x="${totalWidth / 2}" y="${textBaselineY.toFixed(1)}" text-anchor="middle" font-family="ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace" font-size="${fontSize}" font-weight="700" style="letter-spacing: 2px;" fill="currentColor">${esc(text)}</text>` 
    : '';

  return `<svg class="barcode-128" viewBox="0 0 ${totalWidth} ${totalHeight}" style="width:${width}px;height:auto;max-width:100%;color:currentColor;display:block;margin:0 auto" xmlns="http://www.w3.org/2000/svg" aria-label="Barcode ${esc(text)}">
    <rect width="${totalWidth}" height="${totalHeight}" fill="transparent"/>
    ${rects}
    ${textSvg}
  </svg>`;
}

function emptyState(icon,msg,btn){
  return `<div class="empty card">${ic[icon]}<p>${msg}</p>${btn||''}</div>`;
}
function sectionHd(title, linkText, go, scopeBadge = ''){
