  `;
}

/* -------------------------------------------------------------------------
   KALENDER PDF VIEWER (Pesantren & Sekolah - Continuous Vertical Pages)
   ------------------------------------------------------------------------- */
const CAL_PDF_CONFIG = {
  pesantren: {
    title: 'Kalender Akademik Pesantren 2026',
    subtitle: 'Arsip & Dokumen Resmi Santri dan Pesantren Progresif Bumi Shalawat',
    icon: 'fa-solid fa-mosque',
    iconColor: '#059669',
    iconBg: 'rgba(16,185,129,0.12)',
    relPath: '/wp-content/uploads/KALENDER-2026@KHOLIL.pdf',
    downloadName: 'Kalender-Pesantren-2026.pdf',
    totalPages: 8
  },
  sekolah: {
    title: 'Kalender Akademik Sekolah',
    subtitle: 'Arsip & Dokumen Resmi Pendidikan Yayasan Bumi Shalawat',
    icon: 'fa-solid fa-graduation-cap',
    iconColor: '#2563eb',
    iconBg: 'rgba(37,99,235,0.12)',
    relPath: '/wp-content/uploads/01.013-SK-Agenda-Sekolah.pdf',
    downloadName: '01.013-SK-Agenda-Sekolah.pdf',
    totalPages: 4
  }
};

const calPdfDocCache = {
  pesantren: null,
  sekolah: null
};

let calCurrentPdfType = null;
let calPdfTotalPages = 1;
let calPdfZoom = 1.0;
let calPdfPanX = 0;
let calPdfPanY = 24;
let calPdfRenderCancelled = false;
let activeCalPdfRenderTasks = [];
let calPdfCurrentLoadId = 0;

function getCalPdfUrl(target) {
  const cfg = CAL_PDF_CONFIG[target] || CAL_PDF_CONFIG.sekolah;
  const origin = (typeof window !== 'undefined' && window.location && window.location.origin)
    ? window.location.origin.replace(/\/+$/, '')
    : '';
  return origin + cfg.relPath;
}

async function ensurePdfJs() {
  if (typeof window.pdfjsLib !== 'undefined') return true;
  return new Promise(function(resolve) {
    var s = document.createElement('script');
    s.src = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';
    s.onload = function() {
      if (window.pdfjsLib) {
        window.pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
        resolve(true);
      } else {
        resolve(false);
      }
    };
    s.onerror = function() {
      var s2 = document.createElement('script');
      s2.src = 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.min.js';
      s2.onload = function() {
        if (window.pdfjsLib) {
          window.pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js';
          resolve(true);
        } else {
          resolve(false);
        }
      };
      s2.onerror = function() { resolve(false); };
      document.head.appendChild(s2);
    };
    document.head.appendChild(s);
  });
}

function calPdfApplyTransform(withTransition) {
  const stage = document.getElementById('calPdfPaperStage');
  if (!stage) return;
  stage.style.transition = withTransition ? 'transform 0.18s cubic-bezier(0.16, 1, 0.3, 1)' : 'none';
  stage.style.transformOrigin = 'top left';
  stage.style.transform = 'translate3d(' + Math.round(calPdfPanX) + 'px, ' + Math.round(calPdfPanY) + 'px, 0) scale(' + calPdfZoom + ')';
}
window.calPdfApplyTransform = calPdfApplyTransform;

function calPdfClampPosition(targetX, targetY) {
  const vp = document.getElementById('calPdfViewport');
  const stage = document.getElementById('calPdfPaperStage');
  const vpW = vp ? (vp.clientWidth || 360) : 360;
  const vpH = vp ? (vp.clientHeight || 460) : 460;
  const scaledW = 820 * calPdfZoom;
  const rawH = (stage && stage.offsetHeight > 100) ? stage.offsetHeight : (1180 * calPdfTotalPages);
  const scaledH = rawH * calPdfZoom;

  // Horizontal bounds
  let minX, maxX;
  if (scaledW <= vpW) {
    const centeredX = (vpW - scaledW) / 2;
    minX = centeredX - 80;
    maxX = centeredX + 80;
  } else {
    minX = -(scaledW - vpW + 60);
    maxX = 60;
  }

  // Vertical bounds: allow scrolling all the way to the end of the last page
  let minY, maxY;
  if (scaledH <= vpH) {
    minY = 16;
    maxY = Math.max(24, vpH - scaledH);
  } else {
    minY = -(scaledH - vpH + 60);
    maxY = 24;
  }

  return {
    x: Math.max(minX, Math.min(maxX, targetX)),
    y: Math.max(minY, Math.min(maxY, targetY))
  };
}

function calPdfCenterPaper(withTransition, resetY) {
  const vp = document.getElementById('calPdfViewport');
  if (!vp) return;
  const vpW = vp.clientWidth || 360;
  const scaledW = 820 * calPdfZoom;
  calPdfPanX = Math.round((vpW - scaledW) / 2);
  if (resetY) {
    calPdfPanY = 24;
  }
  const clamped = calPdfClampPosition(calPdfPanX, calPdfPanY);
  calPdfPanX = clamped.x;
  calPdfPanY = clamped.y;
  calPdfApplyTransform(withTransition);
}
window.calPdfCenterPaper = calPdfCenterPaper;

function calPdfApplyZoom(newZoom) {
  const oldZoom = calPdfZoom;
  calPdfZoom = Math.min(Math.max(Number(newZoom.toFixed(2)), 0.35), 5.0);
  const disp = document.getElementById('calPdfZoomDisplay');
  if (disp) disp.textContent = Math.round(calPdfZoom * 100) + '%';

  // Smooth focal point scaling around viewport center
  const vp = document.getElementById('calPdfViewport');
  if (vp) {
    const vpW = vp.clientWidth || 360;
    const vpH = vp.clientHeight || 460;
    const centerStageX = (vpW / 2 - calPdfPanX) / oldZoom;
    const centerStageY = (vpH / 2 - calPdfPanY) / oldZoom;
    const targetX = vpW / 2 - (centerStageX * calPdfZoom);
    const targetY = vpH / 2 - (centerStageY * calPdfZoom);
    const clamped = calPdfClampPosition(targetX, targetY);
    calPdfPanX = clamped.x;
    calPdfPanY = clamped.y;
  }
  calPdfApplyTransform(true);
}
window.calPdfZoomIn = function() { calPdfApplyZoom(calPdfZoom + 0.25); };
window.calPdfZoomOut = function() { calPdfApplyZoom(calPdfZoom - 0.25); };
window.calPdfZoomReset = function() {
  const vp = document.getElementById('calPdfViewport');
  const vpW = vp ? (vp.clientWidth || 360) : 360;
  const targetW = 820;
  let fit = 1.0;
  if (vpW < 768) {
    fit = Math.max(0.35, Math.min(1.0, (vpW - 32) / targetW));
  } else {
    fit = Math.max(0.55, Math.min(1.0, (vpW - 48) / targetW));
  }
  calPdfZoom = Number(fit.toFixed(2));
  const disp = document.getElementById('calPdfZoomDisplay');
  if (disp) disp.textContent = Math.round(calPdfZoom * 100) + '%';
  calPdfCenterPaper(true, false);
};

function calPdfScrollToPage(pageNum) {
  const wrap = document.getElementById('calPdfPageWrap_' + pageNum);
  if (!wrap) return;
  const targetStageY = wrap.offsetTop;
  const targetY = Math.round(24 - (targetStageY * calPdfZoom));
  const clamped = calPdfClampPosition(calPdfPanX, targetY);
  calPdfPanY = clamped.y;
  calPdfApplyTransform(true);
}
window.calPdfScrollToPage = calPdfScrollToPage;

function calPdfScrollToTop() {
  calPdfScrollToPage(1);
}
window.calPdfScrollToTop = calPdfScrollToTop;

function initCalPdfPanner() {
  const vp = document.getElementById('calPdfViewport');
  const stage = document.getElementById('calPdfPaperStage');
  if (!vp || !stage) return;
  if (vp._calPannerInit) return;
  vp._calPannerInit = true;

  // Wheel scroll for smooth vertical pan & ctrl-wheel zoom
  vp.addEventListener('wheel', function(e) {
    e.preventDefault();
    if (e.ctrlKey) {
      const zoomDelta = e.deltaY < 0 ? 0.08 : -0.08;
      calPdfApplyZoom(calPdfZoom + zoomDelta);
      return;
    }
    const dx = e.deltaX || 0;
    const dy = e.deltaY || 0;
    const clamped = calPdfClampPosition(calPdfPanX - dx, calPdfPanY - dy);
    calPdfPanX = clamped.x;
    calPdfPanY = clamped.y;
    calPdfApplyTransform(false);
  }, { passive: false });

  // Mouse Drag / Pan
  let isMouseDown = false;
  let startX = 0, startY = 0;
  let startPanX = 0, startPanY = 0;

  vp.addEventListener('mousedown', function(e) {
    if (e.target.closest('button, input, select, a, textarea')) return;
    isMouseDown = true;
    vp.style.cursor = 'grabbing';
    startX = e.clientX;
    startY = e.clientY;
    startPanX = calPdfPanX;
    startPanY = calPdfPanY;
  });

  window.addEventListener('mouseup', function() {
    if (isMouseDown) {
      isMouseDown = false;
      if (vp) vp.style.cursor = 'grab';
    }
  });

  vp.addEventListener('mousemove', function(e) {
    if (!isMouseDown) return;
    e.preventDefault();
    const dx = e.clientX - startX;
    const dy = e.clientY - startY;
    const clamped = calPdfClampPosition(startPanX + dx, startPanY + dy);
    calPdfPanX = clamped.x;
    calPdfPanY = clamped.y;
    calPdfApplyTransform(false);
  });

  // Touch Drag / Pan & Two-finger Pinch-to-Zoom for mobile
  let touchActive = false;
  let touchStartX = 0, touchStartY = 0;
  let touchStartPanX = 0, touchStartPanY = 0;
  let touchStartDist = 0;
  let touchStartZoom = 1.0;
  let touchStartMidX = 0, touchStartMidY = 0;

  vp.addEventListener('touchstart', function(e) {
    if (e.target.closest('button, input, select, a, textarea')) return;
    if (e.touches.length === 1) {
      touchActive = true;
      vp.style.cursor = 'grabbing';
      touchStartX = e.touches[0].clientX;
      touchStartY = e.touches[0].clientY;
      touchStartPanX = calPdfPanX;
      touchStartPanY = calPdfPanY;
      touchStartDist = 0;
    } else if (e.touches.length === 2) {
      touchActive = false;
      const t0 = e.touches[0];
      const t1 = e.touches[1];
      touchStartDist = Math.hypot(t0.clientX - t1.clientX, t0.clientY - t1.clientY);
      touchStartZoom = calPdfZoom;
      touchStartPanX = calPdfPanX;
      touchStartPanY = calPdfPanY;
      touchStartMidX = (t0.clientX + t1.clientX) / 2;
      touchStartMidY = (t0.clientY + t1.clientY) / 2;
    }
  }, { passive: true });

  vp.addEventListener('touchmove', function(e) {
    if (e.touches.length === 1 && touchActive) {
      if (e.cancelable) e.preventDefault();
      const dx = e.touches[0].clientX - touchStartX;
      const dy = e.touches[0].clientY - touchStartY;
      const clamped = calPdfClampPosition(touchStartPanX + dx, touchStartPanY + dy);
      calPdfPanX = clamped.x;
      calPdfPanY = clamped.y;
      calPdfApplyTransform(false);
    } else if (e.touches.length === 2 && touchStartDist > 0) {
      if (e.cancelable) e.preventDefault();
      const t0 = e.touches[0];
      const t1 = e.touches[1];
      const currentDist = Math.hypot(t0.clientX - t1.clientX, t0.clientY - t1.clientY);
      if (currentDist <= 0) return;

      const ratio = currentDist / touchStartDist;
      const newZoom = Math.min(Math.max(touchStartZoom * ratio, 0.35), 5.0);

      const vpRect = vp.getBoundingClientRect();
      const localStartMidX = touchStartMidX - vpRect.left;
      const localStartMidY = touchStartMidY - vpRect.top;
      const stageX = (localStartMidX - touchStartPanX) / touchStartZoom;
      const stageY = (localStartMidY - touchStartPanY) / touchStartZoom;

      const currentMidX = (t0.clientX + t1.clientX) / 2;
      const currentMidY = (t0.clientY + t1.clientY) / 2;
      const localCurrentMidX = currentMidX - vpRect.left;
      const localCurrentMidY = currentMidY - vpRect.top;

      const targetPanX = localCurrentMidX - (stageX * newZoom);
      const targetPanY = localCurrentMidY - (stageY * newZoom);

      const clamped = calPdfClampPosition(targetPanX, targetPanY);
      calPdfZoom = Number(newZoom.toFixed(3));
      calPdfPanX = clamped.x;
      calPdfPanY = clamped.y;

      const disp = document.getElementById('calPdfZoomDisplay');
      if (disp) disp.textContent = Math.round(calPdfZoom * 100) + '%';

      calPdfApplyTransform(false);
    }
  }, { passive: false });

  const finishTouch = function(e) {
    if (e && e.touches && e.touches.length === 1) {
      // Seamlessly transition back to 1-finger panning if 1 finger remains
      touchActive = true;
      touchStartX = e.touches[0].clientX;
      touchStartY = e.touches[0].clientY;
      touchStartPanX = calPdfPanX;
      touchStartPanY = calPdfPanY;
      touchStartDist = 0;
    } else if (!e || !e.touches || e.touches.length === 0) {
      touchActive = false;
      touchStartDist = 0;
      if (vp) vp.style.cursor = 'grab';
    }
  };
  vp.addEventListener('touchend', finishTouch, { passive: true });
  vp.addEventListener('touchcancel', finishTouch, { passive: true });

  window.addEventListener('resize', function() {
    if (vp && vp.offsetParent !== null) {
      calPdfCenterPaper(false, false);
    }
  });
}
window.initCalPdfPanner = initCalPdfPanner;

async function loadCalPdf(target) {
  // 1. Cancel previous running render tasks cleanly
  calPdfRenderCancelled = true;
  activeCalPdfRenderTasks.forEach(task => {
    try { if (task && typeof task.cancel === 'function') task.cancel(); } catch(e){}
  });
  activeCalPdfRenderTasks = [];
  const thisLoadId = ++calPdfCurrentLoadId;

  const loadingEl = document.getElementById('calPdfLoading');
  const stageEl = document.getElementById('calPdfPaperStage');
  const fallbackEl = document.getElementById('calPdfFallback');
  if (loadingEl) {
    loadingEl.style.display = 'flex';
    loadingEl.innerHTML = `
      <i class="fa-solid fa-spinner fa-spin" style="font-size:30px; color:#38bdf8;"></i>
      <span>Memuat dokumen kalender resmi...</span>
    `;
  }
  if (stageEl) stageEl.style.display = 'none';
  if (fallbackEl) fallbackEl.style.display = 'none';

  calPdfRenderCancelled = false;

  const isReady = await ensurePdfJs();
  if (thisLoadId !== calPdfCurrentLoadId) return;
  if (!isReady || typeof window.pdfjsLib === 'undefined') {
    if (loadingEl) loadingEl.style.display = 'none';
    if (fallbackEl) fallbackEl.style.display = 'block';
    return;
  }

  const pdfUrl = getCalPdfUrl(target);

  try {
    if (!calPdfDocCache[target]) {
      const loadingTask = window.pdfjsLib.getDocument({
        url: pdfUrl,
        cMapUrl: 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/cmaps/',
        cMapPacked: true
      });
      calPdfDocCache[target] = await loadingTask.promise;
    }
    if (thisLoadId !== calPdfCurrentLoadId) return;
    const pdfDoc = calPdfDocCache[target];
    const totalPages = pdfDoc.numPages;
    calPdfTotalPages = totalPages;

    const targetW = 820;
    const dpr = (typeof window !== 'undefined' && window.devicePixelRatio) ? window.devicePixelRatio : 1;
    const isMobile = (typeof window !== 'undefined' && window.innerWidth < 768);
    const hdScale = isMobile ? Math.max(dpr * 1.2, 2.4) : Math.max(dpr * 1.5, 2.85);

    const page1 = await pdfDoc.getPage(1);
    if (thisLoadId !== calPdfCurrentLoadId) return;
    const unscaled1 = page1.getViewport({ scale: 1.0 });
    const page1H = Math.round(targetW * (unscaled1.height / unscaled1.width));

    // Buat kontainer halaman berurutan ke bawah (continuous vertical stack)
    let pagesHtml = '';
    for (let p = 1; p <= totalPages; p++) {
      pagesHtml += `
        <div id="calPdfPageWrap_${p}" class="cal-pdf-page-wrap" style="position:relative; display:flex; flex-direction:column; align-items:center; width:820px; flex-shrink:0;">
          <div style="width:100%; display:flex; justify-content:space-between; align-items:center; margin-bottom:12px; padding:0 4px; box-sizing:border-box;">
            <span style="font-size:11px; font-weight:700; color:#64748b; text-transform:uppercase; letter-spacing:0.04em;">
              <i class="fa-regular fa-file" style="margin-right:6px; color:#94a3b8;"></i>Halaman ${p} dari ${totalPages}
            </span>
            <button type="button" onclick="calPdfScrollToTop()" style="cursor:pointer; background:#ffffff; border:1px solid #e2e8f0; color:#64748b; font-size:11px; font-weight:600; padding:3px 10px; border-radius:6px; display:inline-flex; align-items:center; gap:5px; box-shadow:0 1px 2px rgba(0,0,0,0.04); transition:all 0.15s;" onmouseover="this.style.color='#0f172a';this.style.borderColor='#cbd5e1'" onmouseout="this.style.color='#64748b';this.style.borderColor='#e2e8f0'">
              <i class="fa-solid fa-arrow-up"></i> Ke Atas
            </button>
          </div>
          <canvas id="calPdfCanvas_${p}" class="paper-preview" style="background:#ffffff; border-radius:8px; border:1px solid rgba(226,232,240,0.8); box-shadow:0 10px 25px rgba(15,23,42,0.08), 0 2px 6px rgba(15,23,42,0.04); display:block; width:820px; min-height:500px;"></canvas>
        </div>
      `;
    }
    if (stageEl) {
      stageEl.innerHTML = pagesHtml;
      stageEl.style.display = 'flex';
    }

    // Hitung zoom fit awal berdasarkan lebar layar
    const vp = document.getElementById('calPdfViewport');
    const vpW = vp ? (vp.clientWidth || 360) : 360;
    let initialFit = 1.0;
    if (vpW < 768) {
      initialFit = Math.max(0.35, Math.min(1.0, (vpW - 32) / targetW));
    } else {
      initialFit = Math.max(0.55, Math.min(1.0, (vpW - 48) / targetW));
    }
    calPdfZoom = Number(initialFit.toFixed(2));
    const disp = document.getElementById('calPdfZoomDisplay');
    if (disp) disp.textContent = Math.round(calPdfZoom * 100) + '%';

    // 2. Render Halaman 1 terlebih dahulu dengan kualitas Ultra HD
    const baseScale1 = targetW / unscaled1.width;
    const renderScale1 = baseScale1 * hdScale;
    const viewport1 = page1.getViewport({ scale: renderScale1 });
    const canvas1 = document.getElementById('calPdfCanvas_1');
    if (canvas1) {
      canvas1.width = Math.round(viewport1.width);
      canvas1.height = Math.round(viewport1.height);
      canvas1.style.width = targetW + 'px';
      canvas1.style.height = page1H + 'px';
      const ctx1 = canvas1.getContext('2d');
      ctx1.imageSmoothingEnabled = true;
      ctx1.imageSmoothingQuality = 'high';
      const rTask1 = page1.render({ canvasContext: ctx1, viewport: viewport1 });
      activeCalPdfRenderTasks.push(rTask1);
      try {
        await rTask1.promise;
      } catch(rErr1) {
        if (thisLoadId !== calPdfCurrentLoadId || calPdfRenderCancelled) return;
        if (rErr1 && (rErr1.name === 'RenderingCancelledException' || String(rErr1).includes('RenderingCancelledException'))) return;
        throw rErr1;
      }
    }

    if (thisLoadId !== calPdfCurrentLoadId || calPdfRenderCancelled) return;
    if (loadingEl) loadingEl.style.display = 'none';

    // Pusatkan lembar kerja & inisialisasi panner (drag & smooth zoom)
    calPdfCenterPaper(false, true);
    initCalPdfPanner();

    // 3. Render halaman-halaman berikutnya secara berurutan ke bawah dengan resolusi Ultra HD
    for (let p = 2; p <= totalPages; p++) {
      if (thisLoadId !== calPdfCurrentLoadId || calPdfRenderCancelled) break;
      const page = await pdfDoc.getPage(p);
      if (thisLoadId !== calPdfCurrentLoadId || calPdfRenderCancelled) break;
      const unscaled = page.getViewport({ scale: 1.0 });
      const pageH = Math.round(targetW * (unscaled.height / unscaled.width));
      const bScale = targetW / unscaled.width;
      const rScale = bScale * hdScale;
      const vpPage = page.getViewport({ scale: rScale });
      const canvas = document.getElementById('calPdfCanvas_' + p);
      if (canvas) {
        canvas.width = Math.round(vpPage.width);
        canvas.height = Math.round(vpPage.height);
        canvas.style.width = targetW + 'px';
        canvas.style.height = pageH + 'px';
        const ctx = canvas.getContext('2d');
        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = 'high';
        const rTask = page.render({ canvasContext: ctx, viewport: vpPage });
        activeCalPdfRenderTasks.push(rTask);
        try {
          await rTask.promise;
        } catch(rErr) {
          if (thisLoadId !== calPdfCurrentLoadId || calPdfRenderCancelled) break;
          if (rErr && (rErr.name === 'RenderingCancelledException' || String(rErr).includes('RenderingCancelledException'))) break;
          throw rErr;
        }
      }
    }
  } catch(err) {
    if (thisLoadId !== calPdfCurrentLoadId || calPdfRenderCancelled) return;
    if (err && (err.name === 'RenderingCancelledException' || String(err).includes('RenderingCancelledException'))) return;
    console.error('Error rendering continuous PDF:', err);
    if (loadingEl) loadingEl.style.display = 'none';
    if (fallbackEl) fallbackEl.style.display = 'block';
  }
}

