function getKalenderNavFilters(){
  const isPtv = (calLayer === 'ptv' || calLayer === 'semua' || !calLayer);
  const isPesantren = (calLayer === 'pesantren');
  const isSekolah = (calLayer === 'sekolah');

  return `
    <div class="filters mb16" id="calFiltersBar">
      <button class="fchip${isPtv?' on':''}" data-cal-layer="ptv">
        <i class="fa-solid fa-calendar-days" style="margin-right:5px;"></i>Kalender PTV
      </button>
      <button class="fchip${isPesantren?' on':''}" data-cal-layer="pesantren">
        <i class="fa-solid fa-mosque" style="margin-right:5px;"></i>Kalender Pesantren
      </button>
      <button class="fchip${isSekolah?' on':''}" data-cal-layer="sekolah">
        <i class="fa-solid fa-graduation-cap" style="margin-right:5px;"></i>Kalender Sekolah
      </button>
    </div>
  `;
}

function getKalenderStageContent(layer){
  layer = layer || calLayer || 'ptv';
  const isPesantren = (layer === 'pesantren');
  const isSekolah = (layer === 'sekolah');

  if (isPesantren) {
    setTimeout(function(){
      calPdfRenderCancelled = true;
      loadCalPdf('pesantren');
    }, 60);
    return renderKalenderPdfViewer('pesantren');
  }

  if (isSekolah) {
    setTimeout(function(){
      calPdfRenderCancelled = true;
      loadCalPdf('sekolah');
    }, 60);
    return renderKalenderPdfViewer('sekolah');
  }

  const y = calCursor.getFullYear(), m = calCursor.getMonth();
  const first = new Date(y, m, 1);
  const start = first.getDay(); // 0: Min, 1: Sen, 2: Sel, ...
  const days = new Date(y, m + 1, 0).getDate();
  const prevDays = new Date(y, m, 0).getDate();
  const cells = [];

  for(let i = start - 1; i >= 0; i--){
    const prevD = prevDays - i;
    const prevM = m === 0 ? 11 : m - 1;
    const prevY = m === 0 ? y - 1 : y;
    cells.push({ d: prevD, out: true, iso: `${prevY}-${pad(prevM + 1)}-${pad(prevD)}` });
  }
  for(let d = 1; d <= days; d++){
    cells.push({ d, out: false, iso: `${y}-${pad(m + 1)}-${pad(d)}` });
  }
  let nextD = 1;
  while(cells.length % 7 !== 0){
    const nextM = m === 11 ? 0 : m + 1;
    const nextY = m === 11 ? y + 1 : y;
    cells.push({ d: nextD, out: true, iso: `${nextY}-${pad(nextM + 1)}-${pad(nextD)}` });
    nextD++;
  }

  // Month Hijri header range
  const firstHijri = getHijriInfo(`${y}-${pad(m + 1)}-01`);
  const lastHijri = getHijriInfo(`${y}-${pad(m + 1)}-${pad(days)}`);
  const hijriMonthHeader = (firstHijri.monthName === lastHijri.monthName)
    ? `${firstHijri.monthName} ${firstHijri.year} H`
    : `${firstHijri.monthName} – ${lastHijri.monthName} ${lastHijri.year} H`;

  return `
    <div class="cols mt12">
      <!-- Kolom Kiri: Kalender PTV Utama & Momentum Konten (Lebar Sama Sesuai Card Kalender) -->
      <div style="display:flex;flex-direction:column;gap:20px;">
        <!-- Card 1: Kalender PTV Utama -->
        <div class="cal-card-box">
          <!-- Month Navigation Bar (Clean & Responsive Header) -->
          <div class="cal-nav-bar">
            <div class="cal-nav-mobile-top">
              <div style="justify-self:start;display:flex;align-items:center;">
                <button class="cal-nav-btn" data-cal="-1" aria-label="Bulan Sebelumnya">${ic.chevL}</button>
              </div>
              <div style="text-align:center;justify-self:center;">
                <h2 class="cal-nav-title">${MONTHS[m]} ${y}</h2>
                <div class="cal-nav-desktop-hijri" style="margin-top:3px;">
                  <span class="cal-nav-hijri-badge">
                    <i class="fa-solid fa-moon" style="font-size:9.5px;"></i>${esc(hijriMonthHeader)}
                  </span>
                </div>
              </div>
              <div class="cal-nav-right-actions">
                <button class="btn sm cal-today-btn" data-act="calToday">Hari Ini</button>
                <button class="cal-nav-btn" data-cal="1" aria-label="Bulan Berikutnya">${ic.chev}</button>
              </div>
            </div>
            <div class="cal-nav-mobile-bottom">
              <span class="cal-nav-hijri-badge">
                <i class="fa-solid fa-moon" style="font-size:9.5px;"></i>${esc(hijriMonthHeader)}
              </span>
              <button class="btn sm cal-today-btn" data-act="calToday">Hari Ini</button>
            </div>
          </div>

          <!-- Day of Week Headers -->
          <div class="cal-dow-row">
            ${DOW.map(d => `<div class="cal-dow-col">${d}</div>`).join('')}
          </div>

          <!-- Calendar Days Grid -->
          <div class="cal-days-grid">
            ${cells.map(c => {
              const hInfo = getHijriInfo(c.iso);
              const wInfo = getWetonInfo(c.iso);
              if(c.out) {
                return `
                  <div class="cal-day-cell out">
                    <span class="cal-day-num">${c.d}</span>
                    <span class="cal-day-sub"><span class="cal-hijri-num">${hInfo.day}</span><span class="cal-pasaran-lbl">${esc(wInfo.pasaran)}</span></span>
                  </div>`;
              }
              const hasAcara = (DB.events || []).some(e => e.date === c.iso);
              const hasPlanner = (DB.content_planner || []).some(p => matchPlannerRule(p, c.iso, hInfo, wInfo));

              let dotsHTML = '';
              if (hasAcara && hasPlanner) {
                dotsHTML = '<span class="cal-dots-wrap"><i class="cal-event-dot"></i><i class="cal-planner-dot"></i></span>';
              } else if (hasAcara) {
                dotsHTML = '<i class="cal-event-dot"></i>';
              } else if (hasPlanner) {
                dotsHTML = '<i class="cal-planner-dot"></i>';
              }

              const isToday = (c.iso === iso(today));
              const isSel = (c.iso === calSel);
              const cls = ['cal-day-cell'];
              if(isToday) cls.push('today');
              if(isSel) cls.push('sel');

              if (hasAcara && hasPlanner) cls.push('has-both');
              else if (hasAcara) cls.push('has-event');
              else if (hasPlanner) cls.push('has-planner');

              return `
                <button class="${cls.join(' ')}" data-calday="${c.iso}" aria-label="${fmtDate(c.iso, true)} · ${esc(hInfo.full)} · ${esc(wInfo.full)}">
                  <span class="cal-day-num">${c.d}</span>
                  <span class="cal-day-sub"><span class="cal-hijri-num">${hInfo.day}</span><span class="cal-pasaran-lbl">${esc(wInfo.pasaran)}</span></span>
                  ${dotsHTML}
                </button>`;
            }).join('')}
          </div>
        </div>

        <!-- Card 2: Momentum & Ide Konten Seluruh Bulan (Lebar Persis Menyesuaikan Card Kalender) -->
        <div class="cal-card-box" style="padding:22px 24px;">
          ${getMonthPlannersContent(y, m, days)}
        </div>
      </div>

      <!-- Kolom Kanan: Sidebar Agenda Acara Liputan (Khusus Acara) -->
      <div id="calAgendaSidebarContainer">
        ${getKalenderSidebarContent(calSel)}
      </div>
    </div>`;
}

function getKalenderContent(){
  return getKalenderNavFilters() + `<div id="calViewStage">${getKalenderStageContent(calLayer)}</div>`;
}

function pgKalender(){
  return renderAcaraShell('kalender', getKalenderContent());
}

