const NOTE_COLORS = Object.assign({}, NOTE_CATEGORIES, {
  emerald: NOTE_CATEGORIES.green,
  amber:   NOTE_CATEGORIES.yellow,
  blue:    NOTE_CATEGORIES.purple,
  cyan:    NOTE_CATEGORIES.green,
  slate:   NOTE_CATEGORIES.orange,
  default: NOTE_CATEGORIES.orange
});

function getNoteCategory(n) {
  const raw = n && n.warna ? String(n.warna).toLowerCase().trim() : 'orange';
  if (NOTE_COLORS[raw]) return NOTE_COLORS[raw];
  return NOTE_CATEGORIES.orange;
}

function getNoteType(n) {
  if (!n) return 'shared';
  const rawType = String(n.tipe || n.type || n.note_type || '').toLowerCase().trim();
  if (rawType === 'meeting_minutes' || rawType === 'notulensi' || rawType === 'notulensi_rapat') return 'meeting_minutes';
  if (Array.isArray(n.tags)) {
    if (n.tags.some(t => {
      const s = String(t).toLowerCase().trim();
      return s === 'notulensi' || s === 'notulensi_rapat' || s === 'notulen' || s === 'meeting_minutes';
    })) return 'meeting_minutes';
  } else if (typeof n.tags === 'string' && n.tags) {
    const s = n.tags.toLowerCase();
    if (s.includes('notulensi') || s.includes('notulensi_rapat') || s.includes('notulen') || s.includes('meeting_minutes')) return 'meeting_minutes';
  }
  if (typeof n.isi === 'string' && /<!--\s*PTV_META:.*?("type"|"tipe")\s*:\s*"meeting_minutes"/s.test(n.isi)) return 'meeting_minutes';
  return 'shared';
}

function extractMeetingMeta(isi) {
  if (!isi || typeof isi !== 'string') return null;
  const m = isi.match(/<!--\s*PTV_META:\s*({.*?})\s*-->/s);
  if (m && m[1]) {
    try {
      return JSON.parse(m[1]);
    } catch(e){}
  }
  return null;
}

function formatNotePreview(text){
  if(!text) return '';
  let clean = String(text)
    .replace(/<!--\s*PTV_META:[\s\S]*?-->/g, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<\/h[1-6]>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<br\s*[\/]?>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n');
  return clean.split('\n')
    .map(l => l.trim())
    .filter((l, idx, arr) => {
      if (l) return true;
      return idx > 0 && arr[idx - 1] !== '';
    })
    .join('\n')
    .trim();
}

/* ============================================================
   NOTE DRAFT STATE (Catatan & Notulensi Rapat)
   Manual Save Only: Autosave DINONAKTIFKAN secara penuh.
   Membuka modal, mengetik, mengganti tipe, close X, backdrop,
   Escape, atau blur TIDAK PERNAH menyimpan ke Supabase.
   Satu-satunya pemicu persistensi adalah tombol Simpan/Perbarui.
   ============================================================ */
const noteAutoSaveManager = {
  activeNoteId: null,
  isEdit: false,
  isDirty: false,
  clearTimer() {},
  init(isEdit, noteId) {
    this.isEdit = !!isEdit;
    this.activeNoteId = isEdit && noteId ? String(noteId) : null;
    this.isDirty = false;
  },
  markDirty() {
    this.isDirty = true;
  },
  updateStatus() {}
};

window.noteAutoSaveManager = noteAutoSaveManager;
window.markNoteDirty = function() {
  if (typeof noteAutoSaveManager !== 'undefined') {
    noteAutoSaveManager.markDirty();
  }
};
window.isNoteEditorOpenAndDirty = function() {
  return false;
};
window.onNoteEditorBlur = function() {
  // Manual save only: blur editor tidak pernah melakukan persistence ke server
};

function renderCategoryCustomDropdown(selectedKey) {
  const currentKey = (selectedKey && NOTE_COLORS[selectedKey]) ? NOTE_COLORS[selectedKey].key : 'orange';
  const currentCat = NOTE_CATEGORIES[currentKey] || NOTE_CATEGORIES.orange;

  return `
    <div class="note-custom-dropdown" id="noteCategoryCustomDropdown">
      <!-- Trigger Dropdown Box -->
      <div class="note-dropdown-trigger" id="noteDropdownTrigger" onclick="toggleNoteCategoryDropdown(event)" style="background:${currentCat.bg};color:${currentCat.text};">
        <div style="display:flex;align-items:center;gap:12px;min-width:0;">
          <span class="note-dropdown-trigger-icon" style="background:${currentCat.pillBg};color:${currentCat.pillText};">
            <i class="fa-solid ${currentCat.icon}"></i>
          </span>
          <div style="display:flex;flex-direction:column;align-items:flex-start;min-width:0;line-height:1.25;">
            <span style="font-size:14px;font-weight:800;letter-spacing:-0.01em;" id="noteDropdownSelectedLabel">${esc(currentCat.label)}</span>
            <span style="font-size:11.5px;font-weight:600;opacity:0.9;" id="noteDropdownSelectedSub">Contoh: ${esc(currentCat.example)}</span>
          </div>
        </div>
        <span class="note-dropdown-chevron" id="noteDropdownChevron" style="color:${currentCat.text};">
          <i class="fa-solid fa-chevron-down"></i>
        </span>
      </div>

      <!-- Floating Popover Menu -->
      <div class="note-dropdown-menu" id="noteDropdownMenu">
        ${Object.values(NOTE_CATEGORIES).map(cat => `
          <div class="note-dropdown-item ${cat.key === currentKey ? 'is-selected' : ''}" 
               data-cat-key="${cat.key}"
               onclick="selectNoteCategoryDropdown('${cat.key}')"
               style="background:${cat.bg};color:${cat.text};">
            <div style="display:flex;align-items:center;gap:11px;min-width:0;">
              <span class="note-dropdown-item-icon" style="background:${cat.pillBg};color:${cat.pillText};">
                <i class="fa-solid ${cat.icon}"></i>
              </span>
              <div style="display:flex;flex-direction:column;align-items:flex-start;min-width:0;line-height:1.25;">
                <span style="font-size:13.5px;font-weight:800;">${esc(cat.label)}</span>
                <span style="font-size:11px;font-weight:600;opacity:0.9;">Contoh: ${esc(cat.example)}</span>
              </div>
            </div>
            <span class="note-dropdown-item-check" style="background:${cat.pillBg};color:${cat.pillText};">
              <i class="fa-solid fa-check"></i>
            </span>
          </div>
        `).join('')}
      </div>
      <input type="hidden" id="note_warna" value="${currentKey}">
    </div>
  `;
}

window.toggleNoteCategoryDropdown = function(e) {
  if (e) e.stopPropagation();
  const el = document.getElementById('noteCategoryCustomDropdown');
  if (el) el.classList.toggle('is-open');
};

window.selectNoteCategoryDropdown = function(key) {
  const cat = NOTE_CATEGORIES[key] || NOTE_CATEGORIES.orange;
  const input = document.getElementById('note_warna');
  if (input) input.value = key;

  const trigger = document.getElementById('noteDropdownTrigger');
  if (trigger) {
    trigger.style.background = cat.bg;
    trigger.style.color = cat.text;
  }
  const triggerIcon = trigger ? trigger.querySelector('.note-dropdown-trigger-icon') : null;
  if (triggerIcon) {
    triggerIcon.style.background = cat.pillBg;
    triggerIcon.style.color = cat.pillText;
    triggerIcon.innerHTML = `<i class="fa-solid ${cat.icon}"></i>`;
  }
  const labelEl = document.getElementById('noteDropdownSelectedLabel');
  if (labelEl) labelEl.textContent = cat.label;
  const subEl = document.getElementById('noteDropdownSelectedSub');
  if (subEl) subEl.textContent = 'Contoh: ' + cat.example;
  const chevronEl = document.getElementById('noteDropdownChevron');
  if (chevronEl) chevronEl.style.color = cat.text;

  document.querySelectorAll('#noteDropdownMenu .note-dropdown-item').forEach(item => {
    if (item.getAttribute('data-cat-key') === key) {
      item.classList.add('is-selected');
    } else {
      item.classList.remove('is-selected');
    }
  });

  const el = document.getElementById('noteCategoryCustomDropdown');
  if (el) el.classList.remove('is-open');
  if (typeof markNoteDirty === 'function') markNoteDirty();
};

if (!window._noteDropdownGlobalInit) {
  window._noteDropdownGlobalInit = true;
  document.addEventListener('click', function(e) {
    const dd = document.getElementById('noteCategoryCustomDropdown');
    if (dd && !dd.contains(e.target)) {
      dd.classList.remove('is-open');
    }
  });
}

window.insertMeetingMinutesTemplate = function() {
  const editor = document.getElementById('note_isi_editor');
  if (!editor) return;
  const dVal = document.getElementById('note_meeting_date')?.value || '';
  const tVal = document.getElementById('note_meeting_time')?.value || '';
  const locVal = document.getElementById('note_meeting_location')?.value || '';
  const attVal = document.getElementById('note_meeting_attendees')?.value || '';
  
  const todayIso = new Date().toISOString().split('T')[0];
  let formattedDate = dVal ? fmtDate(dVal) : fmtDate(todayIso);
  let formattedTime = tVal || '09:00 - 11:30 WIB';
  let formattedLoc = locVal || 'Studio PTV / Google Meet';
  let formattedAtt = attVal || 'Tim PTV';

  const tpl = `<h1>Notulensi Rapat: </h1>
<p><strong>Hari / Tanggal:</strong> ${esc(formattedDate)}<br>
<strong>Waktu:</strong> ${esc(formattedTime)}<br>
<strong>Tempat / Media:</strong> ${esc(formattedLoc)}<br>
<strong>Peserta:</strong> ${esc(formattedAtt)}</p>

<h2>1. Agenda Pembahasan</h2>
<p>• </p>

<h2>2. Pembahasan & Keputusan Rapat</h2>
<p>• </p>

<h2>3. Tindak Lanjut (Action Items) & PIC</h2>
<p>• </p>`;

  editor.innerHTML = tpl;
  toast('Template Notulensi Rapat disisipkan.', 'check');
  editor.focus();
  if (typeof markNoteDirty === 'function') markNoteDirty();
};

window.onNoteTypeChoiceChange = function(val) {
  const hidden = document.getElementById('note_tipe');
  if (hidden) hidden.value = val;

  const lblShared = document.getElementById('lbl_type_shared');
  const lblMeeting = document.getElementById('lbl_type_meeting');
  const metaBox = document.getElementById('noteMeetingMetaBox');
  const editor = document.getElementById('note_isi_editor');

  if (val === 'meeting_minutes') {
    if (lblMeeting) {
      lblMeeting.style.borderColor = '#2563eb';
      lblMeeting.style.background = 'rgba(37, 99, 235, 0.08)';
    }
    if (lblShared) {
      lblShared.style.borderColor = 'var(--line-2, #e2e8f0)';
      lblShared.style.background = 'transparent';
    }
    if (metaBox) metaBox.style.display = 'block';

    if (editor) {
      const text = (editor.textContent || editor.innerText || '').trim();
      if (!text) {
        window.insertMeetingMinutesTemplate();
      }
    }
  } else {
    // Berpindah ke Catatan Bersama (shared)
    if (lblShared) {
      lblShared.style.borderColor = '#2563eb';
      lblShared.style.background = 'rgba(37, 99, 235, 0.08)';
    }
    if (lblMeeting) {
      lblMeeting.style.borderColor = 'var(--line-2, #e2e8f0)';
      lblMeeting.style.background = 'transparent';
    }
    if (metaBox) metaBox.style.display = 'none';

    if (editor) {
      const raw = editor.innerHTML || '';
      const text = (editor.textContent || editor.innerText || '').trim();
      const isDefaultTpl = (
        raw.includes('Notulensi Rapat:') &&
        raw.includes('Agenda Pembahasan') &&
        (!text || text.length < 240)
      );

      if (isDefaultTpl) {
        // Bersihkan template rapat sehingga editor kosong untuk Catatan Bersama
        editor.innerHTML = '<p><br></p>';
      } else {
        // Hapus metadata komentar jika user sudah menulis catatan kustom
        editor.innerHTML = raw.replace(/<!--\s*PTV_META:[\s\S]*?-->/g, '').trim();
      }
    }
  }
  if (typeof markNoteDirty === 'function') markNoteDirty();
};

function pgCatatan(){
  const rawNotes = DB.notes || [];
  const seenIds = new Set();
  const allNotes = [];
  for (const n of rawNotes) {
    const nid = String(n && n.id ? n.id : '');
    if (nid && !seenIds.has(nid)) {
      seenIds.add(nid);
      allNotes.push(n);
    }
  }
  const q = (noteSearch || '').trim().toLowerCase();

  // 1. Calculate overall counts for all types
  const sharedCount = allNotes.filter(n => getNoteType(n) === 'shared').length;
  const notulensiCount = allNotes.filter(n => getNoteType(n) === 'meeting_minutes').length;
  const allCount = allNotes.length;

  // 2. Strict type scoping based on active noteTypeFilter
  // Default is 'shared' (Catatan Bersama) which explicitly excludes 'meeting_minutes'
  let typeScopedNotes = allNotes;
  if (noteTypeFilter === 'shared') {
    typeScopedNotes = allNotes.filter(n => getNoteType(n) === 'shared');
  } else if (noteTypeFilter === 'meeting_minutes') {
    typeScopedNotes = allNotes.filter(n => getNoteType(n) === 'meeting_minutes');
  }

  // 3. Search filter strictly applied ONLY to typeScopedNotes!
  let rows = typeScopedNotes.slice();
  if(q){
    rows = rows.filter(n => (n.judul || '').toLowerCase().includes(q) || 
      (n.isi || '').toLowerCase().includes(q) || 
      (Array.isArray(n.tags) ? n.tags.join(' ') : (n.tags || '')).toLowerCase().includes(q) || 
      (n.created_by_name || '').toLowerCase().includes(q));
  }

  // 4. Color / Pinned sub-filter within the scoped view
  if(noteFilter === 'pinned'){
    rows = rows.filter(n => n.is_pinned);
  } else if(noteFilter !== 'semua'){
    rows = rows.filter(n => {
      const cat = getNoteCategory(n);
      return cat.key === noteFilter;
    });
  }

  const pinnedNotes = rows.filter(n => n.is_pinned);
  const otherNotes = (noteFilter === 'pinned') ? [] : rows.filter(n => !n.is_pinned);

  const filterList = [
    ['semua', 'Semua (' + typeScopedNotes.length + ')', '#64748b', null],
    ['pinned', 'Tersemat (' + typeScopedNotes.filter(n => n.is_pinned).length + ')', '#d97706', 'fa-thumbtack'],
    ['orange', 'Penting', '#F46E56', null],
    ['yellow', 'Ide', '#E5A84D', null],
    ['green', 'Info', '#2CB6A8', null],
    ['purple', 'Agenda', '#9489BD', null],
    ['rose', 'Tugas', '#E57368', null]
  ];

  const renderCard = (n) => {
    const cat = getNoteCategory(n);
    const isMeeting = getNoteType(n) === 'meeting_minutes';
    const tagsArr = Array.isArray(n.tags) ? n.tags : (typeof n.tags === 'string' && n.tags.trim() ? n.tags.split(/,\s*/) : []);
    const cleanPreview = formatNotePreview(n.isi);
    const metaObj = isMeeting ? extractMeetingMeta(n.isi) : null;

    return `
      <div class="note-card-docket color-${cat.key} ${n.is_pinned ? 'is-pinned' : ''}" 
           data-act="openNoteDetail:${n.id}"
           style="background:${cat.bg};color:${cat.text};"
           tabindex="0" role="button">
        
        <!-- Header: Kategori Tag, Notulensi Badge & Thumbtack Pin Badge -->
        <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;width:100%;">
          <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;">
            <span style="display:inline-flex;align-items:center;gap:5px;padding:4px 10px;border-radius:var(--r-full);background:${cat.pillBg};color:${cat.pillText};font-size:11px;font-weight:750;letter-spacing:0.02em;">
              <i class="fa-solid ${cat.icon}" style="font-size:10px;"></i>
              <span>${esc(cat.short)}</span>
            </span>
            ${isMeeting ? `
              <span class="note-type-badge-pill" title="Notulensi Rapat">
                <i class="fa-solid fa-handshake" style="font-size:9.5px;"></i>
                <span>Notulensi Rapat</span>
              </span>
            ` : ''}
          </div>
          ${n.is_pinned ? `
            <span class="note-pin-badge" style="background:${cat.pillBg};color:${cat.pillText};" title="Catatan Tersemat">
              <i class="fa-solid fa-thumbtack" style="font-size:11px;transform:rotate(-30deg);"></i>
            </span>
          ` : ''}
        </div>

        <!-- Body: Judul & Isi Preview -->
        <div style="flex:1;display:flex;flex-direction:column;margin-top:10px;margin-bottom:12px;">
          <h3 style="margin:0 0 6px 0;font-size:16.5px;font-weight:800;color:${cat.text};line-height:1.35;word-break:break-word;letter-spacing:-0.015em;">
            ${esc(n.judul || 'Tanpa Judul')}
          </h3>
          ${metaObj && (metaObj.date || metaObj.loc) ? `
            <div style="display:flex;align-items:center;gap:10px;font-size:11.5px;font-weight:700;color:${cat.meta};margin-bottom:6px;flex-wrap:wrap;">
              ${metaObj.date ? `<span><i class="fa-solid fa-calendar" style="margin-right:4px;"></i>${fmtDate(metaObj.date)}</span>` : ''}
              ${metaObj.loc ? `<span><i class="fa-solid fa-location-dot" style="margin-right:4px;"></i>${esc(metaObj.loc)}</span>` : ''}
            </div>
          ` : ''}
          <p style="margin:0;padding:0;color:${cat.body};font-size:13.5px;line-height:1.55;display:-webkit-box;-webkit-line-clamp:4;-webkit-box-orient:vertical;overflow:hidden;word-break:break-word;white-space:pre-line;text-align:left;">
            ${esc(cleanPreview)}
          </p>
        </div>

        <!-- Footer: Tanggal, Penulis & Action Button -->
        <div style="padding-top:10px;border-top:1px solid ${cat.pillBg};display:flex;align-items:center;justify-content:space-between;gap:8px;">
          <div style="display:flex;flex-direction:column;gap:1px;min-width:0;">
            <span style="font-size:12px;font-weight:750;color:${cat.meta};">${formatNoteTimeAgo(n.updated_at || n.created_at)}</span>
            <span class="trunc" style="font-size:11px;font-weight:600;color:${cat.meta};">Oleh ${esc(n.created_by_name || 'Kru PTV')}</span>
          </div>
          <button class="note-card-action-btn" style="background:${cat.pillBg};color:${cat.pillText};" title="Buka Detail & Edit">
            <i class="fa-solid fa-arrow-up-right-from-square"></i>
          </button>
        </div>
      </div>
    `;
  };

  const renderNewActionCard = (isStretched, targetCatKey) => {
    const isCat = targetCatKey && NOTE_CATEGORIES[targetCatKey];
    const cat = isCat ? NOTE_CATEGORIES[targetCatKey] : null;
    const catShort = cat ? cat.short : '';
    const catLabel = cat ? cat.label : '5 Kategori';
    const isMeetingMode = noteTypeFilter === 'meeting_minutes';
    
    return `
      <div class="note-card-new-action ${isStretched ? 'is-hero-stretched' : ''}" 
           data-act="openNewNote:${targetCatKey || 'orange'}:${isMeetingMode ? 'meeting_minutes' : 'shared'}" 
           role="button" tabindex="0">
        <div class="note-new-circle-icon"><i class="fa-solid fa-plus"></i></div>
        <div style="font-size:16px;font-weight:800;color:var(--ink);margin-top:2px;">
          ${isMeetingMode ? 'Tambah Notulensi Rapat Baru' : (cat ? `Tambah Catatan ${esc(catShort)} Baru` : 'Tambah Catatan Bersama Baru')}
        </div>
        <div style="font-size:12.5px;color:var(--muted);font-weight:500;max-width:340px;line-height:1.45;">
          ${isMeetingMode ? 'Dokumentasikan hasil rapat, keputusan, dan tindak lanjut tim PTV' : (isStretched && cat ? `Belum ada catatan di kategori <strong>${esc(catLabel)}</strong>. Klik di sini untuk membuat catatan pertama!` : (cat ? `Tulis catatan baru khusus kategori ${esc(catLabel)}` : 'Pilih dari 5 kategori warna untuk kolaborasi dan koordinasi tim'))}
        </div>
        <div style="display:flex;gap:7px;margin-top:4px;">
          ${Object.values(NOTE_CATEGORIES).map(c => `
            <span style="width:11px;height:11px;border-radius:50%;background:${c.bg};${c.key === targetCatKey ? 'outline:2px solid #2563eb;outline-offset:2.5px;' : ''}" title="${esc(c.label)}"></span>
          `).join('')}
        </div>
      </div>
    `;
  };

  const isSpecificCat = noteFilter !== 'semua' && noteFilter !== 'pinned' && NOTE_CATEGORIES[noteFilter];

  return `
    <div class="page">
      <!-- Header Row -->
      <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:16px;margin-bottom:16px;flex-wrap:wrap;">
        <div>
          <h1 style="font-size:28px;font-weight:850;letter-spacing:-0.03em;color:var(--ink);margin:0;line-height:1.2;">
            ${noteTypeFilter === 'meeting_minutes' ? 'Notulensi Rapat PTV' : (noteTypeFilter === 'semua' ? 'Semua Catatan & Notulensi' : 'Catatan Bersama')}
          </h1>
          <p style="font-size:13px;color:var(--muted);margin:4px 0 0;font-weight:500;">
            ${noteTypeFilter === 'meeting_minutes' ? 'Arsip dan ringkasan hasil rapat, keputusan, serta tindak lanjut tim PTV' : 'Papan catatan 5 warna untuk koordinasi, ide, SOP, dan agenda tim PTV'}
          </p>
        </div>
        <div>
          <button class="btn pri" data-act="openNewNote:orange:${noteTypeFilter === 'meeting_minutes' ? 'meeting_minutes' : 'shared'}" style="background:#2563eb;color:#fff;font-weight:750;border-radius:12px;padding:10px 18px;border:none;cursor:pointer;box-shadow:0 4px 14px rgba(37,99,235,0.28);display:inline-flex;align-items:center;gap:6px;">
            <i class="fa-solid fa-plus"></i>
            <span>${noteTypeFilter === 'meeting_minutes' ? 'Tambah Notulensi' : 'Tambah Catatan'}</span>
          </button>
        </div>
      </div>

      <!-- Segmented Note Type Control: Catatan Bersama | Notulensi Rapat | Semua -->
      <div class="note-type-segment">
        <button class="note-type-btn ${noteTypeFilter === 'shared' ? 'is-active' : ''}" data-act="setNoteTypeFilter:shared">
          <i class="fa-solid fa-note-sticky"></i>
          <span>Catatan Bersama</span>
          <span class="badge-count">${sharedCount}</span>
        </button>
        <button class="note-type-btn ${noteTypeFilter === 'meeting_minutes' ? 'is-active' : ''}" data-act="setNoteTypeFilter:meeting_minutes">
          <i class="fa-solid fa-handshake"></i>
          <span>Notulensi Rapat</span>
          <span class="badge-count">${notulensiCount}</span>
        </button>
        <button class="note-type-btn ${noteTypeFilter === 'semua' ? 'is-active' : ''}" data-act="setNoteTypeFilter:semua">
          <i class="fa-solid fa-layer-group"></i>
          <span>Semua</span>
          <span class="badge-count">${allCount}</span>
        </button>
      </div>

      <!-- Search Bar -->
      <div class="row gap8" style="align-items:center;margin-bottom:14px;">
        <div class="searchbar" style="flex:1;">
          ${ic.search}
          <input id="notesSearch" value="${esc(noteSearch)}" placeholder="${noteTypeFilter === 'meeting_minutes' ? 'Cari judul notulensi, topik rapat, tanggal, atau nama kru...' : 'Cari judul catatan, isi, tag, atau nama kru...'}" autocomplete="off">
        </div>
      </div>

      <!-- Minimalist & Premium Filter Pills Bar (Filtered by active type) -->
      <div class="notes-filter-bar">
        ${filterList.map(([k, l, dotCol, iconClass]) => `
          <button class="notes-filter-pill${noteFilter === k ? ' on' : ''}" data-filter-note="${k}">
            ${iconClass ? `<i class="fa-solid ${iconClass}" style="font-size:11px;${iconClass==='fa-thumbtack'?'transform:rotate(-30deg);':''}"></i>` : (dotCol ? `<span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${dotCol};"></span>` : '')}
            <span>${l}</span>
          </button>
        `).join('')}
      </div>

      <div id="notesContainer">
        ${(pinnedNotes.length > 0 && noteFilter === 'semua') ? `
          <div style="margin-bottom:24px;">
            <div style="display:flex;align-items:center;gap:6px;margin-bottom:12px;font-size:11.5px;font-weight:800;text-transform:uppercase;letter-spacing:0.06em;color:var(--muted);">
              <i class="fa-solid fa-thumbtack" style="color:#d97706;transform:rotate(-30deg);font-size:11.5px;"></i>
              <span>${noteTypeFilter === 'meeting_minutes' ? 'Notulensi Tersemat' : 'Catatan Tersemat'}</span>
            </div>
            <div class="notes-grid">
              ${pinnedNotes.map(renderCard).join('')}
            </div>
          </div>
        ` : ''}

        ${(pinnedNotes.length > 0 && noteFilter === 'pinned') ? `
          <div class="notes-grid">
            ${pinnedNotes.map(renderCard).join('')}
          </div>
        ` : ''}

        ${(noteFilter === 'pinned' && pinnedNotes.length === 0) ? `
          <div class="notes-grid">
            ${renderNewActionCard(true, 'orange')}
          </div>
        ` : ''}

        ${(noteFilter === 'semua') ? `
          <div>
            ${(pinnedNotes.length > 0) ? `
              <div style="display:flex;align-items:center;gap:6px;margin-bottom:12px;font-size:11.5px;font-weight:800;text-transform:uppercase;letter-spacing:0.06em;color:var(--muted);">
                <span>${noteTypeFilter === 'meeting_minutes' ? 'Semua Notulensi Rapat' : (noteTypeFilter === 'semua' ? 'Semua Catatan & Notulensi' : 'Semua Catatan Bersama')}</span>
              </div>
            ` : ''}
            <div class="notes-grid">
              ${otherNotes.length === 0 && pinnedNotes.length === 0 ? renderNewActionCard(true, 'orange') : renderNewActionCard(false, 'orange')}
              ${otherNotes.map(renderCard).join('')}
            </div>
          </div>
        ` : ''}

        ${(isSpecificCat) ? `
          <div>
            <div class="notes-grid">
              ${rows.length === 0 ? renderNewActionCard(true, noteFilter) : renderNewActionCard(false, noteFilter)}
              ${rows.map(renderCard).join('')}
            </div>
          </div>
        ` : ''}
      </div>
    </div>
  `;
}

function renderNoteTagInput(initialTags) {
  let tagsArr = [];
  if (Array.isArray(initialTags)) {
    tagsArr = initialTags;
  } else if (typeof initialTags === 'string' && initialTags.trim()) {
    tagsArr = initialTags.split(/,\s*/);
  }
  tagsArr = tagsArr.map(t => String(t).trim().replace(/^#+/, '')).filter(Boolean).slice(0, 5);

  return `
    <div class="note-tag-wrapper">
      <div class="note-tag-header">
        <label style="font-size:12.5px;font-weight:750;color:var(--muted);text-transform:uppercase;letter-spacing:0.04em;">Tag Tambahan</label>
        <span class="note-tag-count-badge ${tagsArr.length >= 5 ? 'is-max' : ''}" id="noteTagCountBadge">${tagsArr.length}/5 Tag</span>
      </div>
      <div class="note-tag-box" id="noteTagBox" onclick="const el=document.getElementById('noteTagInput');if(el)el.focus();">
        <div id="noteTagChips" style="display:contents;">
          ${tagsArr.map(t => `
            <span class="note-tag-chip" data-tag="${esc(t)}">
              <span>#${esc(t)}</span>
              <span class="note-tag-chip-remove" onclick="removeNoteTag(event, '${esc(t)}')"><i class="fa-solid fa-xmark"></i></span>
            </span>
          `).join('')}
        </div>
        <input class="note-tag-input-field" id="noteTagInput" 
               type="search"
               name="note_tag_box_custom"
               placeholder="${tagsArr.length >= 5 ? 'Batas 5 tag tercapai' : (tagsArr.length === 0 ? 'Ketik tag lalu tekan Enter atau Koma...' : 'Tambah tag...')}" 
               ${tagsArr.length >= 5 ? 'disabled' : ''}
               onkeydown="handleNoteTagKey(event)"
               onblur="handleNoteTagBlur(event)"
               autocomplete="new-password"
               autocorrect="off"
               autocapitalize="off"
               spellcheck="false"
               data-lpignore="true"
               data-form-type="other">
      </div>
      <input type="hidden" id="note_tags" value="${esc(tagsArr.join(', '))}">
      <div style="font-size:11.5px;color:var(--muted);margin-top:5px;font-weight:500;">
        Ketik tag lalu tekan <kbd style="background:rgba(0,0,0,0.06);padding:1px 5px;border-radius:4px;font-size:10.5px;font-weight:700;">Enter</kbd> atau <kbd style="background:rgba(0,0,0,0.06);padding:1px 5px;border-radius:4px;font-size:10.5px;font-weight:700;">,</kbd> (Maksimal 5 tag seperti Instagram)
      </div>
    </div>
  `;
}

window.addNoteTag = function(rawVal) {
  if (!rawVal) return;
  const cleaned = String(rawVal).trim().replace(/^#+/, '').replace(/[,\s]+/g, '').toLowerCase();
  if (!cleaned) return;
  
  let currentTags = getActiveNoteTags();
  if (currentTags.length >= 5) {
    toast('Maksimal 5 tag telah tercapai', 'info');
    return;
  }
  if (currentTags.includes(cleaned)) {
    toast('Tag #' + cleaned + ' sudah ditambahkan', 'info');
    return;
  }
  
  currentTags.push(cleaned);
  syncNoteTags(currentTags);
};

window.removeNoteTag = function(e, tag) {
  if (e) e.stopPropagation();
  let currentTags = getActiveNoteTags();
  currentTags = currentTags.filter(t => t !== tag);
  syncNoteTags(currentTags);
  const input = document.getElementById('noteTagInput');
  if (input) input.focus();
};

window.getActiveNoteTags = function() {
  const hidden = document.getElementById('note_tags');
  if (!hidden || !hidden.value.trim()) return [];
  return hidden.value.split(/,\s*/).map(t => t.trim().replace(/^#+/, '')).filter(Boolean);
};

window.syncNoteTags = function(tags) {
  const hidden = document.getElementById('note_tags');
  if (hidden) hidden.value = tags.join(', ');
  
  const chipsContainer = document.getElementById('noteTagChips');
  if (chipsContainer) {
    chipsContainer.innerHTML = tags.map(t => `
      <span class="note-tag-chip" data-tag="${esc(t)}">
        <span>#${esc(t)}</span>
        <span class="note-tag-chip-remove" onclick="removeNoteTag(event, '${esc(t)}')"><i class="fa-solid fa-xmark"></i></span>
      </span>
    `).join('');
  }
  
  const badge = document.getElementById('noteTagCountBadge');
  if (badge) {
    badge.textContent = `${tags.length}/5 Tag`;
    if (tags.length >= 5) {
      badge.classList.add('is-max');
    } else {
      badge.classList.remove('is-max');
    }
  }
  
  const input = document.getElementById('noteTagInput');
  if (input) {
    if (tags.length >= 5) {
      input.disabled = true;
      input.placeholder = 'Batas 5 tag tercapai';
      input.value = '';
    } else {
      input.disabled = false;
      input.placeholder = tags.length === 0 ? 'Ketik tag lalu tekan Enter atau Koma...' : 'Tambah tag...';
    }
  }
  if (typeof markNoteDirty === 'function') markNoteDirty();
};

window.handleNoteTagKey = function(e) {
  const input = e.target;
  const val = input ? input.value : '';
  
  if (e.key === 'Enter' || e.key === ',' || e.key === ' ') {
    e.preventDefault();
    if (val.trim()) {
      addNoteTag(val);
      input.value = '';
    }
  } else if (e.key === 'Backspace' && !val) {
    let currentTags = getActiveNoteTags();
    if (currentTags.length > 0) {
      removeNoteTag(null, currentTags[currentTags.length - 1]);
    }
  }
};

window.handleNoteTagBlur = function(e) {
  const input = e.target;
  const val = input ? input.value.trim() : '';
  if (val) {
    addNoteTag(val);
    input.value = '';
  }
};

let _savedNoteSelection = null;

window.saveNoteSelection = function() {
  const sel = window.getSelection();
  if (sel && sel.rangeCount > 0) {
    _savedNoteSelection = sel.getRangeAt(0).cloneRange();
  }
};

window.restoreNoteSelection = function() {
  if (_savedNoteSelection) {
    try {
      const sel = window.getSelection();
      sel.removeAllRanges();
      sel.addRange(_savedNoteSelection);
    } catch(err){}
  }
};

window.updateNoteToolbarState = function() {
  const editor = document.getElementById('note_isi_editor');
  if (!editor) return;

  const sel = window.getSelection();
  if (!sel || !sel.anchorNode || !editor.contains(sel.anchorNode)) return;

  const isBold = document.queryCommandState('bold');
  const isItalic = document.queryCommandState('italic');
  const isUnderline = document.queryCommandState('underline');
  const isStrike = document.queryCommandState('strikeThrough');
  const isUl = document.queryCommandState('insertUnorderedList');
  const isOl = document.queryCommandState('insertOrderedList');

  let blockTag = '';
  let curr = sel.anchorNode.nodeType === 1 ? sel.anchorNode : sel.anchorNode.parentElement;
  while (curr && curr !== editor) {
    const tag = curr.tagName ? curr.tagName.toLowerCase() : '';
    if (tag === 'h1' || tag === 'h2' || tag === 'blockquote' || tag === 'p') {
      blockTag = tag;
      break;
    }
    curr = curr.parentElement;
  }
  if (!blockTag) {
    try {
      const fbVal = String(document.queryCommandValue('formatBlock') || '').toLowerCase();
      if (fbVal.includes('h1')) blockTag = 'h1';
      else if (fbVal.includes('h2')) blockTag = 'h2';
      else if (fbVal.includes('blockquote')) blockTag = 'blockquote';
      else if (fbVal.includes('p')) blockTag = 'p';
    } catch(e){}
  }

  const setBtnActive = (id, active) => {
    const btn = document.getElementById(id);
    if (btn) {
      if (active) btn.classList.add('is-active');
      else btn.classList.remove('is-active');
    }
  };

  setBtnActive('btn_note_h1', blockTag === 'h1');
  setBtnActive('btn_note_h2', blockTag === 'h2');
  setBtnActive('btn_note_p', blockTag === 'p' || (!blockTag && !isUl && !isOl));
  setBtnActive('btn_note_bold', isBold);
  setBtnActive('btn_note_italic', isItalic);
  setBtnActive('btn_note_underline', isUnderline);
  setBtnActive('btn_note_strike', isStrike);
  setBtnActive('btn_note_ul', isUl);
  setBtnActive('btn_note_ol', isOl);
  setBtnActive('btn_note_quote', blockTag === 'blockquote');
};

window.toggleNoteFormat = function(type, tagOrCmd) {
  window.restoreNoteSelection();
  const editor = document.getElementById('note_isi_editor');
  if (editor) editor.focus();

  if (type === 'block') {
    const sel = window.getSelection();
    let currentBlock = '';
    if (sel && sel.anchorNode) {
      let curr = sel.anchorNode.nodeType === 1 ? sel.anchorNode : sel.anchorNode.parentElement;
      while (curr && curr !== editor) {
        const t = curr.tagName ? curr.tagName.toLowerCase() : '';
        if (t === 'h1' || t === 'h2' || t === 'blockquote' || t === 'p') {
          currentBlock = t;
          break;
        }
        curr = curr.parentElement;
      }
    }

    const targetTag = tagOrCmd.replace(/[<>]/g, '').toLowerCase();

    // Toggle off: if currently active, reset back to paragraph '<p>'
    if (currentBlock === targetTag && targetTag !== 'p') {
      document.execCommand('formatBlock', false, '<p>');
    } else {
      document.execCommand('formatBlock', false, '<' + targetTag + '>');
    }
  } else {
    document.execCommand(tagOrCmd, false, null);
  }

  window.saveNoteSelection();
  window.updateNoteToolbarState();
  window.hideNoteContextMenu();
  if (editor) editor.focus();
};

window.formatNoteDoc = function(cmd, val) {
  if (cmd === 'formatBlock') {
    window.toggleNoteFormat('block', val);
  } else {
    window.toggleNoteFormat('inline', cmd);
  }
};

window.onNoteLineSpacingSlider = function(val) {
  const num = parseFloat(val) || 0;
  const badge = document.getElementById('val_line_spacing');
  if (badge) {
    badge.textContent = (num > 0 ? '+' : '') + (num === 0 ? '0' : num.toFixed(1));
  }
  const computedLineHeight = Math.max(0.85, 1.65 + (num * 0.25)).toFixed(2);
  window.setNoteLineSpacing(computedLineHeight);
};

window.onNoteLetterSpacingSlider = function(val) {
  const num = parseFloat(val) || 0;
  const badge = document.getElementById('val_letter_spacing');
  if (badge) {
    badge.textContent = (num > 0 ? '+' : '') + (num === 0 ? '0' : num.toFixed(1));
  }
  window.setNoteLetterSpacing(num + 'px');
};

window.resetNoteSpacing = function() {
  const lineSlider = document.getElementById('slider_line_spacing');
  if (lineSlider) lineSlider.value = 0;
  const lineBadge = document.getElementById('val_line_spacing');
  if (lineBadge) lineBadge.textContent = '0';
  window.setNoteLineSpacing('1.65');

  const letterSlider = document.getElementById('slider_letter_spacing');
  if (letterSlider) letterSlider.value = 0;
  const letterBadge = document.getElementById('val_letter_spacing');
  if (letterBadge) letterBadge.textContent = '0';
  window.setNoteLetterSpacing('0px');
};

window.setNoteLineSpacing = function(val) {
  const editor = document.getElementById('note_isi_editor');
  if (!editor) return;

  editor.style.lineHeight = val;
  editor.querySelectorAll('p, h1, h2, h3, li, blockquote, div').forEach(el => {
    el.style.lineHeight = val;
  });
};

window.setNoteLetterSpacing = function(val) {
  const editor = document.getElementById('note_isi_editor');
  if (!editor) return;

  editor.style.letterSpacing = val;
  editor.querySelectorAll('p, h1, h2, h3, li, blockquote, div, span, b, i, u').forEach(el => {
    el.style.letterSpacing = val;
  });
};

window.toggleNoteSpacingMenu = function(e) {
  if (e) e.stopPropagation();
  const menu = document.getElementById('noteSpacingPopover');
  if (menu) {
    menu.classList.toggle('is-open');
  }
};

window.hideNoteSpacingMenu = function() {
  const menu = document.getElementById('noteSpacingPopover');
  if (menu) menu.classList.remove('is-open');
};

window.handleNoteContextMenu = function(e) {
  e.preventDefault();
  window.saveNoteSelection();
  
  let menu = document.getElementById('noteFormattingContextMenu');
  if (!menu) {
    menu = document.createElement('div');
    menu.id = 'noteFormattingContextMenu';
    menu.className = 'note-context-menu';
    document.body.appendChild(menu);
  }

  menu.innerHTML = `
    <div class="note-context-header">Gaya Judul & Teks</div>
    <div class="note-context-item" onclick="toggleNoteFormat('block', 'h1')">
      <span><b>H1</b> &nbsp;Heading 1</span>
      <span class="note-context-sc">Judul</span>
    </div>
    <div class="note-context-item" onclick="toggleNoteFormat('block', 'h2')">
      <span><b>H2</b> &nbsp;Heading 2</span>
      <span class="note-context-sc">Subjudul</span>
    </div>
    <div class="note-context-item" onclick="toggleNoteFormat('block', 'p')">
      <span><i class="fa-solid fa-paragraph"></i> &nbsp;Paragraf</span>
      <span class="note-context-sc">Normal</span>
    </div>

    <div class="note-context-divider"></div>
    <div class="note-context-header">Format Huruf</div>
    <div class="note-context-item" onclick="toggleNoteFormat('inline', 'bold')">
      <span><i class="fa-solid fa-bold" style="width:14px;"></i> &nbsp;Tebal (Bold)</span>
      <span class="note-context-sc">Ctrl+B</span>
    </div>
    <div class="note-context-item" onclick="toggleNoteFormat('inline', 'italic')">
      <span><i class="fa-solid fa-italic" style="width:14px;"></i> &nbsp;Miring (Italic)</span>
      <span class="note-context-sc">Ctrl+I</span>
    </div>
    <div class="note-context-item" onclick="toggleNoteFormat('inline', 'underline')">
      <span><i class="fa-solid fa-underline" style="width:14px;"></i> &nbsp;Garis Bawah</span>
      <span class="note-context-sc">Ctrl+U</span>
    </div>
    <div class="note-context-item" onclick="toggleNoteFormat('inline', 'strikeThrough')">
      <span><i class="fa-solid fa-strikethrough" style="width:14px;"></i> &nbsp;Coret (Strike)</span>
    </div>

    <div class="note-context-divider"></div>
    <div class="note-context-header">Daftar & Format</div>
    <div class="note-context-item" onclick="toggleNoteFormat('inline', 'insertUnorderedList')">
      <span><i class="fa-solid fa-list-ul" style="width:14px;"></i> &nbsp;Daftar Poin</span>
    </div>
    <div class="note-context-item" onclick="toggleNoteFormat('inline', 'insertOrderedList')">
      <span><i class="fa-solid fa-list-ol" style="width:14px;"></i> &nbsp;Daftar Nomor</span>
    </div>
    <div class="note-context-item" onclick="toggleNoteFormat('block', 'blockquote')">
      <span><i class="fa-solid fa-quote-left" style="width:14px;"></i> &nbsp;Kutipan (Quote)</span>
    </div>

    <div class="note-context-divider"></div>
    <div class="note-context-item" onclick="toggleNoteFormat('inline', 'removeFormat')">
      <span><i class="fa-solid fa-eraser" style="width:14px;"></i> &nbsp;Hapus Format</span>
    </div>
  `;

  menu.style.display = 'flex';
  
  const menuWidth = 205;
  const menuHeight = 360;
  let posX = e.clientX;
  let posY = e.clientY;

  if (posX + menuWidth > window.innerWidth) {
    posX = window.innerWidth - menuWidth - 12;
  }
  if (posY + menuHeight > window.innerHeight) {
    posY = window.innerHeight - menuHeight - 12;
  }

  menu.style.left = `${Math.max(10, posX)}px`;
  menu.style.top = `${Math.max(10, posY)}px`;
};

window.hideNoteContextMenu = function() {
  const menu = document.getElementById('noteFormattingContextMenu');
  if (menu) menu.style.display = 'none';
};

if (!window._noteContextMenuGlobalInit) {
  window._noteContextMenuGlobalInit = true;
  document.addEventListener('click', function(e) {
    const menu = document.getElementById('noteFormattingContextMenu');
    if (menu && !menu.contains(e.target)) {
      menu.style.display = 'none';
    }
    const spMenu = document.getElementById('noteSpacingPopover');
    if (spMenu && !spMenu.contains(e.target)) {
      spMenu.classList.remove('is-open');
    }
  });
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') {
      window.hideNoteContextMenu();
      window.hideNoteSpacingMenu();
    }
  });
  document.addEventListener('selectionchange', function() {
    window.updateNoteToolbarState();
  });
}

