function extractTitleFromContent(html) {
  if (!html) return 'Tanpa Judul';
  const clean = html.replace(/<!--\s*PTV_META:[\s\S]*?-->/g, '');
  const temp = document.createElement('div');
  temp.innerHTML = clean;
  
  const heading = temp.querySelector('h1, h2, h3, h4');
  if (heading && heading.textContent.trim()) {
    return heading.textContent.trim().substring(0, 90);
  }
  
  const text = (temp.textContent || temp.innerText || '').trim();
  if (!text) return 'Tanpa Judul';
  const firstLine = text.split('\n').map(l => l.trim()).filter(Boolean)[0];
  return (firstLine || 'Tanpa Judul').substring(0, 90);
}

function renderNoteDetailContent(content) {
  if (!content) return '';
  const clean = String(content).replace(/<!--\s*PTV_META:[\s\S]*?-->/g, '').trim();
  if (/<(p|h[1-6]|ul|ol|li|strong|b|em|i|u|blockquote|br|div)[^>]*>/i.test(clean)) {
    return clean;
  }
  return esc(clean).replace(/\n/g, '<br>');
}

function isNoteExecutive() {
  const r = normRole(state.role || (typeof ME !== 'undefined' && ME.role));
  return r === 'eksekutif' || r === 'administrasi';
}

function canUserEditNote(n) {
  if (!n) return false;
  if (isNoteExecutive()) return true;
  const myId = String((typeof ME !== 'undefined' && ME.id) || '').trim();
  const myName = String((typeof ME !== 'undefined' && ME.name) || '').trim().toLowerCase();
  const creatorId = String(n.created_by_id || '').trim();
  const creatorName = String(n.created_by_name || '').trim().toLowerCase();
  if (myId && creatorId && myId === creatorId) return true;
  if (myName && creatorName && myName === creatorName) return true;
  return false;
}

function openLinkEventNoteModal(eventId){
  const e = (DB.events||[]).find(x => String(x.id) === String(eventId));
  if(!e) return;
  const isExec = ['eksekutif','executive'].includes(normRole(state.role || ME.role));
  const isAdmin = ['administrasi','admin'].includes(normRole(state.role || ME.role));
  if(!isExec && !isAdmin){
    toast('Hanya Eksekutif dan Administrasi yang berwenang menautkan notulensi.', 'alert');
    return;
  }

  const allMeetingNotes = (DB.notes || []).filter(n => {
    return (typeof getNoteType === 'function' ? getNoteType(n) : n.tipe) === 'meeting_minutes' || (Array.isArray(n.tags) && n.tags.includes('notulensi'));
  });

  const renderNoteOptions = (query = '') => {
    const q = (query || '').toLowerCase().trim();
    let filtered = allMeetingNotes;
    if(q){
      filtered = filtered.filter(n => {
        const titleMatch = (n.judul || '').toLowerCase().includes(q);
        const snippetMatch = (n.isi || '').toLowerCase().includes(q);
        const tagMatch = Array.isArray(n.tags) && n.tags.some(t => t.toLowerCase().includes(q));
        return titleMatch || snippetMatch || tagMatch;
      });
    }

    if(!filtered.length){
      return `
        <div style="text-align:center;padding:32px 16px;color:#64748b;">
          <i class="fa-solid fa-clipboard-question" style="font-size:26px;color:#cbd5e1;display:block;margin-bottom:8px;"></i>
          ${allMeetingNotes.length === 0 ? 'Belum ada Notulensi Rapat yang tercatat di sistem Catatan Bersama.' : 'Tidak ada notulensi yang cocok dengan pencarian.'}
        </div>
      `;
    }

    return filtered.map(n => {
      const isAlreadyLinked = getEventRelatedNotulensi(e).some(x => String(x.id) === String(n.id));
      const meta = (typeof extractMeetingMeta === 'function' ? extractMeetingMeta(n.isi) : null) || {};
      const mDate = meta.date ? fmtDate(meta.date) : fmtDate(n.updated_at || n.created_at);
      const snippet = (typeof formatNotePreview === 'function' ? formatNotePreview(n.isi) : (n.isi || '').replace(/<[^>]+>/g, '').trim());
      const shortSnippet = snippet.length > 140 ? snippet.slice(0, 140) + '...' : snippet;

      return `
        <div style="padding:14px;border-radius:14px;border:1.5px solid ${isAlreadyLinked ? '#2563eb' : '#e2e8f0'};background:${isAlreadyLinked ? '#f0f7ff' : '#ffffff'};display:flex;flex-direction:column;gap:8px;box-shadow:${isAlreadyLinked ? '0 2px 8px rgba(37,99,235,0.08)' : 'none'};">
          <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:10px;">
            <div style="flex:1;min-width:0;">
              <div style="display:flex;align-items:center;gap:6px;margin-bottom:4px;flex-wrap:wrap;">
                <span style="font-size:10.5px;font-weight:750;background:${isAlreadyLinked ? '#dbeafe' : 'rgba(37,99,235,0.08)'};color:#1e40af;padding:2px 8px;border-radius:999px;">
                  <i class="fa-solid fa-handshake" style="margin-right:3px;"></i>${esc(mDate)}
                </span>
                ${isAlreadyLinked ? `<span class="chip" style="background:#2563eb;color:#fff;font-size:10px;padding:2px 7px;font-weight:700;"><i class="fa-solid fa-check" style="margin-right:3px;"></i>Terkait Acara Ini</span>` : ''}
              </div>
              <h4 style="margin:0 0 4px;font-size:14px;font-weight:750;color:#0f172a;line-height:1.35;">${esc(n.judul || 'Notulensi Rapat')}</h4>
              ${shortSnippet ? `<p style="margin:0;font-size:12px;color:#64748b;line-height:1.45;">${esc(shortSnippet)}</p>` : ''}
            </div>
            <div style="flex-shrink:0;">
              ${isAlreadyLinked ? `
                <button type="button" class="btn sm" data-act="unlinkNoteFromEvent:${e.id}:${n.id}" style="color:#ef4444;border:1px solid rgba(239,68,68,0.25);background:rgba(239,68,68,0.06);font-size:11px;font-weight:650;padding:5px 12px;border-radius:8px;">
                  <i class="fa-solid fa-link-slash" style="margin-right:4px;"></i>Lepas
                </button>
              ` : `
                <button type="button" class="btn sm pri" data-act="linkNoteToEvent:${e.id}:${n.id}" style="font-size:11px;font-weight:700;padding:5px 12px;border-radius:8px;background:#2563eb;color:#fff;">
                  <i class="fa-solid fa-link" style="margin-right:4px;"></i>Pilih
                </button>
              `}
            </div>
          </div>
        </div>
      `;
    }).join('');
  };

  openSheet('Pilih Notulensi untuk Ditautkan',
    `<div class="tight" style="background:#f8fafc;padding:12px 14px;border-radius:12px;border:1px solid #e2e8f0;margin-bottom:14px;">
      <div style="font-size:11px;font-weight:750;color:#2563eb;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:2px;">Acara Target</div>
      <div style="font-weight:750;font-size:14px;color:#0f172a;">${esc(e.name)}</div>
      <p style="margin:4px 0 0;font-size:11.5px;color:#64748b;line-height:1.4;">Pilih notulensi rapat yang sudah ada untuk dihubungkan ke acara ini.</p>
    </div>
    <div class="searchbar" style="margin-bottom:14px;">
      ${ic.search}
      <input id="noteLinkSearchIn" placeholder="Cari judul notulensi..." autocomplete="off">
    </div>
    <div id="noteLinkListWrap" style="max-height:400px;overflow-y:auto;display:flex;flex-direction:column;gap:10px;">
      ${renderNoteOptions()}
    </div>`,
    {
      foot: `<button class="btn block" data-act="closeSheet" style="border-radius:12px;">Tutup</button>`,
      then: (sheetBody) => {
        const searchIn = sheetBody.querySelector('#noteLinkSearchIn');
        const wrap = sheetBody.querySelector('#noteLinkListWrap');
        if (searchIn && wrap) {
          searchIn.addEventListener('input', () => {
            wrap.innerHTML = renderNoteOptions(searchIn.value);
          });
        }
      }
    }
  );
}

function linkNoteToEvent(eventId, noteId){
  const e = (DB.events||[]).find(x => String(x.id) === String(eventId));
  const n = (DB.notes||[]).find(x => String(x.id) === String(noteId));
  if(!e || !n) return;

  const isExec = ['eksekutif','executive'].includes(normRole(state.role || ME.role));
  const isAdmin = ['administrasi','admin'].includes(normRole(state.role || ME.role));
  if(!isExec && !isAdmin){
    toast('Hanya Eksekutif dan Administrasi yang berwenang menautkan notulensi.', 'alert');
    return;
  }

  let cleanHtml = (n.isi || '').replace(/<!--\s*PTV_META:[\s\S]*?-->/g, '').trim();
  const metaObj = (typeof extractMeetingMeta === 'function' ? extractMeetingMeta(n.isi) : null) || {};
  metaObj.type = 'meeting_minutes';
  metaObj.event_id = String(eventId);
  metaObj.event_name = e.name;
  cleanHtml += `\n<!-- PTV_META:${JSON.stringify(metaObj)} -->`;

  let tags = Array.isArray(n.tags) ? [...n.tags] : (typeof n.tags === 'string' && n.tags ? n.tags.split(/,\s*/) : []);
  if (!tags.includes('notulensi')) tags.push('notulensi');
  if (!tags.includes('acara_' + eventId)) tags.push('acara_' + eventId);

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_save_note');
  fd.append('id', n.id);
  fd.append('tipe', 'meeting_minutes');
  fd.append('judul', n.judul || 'Notulensi Rapat');
  fd.append('isi', cleanHtml);
  fd.append('warna', n.warna || 'orange');
  fd.append('tags', JSON.stringify(tags));
  fd.append('is_pinned', n.is_pinned ? '1' : '0');
  if (typeof PTV_NONCE !== 'undefined' && PTV_NONCE) fd.append('nonce', PTV_NONCE);

  fetch(AJAX_URL, { method: 'POST', body: fd, credentials: 'same-origin' })
    .then(r => r.json())
    .then(res => {
      if(res && res.success && res.data?.note){
        const idx = DB.notes.findIndex(x => String(x.id) === String(n.id));
        if (idx !== -1) DB.notes[idx] = Object.assign({}, DB.notes[idx], res.data.note);
        toast('Notulensi berhasil ditautkan ke acara.', 'check');
        closeSheet();
        render();
      } else {
        toast(res?.data?.message || 'Gagal menautkan notulensi.', 'alert');
      }
    })
    .catch(err => {
      console.error('[PTV Link Note Error]', err);
      toast('Terjadi kendala koneksi.', 'alert');
    });
}

function unlinkNoteFromEvent(eventId, noteId){
  const n = (DB.notes||[]).find(x => String(x.id) === String(noteId));
  if(!n) return;

  const isExec = ['eksekutif','executive'].includes(normRole(state.role || ME.role));
  const isAdmin = ['administrasi','admin'].includes(normRole(state.role || ME.role));
  if(!isExec && !isAdmin){
    toast('Hanya Eksekutif dan Administrasi yang berwenang melepas tautan notulensi.', 'alert');
    return;
  }

  let cleanHtml = (n.isi || '').replace(/<!--\s*PTV_META:[\s\S]*?-->/g, '').trim();
  const metaObj = (typeof extractMeetingMeta === 'function' ? extractMeetingMeta(n.isi) : null) || {};
  if (metaObj.event_id === String(eventId)) {
    delete metaObj.event_id;
    delete metaObj.event_name;
  }
  cleanHtml += `\n<!-- PTV_META:${JSON.stringify(metaObj)} -->`;

  let tags = Array.isArray(n.tags) ? [...n.tags] : (typeof n.tags === 'string' && n.tags ? n.tags.split(/,\s*/) : []);
  tags = tags.filter(t => t !== ('acara_' + eventId) && t !== ('event_' + eventId));

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_save_note');
  fd.append('id', n.id);
  fd.append('tipe', 'meeting_minutes');
  fd.append('judul', n.judul || 'Notulensi Rapat');
  fd.append('isi', cleanHtml);
  fd.append('warna', n.warna || 'orange');
  fd.append('tags', JSON.stringify(tags));
  fd.append('is_pinned', n.is_pinned ? '1' : '0');
  if (typeof PTV_NONCE !== 'undefined' && PTV_NONCE) fd.append('nonce', PTV_NONCE);

  fetch(AJAX_URL, { method: 'POST', body: fd, credentials: 'same-origin' })
    .then(r => r.json())
    .then(res => {
      if(res && res.success && res.data?.note){
        const idx = DB.notes.findIndex(x => String(x.id) === String(n.id));
        if (idx !== -1) DB.notes[idx] = Object.assign({}, DB.notes[idx], res.data.note);
        toast('Tautan notulensi berhasil dilepas.', 'check');
        closeSheet();
        render();
      } else {
        toast(res?.data?.message || 'Gagal melepas tautan notulensi.', 'alert');
      }
    })
    .catch(err => {
      console.error('[PTV Unlink Note Error]', err);
      toast('Terjadi kendala koneksi.', 'alert');
    });
}

function openNewNote(presetTag, presetCategory, presetType){
  let initialCategory = 'orange';
  let initialTag = '';
  let initialType = presetType || (noteTypeFilter === 'meeting_minutes' ? 'meeting_minutes' : 'shared');

  if (typeof presetTag === 'string' && presetTag.includes(':')) {
    const parts = presetTag.split(':');
    presetTag = parts[0];
    if (parts[1]) initialType = parts[1];
  }

  let selectedEventId = '';
  if (typeof presetTag === 'string' && presetTag.startsWith('acara_')) {
    selectedEventId = presetTag.replace('acara_', '');
  }

  if (presetCategory && NOTE_CATEGORIES[presetCategory]) {
    initialCategory = presetCategory;
  } else if (presetTag && NOTE_CATEGORIES[presetTag]) {
    initialCategory = presetTag;
  } else if (presetTag) {
    initialTag = presetTag;
  }

  const isExec = isNoteExecutive();
  const todayIso = new Date().toISOString().split('T')[0];
  const evObj = selectedEventId ? (DB.events || []).find(x => String(x.id) === String(selectedEventId)) : null;

  let initialEditorHtml = '';
  if (initialType === 'meeting_minutes') {
    const evTitle = evObj ? evObj.name : '';
    const evDate = evObj ? (evObj.date || todayIso) : todayIso;
    const evLoc = evObj ? (evObj.loc || 'Studio PTV') : 'Studio PTV / Google Meet';
    const evCrew = (evObj && Array.isArray(evObj.crew) && evObj.crew.length)
      ? evObj.crew.map(c => typeof c === 'object' ? c.name : c).filter(Boolean).join(', ')
      : 'Tim PTV';
    initialEditorHtml = `<h1>Notulensi Rapat: ${esc(evTitle)}</h1>
<p><strong>Hari / Tanggal:</strong> ${esc(fmtDate(evDate))}<br>
<strong>Waktu:</strong> ${esc(evObj?.time || '09:00 - 11:00 WIB')}<br>
<strong>Tempat / Media:</strong> ${esc(evLoc)}<br>
<strong>Peserta:</strong> ${esc(evCrew)}</p>

<h2>1. Agenda Pembahasan</h2>
<p>• Persiapan teknis & operasional ${esc(evTitle || 'acara')}</p>

<h2>2. Pembahasan & Keputusan Rapat</h2>
<p>• </p>

<h2>3. Tindak Lanjut (Action Items)</h2>
<p>• </p>`;
  }

  openSheet(initialType === 'meeting_minutes' ? 'Tambah Notulensi Rapat' : 'Tambah Catatan Bersama', `
    <div style="display:flex;flex-direction:column;gap:18px;">
      <!-- Pilihan Jenis Catatan: Catatan Bersama vs Notulensi Rapat -->
      <div>
        <label style="font-size:12.5px;font-weight:750;color:var(--muted);text-transform:uppercase;letter-spacing:0.04em;display:block;margin-bottom:8px;">Jenis Catatan</label>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">
          <label id="lbl_type_shared" style="display:flex;align-items:flex-start;gap:10px;padding:12px 14px;border-radius:14px;border:1.5px solid ${initialType === 'shared' ? '#2563eb' : 'var(--line-2, #e2e8f0)'};background:${initialType === 'shared' ? 'rgba(37,99,235,0.08)' : 'transparent'};cursor:pointer;transition:all 0.15s ease;">
            <input type="radio" name="note_tipe_choice" value="shared" ${initialType === 'shared' ? 'checked' : ''} onchange="onNoteTypeChoiceChange(this.value)" style="accent-color:#2563eb;width:17px;height:17px;margin-top:2px;">
            <div>
              <div style="font-size:13.5px;font-weight:800;color:var(--ink);display:flex;align-items:center;gap:6px;">
                <i class="fa-solid fa-note-sticky" style="color:#2563eb;font-size:12px;"></i>
                <span>Catatan Bersama</span>
              </div>
              <div style="font-size:11.5px;color:var(--muted);margin-top:2px;line-height:1.35;">SOP, ide, panduan operasional & info tim</div>
            </div>
          </label>
          <label id="lbl_type_meeting" style="display:flex;align-items:flex-start;gap:10px;padding:12px 14px;border-radius:14px;border:1.5px solid ${initialType === 'meeting_minutes' ? '#2563eb' : 'var(--line-2, #e2e8f0)'};background:${initialType === 'meeting_minutes' ? 'rgba(37,99,235,0.08)' : 'transparent'};cursor:pointer;transition:all 0.15s ease;">
            <input type="radio" name="note_tipe_choice" value="meeting_minutes" ${initialType === 'meeting_minutes' ? 'checked' : ''} onchange="onNoteTypeChoiceChange(this.value)" style="accent-color:#2563eb;width:17px;height:17px;margin-top:2px;">
            <div>
