            <label style="font-size:11.5px;font-weight:700;color:var(--muted);display:block;margin-bottom:4px;">Waktu Rapat</label>
            <input type="text" id="note_meeting_time" class="input" value="${esc(evObj?.time || '')}" placeholder="Misal: 09:00 - 11:30 WIB" style="font-size:13px;padding:8px 10px;border-radius:8px;width:100%;">
          </div>
          <div>
            <label style="font-size:11.5px;font-weight:700;color:var(--muted);display:block;margin-bottom:4px;">Tempat / Media</label>
            <input type="text" id="note_meeting_location" class="input" value="${esc(evObj?.loc || '')}" placeholder="Misal: Studio PTV / Zoom" style="font-size:13px;padding:8px 10px;border-radius:8px;width:100%;">
          </div>
