  `, {
    foot: `<button type="button" class="btn block pri" data-act="saveNewNote" style="background:#2563eb;color:#fff;border-radius:14px;padding:13px;font-weight:750;font-size:14.5px;box-shadow:0 4px 14px rgba(37,99,235,0.28);border:none;cursor:pointer;"><i class="fa-solid fa-check" style="margin-right:6px;"></i> Simpan Catatan</button>`
  });
  if (typeof window.noteAutoSaveManager !== 'undefined') {
    window.noteAutoSaveManager.init(false, null);
  }
}

function openEditNote(id){
  const n = noteById(id);
  if(!n) return;

  if(!canUserEditNote(n)){
    toast('Anda hanya dapat mengedit catatan yang Anda buat sendiri.', 'info');
    return;
  }

  const currentType = getNoteType(n);
  const cat = getNoteCategory(n);
  const isExec = isNoteExecutive();
  const metaObj = extractMeetingMeta(n.isi) || {};
  let selectedEventId = metaObj.event_id || '';
  if (!selectedEventId && Array.isArray(n.tags)) {
    const evTag = n.tags.find(t => t.startsWith('acara_') || t.startsWith('event_'));
    if (evTag) selectedEventId = evTag.replace(/^(acara_|event_)/, '');
  }
  
  let initialHtml = n.isi || '';
  // Clean out PTV_META comment from editable HTML so it doesn't clutter user's view
  initialHtml = initialHtml.replace(/<!--\s*PTV_META:[\s\S]*?-->/g, '').trim();

  if (initialHtml && !/<(p|h[1-6]|ul|ol|li|div|br)[^>]*>/i.test(initialHtml)) {
    if (n.judul && n.judul !== 'Tanpa Judul' && !initialHtml.startsWith(n.judul)) {
      initialHtml = `<h2>${esc(n.judul)}</h2><p>${esc(initialHtml).replace(/\n/g, '<br>')}</p>`;
    } else {
      initialHtml = `<p>${esc(initialHtml).replace(/\n/g, '<br>')}</p>`;
    }
  }

  openSheet(currentType === 'meeting_minutes' ? 'Edit Notulensi Rapat' : 'Edit Catatan Bersama', `
    <div style="display:flex;flex-direction:column;gap:18px;">
      <!-- Pilihan Jenis Catatan: Catatan Bersama vs Notulensi Rapat -->
      <div>
        <label style="font-size:12.5px;font-weight:750;color:var(--muted);text-transform:uppercase;letter-spacing:0.04em;display:block;margin-bottom:8px;">Jenis Catatan</label>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">
          <label id="lbl_type_shared" style="display:flex;align-items:flex-start;gap:10px;padding:12px 14px;border-radius:14px;border:1.5px solid ${currentType === 'shared' ? '#2563eb' : 'var(--line-2, #e2e8f0)'};background:${currentType === 'shared' ? 'rgba(37,99,235,0.08)' : 'transparent'};cursor:pointer;transition:all 0.15s ease;">
            <input type="radio" name="note_tipe_choice" value="shared" ${currentType === 'shared' ? 'checked' : ''} onchange="onNoteTypeChoiceChange(this.value)" style="accent-color:#2563eb;width:17px;height:17px;margin-top:2px;">
            <div>
              <div style="font-size:13.5px;font-weight:800;color:var(--ink);display:flex;align-items:center;gap:6px;">
                <i class="fa-solid fa-note-sticky" style="color:#2563eb;font-size:12px;"></i>
                <span>Catatan Bersama</span>
