  });
  if (typeof window.noteAutoSaveManager !== 'undefined') {
    window.noteAutoSaveManager.init(true, id);
  }
}

function openNoteDetail(id){
  const n = noteById(id);
  if(!n) return;

  const isMeeting = getNoteType(n) === 'meeting_minutes';
  const cat = getNoteCategory(n);
  const tagsArr = Array.isArray(n.tags) ? n.tags : (typeof n.tags === 'string' && n.tags.trim() ? n.tags.split(/,\s*/) : []);
  const canEdit = canUserEditNote(n);
  const canPin = isNoteExecutive();
  const canDelete = isNoteExecutive();
  const metaObj = isMeeting ? extractMeetingMeta(n.isi) : null;

  // Clean out PTV_META comment from rendered body
  let cleanIsi = (n.isi || '').replace(/<!--\s*PTV_META:[\s\S]*?-->/g, '').trim();

  openSheet(isMeeting ? 'Notulensi Rapat' : 'Catatan Tim', `
    <div style="background:${cat.bg};padding:26px 24px;border-radius:22px;color:${cat.text};box-shadow:0 10px 30px rgba(0,0,0,0.06);border:1px solid rgba(0,0,0,0.04);display:flex;flex-direction:column;gap:16px;">
      <!-- Header: Kategori & Pin Badge -->
      <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;">
        <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;">
          <span style="display:inline-flex;align-items:center;gap:6px;padding:4px 12px;border-radius:999px;background:${cat.pillBg};color:${cat.pillText};font-size:12px;font-weight:800;letter-spacing:0.02em;">
            <i class="fa-solid ${cat.icon}"></i> ${esc(cat.label)}
          </span>
          ${isMeeting ? `
            <span class="note-type-badge-pill" style="padding:4px 12px;font-size:11.5px;">
              <i class="fa-solid fa-handshake"></i> Notulensi Rapat
            </span>
          ` : ''}
        </div>
        ${n.is_pinned ? `<span class="note-pin-badge" style="background:${cat.pillBg};color:${cat.pillText};"><i class="fa-solid fa-thumbtack" style="font-size:11.5px;transform:rotate(-30deg);"></i></span>` : ''}
      </div>

      <!-- Judul Catatan -->
      <div>
        <h2 style="margin:0 0 8px;font-size:24px;font-weight:850;color:${cat.text};line-height:1.25;word-break:break-word;letter-spacing:-0.025em;">
          ${esc(n.judul || 'Tanpa Judul')}
        </h2>
        <div style="display:flex;align-items:center;gap:8px;font-size:12.5px;color:${cat.meta};font-weight:650;flex-wrap:wrap;">
          <span>Ditulis oleh <strong>${esc(n.created_by_name || 'Kru PTV')}</strong></span>
          <span>&bull;</span>
          <span>${fmtDate(n.updated_at || n.created_at, true)}</span>
        </div>
      </div>

      <!-- Detail Atribut Rapat jika ada -->
      ${metaObj && (metaObj.date || metaObj.time || metaObj.loc || metaObj.att || metaObj.event_id) ? `
        <div style="background:${cat.pillBg};border-radius:12px;padding:12px 14px;font-size:13px;line-height:1.6;display:grid;grid-template-columns:repeat(auto-fit, minmax(180px, 1fr));gap:8px;">
          ${metaObj.date ? `<div><span style="opacity:0.8;font-size:11.5px;font-weight:600;display:block;">Tanggal:</span><strong>${fmtDate(metaObj.date)}</strong></div>` : ''}
          ${metaObj.time ? `<div><span style="opacity:0.8;font-size:11.5px;font-weight:600;display:block;">Waktu:</span><strong>${esc(metaObj.time)}</strong></div>` : ''}
          ${metaObj.loc ? `<div><span style="opacity:0.8;font-size:11.5px;font-weight:600;display:block;">Tempat/Media:</span><strong>${esc(metaObj.loc)}</strong></div>` : ''}
          ${metaObj.att ? `<div><span style="opacity:0.8;font-size:11.5px;font-weight:600;display:block;">Peserta:</span><strong>${esc(metaObj.att)}</strong></div>` : ''}
          ${metaObj.event_id ? `<div style="grid-column:1 / -1;"><span style="opacity:0.8;font-size:11.5px;font-weight:600;display:block;">Terkait Acara:</span><button class="link" data-go="acaraDetail:${esc(metaObj.event_id)}" style="color:inherit;text-decoration:underline;font-weight:750;display:inline-flex;align-items:center;gap:4px;cursor:pointer;"><i class="fa-solid fa-calendar-check" style="font-size:11px;"></i>${esc(metaObj.event_name || 'Buka Detail Acara')}</button></div>` : ''}
        </div>
      ` : ''}

      <!-- Tag Metadata -->
      ${tagsArr.length ? `
        <div style="display:flex;flex-wrap:wrap;gap:6px;">
          ${tagsArr.map(t => `<span style="font-size:11.5px;padding:3px 10px;background:${cat.pillBg};color:${cat.pillText};border-radius:999px;font-weight:700;">#${esc(t)}</span>`).join('')}
        </div>
      ` : ''}

      <div style="height:1px;background:${cat.pillBg};margin:2px 0;"></div>

      <!-- Isi Catatan (Render Rich HTML) -->
      <div class="note-detail-body" style="font-size:15px;line-height:1.7;color:${cat.body};word-break:break-word;text-align:left;font-family:inherit;">
        ${renderNoteDetailContent(cleanIsi)}
      </div>
    </div>
  `, {
    foot: `
      <div class="wrap" style="width:100%;display:flex;justify-content:space-between;gap:8px;align-items:center;">
        <div style="display:flex;gap:6px;align-items:center;">
          ${canPin ? `<button class="btn sm" data-act="togglePinNote:${n.id}">${n.is_pinned ? '<i class="fa-solid fa-thumbtack" style="margin-right:4px;"></i> Lepas Sematan' : '<i class="fa-solid fa-thumbtack" style="margin-right:4px;transform:rotate(-30deg);"></i> Sematkan'}</button>` : ''}
          ${canDelete ? `<button class="btn sm dang" data-act="confirmDeleteNote:${n.id}"><i class="fa-solid fa-trash"></i> Hapus</button>` : ''}
        </div>
        <div>
          ${canEdit ? `<button class="btn sm pri" data-act="openEditNote:${n.id}" style="background:#2563eb;color:#fff;font-weight:750;border-radius:12px;padding:8px 18px;border:none;cursor:pointer;box-shadow:0 2px 8px rgba(37,99,235,0.25);"><i class="fa-solid fa-pen-to-square" style="margin-right:4px;"></i> Edit ${isMeeting ? 'Notulensi' : 'Catatan'}</button>` : ''}
        </div>
      </div>
    `
  });
}

let _isSavingNoteLock = false;
async function saveNote(isEdit, id){
  if (_isSavingNoteLock) {
    console.warn('[NOTE CREATE] Double-submit prevented by lock');
    return;
  }
  _isSavingNoteLock = true;

  const pendingTagInput = document.getElementById('noteTagInput');
  if (pendingTagInput && pendingTagInput.value.trim()) {
    if (typeof addNoteTag === 'function') addNoteTag(pendingTagInput.value);
    pendingTagInput.value = '';
  }

  const editor = document.getElementById('note_isi_editor');
  let rawHtml = editor ? editor.innerHTML.trim() : '';
  const textCheck = editor ? (editor.textContent || editor.innerText || '').trim() : '';

  if(!textCheck && !rawHtml){
    toast('Isi catatan tidak boleh kosong.', 'info');
    _isSavingNoteLock = false;
    return;
  }

  // Bersihkan debounce timer dari NoteAutoSaveManager agar tidak ada concurrent race condition
  if (typeof window.noteAutoSaveManager !== 'undefined') {
    window.noteAutoSaveManager.clearTimer();
  }

  const tipe = $('#note_tipe')?.value === 'meeting_minutes' ? 'meeting_minutes' : 'shared';
  let cleanHtml = rawHtml.replace(/<!--\s*PTV_META:[\s\S]*?-->/g, '').trim();
  const judul = (typeof extractTitleFromContent === 'function' ? extractTitleFromContent(cleanHtml) : '') || (tipe === 'meeting_minutes' ? 'Notulensi Rapat' : 'Catatan');
  const warna = $('#note_warna')?.value || 'orange';
  const rawTags = ($('#note_tags')?.value || '').trim();
  let tags = rawTags ? rawTags.split(/,\s*/).map(s => s.trim().replace(/^#+/, '')).filter(Boolean) : [];

  if (tipe === 'meeting_minutes') {
    if (!tags.includes('notulensi')) tags.push('notulensi');
    const mDate = $('#note_meeting_date')?.value || '';
    const mTime = $('#note_meeting_time')?.value || '';
    const mLoc  = $('#note_meeting_location')?.value || '';
    const mAtt  = $('#note_meeting_attendees')?.value || '';
    const mEventId = $('#note_meeting_event')?.value || '';
    const mEventObj = mEventId ? eventById(mEventId) : null;
    if (mEventId && !tags.includes('acara_' + mEventId)) {
      tags.push('acara_' + mEventId);
    }
    const metaPayload = {
      type: 'meeting_minutes',
      date: mDate,
      time: mTime,
      loc: mLoc,
      att: mAtt,
      event_id: mEventId || '',
      event_name: mEventObj?.name || ''
    };
    cleanHtml += `\n<!-- PTV_META:${JSON.stringify(metaPayload)} -->`;
  } else {
    tags = tags.filter(t => t !== 'notulensi' && t !== 'notulensi_rapat' && t !== 'notulen');
  }

  const isi = cleanHtml;
  
  let originalNote = null;
  const targetId = (isEdit && id) ? String(id) : null;
  const isActualEdit = !!(isEdit && targetId && targetId !== 'null' && !targetId.startsWith('note_'));

  if (isActualEdit && DB.notes) {
    originalNote = DB.notes.find(x => String(x.id) === String(targetId));
  }

  let is_pinned = 0;
  if (isNoteExecutive()) {
    is_pinned = $('#note_is_pinned')?.checked ? 1 : 0;
  } else if (originalNote) {
    is_pinned = originalNote.is_pinned ? 1 : 0;
  }

  // 1. UI Feedback: Disable button & show spinner
  const saveBtn = document.querySelector('#sheetFoot button[data-act^="save"]') || document.querySelector('#sheetFoot button');
  const origBtnHtml = saveBtn ? saveBtn.innerHTML : '';
  if (saveBtn) {
    saveBtn.disabled = true;
    saveBtn.style.pointerEvents = 'none';
    saveBtn.innerHTML = `<i class="fa-solid fa-spinner fa-spin" style="margin-right:6px;"></i> Menyimpan...`;
  }

  console.log('[NOTE CREATE] client request', { isEdit: isActualEdit, id: targetId, judul: judul, tipe: tipe });

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_save_note');
  if (isActualEdit) fd.append('id', targetId);
  fd.append('tipe', tipe);
  fd.append('judul', judul);
  fd.append('isi', isi);
  fd.append('warna', warna);
  fd.append('tags', JSON.stringify(tags));
  fd.append('is_pinned', is_pinned ? '1' : '0');
  if (typeof PTV_NONCE !== 'undefined' && PTV_NONCE) fd.append('nonce', PTV_NONCE);

  try {
    const res = await fetch(AJAX_URL, {
      method: 'POST',
      body: fd,
      credentials: 'same-origin'
    }).then(r => r.json());

    if (res && res.success && res.data?.note) {
      const real = res.data.note;
      const realId = String(real.id || '');
      console.log('[NOTE CREATE SUCCESS] id:', realId);

      if (realId && typeof window._markLocalMutation === 'function') {
        window._markLocalMutation(realId);
      }

      if (!DB.notes) DB.notes = [];
      const beforeCount = DB.notes.length;

      // Single Source of Truth: Reconcile by canonical UUID
      const idx = DB.notes.findIndex(x => String(x.id) === realId || (isActualEdit && String(x.id) === String(targetId)));
      if (idx !== -1) {
        DB.notes[idx] = Object.assign({}, DB.notes[idx], real);
      } else {
        DB.notes.unshift(real);
      }

      // Strict deduplication by ID canonical
      const seenIds = new Set();
      DB.notes = DB.notes.filter(x => {
        const xid = String(x && x.id ? x.id : '');
        if (!xid || seenIds.has(xid)) return false;
        seenIds.add(xid);
        return true;
      });

      // Pastikan urutan rapi: pinned di atas, lalu updated_at terbaru
      DB.notes.sort((a, b) => {
        if (a.is_pinned && !b.is_pinned) return -1;
        if (!a.is_pinned && b.is_pinned) return 1;
        return new Date(b.updated_at || b.created_at || 0) - new Date(a.updated_at || a.created_at || 0);
      });

      console.log('[NOTE STATE] before:', beforeCount, 'after:', DB.notes.length);

      if (typeof window.noteAutoSaveManager !== 'undefined') {
        window.noteAutoSaveManager.isDirty = false;
        window.noteAutoSaveManager.activeNoteId = null;
        window.noteAutoSaveManager.isEdit = false;
      }

      // Bersihkan foot segera agar tombol tidak bisa diklik kembali saat animasi sheet closing
      const foot = document.getElementById('sheetFoot');
      if (foot) {
        foot.innerHTML = '';
        foot.classList.add('hide');
      }

      closeSheet();

      toast(isActualEdit ? (tipe === 'meeting_minutes' ? 'Notulensi rapat diperbarui.' : 'Catatan diperbarui.') : (tipe === 'meeting_minutes' ? 'Notulensi rapat berhasil disimpan.' : 'Catatan berhasil disimpan.'), 'check');

      if (state.route.page === 'catatan') {
        smartUpdateFilterView('catatan');
      }

      if (typeof requestSyncScope === 'function') {
        requestSyncScope('notes', false);
      }
    } else {
      const errMsg = res?.data?.message || res?.data || 'Gagal menyimpan catatan ke server.';
      console.error('[PTV Notes] Save failed:', errMsg);
      toast(errMsg, 'alert');
      if (saveBtn) {
        saveBtn.disabled = false;
        saveBtn.style.pointerEvents = '';
        saveBtn.innerHTML = origBtnHtml || (isActualEdit ? '<i class="fa-solid fa-check" style="margin-right:6px;"></i> Perbarui Catatan' : '<i class="fa-solid fa-check" style="margin-right:6px;"></i> Simpan Catatan');
      }
    }
  } catch (err) {
    console.error('[PTV Notes] Save error:', err);
    toast('Terjadi kesalahan jaringan saat menyimpan catatan.', 'alert');
    if (saveBtn) {
      saveBtn.disabled = false;
      saveBtn.style.pointerEvents = '';
      saveBtn.innerHTML = origBtnHtml || (isActualEdit ? '<i class="fa-solid fa-check" style="margin-right:6px;"></i> Perbarui Catatan' : '<i class="fa-solid fa-check" style="margin-right:6px;"></i> Simpan Catatan');
    }
  } finally {
    setTimeout(() => {
      _isSavingNoteLock = false;
    }, 500);
  }
}

function confirmDeleteNote(id){
  if (!isNoteExecutive()) {
    toast('Hanya eksekutif yang dapat menghapus catatan.', 'info');
    return;
  }

  const n = noteById(id);
  if(!n) return;
  if(!confirm(`Hapus catatan "${n.judul || 'Tanpa Judul'}"?`)) return;

  const prevNotes = [...(DB.notes || [])];
  DB.notes = (DB.notes || []).filter(x => String(x.id) !== String(id));
  if (typeof window.ptvMarkDeleted === 'function') window.ptvMarkDeleted(id);

  closeSheet();
  toast('Catatan telah dihapus.', 'check');
  if(state.route.page === 'catatan') smartUpdateFilterView('catatan');

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_delete_note');
  fd.append('id', id);
  if (typeof PTV_NONCE !== 'undefined' && PTV_NONCE) fd.append('nonce', PTV_NONCE);

  fetch(AJAX_URL, { method: 'POST', body: fd, credentials: 'same-origin' })
    .then(r => r.json())
    .then(res => {
      if (!res || !res.success) {
        console.error('[PTV Notes] Delete failed:', res?.data?.message || res?.data);
        toast(res?.data?.message || 'Gagal menghapus catatan di server.', 'alert');
        DB.notes = prevNotes;
        if(state.route.page === 'catatan') render();
      } else {
        if (typeof requestSyncScope === 'function') requestSyncScope('notes', true);
      }
    })
    .catch(err => {
      console.error('[PTV Notes] Delete error:', err);
      toast('Koneksi gagal saat menghapus catatan.', 'alert');
      DB.notes = prevNotes;
      if(state.route.page === 'catatan') render();
    });
}

function togglePinNote(id){
  if (!isNoteExecutive()) {
    toast('Hanya eksekutif yang dapat menyematkan catatan.', 'info');
    return;
  }

  const n = noteById(id);
  if(!n) return;
  const prevPinned = n.is_pinned;
  n.is_pinned = !n.is_pinned;
  haptic(8);

  // Pastikan urutan catatan ter-update seketika
  if (DB.notes) {
    DB.notes.sort((a, b) => {
      if (a.is_pinned && !b.is_pinned) return -1;
      if (!a.is_pinned && b.is_pinned) return 1;
      return new Date(b.updated_at || b.created_at || 0) - new Date(a.updated_at || a.created_at || 0);
    });
  }

  toast(n.is_pinned ? 'Catatan disematkan di atas.' : 'Sematan catatan dilepas.', 'check');
  if(state.route.page === 'catatan') smartUpdateFilterView('catatan');

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_toggle_pin_note');
  fd.append('id', id);
  fd.append('is_pinned', n.is_pinned ? '1' : '0');
  if (typeof PTV_NONCE !== 'undefined' && PTV_NONCE) fd.append('nonce', PTV_NONCE);

  fetch(AJAX_URL, { method: 'POST', body: fd, credentials: 'same-origin' })
    .then(r => r.json())
    .then(res => {
      if (!res || !res.success) {
        console.error('[PTV Notes] Pin toggle failed:', res?.data?.message || res?.data);
        toast(res?.data?.message || 'Gagal mengubah pin catatan.', 'alert');
        n.is_pinned = prevPinned;
        if(state.route.page === 'catatan') render();
      } else {
        if (typeof requestSyncScope === 'function') requestSyncScope('notes', true);
      }
    })
    .catch(err => {
      console.error('[PTV Notes] Pin toggle error:', err);
      n.is_pinned = prevPinned;
      if(state.route.page === 'catatan') render();
    });
}

function confirmDeleteLostFound(id){
  const l = (DB.lost || []).find(x => String(x.id) === String(id));
  if(!l) return;
  if(!confirm(`Hapus laporan barang "${l.name}"?`)) return;

  DB.lost = (DB.lost || []).filter(x => String(x.id) !== String(id));
  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_delete_lost_found');
  fd.append('id', id);
  fetch(AJAX_URL, { method: 'POST', body: fd }).catch(()=>{});

  closeSheet();
  toast('Laporan barang dihapus.', 'check');
  if(state.route.page === 'lostfound') render();
}

/* ============================================================
   PAGE: INVENTARIS
   ============================================================ */
let invFilter = 'semua';       // Ketersediaan: 'semua', 'Tersedia', 'Dipinjam', 'Rusak', 'Tidak tersedia', 'Hilang'
let invCatFilter = 'semua';    // Kategori: 'semua' or category name
let invLocFilter = 'semua';    // Lokasi: 'semua' or location name
let invSourceFilter = 'semua'; // Sumber: 'semua' or source name
let invGroupBy = 'kategori';   // Group by: 'kategori', 'lokasi', 'status', 'sumber', 'none'
let invFilterOpen = false;
let invGroupOpen = false;
let invQ = '';

function getActiveInventoryLocations(){
  const baseLocs = getInventoryLocations();
  const present = (DB.inventory || []).map(x => (x.loc || 'Studio PTV').trim()).filter(Boolean);
  return Array.from(new Set([...present, ...baseLocs])).sort((a,b) => a.localeCompare(b, 'id'));
}

function getActiveInventorySources(){
  const baseSources = getInventorySourcesList();
  const present = (DB.inventory || []).map(x => (x.sumber_perolehan || x.sumber || 'Yayasan').trim()).filter(Boolean);
  return Array.from(new Set([...present, ...baseSources])).sort((a,b) => a.localeCompare(b, 'id'));
}

function getInvFilterCount(type, val){
  let base = (DB.inventory || []).slice();
  if(type !== 'status' && invFilter !== 'semua'){
    if(invFilter === 'Tersedia') base = base.filter(x => getAssetUnitSummary(x).available > 0);
    else if(invFilter === 'Dipinjam') base = base.filter(x => getAssetUnitSummary(x).borrowed > 0);
    else if(invFilter === 'Rusak') base = base.filter(x => getAssetUnitSummary(x).damaged > 0);
    else if(invFilter === 'Tidak tersedia') base = base.filter(x => getAssetUnitSummary(x).available === 0);
    else if(invFilter === 'Hilang') base = base.filter(x => getAssetUnitSummary(x).lost > 0);
    else base = base.filter(x => x.status === invFilter);
  }
  if(type !== 'cat' && invCatFilter !== 'semua'){
    base = base.filter(x => normalizeInventoryCategory(x.cat) === invCatFilter);
  }
  if(type !== 'loc' && invLocFilter !== 'semua'){
    base = base.filter(x => (x.loc || 'Studio PTV').trim() === invLocFilter);
  }
  if(type !== 'source' && invSourceFilter !== 'semua'){
    base = base.filter(x => (x.sumber_perolehan || x.sumber || 'Yayasan').trim() === invSourceFilter);
  }

  if(type === 'status'){
    if(val === 'semua') return base.length;
    if(val === 'Tersedia') return base.filter(x => getAssetUnitSummary(x).available > 0).length;
    if(val === 'Dipinjam') return base.filter(x => getAssetUnitSummary(x).borrowed > 0).length;
    if(val === 'Rusak') return base.filter(x => getAssetUnitSummary(x).damaged > 0).length;
    if(val === 'Tidak tersedia') return base.filter(x => getAssetUnitSummary(x).available === 0).length;
    if(val === 'Hilang') return base.filter(x => getAssetUnitSummary(x).lost > 0).length;
    return base.filter(x => x.status === val).length;
  }
  if(type === 'cat'){
    if(val === 'semua') return base.length;
    return base.filter(x => normalizeInventoryCategory(x.cat) === val).length;
  }
  if(type === 'loc'){
    if(val === 'semua') return base.length;
    return base.filter(x => (x.loc || 'Studio PTV').trim() === val).length;
  }
  if(type === 'source'){
    if(val === 'semua') return base.length;
    return base.filter(x => (x.sumber_perolehan || x.sumber || 'Yayasan').trim() === val).length;
  }
  return base.length;
}

function renderInventoryItemRow(x){
  const sum = getAssetUnitSummary(x);
  const total = sum.total;
  const avail = sum.available;
  const unitLabel = `Total ${total} Unit`;
  const availSub = sum.summaryText;
  const catName = normalizeInventoryCategory(x.cat);
  const locName = (x.loc || 'Studio PTV').trim();
  const sourceName = (x.sumber_perolehan || x.sumber || 'Yayasan').trim();

  const brandClean = cleanMojibake(x.brand, '');
  const modelClean = cleanMojibake(x.model, '');
  const nameClean = cleanMojibake(x.name, 'Alat PTV');
  const brandModelText = brandClean ? (brandClean + (modelClean ? ' ' + modelClean : '')) : (modelClean || '');

  let statusBadge = '';
  if (avail > 0) {
    statusBadge = (avail === total)
      ? chip('Tersedia')
      : `<span class="chip ok" style="font-size:11px;font-weight:650">${avail} Tersedia</span>`;
  } else if (sum.damaged >= total) {
    statusBadge = `<span class="chip dang" style="font-size:11px;font-weight:650">${sum.damaged > 1 ? sum.damaged + ' ' : ''}Rusak</span>`;
  } else if (sum.lost >= total) {
    statusBadge = `<span class="chip muted" style="font-size:11px;font-weight:650">${sum.lost > 1 ? sum.lost + ' ' : ''}Hilang</span>`;
  } else if (sum.borrowed > 0) {
    statusBadge = `<span class="chip info" style="font-size:11px;font-weight:650">${sum.borrowed > 1 ? sum.borrowed + ' ' : ''}Dipinjam</span>`;
  } else {
    statusBadge = chip(sum.masterStatus || x.status || 'Tersedia');
  }

  return `
  <button class="li" data-go="alatDetail:${x.id}">
    ${itemThumbHTML(x)}
    <span class="li-body">
      <span class="li-t trunc" style="display:flex;align-items:center;gap:6px">
        <span>${esc(nameClean)}</span>
        <span class="chip blue" style="font-size:10px;padding:1px 6px;font-weight:700">${esc(x.code || 'INV')}</span>
      </span>
      <span class="li-s trunc" style="font-weight:600;color:var(--ink-2);"><span style="color:var(--b-600);">${unitLabel}</span> &bull; <span style="color:${avail > 0 ? 'var(--ok)' : (sum.damaged > 0 ? 'var(--dang)' : 'var(--warn)')}">${availSub}</span></span>
      <span class="li-s trunc muted">${brandModelText ? esc(brandModelText) + ' · ' : ''}${esc(catName)} · Lokasi: ${esc(locName)} · ${esc(sourceName)}${x.holder?` · Dipegang ${esc(x.holder.split(' ')[0])}`:''}</span>
    </span>
    ${statusBadge}
  </button>
  `;
}

function getCategoryIconMarkup(cat){
  const c = String(cat || '').toLowerCase().trim();
  if(c === 'semua') return '<i class="fa-solid fa-boxes-stacked"></i>';
  if(c.includes('kamera') || c.includes('camera')) return '<i class="fa-solid fa-camera"></i>';
  if(c.includes('lensa') || c.includes('lens')) return '<i class="fa-solid fa-camera-rotate"></i>';
  if(c.includes('smartphone') || c.includes('tablet') || c.includes('phone') || c.includes('hp')) return '<i class="fa-solid fa-mobile-screen-button"></i>';
  if(c.includes('komputer') || c.includes('laptop') || c.includes('pc')) return '<i class="fa-solid fa-laptop"></i>';
  if(c.includes('audio') || c.includes('mic') || c.includes('sound') || c.includes('suara')) return '<i class="fa-solid fa-microphone-lines"></i>';
  if(c.includes('lighting') || c.includes('lampu') || c.includes('light')) return '<i class="fa-solid fa-lightbulb"></i>';
  if(c.includes('streaming') || c.includes('live') || c.includes('switcher')) return '<i class="fa-solid fa-tower-broadcast"></i>';
  if(c.includes('kabel') || c.includes('cable') || c.includes('adapter') || c.includes('converter')) return '<i class="fa-solid fa-plug"></i>';
  if(c.includes('dry cabinet') || c.includes('cabinet') || c.includes('drybox')) return '<i class="fa-solid fa-box-archive"></i>';
  if(c.includes('tv') || c.includes('smart tv') || c.includes('monitor') || c.includes('layar')) return '<i class="fa-solid fa-tv"></i>';
  if(c.includes('storage') || c.includes('memory') || c.includes('kartu') || c.includes('ssd') || c.includes('harddisk') || c.includes('sd card')) return '<i class="fa-solid fa-hard-drive"></i>';
  if(c.includes('perkakas') || c.includes('peralatan') || c.includes('tool')) return '<i class="fa-solid fa-screwdriver-wrench"></i>';
  if(c.includes('atk') || c.includes('tulis') || c.includes('kertas') || c.includes('alat tulis')) return '<i class="fa-solid fa-pen-ruler"></i>';
  if(c.includes('jaringan') || c.includes('network') || c.includes('router') || c.includes('wifi') || c.includes('lan')) return '<i class="fa-solid fa-network-wired"></i>';
  if(c.includes('tripod') || c.includes('rig') || c.includes('monopod') || c.includes('stand')) return '<i class="fa-solid fa-arrows-to-dot"></i>';
  if(c.includes('drone')) return '<i class="fa-solid fa-helicopter"></i>';
  if(c.includes('gimbal') || c.includes('stabilizer')) return '<i class="fa-solid fa-arrows-up-down-left-right"></i>';
  if(c.includes('baterai') || c.includes('power') || c.includes('battery') || c.includes('charger')) return '<i class="fa-solid fa-battery-three-quarters"></i>';
  if(c.includes('aksesoris') || c.includes('perlengkapan')) return '<i class="fa-solid fa-toolbox"></i>';
  return '<i class="fa-solid fa-shapes"></i>';
}

function quickAddAssetToBasket(assetId, ev){
  if(ev){ ev.stopPropagation(); ev.preventDefault(); }
  const it = itemById(String(assetId));
  if(!it) return;
  const s = getAssetUnitSummary(it);
  const availUnits = s.units.filter(u => u.status === 'Tersedia');
  if(availUnits.length === 0){
    toast(`Semua unit "${it.name}" sedang tidak tersedia.`, 'alert');
    return;
  }

  // Jika inventaris mempunyai lebih dari 1 unit fisik: wajibkan memilih unit keberapa yang dia ingin!
  if(s.units.length > 1){
    openUnitPickerModal(assetId, 'basket');
    return;
  }

  // Jika hanya memiliki 1 unit fisik: langsung toggle di basket
  toggleUnitInLoanBasket(assetId, availUnits[0]?.unit || 1);
}

function pgInventaris(){
  let rows = (DB.inventory || []).slice();

  // 1. Status / Ketersediaan
  if(invFilter !== 'semua'){
    if(invFilter === 'Tersedia') rows = rows.filter(x => getAssetUnitSummary(x).available > 0);
    else if(invFilter === 'Dipinjam') rows = rows.filter(x => getAssetUnitSummary(x).borrowed > 0);
    else if(invFilter === 'Rusak') rows = rows.filter(x => getAssetUnitSummary(x).damaged > 0);
    else if(invFilter === 'Tidak tersedia') rows = rows.filter(x => getAssetUnitSummary(x).available === 0);
    else if(invFilter === 'Hilang') rows = rows.filter(x => getAssetUnitSummary(x).lost > 0);
    else rows = rows.filter(x => x.status === invFilter);
  }

  // 2. Kategori
  if(invCatFilter !== 'semua'){
    rows = rows.filter(x => normalizeInventoryCategory(x.cat) === invCatFilter);
  }

  // 3. Lokasi
  if(invLocFilter !== 'semua'){
    rows = rows.filter(x => (x.loc || 'Studio PTV').trim() === invLocFilter);
  }

  // 4. Sumber Perolehan
  if(invSourceFilter !== 'semua'){
    rows = rows.filter(x => (x.sumber_perolehan || x.sumber || 'Yayasan').trim() === invSourceFilter);
  }

  // 5. Search query
  if(invQ){
    const qLower = invQ.toLowerCase();
    rows = rows.filter(x => (
      (x.name || '') + ' ' +
      (x.code || '') + ' ' +
      (x.brand || '') + ' ' +
      (x.model || '') + ' ' +
      (x.sn || '') + ' ' +
      (x.loc || '') + ' ' +
      (x.cat || '') + ' ' +
      (x.sumber_perolehan || x.sumber || '')
    ).toLowerCase().includes(qLower));
  }

  // Explicit Level 1 (Category) -> Level 2 (Name A-Z) sorting before render
  rows = sortInventoryItems(rows);

  const totalCount = rows.length;
  const isFiltered = (invFilter !== 'semua' || invCatFilter !== 'semua' || invLocFilter !== 'semua' || invSourceFilter !== 'semua' || !!invQ);
  const curUserRole = normRole(state.role || ME.role);
  const isExec = curUserRole === 'eksekutif';
  const isAdmin = curUserRole === 'administrasi';
  const canAddAsset = isExec || isAdmin;
  const basketCount = loanBasket.size;

  // Active categories present in DB
  const catSet = new Set();
  (DB.inventory || []).forEach(x => catSet.add(normalizeInventoryCategory(x.cat)));
  const activeCats = INVENTORY_CATEGORIES.filter(c => catSet.has(c));
  catSet.forEach(c => { if(!activeCats.includes(c)) activeCats.push(c); });

  // Daftar Pinjaman button
  const daftarBtnLabel = basketCount > 0
    ? `<i class="fa-solid fa-clipboard-list"></i> Daftar Pinjaman <span class="badge-count">${basketCount}</span>`
    : `<i class="fa-solid fa-clipboard-list"></i><span style="margin-left:5px">Daftar Pinjaman</span>`;

  // Render catalog product card
  const renderCard = (x) => {
    const sum = getAssetUnitSummary(x);
    const avail = sum.available;
    const nameClean = cleanMojibake(x.name, 'Alat PTV');
    const brandClean = cleanMojibake(x.brand, '');
    const modelClean = cleanMojibake(x.model, '');
    const brandModel = brandClean ? (brandClean + (modelClean ? ' ' + modelClean : '')) : modelClean;
    const photo = String(x?.photo || x?.foto_url || x?.gambar || x?.foto || '').trim();
    const iconKey = catIcon(x?.cat);
    const fallbackSvg = ic[iconKey] || ic.box;
    const invCode = x.code || ('INV-' + String(x.id).slice(0,5).toUpperCase());

    let badgeTxt, badgeColor, dotColor, badgeBorder;
    if (avail === sum.total && sum.total > 0) {
      badgeTxt = 'Tersedia';
      badgeColor = '#15803d'; dotColor = '#22c55e'; badgeBorder = 'rgba(34,197,94,0.3)';
    } else if (avail > 0) {
      badgeTxt = `${avail}/${sum.total} Tersedia`;
      badgeColor = '#047857'; dotColor = '#10b981'; badgeBorder = 'rgba(16,185,129,0.3)';
    } else if (sum.borrowed > 0) {
      badgeTxt = sum.borrowed === sum.total ? 'Dipinjam' : `${sum.borrowed} Dipinjam`;
      badgeColor = '#b45309'; dotColor = '#f59e0b'; badgeBorder = 'rgba(245,158,11,0.3)';
    } else if (sum.damaged > 0) {
      badgeTxt = 'Rusak';
      badgeColor = '#b91c1c'; dotColor = '#ef4444'; badgeBorder = 'rgba(239,68,68,0.3)';
    } else {
      badgeTxt = 'Tidak Ada';
      badgeColor = '#475569'; dotColor = '#94a3b8'; badgeBorder = 'rgba(148,163,184,0.3)';
    }

    // Concise unit breakdown with distinct semantic colors for available/borrowed/damaged (Priority 4)
    let unitStatusBriefHTML = '';
    const availDotColor = avail > 0 ? '#16a34a' : (sum.damaged > 0 ? '#dc2626' : '#d97706');
    if (sum.total <= 1) {
      if (avail === 1) {
        unitStatusBriefHTML = `<span style="color:#16a34a;display:inline-flex;align-items:center;gap:5px;"><span style="width:6px;height:6px;border-radius:50%;background:#16a34a;display:inline-block;flex-shrink:0;"></span>1 unit &bull; Tersedia</span>`;
      } else if (sum.borrowed === 1) {
        unitStatusBriefHTML = `<span style="color:#d97706;display:inline-flex;align-items:center;gap:5px;"><span style="width:6px;height:6px;border-radius:50%;background:#d97706;display:inline-block;flex-shrink:0;"></span>1 unit &bull; Dipinjam</span>`;
      } else if (sum.damaged === 1) {
        unitStatusBriefHTML = `<span style="color:#dc2626;display:inline-flex;align-items:center;gap:5px;"><span style="width:6px;height:6px;border-radius:50%;background:#dc2626;display:inline-block;flex-shrink:0;"></span>1 unit &bull; Rusak</span>`;
      } else {
        unitStatusBriefHTML = `<span style="color:#64748b;display:inline-flex;align-items:center;gap:5px;"><span style="width:6px;height:6px;border-radius:50%;background:#64748b;display:inline-block;flex-shrink:0;"></span>1 unit &bull; Tidak tersedia</span>`;
      }
    } else {
      unitStatusBriefHTML = `<span style="display:inline-flex;align-items:center;gap:5px;color:#0f172a;flex-wrap:wrap;">
        <span style="width:6px;height:6px;border-radius:50%;background:${availDotColor};display:inline-block;flex-shrink:0;"></span>
        <span><b>${sum.total} unit</b> &bull; <span style="color:${avail > 0 ? '#16a34a' : '#dc2626'};font-weight:700;">${avail} tersedia</span></span>
        ${sum.borrowed > 0 ? `<span style="color:#d97706;font-size:10.5px;">(${sum.borrowed} pinjam)</span>` : ''}
      </span>`;
    }

    const sourceName = x.sumber_perolehan || x.sumber || 'Yayasan';
    const locName = x.loc || 'Studio PTV';

    const photoHTML = photo
      ? `<img src="${esc(photo)}" alt="${esc(nameClean)}" loading="lazy" onerror="this.style.display='none';if(this.nextElementSibling)this.nextElementSibling.style.display='flex';" /><span class="inv-prod-icon" style="display:none">${fallbackSvg}</span>`
      : `<span class="inv-prod-icon">${fallbackSvg}</span>`;

    const inBasket = basketCount > 0 && Array.from(loanBasket.values()).some(b => String(b.assetId) === String(x.id));

    return `<button class="inv-prod-card" data-go="alatDetail:${x.id}" style="${inBasket ? 'border-color:var(--b-400);box-shadow:0 0 0 2px var(--b-100);' : ''}">
      <!-- 1. Status ketersediaan (badge pada foto) -->
      <div class="inv-prod-photo">
        ${photoHTML}
        <span class="inv-prod-status-badge" style="color:${badgeColor};border-color:${badgeBorder};">
          <span style="display:inline-block;width:5px;height:5px;border-radius:50%;background:${dotColor};"></span>
          <span>${esc(badgeTxt)}</span>
        </span>
      </div>

      <!-- Detail Card -->
      <div class="inv-prod-body">
        <!-- 2. Kode & Kategori -->
        <div style="display:flex;align-items:center;justify-content:space-between;gap:6px;">
          <div class="inv-prod-code">${esc(invCode)}</div>
          <span style="font-size:10.5px;color:var(--muted);font-weight:650;text-transform:capitalize;">${esc(x.cat || 'Alat')}</span>
        </div>

        <!-- 3. Nama & Merk Alat -->
        <div class="inv-prod-name" style="margin-top:2px;">${esc(nameClean)}</div>
        ${brandModel ? `<div class="inv-prod-brand">${esc(brandModel)}</div>` : ''}

        <!-- 4. Jumlah Unit & Ketersediaan -->
        <div style="margin-top:auto;padding-top:6px;display:flex;flex-direction:column;gap:4px;">
          <div style="font-size:11px;font-weight:650;line-height:1.25;" class="trunc">
            ${unitStatusBriefHTML}
          </div>

          <!-- 5. Lokasi & Quick Action -->
          <div style="display:flex;align-items:center;justify-content:space-between;font-size:11px;color:var(--muted);font-weight:550;gap:6px;padding-top:3px;border-top:1px solid #f1f5f9;">
            <span class="trunc" style="flex:1;" title="Lokasi: ${esc(locName)}">
              <i class="fa-solid fa-location-dot" style="font-size:10px;margin-right:3px;color:#0284c7"></i>${esc(locName)}
            </span>
            ${avail > 0 ? `<span class="inv-prod-quick-add ${inBasket ? 'added' : ''}" data-act="quickAddLoan:${x.id}" title="${inBasket ? 'Keluarkan dari daftar pinjaman' : 'Tambah ke daftar pinjaman'}"><i class="fa-solid ${inBasket ? 'fa-check' : 'fa-plus'}"></i></span>` : ''}
          </div>
        </div>
      </div>
    </button>`;
  };

  // Calculate status counts scoped to currently selected category
  const catScopedItems = (invCatFilter === 'semua')
    ? (DB.inventory || [])
    : (DB.inventory || []).filter(x => normalizeInventoryCategory(x.cat) === invCatFilter);

  const countCatAll = catScopedItems.length;
  const countCatAvail = catScopedItems.filter(x => getAssetUnitSummary(x).available > 0).length;
  const countCatBorrowed = catScopedItems.filter(x => getAssetUnitSummary(x).borrowed > 0).length;
  const countCatDamaged = catScopedItems.filter(x => getAssetUnitSummary(x).damaged > 0).length;

  return `<div class="page">
    <!-- Header: Unified Search Bar with QR Scan inside + Daftar Pinjaman Icon Button -->
    <div class="row gap8" style="align-items:center">
      <div class="inv-search-wrap">
        <span class="search-icon"><i class="fa-solid fa-magnifying-glass"></i></span>
        <input id="invQ" value="${esc(invQ)}" placeholder="Cari nama, kode (INV-xxx), merk, model, lokasi…">
        <button class="inv-search-scan-btn" data-act="scan" aria-label="Pindai Barcode">${ic.scan}<span class="only-desktop" style="margin-left:2px">Scan</span></button>
      </div>
      <button class="inv-top-basket-btn" data-act="openDaftarPinjaman" aria-label="Daftar Pinjaman" title="Daftar Pinjaman">
        <i class="fa-solid fa-clipboard-list"></i>
        ${basketCount > 0 ? `<span class="inv-top-basket-badge">${basketCount}</span>` : ''}
      </button>
    </div>

    <!-- Hero Banner Image -->
    <div class="inv-hero-banner">
      <img src="/wp-content/uploads/STUDIO-PROGRESIF-TV-35-scaled.jpg" alt="Aset Inventaris Progresif TV Production" loading="lazy" />
      <div class="inv-hero-overlay">
        <div class="inv-hero-tag"><i class="fa-solid fa-boxes-stacked"></i> KATALOG INVENTARIS</div>
        <div class="inv-hero-title">Aset Inventaris Progresif TV Production</div>
        <div class="inv-hero-sub">Kelola peminjaman, monitor ketersediaan unit, dan telusuri riwayat alat dengan mudah.</div>
      </div>
    </div>

    <!-- Category Section (Premium Card Rail) -->
    <div class="inv-cat-box">
      <div class="inv-cat-box-header">
        <div class="inv-cat-box-title">
          <i class="fa-solid fa-layer-group"></i> Kategori Alat
        </div>
        <div style="display:flex;align-items:center;gap:8px">
          <span class="inv-cat-box-count">${activeCats.length + 1} Kategori</span>
          <div class="inv-cat-nav-btns">
            <button class="inv-cat-nav-btn" data-act="scrollInvCatPrev" aria-label="Geser Kiri" title="Kategori Sebelumnya"><i class="fa-solid fa-chevron-left"></i></button>
            <button class="inv-cat-nav-btn" data-act="scrollInvCatNext" aria-label="Geser Kanan" title="Kategori Berikutnya"><i class="fa-solid fa-chevron-right"></i></button>
          </div>
        </div>
      </div>
      <div class="inv-cat-scroll-track" id="invCatTrack">
        <button class="inv-cat-card${invCatFilter === 'semua' ? ' on' : ''}" data-filter-inv-cat="semua">
          <div class="inv-cat-card-icon"><i class="fa-solid fa-boxes-stacked"></i></div>
          <div class="inv-cat-card-name">Semua</div>
          <div class="inv-cat-card-count">${(DB.inventory||[]).length} alat</div>
        </button>
        ${activeCats.map(cat => {
          const cnt = (DB.inventory||[]).filter(x => normalizeInventoryCategory(x.cat) === cat).length;
          const iconMarkup = getCategoryIconMarkup(cat);
          return `<button class="inv-cat-card${invCatFilter === cat ? ' on' : ''}" data-filter-inv-cat="${esc(cat)}">
            <div class="inv-cat-card-icon">${iconMarkup}</div>
            <div class="inv-cat-card-name">${esc(cat)}</div>
            <div class="inv-cat-card-count">${cnt} alat</div>
          </button>`;
        }).join('')}
      </div>
    </div>

    <!-- Status Segmented Toolbar (Scoped to Category) + Actions (+ Alat & Reset) -->
    <div class="inv-toolbar-row" style="display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:14px;flex-wrap:wrap">
      <div class="inv-status-segment">
        <button class="inv-segment-btn${invFilter==='semua'?' on':''}" data-filter-inv="semua">
          <span>Semua</span>
          <span class="inv-segment-count">${countCatAll}</span>
        </button>
        <button class="inv-segment-btn${invFilter==='Tersedia'?' on':''}" data-filter-inv="Tersedia">
          <span class="inv-segment-dot" style="background:#22c55e"></span>
          <span>Tersedia</span>
          <span class="inv-segment-count">${countCatAvail}</span>
        </button>
        <button class="inv-segment-btn${invFilter==='Dipinjam'?' on':''}" data-filter-inv="Dipinjam">
          <span class="inv-segment-dot" style="background:#f59e0b"></span>
          <span>Dipinjam</span>
          <span class="inv-segment-count">${countCatBorrowed}</span>
        </button>
        <button class="inv-segment-btn${invFilter==='Rusak'?' on':''}" data-filter-inv="Rusak">
          <span class="inv-segment-dot" style="background:#ef4444"></span>
          <span>Rusak</span>
          <span class="inv-segment-count">${countCatDamaged}</span>
        </button>
      </div>

      <div class="inv-toolbar-actions" style="display:flex;align-items:center;gap:8px;margin-left:auto;flex-shrink:0;flex-wrap:wrap">
        ${isFiltered ? `<button class="btn sm" data-act="resetInvFilters" style="font-size:11.5px;padding:3px 10px;min-height:34px;font-weight:650;color:var(--warn);border-radius:var(--r-m)"><i class="fa-solid fa-rotate-left" style="margin-right:4px;font-size:10.5px"></i>Reset Filter</button>` : ''}
        ${basketCount > 0 ? `<button class="btn sm" data-act="openDaftarPinjaman" style="font-size:12px;padding:0 12px;min-height:34px;font-weight:650;color:var(--b-700);background:var(--b-050);border:1px solid var(--b-200);border-radius:var(--r-full);display:inline-flex;align-items:center;gap:6px;box-shadow:0 1px 4px rgba(18,115,230,0.08);cursor:pointer;" title="Buka Daftar Pinjaman"><i class="fa-solid fa-clipboard-check" style="font-size:12px"></i><span>${basketCount} dalam daftar pinjaman</span></button>` : ''}
        ${canAddAsset ? `<button class="btn sm pri" data-act="openNewAsset" style="min-height:34px;padding:0 14px;border-radius:var(--r-full);font-weight:700;font-size:12.5px;box-shadow:0 2px 8px rgba(18,115,230,0.25);display:inline-flex;align-items:center;gap:4px">${ic.plus}<span>Alat</span></button>` : ''}
      </div>
    </div>

    <!-- Result count & Realtime Status -->
    <div class="row-b mt12 mb10" style="align-items:center;padding:0 1px">
      <span class="t-sm" style="font-weight:700;color:var(--ink)">
        ${totalCount} alat${invCatFilter !== 'semua' ? ` · ${esc(invCatFilter)}` : ''}
        <span id="invScopeStatusBadge" style="margin-left:8px;">${getSectionSyncStatusHTML('inventory')}</span>
      </span>
    </div>

    <!-- Product Catalog Grid -->
    <div id="pgList">
      ${(() => {
        const invState = window.PTV_SCOPES_STATE?.inventory;
        const isFirstLoading = invState && invState.isInitialLoading && !invState.hasData;
        if (isFirstLoading) {
          return renderInventorySkeleton(6);
        }
        return totalCount
          ? `<div class="inv-catalog-grid">${rows.map(x => renderCard(x)).join('')}</div>`
          : emptyState('box', 'Tidak ada alat yang cocok. Ubah filter atau kata kunci.');
      })()}
    </div>
  </div>`;
}

function pgAlatDetail(){
  const x=itemById(state.route.id);
  if(!x)return emptyState('box','Alat tidak ditemukan.');
  const summary = getAssetUnitSummary(x);
  const hist=DB.loans.filter(l=>String(l.item)===String(x.id)).sort((a,b)=>(b.out||'').localeCompare(a.out||''));
  const reports=DB.damages.filter(d=>String(d.item)===String(x.id));
  const invCode = x.code || ('INV-' + String(x.id).slice(0,5).toUpperCase());
  const curUserRole = normRole(state.role || ME.role);
  const isExec = curUserRole === 'eksekutif';
  const isAdmin = curUserRole === 'administrasi';
  const total = summary.total;
  const avail = summary.available;
  const borrowed = summary.borrowed;
  const damaged = summary.damaged;
  const lost = summary.lost;
  const canEditAsset = isExec || isAdmin;
  const canDeleteAsset = isExec;
  const canBorrow = avail > 0;
  const canReturn = borrowed > 0 && (isExec || isAdmin || x.holder === ME.name || DB.loans.some(l => String(l.item) === String(x.id) && !l.back && (l.by === ME.name || isExec || isAdmin)));

  const nameClean = cleanMojibake(x.name, 'Alat PTV');
  const brandClean = cleanMojibake(x.brand, '');
  const modelClean = cleanMojibake(x.model, '');
  const brandModel = brandClean ? (brandClean + (modelClean ? ' ' + modelClean : '')) : (modelClean || '—');
  const photo = String(x?.photo || x?.foto_url || x?.gambar || x?.foto || '').trim();
  const iconKey = catIcon(x?.cat);
  const fallbackSvg = ic[iconKey] || ic.box;
  const sourceName = x.sumber_perolehan || x.sumber || 'Yayasan';
  const locName = x.loc || 'Studio PTV';
  const catName = x.cat || 'Peralatan Studio';

  const inBasket = (typeof loanBasket !== 'undefined') && Array.from(loanBasket.values()).some(b => String(b.assetId) === String(x.id));

  // Active selected unit
  let selectedUnitNum = (typeof window._selectedDetailUnit === 'number') ? window._selectedDetailUnit : 1;
  if (selectedUnitNum > total || selectedUnitNum < 1) selectedUnitNum = 1;
  const selUnit = summary.units.find(u => u.unit === selectedUnitNum) || summary.units[0] || { unit: 1, status: 'Tersedia', cond: 'Baik', code: invCode };

  // Status badge on photo
  let badgeTxt, badgeColor, dotColor, badgeBorder;
  if (avail === total && total > 0) {
    badgeTxt = `${total} Tersedia`;
    badgeColor = '#15803d'; dotColor = '#22c55e'; badgeBorder = 'rgba(34,197,94,0.3)';
  } else if (avail > 0) {
    badgeTxt = `${avail}/${total} Tersedia`;
    badgeColor = '#047857'; dotColor = '#10b981'; badgeBorder = 'rgba(16,185,129,0.3)';
  } else if (borrowed > 0) {
    badgeTxt = borrowed === total ? 'Dipinjam' : `${borrowed} Dipinjam`;
    badgeColor = '#b45309'; dotColor = '#f59e0b'; badgeBorder = 'rgba(245,158,11,0.3)';
  } else if (damaged > 0) {
    badgeTxt = 'Rusak';
    badgeColor = '#b91c1c'; dotColor = '#ef4444'; badgeBorder = 'rgba(239,68,68,0.3)';
  } else {
    badgeTxt = 'Tidak Ada';
    badgeColor = '#475569'; dotColor = '#94a3b8'; badgeBorder = 'rgba(148,163,184,0.3)';
  }

  const isBoxWarning = avail === 0 && borrowed > 0;
  const isBoxDanger = avail === 0 && damaged > 0;

  return `<div class="page">
    <div class="prod-detail-container">
      
      <!-- 1. Breadcrumbs Navigation -->
      <div class="prod-breadcrumb">
        <button data-go="inventaris"><i class="fa-solid fa-boxes-stacked"></i> Inventaris</button>
        <span class="sep"><i class="fa-solid fa-chevron-right"></i></span>
        <button data-filter-inv-cat="${esc(catName)}" data-go="inventaris">${esc(catName)}</button>
        <span class="sep"><i class="fa-solid fa-chevron-right"></i></span>
        <span style="color:var(--ink);font-weight:700" class="trunc">${esc(nameClean)}</span>
      </div>

      <!-- 2. Main E-Commerce Style Showcase Card (2 Columns) -->
      <div class="prod-showcase-card">
        
        <!-- Left Column: Gallery & Utilities -->
        <div class="prod-gallery-col">
          <div class="prod-main-photo-wrap" id="prodMainPhotoWrap">
            ${photo 
              ? `<img id="prodMainImg" src="${esc(photo)}" alt="${esc(nameClean)}" onerror="this.style.display='none';if(this.nextElementSibling)this.nextElementSibling.style.display='flex';" /><div class="prod-photo-fallback" style="display:none">${fallbackSvg}</div>`
              : `<div class="prod-photo-fallback">${fallbackSvg}</div>`
            }
          </div>
        </div>

        <!-- Right Column: Specs, Variant/Unit Picker, CTA -->
        <div class="prod-info-col">

          <!-- Main Title & Subtitle -->
          <div>
            <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:6px;">
              <span class="chip blue" style="font-size:11px;font-weight:750;letter-spacing:0.02em;padding:2px 8px;">${esc(invCode)}</span>
              ${renderUnitBranding(selUnit, { size: 'sm' })}
            </div>
            <h1 class="prod-main-title">${esc(nameClean)}</h1>
            ${brandModel !== '—' ? `<div class="prod-subhead"><i class="fa-solid fa-microchip" style="margin-right:5px;opacity:0.7"></i>${esc(brandModel)}</div>` : ''}
          </div>

          <!-- Stats / Health Badges (Curated gear health & stats) -->
          <div class="prod-stats-bar">
            <span class="prod-stat-pill">
              <i class="fa-solid fa-shield-halved" style="color:#2563eb"></i>
              <span>Kondisi Fisik: <b>Prima</b></span>
            </span>
            <span class="prod-stat-pill">
              <i class="fa-solid fa-clock-rotate-left" style="color:#6366f1"></i>
              <span><b>${hist.length}x</b> Dipinjam</span>
            </span>
            <span class="prod-stat-pill">
              <i class="fa-solid fa-cubes-stacked" style="color:${avail > 0 ? '#16a34a' : '#d97706'}"></i>
              <span>Ketersediaan: <b style="color:${avail > 0 ? '#16a34a' : '#d97706'}">${avail}/${total} Unit</b></span>
            </span>
          </div>

          <!-- Highlight / Availability Banner (Apple-style Hardware Status) -->
          <div class="prod-pricing-box ${isBoxDanger ? 'is-danger' : (isBoxWarning ? 'is-warning' : '')}">
            <div class="prod-price-main">
              <span class="prod-price-label">
                <i class="fa-solid ${avail > 0 ? 'fa-circle-check' : 'fa-triangle-exclamation'}"></i> STATUS KESIAPAN ALAT
              </span>
              <div class="prod-price-val">
                ${avail > 0 ? `${avail} Unit Siap Digunakan` : (borrowed > 0 ? 'Semua Unit Sedang Dipinjam' : (damaged > 0 ? 'Dalam Pemeliharaan / Perbaikan' : 'Tidak Ada Unit Tersedia'))}
              </div>
              <span style="font-size:12px;color:#64748b;font-weight:550;margin-top:2px;">
                <i class="fa-solid fa-building-columns" style="color:#2563eb;margin-right:4px;"></i>Sumber Dana: <b>${esc(sourceName)}</b> &bull; Lokasi: <b>${esc(locName)}</b>
              </span>
            </div>
            <div class="prod-price-badge" style="background:${avail > 0 ? '#22c55e' : (isBoxDanger ? '#ef4444' : '#f59e0b')};color:#ffffff;">
              <i class="fa-solid ${avail > 0 ? 'fa-check' : 'fa-info'}"></i>
              <span>${esc(summary.summaryText)}</span>
            </div>
          </div>

          <!-- Hardware Spec Cards Grid (Sleek 2x2 card grid, NO SN) -->
          <div class="prod-spec-grid">
            <div class="prod-spec-card">
              <div class="prod-spec-card-icon"><i class="fa-solid fa-barcode"></i></div>
              <div class="prod-spec-card-info">
                <span class="label">Kode Inventaris</span>
                <span class="val font-mono" style="color:var(--b-600);">${esc(invCode)}</span>
              </div>
            </div>
            <div class="prod-spec-card">
              <div class="prod-spec-card-icon"><i class="fa-solid fa-tag"></i></div>
              <div class="prod-spec-card-info">
                <span class="label">Merk &amp; Model</span>
                <span class="val">${esc(brandClean || '—')} ${esc(modelClean || '')}</span>
              </div>
            </div>
            <div class="prod-spec-card">
              <div class="prod-spec-card-icon"><i class="fa-solid fa-location-dot"></i></div>
              <div class="prod-spec-card-info">
                <span class="label">Lokasi Penyimpanan</span>
                <span class="val">${esc(locName)}</span>
              </div>
            </div>
            <div class="prod-spec-card">
              <div class="prod-spec-card-icon"><i class="fa-solid fa-building-columns"></i></div>
              <div class="prod-spec-card-info">
                <span class="label">Sumber Perolehan</span>
                <span class="val">${esc(sourceName)}</span>
              </div>
            </div>
            ${x.holder ? `
            <div class="prod-spec-card" style="grid-column: 1 / -1; background:#fffbeb; border-color:#fde68a;">
              <div class="prod-spec-card-icon" style="color:#d97706; background:#ffffff;"><i class="fa-solid fa-user-clock"></i></div>
              <div class="prod-spec-card-info">
                <span class="label" style="color:#92400e;">Peminjam Terkini</span>
                <span class="val" style="color:#b45309;"><i class="fa-solid fa-user" style="margin-right:4px;"></i>${esc(x.holder)}</span>
              </div>
            </div>` : ''}
          </div>

          <!-- Primary Borrow Actions directly in Right Column -->
          <div class="prod-cta-area" style="margin-top:auto;padding-top:14px;">
            ${canBorrow ? `
              <button class="prod-btn-basket ${inBasket ? 'added' : ''}" data-act="quickAddLoan:${x.id}">
                <i class="fa-solid ${inBasket ? 'fa-check' : 'fa-clipboard-list'}"></i>
                <span>${inBasket ? 'Ada di Daftar Pinjaman' : '+ Daftar Pinjaman'}</span>
              </button>
              <button class="prod-btn-primary-borrow" data-act="borrowNowAsset:${x.id}">
                <i class="fa-solid fa-hand-holding-hand"></i>
                <span>Pinjam Sekarang (${avail} Tersedia)</span>
              </button>
            ` : ''}
          </div>
        </div>

        <!-- Full-Width Unit Section: Membentang dari bawah gambar CCTV di kiri hingga paling kanan, dan scrolling -->
        <div class="prod-unit-section full-width">
          <div class="prod-unit-header">
            <span>Rincian Tiap Unit Fisik (${total} Unit)</span>
            <div style="display:flex;align-items:center;gap:6px;">
              <div class="inv-cat-nav-btns" style="display:inline-flex;margin-right:2px;">
                <button class="inv-cat-nav-btn" data-act="scrollProdUnitsPrev" aria-label="Geser Unit ke Kiri" title="Geser Unit ke Kiri"><i class="fa-solid fa-chevron-left"></i></button>
                <button class="inv-cat-nav-btn" data-act="scrollProdUnitsNext" aria-label="Geser Unit ke Kanan" title="Geser Unit ke Kanan"><i class="fa-solid fa-chevron-right"></i></button>
              </div>
              ${canEditAsset ? `
                <button class="btn sm pri prod-unit-action-btn" data-act="openAddUnit:${x.id}" style="font-size:11px;padding:3px 12px;min-height:28px;font-weight:700;border-radius:var(--r-full);background:linear-gradient(135deg, #1d4ed8 0%, #2563eb 100%);color:#fff;border:none;box-shadow:0 2px 6px rgba(37,99,235,0.25);" title="Tambah Unit Fisik Baru">
                  <i class="fa-solid fa-plus"></i><span class="prod-unit-btn-text" style="margin-left:4px;">Tambah Unit</span>
                </button>
                <button class="btn sm prod-unit-action-btn" data-act="openEditAsset:${x.id}" style="font-size:11px;padding:3px 10px;min-height:28px;font-weight:650;border-radius:var(--r-full);" title="Edit Data Alat">
                  <i class="fa-solid fa-pen-to-square"></i><span class="prod-unit-btn-text" style="margin-left:4px;">Edit Data Alat</span>
                </button>
              ` : ''}
              ${canDeleteAsset ? `
                <button class="btn sm dang prod-unit-action-btn" data-act="confirmDeleteAsset:${x.id}" style="font-size:11px;padding:3px 10px;min-height:28px;font-weight:650;border-radius:var(--r-full);color:#ef4444;border-color:#fecaca;background:#fef2f2;" title="Hapus Alat">
                  <i class="fa-solid fa-trash"></i><span class="prod-unit-btn-text" style="margin-left:4px;">Hapus Alat</span>
                </button>
              ` : ''}
            </div>
          </div>

          <!-- List Menyamping: Setiap unit berjejer menyamping, memenuhi lebar dari kiri ke kanan, dan scrolling -->
          <div class="prod-unit-cards-scroll" id="prodUnitCardsScroll" data-horizontal-scroll="true">
            ${summary.units.map(u => {
              const isAvail = (u.status === 'Tersedia');
              const isDamaged = (u.status === 'Rusak');
              const isBorrowed = (u.status === 'Dipinjam');
              const uName = getUnitDisplayName(u, u.unit);
              const uCode = u.code || getUnitBarcode(invCode, u.unit);
              const statusChip = isAvail ? 'ok' : (isDamaged ? 'dang' : 'warn');

              let cardClass = '';
              if (isBorrowed) cardClass += ' is-borrowed';
              if (isDamaged) cardClass += ' is-damaged';

              return `
                <div class="prod-unit-hcard${cardClass}">
                  <div class="prod-unit-hcard-header" style="flex-direction:column;align-items:stretch;gap:6px;">
                    <div style="display:flex;align-items:center;justify-content:space-between;width:100%;gap:6px;">
                      ${renderUnitBranding(u, { size: 'xs' })}
                      <span class="chip ${statusChip}" style="font-size:10px;padding:1px 7px;font-weight:750;">${esc(u.status)}</span>
                    </div>
                    <div style="display:flex;align-items:center;gap:7px;flex-wrap:wrap;">
                      <span class="u-status-dot" style="background:${isAvail ? '#22c55e' : (isDamaged ? '#ef4444' : '#f59e0b')}"></span>
                      <span class="prod-unit-hcard-name">${esc(uName)}</span>
                      <span class="chip blue" style="font-size:10.5px;font-weight:750;letter-spacing:0.02em;padding:1px 7px;">${esc(uCode)}</span>
                    </div>
                  </div>

                  <div class="prod-unit-hcard-body">
                    <span class="prod-unit-hcard-cond">Kondisi: <b>${esc(u.cond || 'Baik')}</b></span>
                    ${u.loan_info ? `<span class="prod-unit-hcard-loan"><i class="fa-solid fa-user-clock"></i> Dipinjam: ${esc(u.loan_info.by || 'Kru')}</span>` : (isBorrowed && u.borrower ? `<span class="prod-unit-hcard-loan"><i class="fa-solid fa-user-clock"></i> Dipinjam: ${esc(u.borrower)}</span>` : '')}
                  </div>

                  <div class="prod-unit-hcard-actions">
                    ${isAvail ? `
                      <button class="btn sm pri" data-act="borrowNowUnit:${x.id}:${u.unit}" style="flex:1;font-size:11.5px;padding:5px 10px;min-height:30px;border-radius:8px;font-weight:700;white-space:nowrap;">
                        <i class="fa-solid fa-box-archive"></i> Pinjam Unit Ini
                      </button>
                    ` : ''}
                    ${isBorrowed ? `
                      <button class="btn sm" data-act="returnSingleUnit:${x.id}:${u.unit}" style="flex:1;font-size:11.5px;padding:5px 10px;min-height:30px;border-radius:8px;font-weight:700;white-space:nowrap;background:linear-gradient(135deg, #15803d, #16a34a);color:#fff;border:none;box-shadow:0 2px 6px rgba(22,163,74,0.25);cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:5px;" title="Kembalikan Unit Ini">
                        <i class="fa-solid fa-rotate-left"></i><span>Kembalikan Sekarang</span>
                      </button>
                    ` : ''}
                    <button class="btn sm" data-quick="lapor" data-preset="${x.id}" data-unit="${u.unit}" style="font-size:11.5px;padding:5px 9px;min-height:30px;color:#d97706;border-radius:8px;" title="Lapor Kerusakan">
                      <i class="fa-solid fa-wrench"></i>
                    </button>
                    <button class="btn sm" data-act="printUnitBarcode:${x.id}:${u.unit}" style="font-size:11.5px;padding:5px 9px;min-height:30px;border-radius:8px;" title="Cetak Barcode">
                      <i class="fa-solid fa-print"></i>
                    </button>
                    ${canEditAsset ? `
                      <button class="btn sm" data-act="openEditUnit:${x.id}:${u.unit}" style="font-size:11.5px;padding:5px 9px;min-height:30px;border-radius:8px;" title="Edit Unit">
                        <i class="fa-solid fa-pen-to-square"></i>
                      </button>
                    ` : ''}
                  </div>
                </div>
              `;
            }).join('')}
            ${canEditAsset ? `
              <div class="prod-unit-hcard" data-act="openAddUnit:${x.id}" style="border:2px dashed #93c5fd;background:#f0f9ff;display:flex;flex-direction:column;align-items:center;justify-content:center;cursor:pointer;min-width:140px;min-height:160px;transition:all 0.2s ease;padding:16px 12px;text-align:center;" title="Tambah Unit Fisik Baru">
