/* ============================================================
   PAGE: MANAJEMEN KRU
   ============================================================ */
const KRU_DIVS = ['Layouter','Editor','Technical','Engagement'];
let kruFilter='Aktif';

function formatAngkatanDisplay(ang, c) {
  const cName = ((c && c.name) || '').toLowerCase();
  const cPid = ((c && c.ptvId) || '').toUpperCase();
  const raw = (ang || '').trim();
  if (raw.toLowerCase() === 'additional' || cPid === 'PTV-017' || cPid === 'PTV-018' || cName.includes('kru testing') || cName.includes('niki santri')) {
    return 'Additional';
  }
  if (!raw) return 'Angkatan belum ditentukan';
  const lower = raw.toLowerCase();
  if (lower === 'internship') return 'Internship';
  if (lower === 'pembina') return 'Pembina';
  if (lower === 'pengarah') return 'Pengarah';
  if (lower.startsWith('angkatan')) return raw;
  return 'Angkatan ' + raw;
}

function groupCrewByAngkatan(crewList) {
  const groups = {};
  (crewList || []).forEach(c => {
    if (!c) return;
    const label = formatAngkatanDisplay(c.angkatan, c);
    if (!groups[label]) groups[label] = [];
    groups[label].push(c);
  });

  const sortedLabels = Object.keys(groups).sort((a, b) => {
    if (a === 'Angkatan belum ditentukan') return 1;
    if (b === 'Angkatan belum ditentukan') return -1;
    if (a === 'Additional') return 1;
    if (b === 'Additional') return -1;
    if (a === 'Internship') return 1;
    if (b === 'Internship') return -1;
    const numA = parseInt(a.replace(/[^\d]/g, ''), 10);
    const numB = parseInt(b.replace(/[^\d]/g, ''), 10);
    if (!isNaN(numA) && !isNaN(numB)) return numB - numA;
    return a.localeCompare(b, 'id');
  });

  return sortedLabels.map(label => {
    let icon = 'fa-solid fa-graduation-cap';
    if (label === 'Additional') {
      icon = 'fa-solid fa-user-plus';
    } else if (label === 'Internship') {
      icon = 'fa-solid fa-user-clock';
    } else if (label === 'Pembina' || label === 'Pengarah') {
      icon = 'fa-solid fa-user-tie';
    } else if (label === 'Angkatan belum ditentukan') {
      icon = 'fa-solid fa-circle-question';
    }

    return {
      label,
      icon,
      rows: groups[label]
    };
  });
}

function pgKru(){
  const aktifCrew = (DB.crew || []).filter(c => KRU_DIVS.includes(c.div) && c.status === 'Aktif');
  const nonaktifCrew = (DB.crew || []).filter(c => KRU_DIVS.includes(c.div) && c.status !== 'Aktif');
  const pembinaCrew = (DB.crew || []).filter(c => c.div === 'Pembina');
  const pengarahCrew = (DB.crew || []).filter(c => c.div === 'Pengarah');

  const aktifCount = aktifCrew.length;
  const canManage = ME.role==='eksekutif';

  const renderCrewGroupList = (list, isAktifSec = true) => {
    const grps = groupCrewByAngkatan(list);
    if (!grps.length) return `<p class="t-sm muted" style="text-align:center;padding:20px 0">Tidak ada data kru di kategori ini.</p>`;
    return grps.map(g => `
      <div class="sec" style="margin-top:14px">
        <div class="sec-hd" style="padding-bottom:6px">
          <div>
            <h3 style="display:inline-block;font-size:13.5px;font-weight:700;color:var(--ink)">
              <i class="${g.icon || 'fa-solid fa-graduation-cap'}" style="font-size:12px;margin-right:6px;opacity:0.8;${g.label==='Additional'?'color:#2563eb':''}"></i>${esc(g.label)}
            </h3>
            <span class="chip ${g.label==='Additional' ? 'blue' : (isAktifSec ? 'blue' : 'muted')}" style="margin-left:8px;font-size:10.5px">${g.rows.length}</span>
          </div>
        </div>
        <div class="list">${g.rows.map(c => `
          <button class="li" data-crew="${c.id}">
            ${avatarHTML(c.name, c.photo || c.foto_url || c.foto, 'sm')}
            <span class="li-body">
              <span class="li-t trunc">${esc(c.name)}</span>
              <span class="li-s trunc">${esc(c.pos)}${KRU_DIVS.includes(c.div)?' · '+esc(c.div):''}</span>
            </span>
            ${chip(c.status)}
          </button>`).join('')}
        </div>
      </div>
    `).join('');
  };

  let contentHtml = '';
  if (kruFilter === 'Aktif') {
    contentHtml = `
      <div class="sec-hd mt16">
        <h2 style="font-size:16px;font-weight:700">KRU AKTIF</h2>
        <span class="chip blue" style="font-size:11px">${aktifCrew.length} Kru</span>
      </div>
      ${renderCrewGroupList(aktifCrew, true)}
    `;
  } else if (kruFilter === 'Nonaktif') {
    contentHtml = `
      <div class="sec-hd mt16">
        <h2 style="font-size:16px;font-weight:700">KRU NONAKTIF</h2>
        <span class="chip muted" style="font-size:11px">${nonaktifCrew.length} Kru</span>
      </div>
      ${renderCrewGroupList(nonaktifCrew, false)}
    `;
  } else if (kruFilter === 'Pengarah') {
    contentHtml = `
      <div class="sec-hd mt16">
        <h2 style="font-size:16px;font-weight:700">PENGARAH</h2>
        <span class="chip" style="font-size:11px">${pengarahCrew.length}</span>
      </div>
      <div class="list mt12">${pengarahCrew.map(c => `
        <button class="li" data-crew="${c.id}">
          ${avatarHTML(c.name, c.photo || c.foto_url || c.foto, 'sm')}
          <span class="li-body"><span class="li-t trunc">${esc(c.name)}</span>
          <span class="li-s trunc">${esc(c.pos)}</span></span>
          ${chip(c.status)}
        </button>`).join('')}</div>
    `;
  } else if (kruFilter === 'Pembina') {
    contentHtml = `
      <div class="sec-hd mt16">
        <h2 style="font-size:16px;font-weight:700">PEMBINA</h2>
        <span class="chip" style="font-size:11px">${pembinaCrew.length}</span>
      </div>
      <div class="list mt12">${pembinaCrew.map(c => `
        <button class="li" data-crew="${c.id}">
          ${avatarHTML(c.name, c.photo || c.foto_url || c.foto, 'sm')}
          <span class="li-body"><span class="li-t trunc">${esc(c.name)}</span>
          <span class="li-s trunc">${esc(c.pos)}</span></span>
          ${chip(c.status)}
        </button>`).join('')}</div>
    `;
  } else {
    // Semua
    contentHtml = `
      <div class="sec-hd mt16">
        <h2 style="font-size:16px;font-weight:700">KRU AKTIF</h2>
        <span class="chip blue" style="font-size:11px">${aktifCrew.length} Kru</span>
      </div>
      ${renderCrewGroupList(aktifCrew, true)}

      <div class="sec-hd mt24" style="border-top:1px solid var(--line);padding-top:18px">
        <h2 style="font-size:16px;font-weight:700">KRU NONAKTIF</h2>
        <span class="chip muted" style="font-size:11px">${nonaktifCrew.length} Kru</span>
      </div>
      ${renderCrewGroupList(nonaktifCrew, false)}

      ${(pembinaCrew.length || pengarahCrew.length) ? `
        <div class="sec-hd mt24" style="border-top:1px solid var(--line);padding-top:18px">
          <h2 style="font-size:16px;font-weight:700">PEMBINA & PENGARAH</h2>
          <span class="chip" style="font-size:11px">${pembinaCrew.length + pengarahCrew.length}</span>
        </div>
        <div class="list mt12">${[...pembinaCrew, ...pengarahCrew].map(c => `
          <button class="li" data-crew="${c.id}">
            ${avatarHTML(c.name, c.photo || c.foto_url || c.foto, 'sm')}
            <span class="li-body"><span class="li-t trunc">${esc(c.name)}</span>
            <span class="li-s trunc">${esc(c.pos)}${c.div ? ' · ' + esc(c.div) : ''}</span></span>
            ${chip(c.status)}
          </button>`).join('')}</div>
      ` : ''}
    `;
  }

  return `<div class="page">
    <div class="row-b" style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:16px;flex-wrap:wrap;">
      <div class="filters" style="margin-bottom:0;">
        ${[['Aktif','Kru Aktif'],['Nonaktif','Kru Nonaktif'],['Pengarah','Pengarah'],['Pembina','Pembina'],['semua','Semua']].map(([k,l])=>
          `<button class="fchip${kruFilter===k?' on':''}" data-filter-kru="${k}">${l}</button>`).join('')}
      </div>
      <div class="row gap8" style="align-items:center;">
        ${canManage?`<button class="btn sm" data-act="openLoginHistory" title="Riwayat Login" aria-label="Riwayat Login" style="min-height:36px;padding:0 10px;white-space:nowrap;font-weight:600"><i class="fa-solid fa-clock-rotate-left"></i><span class="only-desktop" style="margin-left:6px">Riwayat Login</span></button>`:''}
        ${canManage?`<button class="btn sm pri" data-act="openNewCrew" title="Tambah Kru" aria-label="Tambah Kru" style="min-height:36px;padding:0 12px;white-space:nowrap">${ic.plus}<span class="only-desktop">Tambah Kru</span></button>`:''}
      </div>
    </div>
    <div class="grid-2 mt16" style="grid-template-columns:repeat(auto-fit,minmax(150px,1fr))">
      <div class="stat"><b class="num">${aktifCount}</b><span>Kru aktif</span></div>
      <div class="stat"><b class="num">${DB.crew.filter(c=>c.div==='Pembina').length}</b><span>Pembina</span></div>
    </div>
    <div class="mt18" id="pgList">
      ${contentHtml}
    </div>
  </div>`;
}

function isMatchCrewName(target, c) {
  if (!target || !c) return false;
  const t = String(target).trim().toLowerCase();
  const cn = String(c.name || '').trim().toLowerCase();
  if (t === cn) return true;

  const cId = String(c.ptvId || '').trim().toLowerCase();
  if (cId && (t === cId || t.includes(cId))) return true;

  const cu = String(c.username || '').trim().toLowerCase();
  if (cu && (t === cu || t.includes(cu))) return true;

  const cleanWords = (str) => {
    const s = str.replace(/['"`’.,-]/g, ' ');
    const prefixes = ['muhammad', 'mochammad', 'mohammad', 'ahmad', 'akhmad', 'm', 'moh', 'ustadz', 'ust', 'agus', 'gus', 'kh'];
    let words = s.split(/\s+/).map(w => w.trim()).filter(Boolean);
    while (words.length > 0 && prefixes.includes(words[0])) {
      words.shift();
    }
    return words;
  };

  const tWords = cleanWords(t);
  const cWords = cleanWords(cn);
  if (!tWords.length || !cWords.length) return false;

  if (tWords.length === 1) {
    const single = tWords[0];
    for (const cw of cWords) {
      if (single === cw) return true;
      if (single.length >= 5 && (cw.startsWith(single) || single.startsWith(cw))) return true;
    }
    return false;
  }

  const common = tWords.filter(w => cWords.includes(w));
  if (common.length >= 2) return true;
  if (common.length === 1 && tWords.length === 2 && cWords.length === 2) return true;

  return false;
}

function openCrew(id){
  const c=(DB.crew||[]).find(x=>String(x.id)===String(id)); if(!c)return;

  // 1. Acara yang diikuti (hanya acara aktif/selesai yang kru ditugaskan)
  const matchedEvents = (DB.events||[]).filter(e => {
    if (!e || (e.status && (e.status.toLowerCase() === 'batal' || e.status.toLowerCase() === 'cancelled'))) return false;
    if (!Array.isArray(e.crew)) return false;
    return e.crew.some(crName => isMatchCrewName(crName, c));
  });
  const evCount = matchedEvents.length;

  // 2. Alat yang dipinjam (dipisahkan antara sedang aktif dibawa vs total riwayat peminjaman)
  const matchedLoans = (DB.loans||[]).filter(l => {
    if (!l) return false;
    return isMatchCrewName(l.by, c);
  });
  const activeLoans = matchedLoans.filter(l => !l.back);
  const returnedLoans = matchedLoans.filter(l => !!l.back);

  const canManage = ME.role==='eksekutif';
  const hasAccount = !!(c.username);
  const kategori = KRU_DIVS.includes(c.div)?'Kru':(c.div||'Kru');
  const labelDiv = KRU_DIVS.includes(c.div)?`${kategori} &middot; ${esc(c.div)}`:esc(kategori);

  const santriLetters = (DB.docs || []).filter(d => {
    if (!d) return false;
    const isType = d.type === 'Surat Izin Resmi' || d.type === 'Izin Santri' || d.type === 'Surat Izin';
    if (!isType) return false;
    if (Array.isArray(d.recipients) && d.recipients.some(r => isMatchCrewName(typeof r === 'string' ? r : r.nama || '', c))) return true;
    if (isMatchCrewName(d.owner || '', c)) return true;
    return false;
  });

  openSheet('Detail Kru',`
    <div class="row" style="padding-bottom:14px">
      ${avatarHTML(c.name, c.photo || c.foto_url || c.foto, 'lg')}
      <span class="tight"><span class="t-lg" style="display:block">${esc(c.name)}</span>
      <span class="t-sm muted">${esc(c.pos)} &middot; ${labelDiv}</span></span>
    </div>
    <div class="card pad">
      <div class="kv"><span>ID PTV</span><b class="num">${esc(c.ptvId||'—')}</b></div>
      <div class="kv"><span>Kategori</span><b>${kategori}</b></div>
      ${KRU_DIVS.includes(c.div)?`<div class="kv"><span>Divisi</span><b>${esc(c.div)}</b></div>`:''}
      <div class="kv"><span>Status Kru</span>${chip(c.status)}</div>
      <div class="kv"><span>Status Akun</span><span class="chip ${c.accountStatus==='Aktif'?'ok':(c.accountStatus==='Nonaktif'&&hasAccount?'warn':'muted')}" style="font-size:11px">${hasAccount?(c.accountStatus||'Aktif'):'Belum Ada Akun'}</span></div>
      <div class="kv"><span>Akun Portal</span>
        <span style="display:flex;align-items:center;gap:8px">
          <span class="chip ${hasAccount?'blue':'muted'}" style="font-size:11px">${hasAccount?'Tersedia':'Belum Ada'}</span>
          ${hasAccount?`<b class="num" style="font-size:12px">${esc(c.username)}</b>`:''}
          ${canManage&&!hasAccount?`<button class="btn sm pri" data-act="activateCrewAccount:${c.id}" style="padding:0 10px;min-height:28px;font-size:12px">Aktifkan</button>`:''}
        </span>
      </div>
      <div class="kv"><span>Angkatan</span><b>${esc(formatAngkatanDisplay(c.angkatan, c))}</b></div>
      ${c.phone?`<div class="kv"><span>WhatsApp</span><b>${esc(c.phone)}</b></div>`:''}
      ${c.email?`<div class="kv"><span>Email</span><b style="font-size:12px">${esc(c.email)}</b></div>`:''}
      ${c.join_date?`<div class="kv"><span>Bergabung</span><b>${fmtDate(c.join_date.substring(0,10))}</b></div>`:''}
      <div class="kv"><span>Acara diikuti</span><b class="num">${evCount} <span class="muted" style="font-size:12px;font-weight:normal">kegiatan</span></b></div>
      <div class="kv"><span>Alat dipinjam</span><span style="display:inline-flex;align-items:center;gap:5px">${activeLoans.length > 0 ? `<b class="num" style="color:#2563eb">${activeLoans.length} aktif</b><span class="muted" style="font-size:12px">(${matchedLoans.length} total)</span>` : `<b class="num">${matchedLoans.length}</b><span class="muted" style="font-size:12px">riwayat (${activeLoans.length} aktif)</span>`}</span></div>
    </div>
    ${(()=>{
      const isGoogleLinked = !!(c.oauth_uid && (c.oauth_provider === 'google' || !c.oauth_provider));
      const isGoogleRegistered = !!(c.oauth_email && !c.oauth_uid);
      let oauthBadgeClass = 'muted';
      let oauthBadgeText = 'Belum Terhubung';
      let oauthDotColor = '#94a3b8';

      if (isGoogleLinked) {
        oauthBadgeClass = 'ok';
        oauthBadgeText = 'Terhubung';
        oauthDotColor = '#10b981';
      } else if (isGoogleRegistered) {
        oauthBadgeClass = 'warn';
        oauthBadgeText = 'Google Terdaftar (Belum Login)';
        oauthDotColor = '#f59e0b';
      }

      return `
      <div class="card pad mt12" style="border:1px solid var(--line-2)">
        <div class="row-b" style="margin-bottom:8px">
          <div style="display:flex;align-items:center;gap:8px">
            <i class="fa-brands fa-google" style="font-size:16px;color:#4285F4"></i>
            <div>
              <div style="font-size:13px;font-weight:700;line-height:1.2">Google OAuth</div>
              <div style="font-size:11px;color:var(--muted)">Autentikasi SSO Cepat</div>
            </div>
          </div>
          <span class="chip ${oauthBadgeClass}" style="font-size:11px">
            <span style="width:6px;height:6px;border-radius:50%;background:${oauthDotColor};display:inline-block;margin-right:3px"></span>
            ${oauthBadgeText}
          </span>
        </div>
        <div class="kv" style="padding:6px 0;border-top:1px solid var(--line-2)">
          <span style="font-size:12px;color:var(--muted)">Email Google</span>
          <b style="font-size:12.5px;font-weight:600;word-break:break-all">${c.oauth_email ? esc(c.oauth_email) : '<span class="muted" style="font-weight:normal">Belum didaftarkan</span>'}</b>
        </div>
        ${canManage ? `
          <div style="margin-top:10px;padding-top:8px;border-top:1px solid var(--line-2);display:flex;gap:8px;align-items:center;flex-wrap:wrap">
            <button class="btn sm pri" data-act="promptGoogleEmail:${c.id}" style="padding:0 12px;min-height:30px;font-size:12px">
              <i class="fa-brands fa-google"></i> ${c.oauth_email ? 'Ubah Email Google' : 'Tambahkan Email Google'}
            </button>
            ${c.oauth_email ? `
              <button class="btn sm dang" data-act="unlinkGoogleEmail:${c.id}" style="padding:0 10px;min-height:30px;font-size:12px" title="Hapus Email Google">
                <i class="fa-solid fa-trash"></i> Hapus Tautan
              </button>
            ` : ''}
          </div>
        ` : ''}
      </div>`;
    })()}
    ${activeLoans.length ? `
    <div class="sec mt12">
      ${sectionHd('Alat Sedang Dipinjam', `${activeLoans.length} Unit Aktif`)}
      <div class="stack gap8">
        ${activeLoans.map(al => {
          const it = itemById(al.item) || {};
          const uObj = (it?.unit_conditions || []).find(u => Number(u.unit) === Number(al.unit_no));
          const uDisplayName = al.unit_name || (uObj ? getUnitDisplayName(uObj, al.unit_no) : (al.unit_no ? `Unit ${String(al.unit_no).padStart(2,'0')}` : ''));
          const itName = it.name || 'Alat PTV';
          const uCode = al.unit_code || (it?.code && al.unit_no ? getUnitBarcode(it.code, al.unit_no) : '');
          return `
          <div class="card pad" style="background:#eff6ff; border:1px solid #bfdbfe; border-left:4px solid #2563eb; border-radius:10px;">
            <div class="row-b" style="align-items:flex-start;gap:8px;">
              <div style="min-width:0;flex:1;">
                <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;">
                  <span class="font-bold" style="font-size:13px; color:#1e3a8a;"><i class="fa-solid fa-box-open" style="color:#2563eb;margin-right:6px"></i>${esc(itName)}</span>
                  ${renderUnitBranding(uObj || al, { size: 'xs' })}
                </div>
                ${uDisplayName ? `<div style="font-size:11.5px;font-weight:700;color:#1e40af;margin-top:3px;">${esc(uDisplayName)}${uCode ? ` &bull; ${esc(uCode)}` : ''}</div>` : ''}
              </div>
              <span class="chip" style="background:#dbeafe; color:#1e40af; font-size:10px; font-weight:800; border:1px solid #bfdbfe;">${esc(uCode || uDisplayName || '1 unit')}</span>
            </div>
            <div class="t-xs mt4" style="color:#1d4ed8">
              <i class="fa-regular fa-calendar-check"></i> Dipinjam: ${fmtDate(al.out)} &bull; <b>Batas Kembali: ${fmtDate(al.due)}</b>
            </div>
            <div class="t-xs muted mt2"><i class="fa-solid fa-clipboard-list" style="font-size:10px;margin-right:4px"></i>Keperluan: ${esc(al.purpose || 'Operasional PTV')}</div>
          </div>`;
        }).join('')}
      </div>
    </div>` : ''}

    ${matchedEvents.length ? `
    <div class="sec mt12">
      ${sectionHd('Acara & Liputan Diikuti', `${matchedEvents.length} Kegiatan`)}
      <div class="stack gap8">
        ${matchedEvents.slice(0, 10).map(evItem => `
          <div class="card pad" style="background:#f8fafc; border:1px solid #e2e8f0; border-radius:10px;">
            <div class="row-b">
              <span class="font-bold" style="font-size:13px; color:#0f172a;"><i class="fa-regular fa-calendar-check" style="color:#4f46e5;margin-right:6px"></i>${esc(evItem.name)}</span>
              <span class="chip ${evItem.status === 'Selesai' ? 'ok' : 'blue'}" style="font-size:10px;">${esc(evItem.status || 'Terjadwal')}</span>
            </div>
            <div class="t-xs muted mt2">
              <i class="fa-regular fa-calendar"></i> ${fmtDate(evItem.date)} &bull; <i class="fa-solid fa-location-dot" style="margin-left:4px"></i> ${esc(evItem.loc || 'Studio PTV')}
            </div>
          </div>
        `).join('')}
      </div>
    </div>` : ''}

    ${(!activeLoans.length && returnedLoans.length) ? `
    <div class="sec mt12">
      ${sectionHd('Riwayat Peminjaman Alat', `${returnedLoans.length} Unit Selesai`)}
      <div class="stack gap8">
        ${returnedLoans.slice(0, 5).map(rl => {
          const it = itemById(rl.item) || {};
          const uObj = (it?.unit_conditions || []).find(u => Number(u.unit) === Number(rl.unit_no));
          const uDisplayName = rl.unit_name || (uObj ? getUnitDisplayName(uObj, rl.unit_no) : (rl.unit_no ? `Unit ${String(rl.unit_no).padStart(2,'0')}` : ''));
          const itName = it.name || 'Alat PTV';
          const uCode = rl.unit_code || (it?.code && rl.unit_no ? getUnitBarcode(it.code, rl.unit_no) : '');
          return `
          <div class="card pad" style="background:#f8fafc; border:1px solid #e2e8f0; border-radius:10px;">
            <div class="row-b">
              <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;">
                <span class="font-bold" style="font-size:12.5px; color:#334155;">${esc(itName)}</span>
                ${renderUnitBranding(uObj || rl, { size: 'xs' })}
              </div>
              <span class="chip ok" style="font-size:10px;"><i class="fa-solid fa-check"></i> Selesai</span>
            </div>
            <div class="t-xs muted mt2">
              ${esc(uDisplayName ? `${uDisplayName} &bull; ` : '')}${uCode ? `${esc(uCode)} &bull; ` : ''}Dipinjam: ${fmtDate(rl.out)} &bull; Dikembalikan: ${fmtDate(rl.back)}
            </div>
          </div>`;
        }).join('')}
      </div>
    </div>` : ''}

    ${santriLetters.length ? `
    <div class="sec mt12">
      ${sectionHd('Riwayat Surat', 'Dokumen')}
      <div class="stack gap8">
        ${santriLetters.map(sl => `
          <div class="card pad" style="background:#f8fafc; border:1px solid #e2e8f0; border-radius:10px;">
            <div class="row-b">
              <span class="num font-bold" style="font-size:12.5px; color:#1e478f;">${esc(sl.no)}</span>
              <span class="chip ok" style="font-size:10px;">Diterbitkan</span>
            </div>
            <div class="t-md font-bold mt4" style="font-size:13px; color:#0f172a;">${esc(sl.subject)}</div>
            <div class="t-xs muted mt2"><i class="fa-regular fa-calendar"></i> ${fmtDate(sl.date)} &bull; Pengesah: ${esc(sl.owner || 'Eksekutif')}</div>
            <div class="wrap mt8">
              <button class="btn sm" data-doc="${sl.id}"><i class="fa-solid fa-eye"></i> Lihat Dokumen</button>
              <button class="btn sm pri" data-act="pdf:${sl.no}"><i class="fa-solid fa-download"></i> Unduh PDF</button>
            </div>
          </div>
        `).join('')}
      </div>
    </div>` : ''}`,
    {foot:`
      <div class="wrap" style="width:100%">
        ${canManage?`
          <button class="btn pri" data-act="openEditCrew:${c.id}"><i class="fa-solid fa-pen-to-square"></i>Edit Kru</button>
          <button class="btn" data-act="toggleCrewStatus:${c.id}">${c.status==='Aktif'?'Nonaktifkan':'Aktifkan'} Kru</button>
          <button class="btn dang" data-act="confirmDeleteCrew:${c.id}"><i class="fa-solid fa-trash"></i>Hapus</button>
        `:''}
        ${c.phone?`<button class="btn" data-act="wa:${c.phone}">${ic.wa}WhatsApp</button>`:''}
      </div>`});
}

/* ============================================================
   PAGE: ID DIGITAL + VERIFIKASI PUBLIK
   ============================================================ */
function pgID(){
  const hasPtvId = !!(ME.ptvId && ME.ptvId.trim());
  const vBase = (typeof VERIFIKASI_IDENTITAS_BASE_URL !== 'undefined' ? VERIFIKASI_IDENTITAS_BASE_URL : (window.location.origin + '/verifikasi-identitas/')).replace(/\/+$/, '');
  const verifyUrl = hasPtvId ? (vBase + '/?id=' + encodeURIComponent(ME.ptvId)) : '';

  let ptvIdVal = (ME.ptvId || '').trim();
  if (!ptvIdVal) {
    ptvIdVal = 'PTV-XXX';
  } else if (/^\d+$/.test(ptvIdVal)) {
    ptvIdVal = 'PTV-' + ptvIdVal.padStart(3, '0');
  } else if (!ptvIdVal.toUpperCase().startsWith('PTV-')) {
    ptvIdVal = 'PTV-' + ptvIdVal;
  }

  const rolePosVal = (ME.pos || ME.div || 'Layouter').trim();
  const divVal = (ME.div || 'TECHNICAL').trim();
  const photoUrl = ME.photo || ME.foto_url || ME.foto || '';
  const fullName = (ME.name || 'KRU PROGRESIF').trim();
  const inits = fullName.split(' ').map(n=>n[0]).filter(Boolean).slice(0,2).join('').toUpperCase() || 'PTV';
  const statusVal = (ME.status || 'Aktif').trim();

  return `<div class="page" style="padding-bottom:calc(var(--dock-h) + var(--sab) + 48px)">
    <div class="idcard-holder-wrap">
      <div class="idcard">
        <!-- Ambient SVG Wave Background (Inspirasi Arah Visual Reference) -->
        <div class="idcard-bg-layer" aria-hidden="true">
          <svg class="idcard-bg-waves" viewBox="0 0 360 560" fill="none" xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="none">
            <path d="M-20 80C60 40 140 130 240 90C310 60 350 110 380 95V-20H-20V80Z" fill="url(#pdWaveGrad1)" opacity="0.35"/>
            <path d="M-30 220C50 170 120 250 220 200C290 165 330 215 390 190V-20H-30V220Z" fill="url(#pdWaveGrad2)" opacity="0.2"/>
            <path d="M-20 440C70 410 130 480 230 430C300 395 340 440 380 420V580H-20V440Z" fill="url(#pdWaveGrad1)" opacity="0.25"/>
            <path d="M-10 140C90 110 160 210 270 160C330 130 360 170 390 155" stroke="rgba(147, 197, 253, 0.18)" stroke-width="2.5" stroke-linecap="round"/>
            <path d="M-20 380C80 340 150 430 260 380C320 350 350 390 380 375" stroke="rgba(147, 197, 253, 0.14)" stroke-width="2" stroke-linecap="round"/>
            <path d="M-10 490C90 460 170 530 280 480C330 455 360 485 390 475" stroke="rgba(147, 197, 253, 0.12)" stroke-width="2" stroke-linecap="round"/>
            <defs>
              <linearGradient id="pdWaveGrad1" x1="0" y1="0" x2="360" y2="560" gradientUnits="userSpaceOnUse">
                <stop stop-color="#1E40AF" stop-opacity="0.6"/>
                <stop offset="1" stop-color="#0E2F72" stop-opacity="0.1"/>
              </linearGradient>
              <linearGradient id="pdWaveGrad2" x1="360" y1="0" x2="0" y2="560" gradientUnits="userSpaceOnUse">
                <stop stop-color="#3B82F6" stop-opacity="0.4"/>
                <stop offset="1" stop-color="#1D4ED8" stop-opacity="0.05"/>
              </linearGradient>
            </defs>
          </svg>
        </div>

        <!-- Card Body -->
        <div class="idcard-body">
          <!-- Top Bar: Branding on Left, QR Code on Right -->
          <div class="idcard-top-bar">
            <div class="idcard-brand-box">
              <img src="${PTV_ID_CARD_LOGO_URL}" alt="Progresif TV Production" class="idcard-logo-img" style="height:26px;width:auto;max-width:145px;object-fit:contain;display:block;margin-bottom:2px;">
              <div class="idcard-brand-label">KARTU IDENTITAS RESMI</div>
            </div>
            <div class="idcard-qr-box">
              ${hasPtvId ? qrSVG(verifyUrl, 64, { margin: 0 }) : `<div style="font-size:10px;font-weight:850;color:#0A3C74;text-align:center;line-height:1.2">PTV<br>ID</div>`}
            </div>
          </div>

          <!-- Center: Large Portrait Crew Photo -->
          <div class="idcard-photo-frame">
            ${photoUrl ? `
              <img src="${esc(photoUrl)}" alt="${esc(fullName)}" class="idcard-photo-img" onerror="this.onerror=null;this.parentElement.innerHTML='<div class=\\'idcard-photo-fallback\\'>${esc(inits)}</div>'">
            ` : `
              <div class="idcard-photo-fallback">${esc(inits)}</div>
            `}
          </div>

          <!-- Crew Name -->
          <div class="idcard-identity-block">
            <div class="idcard-person-name">${esc(fullName)}</div>
          </div>

          <!-- Credentials Grid -->
          <div class="idcard-creds-grid">
            <div class="idcard-cred-item">
              <div class="idcard-cred-lbl">KRU NO.</div>
              <div class="idcard-cred-val font-mono">${esc(ptvIdVal)}</div>
            </div>
            <div class="idcard-cred-item">
              <div class="idcard-cred-lbl">POSITION</div>
              <div class="idcard-cred-val">${esc(rolePosVal)}</div>
            </div>
            <div class="idcard-cred-item">
              <div class="idcard-cred-lbl">DIVISI</div>
              <div class="idcard-cred-val">${esc(divVal)}</div>
            </div>
            <div class="idcard-cred-item">
              <div class="idcard-cred-lbl">STATUS</div>
              <div class="idcard-cred-val">${esc(statusVal)}</div>
            </div>
          </div>
        </div>

        <!-- Footer Strip: PROGRESIF TV & 2026–2027 -->
        <div class="idcard-footer-strip">
          <div class="idcard-footer-brand">PROGRESIF TV</div>
          <div class="idcard-footer-expiry">2026–2027</div>
        </div>
      </div>

      <div class="card pad mt16">
        <div class="row gap8">
          <span class="li-ic">${ic.info}</span>
          <p class="t-sm ink2" style="margin:0">Kartu identitas resmi kru Progresif TV. Gunakan tautan verifikasi di bawah untuk membuktikan keabsahan status kru secara publik.</p>
        </div>
      </div>
      <div class="wrap mt12" style="padding-bottom:16px;gap:8px;justify-content:center">
        ${hasPtvId ? `
          <a href="${verifyUrl}" target="_blank" rel="noopener" class="btn pri">${ic.eye}Lihat halaman verifikasi</a>
          <button class="btn" data-act="downloadIdCard" data-id-fn="ID-Card-${esc(ME.ptvId || 'PTV')}">${ic.download}Unduh ID</button>
        ` : `
          <button class="btn pri" disabled style="opacity:0.6">${ic.eye}ID belum tersedia</button>
        `}
      </div>
    </div>
  </div>`;
}

function pgVerifikasi(){
  const rawId = state.route.id ? decodeURIComponent(state.route.id) : '';
  const isDocVerify = rawId.startsWith('DOC-') || rawId.includes('/SI-') || rawId.includes('/ST-') || /^\d{3}\//.test(rawId);
  
  if (isDocVerify) {
    const searchNo = rawId.replace(/^DOC-/, '').trim();
    const doc = (DB.docs || []).find(d => String(d.no || '').trim() === searchNo || String(d.id || '').trim() === searchNo);
    const docNo = doc ? doc.no : searchNo;
    const docSubject = doc ? doc.subject : 'Surat Izin Resmi';
    const docDate = doc ? fmtDate(doc.date, true) : fmtDate(iso(today), true);
    const docIssuer = doc ? (doc.owner || 'Eksekutif') : (ME.name || 'Eksekutif');
    const recipientCount = (doc && Array.isArray(doc.recipients)) ? doc.recipients.length : (doc && Array.isArray(doc.santri_details) ? doc.santri_details.length : 0);

    return `<div class="page" style="max-width:540px;margin:0 auto;padding-bottom:40px;">
      <div class="row-b mb12" style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;">
        <button class="back" data-go="arsip">${ic.chevL} Kembali ke Surat & Arsip</button>
        <span class="chip ok"><i class="fa-solid fa-circle-check"></i> RESMI & TERDAFTAR</span>
      </div>
      <div class="card pad" style="text-align:center;padding:32px 24px;border-radius:18px;border:1.5px solid #a7f3d0;background:#fff;box-shadow:0 8px 30px rgba(16,185,129,0.08);">
        <div style="width:64px;height:64px;border-radius:50%;background:linear-gradient(135deg,#ecfdf5,#d1fae5);color:#059669;display:grid;place-items:center;margin:0 auto 16px;box-shadow:0 4px 14px rgba(16,185,129,0.2);">
          <i class="fa-solid fa-certificate" style="font-size:30px;"></i>
        </div>
        <p class="t-xs" style="margin:0;letter-spacing:.14em;color:#059669;font-weight:800;text-transform:uppercase;">DOKUMEN RESMI TERVERIFIKASI</p>
        <h1 class="t-xl font-bold" style="margin:8px 0 4px;font-size:20px;color:#0f172a;">${esc(docSubject)}</h1>
        <p class="t-sm muted" style="margin:0;color:#64748b;font-weight:600;">Progresif TV — Pesantren Progresif Bumi Shalawat</p>
        
        <div class="divider" style="margin:18px 0;"></div>
        
        <div class="stack gap8" style="text-align:left;">
          <div class="kv"><span>Nomor Surat</span><b class="num" style="color:#1e478f;font-weight:800;">${esc(docNo)}</b></div>
          <div class="kv"><span>Status Dokumen</span><b style="color:#059669;font-weight:800;"><i class="fa-solid fa-circle-check"></i> SAH & AKTIF</b></div>
          <div class="kv"><span>Diterbitkan Oleh</span><b>${esc(docIssuer)}</b></div>
          <div class="kv"><span>Tanggal Berlaku</span><b>${esc(docDate)}</b></div>
          ${recipientCount ? `<div class="kv"><span>Jumlah Santri Terdaftar</span><b>${recipientCount} Santri</b></div>` : ''}
          <div class="kv"><span>Sistem Penerbit</span><b>PTV Operations Dashboard</b></div>
        </div>

        <div style="margin-top:20px;padding:12px;background:#f8fafc;border-radius:12px;border:1px dashed #cbd5e1;font-size:12px;color:#64748b;">
          <i class="fa-solid fa-shield-halved" style="color:#059669;margin-right:6px;"></i>
          Keaslian dan integritas dokumen ini terverifikasi secara sah melalui basis data sistem operasional resmi.
        </div>
        
        ${doc ? `<div class="mt18"><button class="btn pri block" data-act="pdf:${esc(doc.no)}">${ic.download} Unduh / Cetak Ulang Dokumen</button></div>` : ''}
      </div>
    </div>`;
  }

  const hasPtvId = !!(ME.ptvId && ME.ptvId.trim());
  const vBase = (typeof VERIFIKASI_IDENTITAS_BASE_URL !== 'undefined' ? VERIFIKASI_IDENTITAS_BASE_URL : (window.location.origin + '/verifikasi-identitas/')).replace(/\/+$/, '');
  const verifyUrl = hasPtvId ? (vBase + '/?id=' + encodeURIComponent(ME.ptvId)) : '';

  return `<div class="page" style="max-width:420px;margin:0 auto">
    <button class="back" data-go="id">${ic.chevL}Kembali ke ID</button>
    <div class="card pad mt8" style="text-align:center;padding:24px 18px">
      <div style="width:52px;height:52px;border-radius:50%;background:var(--ok-bg);color:var(--ok);display:grid;place-items:center;margin:0 auto 12px">
        ${icBig('check',22)}
      </div>
      <p class="t-xs" style="margin:0;letter-spacing:.12em;color:var(--ok);font-weight:750">IDENTITAS RESMI PROGRESIF TV</p>
      <h1 class="t-xl" style="margin:10px 0 2px">${esc(ME.name)}</h1>
      <p class="t-sm muted" style="margin:0">Pesantren Progresif Bumi Shalawat</p>
      <div class="divider"></div>
      <div class="kv"><span>Divisi</span><b>${esc(ME.div)}</b></div>
      <div class="kv"><span>Jabatan</span><b>${esc(ME.pos || 'Kru')}</b></div>
      <div class="kv"><span>ID PTV</span><b class="num">${esc(ME.ptvId || 'Belum diterbitkan')}</b></div>
      <div class="kv"><span>Status</span><b style="color:var(--ok)">${esc(ME.status || 'Aktif')}</b></div>
      ${hasPtvId ? `
        <div class="mt16">
          <a href="${verifyUrl}" target="_blank" rel="noopener" class="btn pri block">${ic.eye}Buka Halaman Verifikasi Publik</a>
        </div>
      ` : ''}
      <p class="hint" style="margin-top:14px">Data diverifikasi langsung dari basis data Supabase ptv_kru Progresif TV.</p>
    </div>
  </div>`;
}

/* ============================================================
   PAGE: DOKUMEN SAYA
   ============================================================ */
let docFilter='Semua';

function isUserInDoc(d) {
  if (!d) return false;
  const isExec = (state.role === 'eksekutif' || ME.role === 'eksekutif' || state.role === 'administrasi' || ME.role === 'administrasi');
  if (isExec) return true;

  const myName = (ME.name || '').toLowerCase().trim();
  const myId   = String(ME.id || '').trim();
  const myPtv  = String(ME.ptvId || ME.crew_id || '').toUpperCase().trim();

  // 1. Owner & Pembawa
  const owner = (d.owner || '').toLowerCase();
  if (owner && (owner === myName || owner.includes(myName))) return true;

  const pembawa = (d.pembawa || '').toLowerCase();
  if (pembawa && (pembawa === myName || pembawa.includes(myName))) return true;

  // 2. Penanggung jawab
  const pj = (d.penanggung_jawab || '').toLowerCase();
  if (pj && (pj === myName || pj.includes(myName))) return true;

  // 3. Diajukan oleh
  const diajukan = String(d.diajukan_oleh || '').trim().toLowerCase();
  if (diajukan && (diajukan === myName || diajukan === myId || (myPtv && diajukan === myPtv.toLowerCase()))) return true;

  // 4. Recipients (multi-kru)
  if (Array.isArray(d.recipients)) {
    if (d.recipients.some(r => {
      const rName = (typeof r === 'string' ? r : (r.nama || r.name || '')).toLowerCase().trim();
      return rName && (rName === myName || rName.includes(myName) || myName.includes(rName));
    })) return true;
  }
  return false;
}

function pgDokumen(){
  let rows = DB.docs.filter(d => isUserInDoc(d));
  if(docFilter!=='Semua')rows=rows.filter(d=>d.status===docFilter);
  rows.sort((a,b)=>(b.date || '').localeCompare(a.date || ''));
  return `<div class="page">
    <div class="filters" style="display:flex;align-items:center;justify-content:space-between;gap:8px;">
      <div style="display:flex;gap:6px;overflow-x:auto;">
        ${['Semua','Menunggu','Disetujui','Revisi','Ditolak'].map(k=>
          `<button class="fchip${docFilter===k?' on':''}" data-filter-doc="${k}">${k}</button>`).join('')}
      </div>
      <span id="docScopeStatusBadge">${getSectionSyncStatusHTML('docs')}</span>
    </div>
    <div class="mt18" id="pgList">
      ${(() => {
        const docState = window.PTV_SCOPES_STATE?.docs;
        const isFirstLoading = docState && docState.isInitialLoading && !docState.hasData;
        if (isFirstLoading) {
          return renderDocsSkeleton(4);
        }
        return rows.length ? `<div class="stack">${rows.map(d=>`
          <div class="card pad">
            <div class="row-b" style="align-items:flex-start">
              <div class="tight">
                <div class="t-md trunc">${esc(d.subject)}</div>
                <div class="t-sm muted trunc">${esc(d.type)} · ${(d.status==='Disetujui'&&d.no&&!d.no.includes('Menunggu')&&d.no!=='—')?esc(d.no):'Belum diterbitkan'}</div>
              </div>${chip(d.status)}
            </div>
            <div class="row-b mt12">
              <span class="t-xs muted">${fmtDate(d.date)}</span>
              <span class="row gap6">
                <button class="btn sm" data-doc="${d.id}">${ic.eye}Lihat</button>
                <button class="btn sm ${d.status==='Disetujui'?'pri':''}" data-act="pdf:${d.no}" ${d.status==='Disetujui'?'':'disabled'}>${ic.download}PDF</button>
              </span>
            </div>
          </div>`).join('')}</div>`
        : emptyState('doc','Belum ada dokumen di filter ini.','<button class="btn sm pri" data-quick="izin">Ajukan sesuatu</button>');
      })()}
    </div>
  </div>`;
}

function openDoc(id){
  window._currentOpenDocId = id;
  const d=DB.docs.find(x=>String(x.id)===String(id)); if(!d)return;
  const isExec = (state.role === 'eksekutif' || ME.role === 'eksekutif');
  const isAdm = (state.role === 'administrasi' || ME.role === 'administrasi');
  const isSuratIzin = (d.type || '').toLowerCase().includes('izin');
  const canApprove = isExec || (isAdm && !isSuratIzin);
  const isPending = d.status==='Menunggu';
  const isApproved = d.status === 'Disetujui';
  const isRejected = d.status === 'Ditolak';
  const isRevision = d.status === 'Revisi';
  const hasOfficialNo = isApproved && d.no && !d.no.includes('Menunggu') && d.no !== '—';

  // Step 1: Pengajuan
  const submitTs = d.created_at || (d.date ? d.date + 'T08:00:00' : '');
  const submitTimeStr = fmtDateTimeWIB(submitTs);

  // Step 2: Review
  let reviewStatus = 'Belum';
  let reviewTimeStr = '';
  if (isApproved || isRejected || isRevision) {
    reviewStatus = 'Selesai';
    reviewTimeStr = fmtDateTimeWIB(d.updated_at || submitTs);
  } else if (isPending) {
    reviewStatus = 'Sedang berjalan';
    reviewTimeStr = fmtDateTimeWIB(d.created_at || submitTs);
  }

  // Step 3: Keputusan
  let decisionStatus = 'Belum';
  let decisionTitle = 'Disetujui';
  let decisionTimeStr = '';
  if (isApproved) {
    decisionStatus = 'Selesai';
    decisionTitle = 'Disetujui / ACC';
    decisionTimeStr = fmtDateTimeWIB(d.approved_at || d.updated_at || submitTs);
  } else if (isRejected) {
    decisionStatus = 'Ditolak';
    decisionTitle = 'Ditolak';
    decisionTimeStr = fmtDateTimeWIB(d.updated_at || submitTs);
  } else if (isRevision) {
    decisionStatus = 'Perlu Revisi';
    decisionTitle = 'Revisi';
    decisionTimeStr = fmtDateTimeWIB(d.updated_at || submitTs);
  } else {
    decisionTitle = 'Keputusan';
    decisionStatus = 'Menunggu';
  }

  // Step 4: Arsip
  let archiveStatus = isApproved ? 'Diarsipkan' : 'Belum';
  let archiveTimeStr = isApproved ? fmtDateTimeWIB(d.updated_at || submitTs) : '';

  const canDeleteDoc = isExec || isAdm;
  let footButtons = '';
  if (canApprove && isPending) {
    footButtons = `<div class="row gap8" style="width:100%"><button class="btn pri" style="flex:1" data-act="docApprove:${d.id}">${ic.check}Setujui</button><button class="btn" data-act="docReject:${d.id}">Tolak</button></div>`;
  } else {
    footButtons = `<button class="btn block ${hasOfficialNo?'pri':''}" data-act="pdf:${d.no}" ${hasOfficialNo?'':'disabled'}>${ic.download}Unduh PDF</button>`;
  }
  if (canDeleteDoc) {
    footButtons += `<button class="btn dang" data-act="confirmDeleteDoc:${d.id}" style="margin-top:8px;width:100%"><i class="fa-solid fa-trash"></i>Hapus Surat</button>`;
  }
  const footHtml = footButtons;
  
  const baseVUrl = (typeof VERIFIKASI_SURAT_BASE_URL !== 'undefined' ? VERIFIKASI_SURAT_BASE_URL : (window.location.origin + '/verifikasi-surat/')).replace(/\/+$/, '');
  const verifyDocUrl = hasOfficialNo ? (baseVUrl + '/' + encodeURIComponent(d.no)) : '';

  openSheet(d.type,`
    <div class="row-b" style="align-items:flex-start">
      <div class="tight"><div class="t-lg">${esc(d.subject)}</div>
      <div class="t-sm muted num">${hasOfficialNo ? esc(d.no) : 'Belum diterbitkan (Menunggu ACC Eksekutif)'}</div></div>${chip(d.status)}
    </div>
    <div class="card pad mt12">
      <div class="kv"><span>Pemohon / Diterbitkan</span><b>${esc(d.owner)}</b></div>
      <div class="kv"><span>Tanggal</span><b>${fmtDate(d.date)}</b></div>
      ${d.event?`<div class="kv"><span>Acara</span><b>${eventById(d.event) ? `<button class="link" data-go="acaraDetail:${d.event}">${esc(eventById(d.event).name)}</button>` : esc(d.event)}</b></div>`:''}
      ${d.recipients && d.recipients.length ? `<div class="kv" style="align-items:flex-start"><span>Kru / Personel</span><b>${esc(d.recipients.join(', '))}</b></div>` : ''}
      ${(()=>{
        if (!d.items || !d.items.length) return '';
        const itemStrings = d.items.map(it => {
          if (typeof it === 'string') return it;
          if (typeof it === 'object' && it !== null) {
            return it.nama || it.name || it.item_name || String(it);
          }
          return String(it);
        });
        return `<div class="kv" style="align-items:flex-start"><span>Peralatan &amp; Unit</span><b style="line-height:1.45;color:#0f172a;">${esc(itemStrings.join(', '))}</b></div>`;
      })()}
    </div>
    <div class="sec">${sectionHd('Alur Status Dokumen')}
      <div class="timeline">
        <div class="tl done">
          <div class="t-md font-bold">Pengajuan</div>
          <div class="t-xs muted" style="white-space:pre-line;line-height:1.4;margin-top:2px;">${submitTimeStr || 'Selesai'}</div>
        </div>
        <div class="tl ${reviewStatus === 'Selesai' ? 'done' : (reviewStatus === 'Sedang berjalan' ? 'now' : '')}">
          <div class="t-md font-bold">Review</div>
          <div class="t-xs muted" style="white-space:pre-line;line-height:1.4;margin-top:2px;">${reviewTimeStr || reviewStatus}</div>
        </div>
        <div class="tl ${decisionStatus === 'Selesai' ? 'done' : (decisionStatus === 'Menunggu' ? '' : 'now')}">
          <div class="t-md font-bold">${decisionTitle}</div>
          <div class="t-xs muted" style="white-space:pre-line;line-height:1.4;margin-top:2px;">${decisionTimeStr || decisionStatus}</div>
        </div>
        <div class="tl ${archiveStatus === 'Diarsipkan' ? 'done' : ''}">
          <div class="t-md font-bold">Diarsipkan</div>
          <div class="t-xs muted" style="white-space:pre-line;line-height:1.4;margin-top:2px;">${archiveTimeStr || archiveStatus}</div>
        </div>
      </div>
    </div>
    ${hasOfficialNo ? `<div class="sec">${sectionHd('Verifikasi & Pengesahan Digital')}
      <div class="card pad" style="display:flex;gap:14px;align-items:center">
        <a href="${verifyDocUrl}" target="_blank" rel="noopener noreferrer" style="display:inline-block;cursor:pointer;" title="Buka Halaman Verifikasi Publik Resmi">
          ${qrSVG(verifyDocUrl, 92)}
        </a>
        <div class="tight">
          <div class="t-sm font-bold" style="color:var(--ok);margin-bottom:2px;">Dokumen Resmi Sah & Terverifikasi</div>
          <p class="t-xs muted" style="margin:0 0 6px;">Pindai QR dengan kamera smartphone atau buka tautan verifikasi publik untuk memeriksa keaslian surat nomor <b>${esc(d.no)}</b>.</p>
          <a href="${verifyDocUrl}" target="_blank" rel="noopener noreferrer" class="t-xs font-bold" style="color:var(--b-500);text-decoration:none;display:inline-flex;align-items:center;gap:4px;">Buka Halaman Verifikasi Publik <i class="fa-solid fa-arrow-up-right-from-square" style="font-size:10px;"></i></a>
        </div>
      </div>
    </div>` : `<div class="sec">${sectionHd('Status Pengesahan')}
      <div class="card pad" style="display:flex;gap:12px;align-items:center;background:#f8fafc;border:1px dashed #cbd5e1;">
        <span style="font-size:22px;">${d.status==='Revisi'?'⚠️':(d.status==='Ditolak'?'❌':'⏳')}</span>
        <div class="tight">
          <div class="t-sm font-bold" style="color:var(--ink);">${d.status==='Revisi'?'Dokumen Memerlukan Revisi':(d.status==='Ditolak'?'Dokumen Ditolak':'Menunggu Tinjauan & Pengesahan')}</div>
          <p class="t-xs muted" style="margin:2px 0 0;">Nomor surat resmi dan QR Code verifikasi publik hanya diterbitkan untuk dokumen yang telah disetujui/sah.</p>
        </div>
      </div>
    </div>`}`,
    {foot:footHtml});
}

/* ============================================================
   PAGE: KONTAK INTERNAL (Kru & Pengurus)
   ============================================================ */
let kontakFilter = 'Semua';
let kontakSearch = '';

function pgKontak(){
  const isPembina = c => c && (c.div === 'Pembina' || /pembina/i.test(c.div || '') || /pembina/i.test(c.pos || ''));
  const isPengarah = c => c && !isPembina(c) && (
    c.div === 'Pengarah' ||
    /pengarah/i.test(c.div || '') ||
    /pengarah/i.test(c.pos || '') ||
    /presdir|wadir|pendiri|pengasuh|direktur|penasihat/i.test(c.pos || '')
  );
  const isPengurus = c => c && !isPembina(c) && !isPengarah(c) && /ketua|wakil|sekretaris|bendahara|koordinator|admin|pimpinan|pengurus/i.test(c.pos || '');
  const isKru = c => c && !isPembina(c) && !isPengarah(c) && !isPengurus(c) && (c.status === 'Aktif' || /kru/i.test(c.pos || ''));

  const allCrew = Array.isArray(DB.crew) ? DB.crew : [];
  const q = (kontakSearch || '').trim().toLowerCase();
  const matchQ = c => !q || (c.name || '').toLowerCase().includes(q) || (c.pos || '').toLowerCase().includes(q) || (c.div || '').toLowerCase().includes(q);

  const pembinaRows = allCrew.filter(c => isPembina(c) && matchQ(c));
  const pengarahRows = allCrew.filter(c => isPengarah(c) && matchQ(c));
  const pengurusRows = allCrew.filter(c => isPengurus(c) && matchQ(c));
  const kruRows = allCrew.filter(c => isKru(c) && matchQ(c));

  const allCats = [
    { key: 'Pembina', title: 'Pembina', desc: 'Dewan Pembina PTV', rows: pembinaRows, count: allCrew.filter(isPembina).length },
    { key: 'Pengarah', title: 'Pengarah', desc: 'Pimpinan & Pengarah Lembaga', rows: pengarahRows, count: allCrew.filter(isPengarah).length },
    { key: 'Pengurus', title: 'Pengurus', desc: 'Pengurus & Pimpinan Harian PTV', rows: pengurusRows, count: allCrew.filter(isPengurus).length },
    { key: 'Kru', title: 'Kru', desc: 'Anggota & Kru Operasional PTV', rows: kruRows, count: allCrew.filter(isKru).length },
  ];

  const visibleCats = kontakFilter === 'Semua' 
    ? allCats.filter(c => c.rows.length) 
    : allCats.filter(c => c.key === kontakFilter);

  const filterTabs = [
    ['Semua', `Semua (${allCats.reduce((sum, c) => sum + c.count, 0)})`],
    ['Pembina', `Pembina (${allCats[0].count})`],
    ['Pengarah', `Pengarah (${allCats[1].count})`],
    ['Pengurus', `Pengurus (${allCats[2].count})`],
    ['Kru', `Kru (${allCats[3].count})`],
  ];

  return `<div class="page">
    <div class="row-b" style="margin-bottom:14px;align-items:flex-start">
      <div>
        <h1 class="t-xl font-bold" style="margin:0 0 4px;color:var(--ink)">Kontak Internal</h1>
        <p class="t-sm muted" style="margin:0">Nomor yang bisa dihubungi untuk koordinasi internal dan urusan operasional kru PTV.</p>
      </div>
    </div>

    <div class="searchbar mb16">${ic.search}<input placeholder="Cari nama, jabatan, divisi kru..." id="kontakQ" value="${esc(kontakSearch)}"></div>
    <div class="filters">
      ${filterTabs.map(([k,l])=>`<button class="fchip${kontakFilter===k?' on':''}" data-filter-kontak="${k}">${l}</button>`).join('')}
    </div>
    <div class="mt18" id="pgList">
      ${visibleCats.length === 0 ? emptyState('phone', q ? 'Tidak ada kru yang cocok dengan pencarian.' : 'Belum ada kru di kategori ini.') : visibleCats.map(cat => `
        <div class="sec" style="margin-top:18px">
          <div class="sec-hd">
            <div>
              <h2 style="display:inline-block">${cat.title}</h2>
              <span class="chip" style="margin-left:8px;font-size:11px">${cat.rows.length}</span>
            </div>
            <span class="t-xs muted only-desktop">${cat.desc}</span>
          </div>
          ${cat.key === 'Kru' ? `
            <div style="display:flex;flex-direction:column;gap:14px;margin-top:10px">
              ${groupCrewByAngkatan(cat.rows).map(g => `
                <div>
                  <div style="font-size:12px;font-weight:700;color:var(--ink-muted);padding:4px 8px;display:flex;align-items:center;gap:6px">
                    <i class="${g.icon || 'fa-solid fa-graduation-cap'}" style="font-size:11px;opacity:0.8;${g.label==='Additional'?'color:#2563eb':''}"></i>
                    <span>${esc(g.label)}</span>
                    <span class="chip ${g.label==='Additional' ? 'blue' : ''}" style="font-size:10px;padding:0 5px">${g.rows.length}</span>
                  </div>
                  <div class="list">${g.rows.map(c=>`
                    <div class="li">
                      ${avatarHTML(c.name || 'Kru', c.photo || c.foto_url || c.foto || '', 'sm')}
                      <span class="li-body">
                        <span class="li-t trunc">${esc(c.name || 'Tanpa Nama')}</span>
                        <span class="li-s trunc">${esc(c.pos || 'Kru')}${c.div && c.div !== c.pos ? ' · ' + esc(c.div) : ''}</span>
                      </span>
                      ${c.phone ? `<button class="btn sm" data-act="wa:${c.phone}">${ic.wa}<span class="only-desktop">Chat</span></button>` : ''}
                    </div>`).join('')}
                  </div>
                </div>
              `).join('')}
            </div>
          ` : `
            <div class="list">${cat.rows.map(c=>`
              <div class="li">
                ${avatarHTML(c.name || 'Kru', c.photo || c.foto_url || c.foto || '', 'sm')}
                <span class="li-body">
                  <span class="li-t trunc">${esc(c.name || 'Tanpa Nama')}</span>
                  <span class="li-s trunc">${esc(c.pos || 'Kru')}${c.div && c.div !== c.pos ? ' · ' + esc(c.div) : ''}</span>
                </span>
                ${c.phone ? `<button class="btn sm" data-act="wa:${c.phone}">${ic.wa}<span class="only-desktop">Chat</span></button>` : ''}
              </div>`).join('')}
            </div>
          `}
        </div>`).join('')}
    </div>
  </div>`;
}

/* ============================================================
   PAGE: KONTAK EKSTERNAL (Pondok, Sekolah, Yayasan, Mitra)
   ============================================================ */
let kontakEksternalLembagaFilter = 'Semua';
let kontakEksternalPeranFilter = 'Semua';
let kontakEksternalSearch = '';

function ptvCategorizeKontak(k) {
  if (!k || typeof k !== 'object') return { lembaga: 'Pondok', peran: 'Ustadz' };
  const rawOrg = String(k.organisasi || '').trim();
  const rawJab = String(k.jabatan || '').trim();
  const rawCat = String(k.kategori || '').trim();
  const rawName = String(k.nama || '').trim();
  const orgLow = rawOrg.toLowerCase();
  const catLow = rawCat.toLowerCase();
  const combined = (rawOrg + ' ' + rawJab + ' ' + rawCat + ' ' + rawName).toLowerCase();

  // 1. Lembaga Detection (Priority: explicit org / cat matches first, then keyword fallback)
  let lembaga = 'Pondok';
  if (orgLow === 'pondok' || catLow === 'pondok' || orgLow.startsWith('pondok') || orgLow.includes('pesantren')) {
    lembaga = 'Pondok';
  } else if (orgLow === 'sekolah' || catLow === 'sekolah' || orgLow.startsWith('sekolah') || orgLow.includes('smp') || orgLow.includes('sma') || orgLow.includes('sd')) {
    lembaga = 'Sekolah';
  } else if (orgLow === 'yayasan' || catLow === 'yayasan' || orgLow.startsWith('yayasan') || orgLow.includes('bumi shalawat')) {
    lembaga = 'Yayasan';
  } else if (['mitra', 'vendor', 'mitra & vendor', 'rekanan', 'partner', 'supplier', 'instansi'].includes(orgLow) ||
             ['mitra', 'vendor', 'mitra & vendor', 'partner', 'instansi'].includes(catLow) ||
             orgLow.includes('vendor') || orgLow.includes('mitra') || orgLow.includes('supplier') || orgLow.includes('rental') ||
             catLow.includes('vendor') || catLow.includes('mitra')) {
    lembaga = 'Mitra';
  } else if (/asrama|madin|pengasuhan|keasramaan|tahfidz|diniyah|santri/.test(combined)) {
    lembaga = 'Pondok';
  } else if (/smp|sma|sd|sekolah|kesiswaan|sarpras sm|kurikulum|guru|tu sm|wali kelas/.test(combined)) {
    lembaga = 'Sekolah';
  } else if (/yayasan|spi|direksi|pengurus yayasan|bumi shalawat foundation/.test(combined)) {
    lembaga = 'Yayasan';
  } else if (/vendor|mitra|partner|instansi|supplier|percetakan|rental|sponsor/.test(combined)) {
    lembaga = 'Mitra';
  } else if (rawOrg) {
    lembaga = rawOrg;
  }

  // 2. Peran / Sapaan Detection
  let peran = 'Ustadz';
  if (catLow === 'ustadzah' || combined.includes('ustadzah') || combined.includes('ustzah') || combined.includes('u. isma') || combined.includes('ust. isma') || combined.includes('ustazah') || combined.includes('bu ')) {
    peran = 'Ustadzah';
  } else if (catLow === 'ustadz' || combined.includes('ust.') || combined.includes('u. ') || combined.includes('ustadz') || combined.includes('pak ') || combined.includes('kyai')) {
    peran = 'Ustadz';
  } else if (catLow === 'vendor' || combined.includes('vendor') || combined.includes('supplier')) {
    peran = 'Vendor';
  } else if (catLow === 'partner' || combined.includes('partner') || combined.includes('mitra')) {
    peran = 'Partner';
  } else if (catLow === 'pembina' || combined.includes('pembina')) {
    peran = 'Pembina';
  } else if (catLow === 'narasumber' || combined.includes('narasumber')) {
    peran = 'Narasumber';
  } else {
    peran = rawCat || 'Ustadz';
  }

  return { lembaga, peran };
}

function pgKontakEksternal(){
  try {
    const isExec = ['eksekutif','executive'].includes(normRole(state.role || ME.role));
    const isAdmin = ['administrasi','admin'].includes(normRole(state.role || ME.role));
    const canManageEksternal = isExec || isAdmin;

    const allEksternal = (Array.isArray(DB.kontak_eksternal) ? DB.kontak_eksternal : []).filter(k => k && typeof k === 'object');
    const eq = String(kontakEksternalSearch || '').trim().toLowerCase();

    // Map all contacts with unified category data
    const enrichedList = allEksternal.map(k => {
      const cat = ptvCategorizeKontak(k);
      return Object.assign({}, k, {
        _lembaga: cat.lembaga,
        _peran: cat.peran
      });
    });

    // Counts for Filter Tabs calculated dynamically from real data
    const countLembaga = {
      Semua: enrichedList.length,
      Pondok: enrichedList.filter(c => c._lembaga === 'Pondok').length,
      Sekolah: enrichedList.filter(c => c._lembaga === 'Sekolah').length,
      Yayasan: enrichedList.filter(c => c._lembaga === 'Yayasan').length,
      Mitra: enrichedList.filter(c => c._lembaga === 'Mitra' || c._lembaga === 'Vendor' || c._lembaga === 'Mitra & Vendor').length,
    };

    // Filter Logic
    const matchSearch = k => {
      if (!k) return false;
      if (!eq) return true;
      return String(k.nama || '').toLowerCase().includes(eq) || 
        String(k.jabatan || '').toLowerCase().includes(eq) || 
        String(k.organisasi || '').toLowerCase().includes(eq) || 
        String(k._lembaga || '').toLowerCase().includes(eq) || 
        String(k._peran || '').toLowerCase().includes(eq) || 
        String(k.nomor_telepon || '').toLowerCase().includes(eq) || 
        String(k.whatsapp || '').toLowerCase().includes(eq);
    };

    let filteredList = enrichedList.filter(matchSearch);

    // Apply Lembaga Filter
    if (kontakEksternalLembagaFilter && kontakEksternalLembagaFilter !== 'Semua') {
      filteredList = filteredList.filter(k => {
        if (kontakEksternalLembagaFilter === 'Mitra' || kontakEksternalLembagaFilter === 'Mitra & Vendor') {
          return k._lembaga === 'Mitra' || k._lembaga === 'Vendor' || k._lembaga === 'Mitra & Vendor';
        }
        return k._lembaga === kontakEksternalLembagaFilter;
      });
    }

    // Apply Peran Filter (if set)
    if (kontakEksternalPeranFilter && kontakEksternalPeranFilter !== 'Semua') {
      filteredList = filteredList.filter(k => k._peran === kontakEksternalPeranFilter);
    }

    return `<div class="page">
      <!-- Header Bar -->
      <div class="row-b" style="margin-bottom:22px;align-items:center;">
        <div>
          <h1 class="t-xl font-bold" style="margin:0 0 4px;color:var(--ink)">Kontak Eksternal & Lembaga</h1>
          <p class="t-sm muted" style="margin:0">Direktori resmi kontak Ustadz/ah, Pondok, Sekolah, Yayasan, dan Rekanan.</p>
        </div>
        ${canManageEksternal ? `
          <button class="btn sm pri" data-act="openNewKontakEksternal" style="border-radius:var(--r-full);padding:0 18px;font-weight:650;">
            <i class="fa-solid fa-plus"></i>Tambah Kontak
          </button>
        ` : ''}
      </div>

      <!-- Search Bar -->
      <div class="searchbar" style="margin-bottom:18px;">
        ${ic.search}
        <input placeholder="Cari nama Ustadz/ah, jabatan, instansi..." id="kontakEksternalQ" value="${esc(kontakEksternalSearch)}">
        <button type="button" id="kontakEksternalQClear" data-act="clearKontakEksternalSearch" style="border:none;background:transparent;cursor:pointer;color:var(--ink3);font-size:13px;padding:4px;display:${kontakEksternalSearch ? 'inline-flex' : 'none'};">
          <i class="fa-solid fa-xmark"></i>
        </button>
      </div>
      
      <!-- Clean Single Tab Bar (Lembaga Tabs with dynamic count) -->
      <div class="kontak-eks-filters-wrap">
        <div class="filters kontak-eks-filters">
          ${[
            ['Semua', 'Semua', countLembaga.Semua],
            ['Pondok', 'Pondok', countLembaga.Pondok],
            ['Sekolah', 'Sekolah', countLembaga.Sekolah],
            ['Yayasan', 'Yayasan', countLembaga.Yayasan],
            ['Mitra', 'Mitra & Vendor', countLembaga.Mitra]
          ].map(([k, l, count]) => {
            const isOn = kontakEksternalLembagaFilter === k;
            return `<button type="button" class="fchip${isOn ? ' on' : ''}" data-filter-kontak-eks="${k}" data-filter-kontak-eks-lembaga="${k}">
              <span>${l}</span>
              <span class="cnt">${count}</span>
            </button>`;
          }).join('')}
        </div>
      </div>

      <!-- Clean List View for Kontak Eksternal -->
      <div id="pgList">
        ${filteredList.length === 0 ? emptyState('phone', eq ? 'Tidak ada kontak yang cocok dengan pencarian.' : 'Belum ada kontak terdaftar pada kategori ini.') : `
          <div class="list" style="border-radius:18px;">
            ${filteredList.map(k => {
              const rawWa = String(k.whatsapp || k.nomor_telepon || '').trim();
              const waNum = rawWa ? rawWa.replace(/[^0-9+]/g, '') : '';
              const rawTel = String(k.nomor_telepon || k.whatsapp || '').trim();
              const telNum = rawTel ? rawTel.replace(/[^0-9+]/g, '') : '';

              const isPondok = k._lembaga === 'Pondok';
              const isSekolah = k._lembaga === 'Sekolah';
              const isYayasan = k._lembaga === 'Yayasan';

              let chipClass = 'ok';
              if (isSekolah) chipClass = 'info';
              else if (isYayasan) chipClass = 'purple';
              else if (k._lembaga === 'Mitra' || k._lembaga === 'Vendor') chipClass = 'warn';

              return `
              <div class="li kontak-eks-item" data-act="openKontakEksternalDetail:${k.id || ''}">
                <div class="kontak-eks-main">
                  ${avatarHTML(k.nama || 'Kontak', k.foto_url || '', 'md')}
                  <div class="li-body">
                    <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">
                      <span class="li-t" style="font-weight:700;">${esc(k.nama || 'Tanpa Nama')}</span>
                      <span class="chip ${chipClass}" style="font-size:10.5px;padding:2px 8px;border-radius:var(--r-full);">${esc(k._lembaga === 'Mitra' ? 'Mitra & Vendor' : k._lembaga)}</span>
                    </div>
                    <span class="li-s" style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;">
                      <b style="color:var(--ink-2);font-weight:600;">${esc(k.jabatan || 'Staf')}</b>
                      <span>&bull;</span>
                      <span>${esc(k.organisasi || (isPondok ? 'Pondok Pesantren' : (isSekolah ? 'SMP / SMA Progresif' : (isYayasan ? 'Yayasan Bumi Shalawat' : 'Mitra'))))}</span>
                      ${(rawWa || rawTel) ? `<span>&bull;</span><span class="font-mono" style="color:var(--ink-2);">${esc(rawWa || rawTel)}</span>` : ''}
                    </span>
                  </div>
                </div>

                <div class="kontak-eks-actions">
                  ${waNum ? `
                    <button class="btn sm" data-act="wa:${waNum}" onclick="event.stopPropagation()" style="padding:6px 16px;font-size:12px;font-weight:650;border-radius:var(--r-full);background:#ecfdf5;color:#059669;border:1px solid #a7f3d0;display:inline-flex;align-items:center;gap:6px;">
                      <i class="fa-brands fa-whatsapp" style="font-size:13px"></i>
                      <span>WhatsApp</span>
                    </button>
                  ` : ''}
                  ${telNum ? `
                    <a href="tel:${telNum}" onclick="event.stopPropagation()" class="btn sm btn-telp-icon" title="Telepon" style="padding:6px 12px;font-size:12px;border-radius:var(--r-full);border:1px solid var(--line);background:transparent;color:var(--ink-2);display:inline-flex;align-items:center;justify-content:center;">
                      <i class="fa-solid fa-phone"></i>
                    </a>
                  ` : ''}
                  <button class="btn sm" data-act="openKontakEksternalDetail:${k.id || ''}" onclick="event.stopPropagation()" title="Detail Kontak" style="padding:6px 14px;font-size:12px;border-radius:var(--r-full);border:1px solid var(--line);background:transparent;color:var(--ink-2);display:inline-flex;align-items:center;justify-content:center;gap:6px;">
                    <i class="fa-solid fa-circle-info" style="font-size:12px;"></i>
                    <span>Detail</span>
                  </button>
                </div>
              </div>
              `;
            }).join('')}
          </div>
        `}
      </div>
    </div>`;
  } catch(err) {
    console.error('Error rendering Kontak Eksternal:', err);
    return `<div class="page"><div class="empty card"><i class="fa-solid fa-triangle-exclamation"></i><p>Gagal memuat kontak eksternal: ${esc(err.message)}</p></div></div>`;
  }
}
// ── Kontak Eksternal CRUD Modals ──
function openKontakEksternalDetail(id){
  const k = (DB.kontak_eksternal || []).find(x => x && String(x.id) === String(id));
  if(!k) return;
  const isExec = ['eksekutif','executive'].includes(normRole(state.role || ME.role));
  const isAdmin = ['administrasi','admin'].includes(normRole(state.role || ME.role));
  const canManage = isExec || isAdmin;

  const cat = ptvCategorizeKontak(k);
  const rawWa = String(k.whatsapp || k.nomor_telepon || '').trim();
  const waNum = rawWa ? rawWa.replace(/[^0-9+]/g, '') : '';
  const rawTel = String(k.nomor_telepon || k.whatsapp || '').trim();
  const telNum = rawTel ? rawTel.replace(/[^0-9+]/g, '') : '';

  const isUstadzah = cat.peran === 'Ustadzah';
  const isPondok = cat.lembaga === 'Pondok';
  const isSekolah = cat.lembaga === 'Sekolah';
  const isYayasan = cat.lembaga === 'Yayasan';

  openSheet('Detail Kontak Relasi & Lembaga',
    `<div class="row-b" style="align-items:flex-start;margin-bottom:16px">
      <div style="display:flex;align-items:center;gap:14px">
        ${avatarHTML(k.nama || 'Kontak', k.foto_url || '', 'lg')}
        <div>
          <h2 class="t-lg font-bold" style="margin:0 0 4px;color:var(--ink)">${esc(k.nama || 'Tanpa Nama')}</h2>
          <div style="display:flex;flex-wrap:wrap;gap:6px">
            <span class="chip ${isUstadzah ? 'purple' : 'blue'}" style="font-weight:700">${esc(cat.peran)}</span>
            <span class="chip ok" style="font-weight:700">${esc(cat.lembaga)}</span>
            ${String(k.status || '').toLowerCase() === 'tidak aktif' ? '<span class="chip muted">Nonaktif</span>' : '<span class="chip ok">Aktif</span>'}
          </div>
        </div>
      </div>
    </div>

    <div class="card pad" style="margin-bottom:14px">
      <div class="kv"><span>Institusi / Lembaga</span><b style="color:var(--b-600)">${esc(cat.lembaga === 'Pondok' ? 'Pondok Pesantren' : (cat.lembaga === 'Sekolah' ? 'Sekolah (SMP & SMA)' : (cat.lembaga === 'Yayasan' ? 'Yayasan Bumi Shalawat' : 'Mitra & Eksternal')))}</b></div>
      <div class="kv"><span>Sapaan / Peran</span><b>${esc(cat.peran)}</b></div>
      <div class="kv"><span>Jabatan / Bagian</span><b>${esc(k.jabatan || '—')}</b></div>
      <div class="kv"><span>Detail Organisasi</span><b>${esc(k.organisasi || '—')}</b></div>
      <div class="kv"><span>Nomor Telepon</span><b>${telNum ? `<a href="tel:${telNum}" style="color:var(--b-600);text-decoration:none">${esc(k.nomor_telepon || rawTel)}</a>` : '—'}</b></div>
      <div class="kv"><span>WhatsApp</span><b>${waNum ? `<button class="btn sm" data-act="wa:${waNum}" style="padding:2px 8px;font-size:11px;background:#25D366;color:#ffffff;border:none;font-weight:700">${ic.wa}${esc(k.whatsapp || k.nomor_telepon)}</button>` : '—'}</b></div>
      <div class="kv"><span>Email</span><b>${k.email ? `<a href="mailto:${esc(k.email)}" style="color:var(--b-600);text-decoration:none">${esc(k.email)}</a>` : '—'}</b></div>
      <div class="kv"><span>Alamat</span><b>${esc(k.alamat || '—')}</b></div>
      ${k.catatan ? `<div class="kv" style="flex-direction:column;align-items:flex-start;gap:4px"><span>Catatan Khusus</span><div class="t-sm ink2" style="white-space:pre-wrap">${esc(k.catatan)}</div></div>` : ''}
    </div>`,
    {
      foot: canManage ? `
        <div class="row gap8">
          <button class="btn pri flex-1" data-act="openEditKontakEksternal:${k.id || ''}"><i class="fa-solid fa-pen-to-square"></i>Edit Kontak</button>
          <button class="btn dang flex-1" data-act="confirmDeleteKontakEksternal:${k.id || ''}"><i class="fa-solid fa-trash"></i>Hapus Kontak</button>
        </div>` : ''
    }
  );
}

