            <img src="${esc(buktiUrl)}" alt="Bukti" style="width:100%;height:100%;object-fit:cover;" onerror="this.onerror=null;this.parentElement.innerHTML='<i class=\\'fa-solid fa-receipt\\' style=\\'color:var(--ptv-green,#0e4f40);font-size:16px;\\'></i>';">
            <div class="fin-thumb-hover">
