function renderFinTabBody(currentTab) {
  const tab = currentTab || finTab || 'kas_kru';
  const canManage = isKeuanganAdmin();
  const fin = DB.keuangan || { pemasukan: [], pengeluaran: [], kas_kru: [], periode: [], tables_ready: false };
  const allPemasukan = (fin.pemasukan || []).filter(x => x.status !== 'void');
  const allPengeluaran = (fin.pengeluaran || []).filter(x => x.status !== 'void');
  const allKasKru = fin.kas_kru || [];
  const allPeriode = fin.periode || [];

  const configuredPeriods = (allPeriode && allPeriode.length) ? allPeriode : [
    { periode_bulan: '2026-07', nominal: 20000, keterangan: 'Juli 2026', status: 'aktif', is_active: true },
    { periode_bulan: '2026-08', nominal: 25000, keterangan: 'Agustus 2026', status: 'aktif', is_active: true },
    { periode_bulan: '2026-09', nominal: 25000, keterangan: 'September 2026', status: 'aktif', is_active: true },
  ];
  const validPeriods = configuredPeriods
    .filter(p => {
      if (!p.periode_bulan || p.periode_bulan < '2026-07') return false;
      if (p.is_active === false || p.status === 'nonaktif' || (p.keterangan || '').includes('[NONAKTIF]')) return false;
      return true;
    })
    .sort((a,b) => a.periode_bulan.localeCompare(b.periode_bulan));

  if (tab === 'kas_kru') {
    let crewListToRender = (DB.crew || []).filter(c => isOperationalCrew(c));

    const meInList = crewListToRender.some(c => 
      (ME.ptvId && (c.crew_id === ME.ptvId || c.ptv_id === ME.ptvId)) ||
      (ME.id && String(c.id) === String(ME.id)) ||
      (ME.name && c.name && c.name.toLowerCase() === ME.name.toLowerCase())
    );
    if (!meInList && ME && ME.name && ME.name !== 'Guest' && isOperationalCrew(ME)) {
      crewListToRender.push({
        id: ME.id || ('me_' + (ME.ptvId || 'admin')),
        name: ME.name,
        ptv_id: ME.ptvId || 'PTV-ADM',
        crew_id: ME.ptvId || 'PTV-ADM',
        divisi: ME.div || 'Eksekutif',
        pos: ME.pos || 'Eksekutif',
        role: ME.role || 'eksekutif',
        status: 'Aktif',
        join: '2026-07-01'
      });
    }

    if (finSearchQ && finSearchQ.trim()) {
      const q = finSearchQ.trim().toLowerCase();
      crewListToRender = crewListToRender.filter(c => 
        (c.name || '').toLowerCase().includes(q) ||
        (c.crew_id || c.ptv_id || '').toLowerCase().includes(q) ||
        (c.divisi || c.div || c.role || '').toLowerCase().includes(q)
      );
    }

    crewListToRender.sort((a,b) => (a.name || '').localeCompare(b.name || ''));

    const matrixRowsHTML = crewListToRender.map(c => {
      const cJoinYM = (c.join ? String(c.join).slice(0, 7) : '2026-07');
      let kruTotalUnpaid = 0;

      const cellsHTML = validPeriods.map(p => {
        if (cJoinYM > p.periode_bulan) {
          return `<td class="fin-td-month fin-td-empty-join" title="Belum bergabung">—</td>`;
        }

        const payStatus = getKruPaymentStatus(c, p.periode_bulan);
        const isLunas = payStatus.isPaid;
        const currentNominal = payStatus.nominal;
        const dibayar = payStatus.dibayar;
        const sisa = payStatus.sisa;
        const crewCode = esc(c.ptvId || c.crew_id || c.ptv_id || '');

        if (isLunas) {
          const tglStr = payStatus.tanggal_bayar ? fmtDate(payStatus.tanggal_bayar) : '';
          const byStr = payStatus.dicatat_oleh_nama ? `oleh ${payStatus.dicatat_oleh_nama}` : '';
          const titlePaid = canManage
            ? `Sudah bayar — klik untuk batalkan${tglStr ? ` (${tglStr} ${byStr})` : ''}`
            : `Sudah bayar${tglStr ? ` (${tglStr})` : ''}`;

          if (canManage) {
            return `
              <td class="fin-td-month">
                <button type="button" 
                  class="fin-matrix-cell paid" 
                  data-act="undoKasKru:${esc(c.id)}:${esc(p.periode_bulan)}:${esc(c.name)}:${crewCode}" 
                  title="${esc(titlePaid)}" 
                  aria-label="${esc(titlePaid)}">
                  <i class="fa-solid fa-check ic-check"></i>
                  <i class="fa-solid fa-rotate-left ic-undo"></i>
                </button>
              </td>`;
          } else {
            return `
              <td class="fin-td-month">
                <span class="fin-matrix-cell paid" title="${esc(titlePaid)}">
                  <i class="fa-solid fa-check"></i>
                </span>
              </td>`;
          }
        }

        kruTotalUnpaid += sisa;
        const titleUnpaid = canManage
          ? (dibayar > 0 
              ? `Kurang bayar ${fmtRupiah(sisa)} (sudah bayar ${fmtRupiah(dibayar)}) — klik untuk lunasi` 
              : `Tandai sudah bayar — ${esc(c.name)} (${esc(fmtPeriodeBulan(p.periode_bulan))})`)
          : (dibayar > 0 
              ? `Kurang bayar ${fmtRupiah(sisa)} (sudah bayar ${fmtRupiah(dibayar)})` 
              : `Belum bayar — ${esc(fmtPeriodeBulan(p.periode_bulan))}`);

        if (canManage) {
          return `
            <td class="fin-td-month">
              <button type="button" 
                class="fin-matrix-cell unpaid" 
                data-act="tandaiKasLunas:${esc(c.id)}:${esc(p.periode_bulan)}:${esc(c.name)}:${crewCode}" 
                title="${esc(titleUnpaid)}" 
                aria-label="${esc(titleUnpaid)}">
                <i class="fa-regular fa-circle ic-circle"></i>
                <i class="fa-solid fa-check ic-hover-check"></i>
              </button>
            </td>`;
        }

        return `
          <td class="fin-td-month">
            <span class="fin-matrix-cell unpaid" title="${esc(titleUnpaid)}">
              <i class="fa-regular fa-circle" style="font-size:11px;"></i>
            </span>
          </td>`;
      }).join('');

      return `
        <tr class="fin-kru-tr-body">
          <td class="fin-td-kru">
            <div class="fin-kru-cell-wrap">
              ${avatarHTML(c.name, c.photo || c.foto_url, 'sm')}
              <div class="fin-kru-info">
                <div class="fin-kru-name-row">
                  <span class="fin-kru-name">${esc(c.name)}</span>
                  <span class="chip ok fin-kru-chip">Aktif</span>
                </div>
                <div class="fin-kru-meta">
                  ${(c.crew_id || c.ptv_id) ? `<span class="fin-kru-id">${esc(c.crew_id || c.ptv_id)}</span>` : ''}
                  <span class="fin-kru-role">${esc(c.pos || c.divisi || c.div || c.role || 'Kru')}</span>
                </div>
              </div>
            </div>
          </td>
          ${cellsHTML}
          <td class="fin-td-total">
            ${kruTotalUnpaid === 0 
              ? '<span style="color:#059669;font-weight:750;font-size:12px;"><i class="fa-solid fa-check-double" style="margin-right:3px;"></i><span class="fin-lunas-full">Lunas Semua</span><span class="fin-lunas-short">Lunas</span></span>' 
              : `<span class="fin-total-val" style="color:#dc2626;font-weight:800;font-size:13px;">${fmtRupiah(kruTotalUnpaid)}</span>`}
          </td>
        </tr>`;
    }).join('');

    let myHistoryHTML = '';
    const myCrew = (DB.crew || []).find(c => 
      (ME.ptvId && (c.crew_id === ME.ptvId || c.ptv_id === ME.ptvId)) ||
      (ME.id && String(c.id) === String(ME.id)) ||
      (ME.name && c.name && c.name.toLowerCase() === ME.name.toLowerCase())
    );
    if (myCrew) {
      const myPayments = allKasKru.filter(k => 
        (String(k.kru_id) === String(myCrew.id) || (k.kru_nama && k.kru_nama.toLowerCase() === myCrew.name.toLowerCase())) &&
        k.status === 'Lunas'
      ).sort((a,b) => (b.periode_bulan || '').localeCompare(a.periode_bulan || ''));

      if (myPayments.length > 0) {
        const myFirstName = (ME.short || (ME.name ? ME.name.split(' ')[0] : 'Kru'));
        myHistoryHTML = `
          <div class="card" style="background:var(--surface);border:1px solid var(--line-2);border-radius:18px;margin-top:20px;overflow:hidden;">
            <div style="padding:14px 18px;border-bottom:1px solid var(--line-2);display:flex;align-items:center;justify-content:space-between;">
              <div style="font-weight:750;font-size:14px;color:var(--ink);display:flex;align-items:center;gap:8px;">
                <i class="fa-solid fa-clock-rotate-left" style="color:var(--ptv-green,#0e4f40)"></i>
                Riwayat Kas Saya (${esc(myFirstName)})
              </div>
              <span class="chip ok" style="font-size:11px;font-weight:750;padding:2px 8px;border-radius:9999px;">
                ${myPayments.length} Pembayaran Tercatat
              </span>
            </div>
            <div style="overflow-x:auto;">
              <table style="width:100%;border-collapse:collapse;text-align:left;font-size:12.5px;">
                <thead>
                  <tr style="background:var(--bg-2);border-bottom:1px solid var(--line-2);color:var(--ink3);font-size:11.5px;font-weight:700;">
                    <th style="padding:10px 14px;">Periode Kas</th>
                    <th style="padding:10px 14px;">Nominal Iuran</th>
                    <th style="padding:10px 14px;">Tanggal Pembayaran</th>
                    <th style="padding:10px 14px;">Status</th>
                    <th style="padding:10px 14px;text-align:right;">Dicatat Oleh</th>
                  </tr>
                </thead>
                <tbody>
                  ${myPayments.map(p => `
                    <tr style="border-bottom:1px solid var(--line-2);">
                      <td style="padding:10px 14px;font-weight:700;color:var(--ink);">${esc(fmtPeriodeBulan(p.periode_bulan))}</td>
                      <td style="padding:10px 14px;font-weight:750;color:#059669;">${fmtRupiah(p.dibayar || p.tagihan)}</td>
                      <td style="padding:10px 14px;color:var(--ink2);">${p.tanggal_bayar ? fmtDate(p.tanggal_bayar) : '—'}</td>
                      <td style="padding:10px 14px;"><span class="chip ok" style="font-size:10.5px;font-weight:800;padding:1px 7px;border-radius:9999px;"><i class="fa-solid fa-check" style="margin-right:3px;"></i>Lunas</span></td>
                      <td style="padding:10px 14px;text-align:right;color:var(--ink3);font-size:11.5px;">${esc(p.dicatat_oleh_nama || 'Admin Keuangan')}</td>
                    </tr>
                  `).join('')}
                </tbody>
              </table>
            </div>
          </div>`;
      }
    }

    return `
      <div class="card pad" style="background:var(--surface);border:1px solid var(--line-2);border-radius:18px;padding:14px 18px;margin-bottom:16px;">
        <div style="display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;">
          <div style="position:relative;flex:1;min-width:240px">
            <i class="fa-solid fa-magnifying-glass" style="position:absolute;left:14px;top:50%;transform:translateY(-50%);color:var(--ink3);font-size:13px"></i>
            <input type="text" id="finSearchInput" class="input" placeholder="Cari nama kru, PTV-ID, atau divisi..." value="${esc(finSearchQ)}" style="padding-left:36px;border-radius:12px;font-size:13px;height:40px;background:var(--bg-2);border:1px solid var(--line-2)">
            ${finSearchQ ? `<button type="button" data-act="clearFinSearch" style="position:absolute;right:10px;top:50%;transform:translateY(-50%);border:none;background:transparent;cursor:pointer;color:var(--ink3);font-size:14px"><i class="fa-solid fa-xmark"></i></button>` : ''}
          </div>
          
          <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
            <div class="filters" style="margin-bottom:0;display:flex;gap:6px">
              <span class="fchip on" style="font-size:12px;padding:5px 14px;border-radius:999px;font-weight:700;display:inline-flex;align-items:center;gap:5px;">
                <i class="fa-solid fa-user-check"></i>Kru Aktif (${crewListToRender.length})
              </span>
            </div>
            ${canManage ? `
              <button type="button" class="btn sm" data-act="openPengaturanIuran" style="font-size:12px;padding:6px 14px;border-radius:10px;font-weight:750;background:var(--bg-2);border:1px solid var(--line-2);color:var(--ink);display:inline-flex;align-items:center;gap:6px;">
                <i class="fa-solid fa-gear" style="color:var(--ptv-green,#0e4f40)"></i><span>Pengaturan Iuran Kas</span>
              </button>
            ` : ''}
          </div>
        </div>
      </div>

      <div class="card fin-kru-table-wrap">
        <div class="fin-kru-table-scroll">
          <table class="fin-kru-table">
            <thead>
              <tr class="fin-kru-tr-head">
                <th class="fin-th-kru">
                  Kru PTV
                </th>
                ${validPeriods.map(p => `
                  <th class="fin-th-month">
                    <div class="fin-th-month-title">
                      <span class="fin-month-full">${esc(fmtPeriodeBulan(p.periode_bulan))}</span>
                      <span class="fin-month-short">${esc(fmtPeriodeBulanShort(p.periode_bulan))}</span>
                    </div>
                    <div class="fin-th-month-sub">
                      <span class="fin-th-month-nom">
                        <span class="fin-month-nom-full">${fmtRupiah(p.nominal)}</span>
                        <span class="fin-month-nom-short">${fmtNominalShort(p.nominal)}</span>
                      </span>
                      ${canManage ? `
                        <button type="button" class="fin-edit-nom-btn" data-act="editPeriodeNominal:${esc(p.periode_bulan)}:${p.nominal}" title="Ubah nominal iuran ${esc(fmtPeriodeBulan(p.periode_bulan))}">
                          <i class="fa-solid fa-pen" style="font-size:9.5px;"></i>
                        </button>
                      ` : ''}
                    </div>
                  </th>
                `).join('')}
                <th class="fin-th-total">
                  <span class="fin-total-full">Total Tunggakan</span>
                  <span class="fin-total-short">Tunggakan</span>
                </th>
              </tr>
            </thead>
            <tbody>
              ${matrixRowsHTML || `<tr><td colspan="${validPeriods.length + 2}" style="padding:40px;text-align:center;color:var(--ink3);">Tidak ada data kru pada filter ini.</td></tr>`}
            </tbody>
          </table>
        </div>
      </div>

      ${myHistoryHTML}
    `;
  }

  if (tab === 'pemasukan') {
    let pemList = allPemasukan.slice().sort((a,b) => (b.tanggal || '').localeCompare(a.tanggal || ''));
    if (finSearchQ && finSearchQ.trim()) {
      const q = finSearchQ.trim().toLowerCase();
      pemList = pemList.filter(x => (x.sumber || '').toLowerCase().includes(q) || (x.kategori || '').toLowerCase().includes(q) || (x.keterangan || '').toLowerCase().includes(q) || (x.kru_nama || '').toLowerCase().includes(q) || String(x.nominal || '').includes(q));
    }

    return `
      <div class="card pad" style="background:var(--surface);border:1px solid var(--line-2);border-radius:18px;padding:14px 18px;margin-bottom:16px;">
        <div style="display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;">
          <div style="position:relative;flex:1;min-width:240px">
            <i class="fa-solid fa-magnifying-glass" style="position:absolute;left:14px;top:50%;transform:translateY(-50%);color:var(--ink3);font-size:13px"></i>
            <input type="text" id="finSearchInput" class="input" placeholder="Cari sumber, kategori, kru, atau keterangan pemasukan..." value="${esc(finSearchQ)}" style="padding-left:36px;border-radius:12px;font-size:13px;height:40px;background:var(--bg-2);border:1px solid var(--line-2)">
            ${finSearchQ ? `<button type="button" data-act="clearFinSearch" style="position:absolute;right:10px;top:50%;transform:translateY(-50%);border:none;background:transparent;cursor:pointer;color:var(--ink3);font-size:14px"><i class="fa-solid fa-xmark"></i></button>` : ''}
          </div>
          ${canManage ? `
            <button type="button" class="btn sm pri" data-act="openCatatPemasukan" style="font-size:12.5px;padding:8px 16px;border-radius:11px;font-weight:750;background:#059669;border:none;box-shadow:0 3px 12px rgba(5,150,105,0.25);display:inline-flex;align-items:center;gap:7px;color:#fff;">
              <i class="fa-solid fa-plus" style="font-size:11px;"></i>
              <i class="fa-solid fa-arrow-down" style="font-size:12px;"></i>
              <span>Catat Pemasukan</span>
            </button>
          ` : ''}
        </div>
      </div>

      <div id="finGroupedContent">
        ${renderPemasukanMonthlyGroups(pemList, canManage)}
      </div>
    `;
  }

  if (tab === 'pengeluaran') {
    let penList = allPengeluaran.slice().sort((a,b) => (b.tanggal || '').localeCompare(a.tanggal || ''));
    if (finSearchQ && finSearchQ.trim()) {
      const q = finSearchQ.trim().toLowerCase();
      penList = penList.filter(x => (x.keperluan || '').toLowerCase().includes(q) || (x.kategori || '').toLowerCase().includes(q) || (x.keterangan || '').toLowerCase().includes(q) || String(x.nominal || '').includes(q));
    }

    return `
      <div class="card pad" style="background:var(--surface);border:1px solid var(--line-2);border-radius:18px;padding:14px 18px;margin-bottom:16px;">
        <div style="display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;">
          <div style="position:relative;flex:1;min-width:240px">
            <i class="fa-solid fa-magnifying-glass" style="position:absolute;left:14px;top:50%;transform:translateY(-50%);color:var(--ink3);font-size:13px"></i>
            <input type="text" id="finSearchInput" class="input" placeholder="Cari keperluan, kategori, atau keterangan pengeluaran..." value="${esc(finSearchQ)}" style="padding-left:36px;border-radius:12px;font-size:13px;height:40px;background:var(--bg-2);border:1px solid var(--line-2)">
            ${finSearchQ ? `<button type="button" data-act="clearFinSearch" style="position:absolute;right:10px;top:50%;transform:translateY(-50%);border:none;background:transparent;cursor:pointer;color:var(--ink3);font-size:14px"><i class="fa-solid fa-xmark"></i></button>` : ''}
          </div>
          ${canManage ? `
            <button type="button" class="btn sm pri" data-act="openCatatPengeluaran" style="font-size:12.5px;padding:8px 16px;border-radius:11px;font-weight:750;background:#dc2626;border:none;box-shadow:0 3px 12px rgba(220,38,38,0.25);display:inline-flex;align-items:center;gap:7px;color:#fff;">
              <i class="fa-solid fa-plus" style="font-size:11px;"></i>
              <i class="fa-solid fa-arrow-up" style="font-size:12px;"></i>
              <span>Catat Pengeluaran</span>
            </button>
          ` : ''}
        </div>
      </div>

      <div id="finGroupedContent">
        ${renderPengeluaranMonthlyGroups(penList, canManage)}
      </div>
    `;
  }

  return '';
}

function syncKeuanganLive() {
  fetch(AJAX_URL + '?action=ptv_dashboard_get_live_data')
    .then(r => r.json())
    .then(res => {
      if (res.success && res.data?.DB?.keuangan) {
        DB.keuangan = Object.assign(DB.keuangan || {}, res.data.DB.keuangan);
        const tabBody = document.getElementById('finTabBody');
        if (tabBody) {
          tabBody.innerHTML = renderFinTabBody(finTab);
        }
      }
    })
    .catch(() => {});
}

function switchFinTab(targetTab) {
  finTab = targetTab || 'kas_kru';
  const tabBody = document.getElementById('finTabBody');
  const tabBar = document.getElementById('finTabBar');
  if (tabBody && tabBar) {
    tabBar.querySelectorAll('[data-act^="setFinTab:"]').forEach(btn => {
      const act = btn.getAttribute('data-act');
      const t = act.split(':')[1];
      const isActive = (t === finTab);
      btn.style.background = isActive ? (t === 'kas_kru' ? 'var(--ptv-green,#0e4f40)' : (t === 'pemasukan' ? '#059669' : '#dc2626')) : 'var(--surface)';
      btn.style.color = isActive ? '#fff' : 'var(--ink2)';
      btn.style.borderColor = isActive ? 'transparent' : 'var(--line-2)';
      btn.style.boxShadow = isActive ? (t === 'kas_kru' ? '0 3px 12px rgba(14,79,64,0.25)' : (t === 'pemasukan' ? '0 3px 12px rgba(5,150,105,0.25)' : '0 3px 12px rgba(220,38,38,0.25)')) : 'none';
    });
    tabBody.innerHTML = renderFinTabBody(finTab);
    syncKeuanganLive();
  } else {
    const savedY = window.scrollY || document.documentElement.scrollTop || 0;
    render();
    requestAnimationFrame(() => {
      window.scrollTo({ top: savedY, behavior: 'instant' });
    });
  }
}

function pgKeuangan(){
  setTimeout(syncKeuanganLive, 100);
  if (!canAccessKeuangan() || (DB.keuangan && DB.keuangan.access_denied)) {
    return `<div class="page">
      <div class="card pad text-center" style="padding:48px 24px; max-width:480px; margin:40px auto; background:var(--surface,#fff); border-radius:18px; border:1px solid var(--line-2,#e2e8f0); box-shadow:var(--shadow-m, 0 4px 20px rgba(0,0,0,0.04));">
        <div style="width:60px; height:60px; border-radius:50%; background:#fee2e2; color:#ef4444; display:grid; place-items:center; margin:0 auto 16px; font-size:24px;">
          <i class="fa-solid fa-lock"></i>
        </div>
        <h2 class="t-lg font-bold" style="margin:0 0 8px; color:var(--ink,#0f172a);">Akses Terbatas: Khusus Kru Aktif</h2>
        <p class="t-sm muted" style="margin:0 0 24px; color:var(--ink2,#64748b); line-height:1.6;">
          Halaman Keuangan dan pembukuan kas PTV hanya dapat diakses oleh <b>Kru Aktif</b> dan <b>Eksekutif</b>. Akun nonaktif atau posisi non-operasional (Pengarah, Pembina, Penasihat) tidak memiliki izin untuk melihat modul ini.
        </p>
        <button class="btn pri" data-go="beranda" style="border-radius:12px; padding:10px 22px; font-weight:700;">
          <i class="fa-solid fa-arrow-left" style="margin-right:6px"></i> Kembali ke Beranda
        </button>
      </div>
    </div>`;
  }

  const canManage = isKeuanganAdmin();
  const fin = DB.keuangan || { pemasukan: [], pengeluaran: [], kas_kru: [], periode: [], tables_ready: false };
  const allPemasukan = (fin.pemasukan || []).filter(x => x.status !== 'void');
  const allPengeluaran = (fin.pengeluaran || []).filter(x => x.status !== 'void');
  const allKasKru = fin.kas_kru || [];
  const allPeriode = fin.periode || [];

  // Konfigurasi Periode & Nominal Dinamis Dimulai Juli 2026
  const configuredPeriods = (allPeriode && allPeriode.length) ? allPeriode : [
    { periode_bulan: '2026-07', nominal: 20000, keterangan: 'Juli 2026', status: 'aktif', is_active: true },
    { periode_bulan: '2026-08', nominal: 25000, keterangan: 'Agustus 2026', status: 'aktif', is_active: true },
    { periode_bulan: '2026-09', nominal: 25000, keterangan: 'September 2026', status: 'aktif', is_active: true },
  ];
  const validPeriods = configuredPeriods
    .filter(p => {
      // 1. Filter awal: Jangan pernah memuat atau menghitung periode sebelum Juli 2026
      if (!p.periode_bulan || p.periode_bulan < '2026-07') return false;
      // 2. Filter status: Periode nonaktif tidak ditampilkan sebagai periode iuran aktif
      if (p.is_active === false || p.status === 'nonaktif' || (p.keterangan || '').includes('[NONAKTIF]')) return false;
      return true;
    })
    .sort((a,b) => a.periode_bulan.localeCompare(b.periode_bulan));

  // 1. METRIK GLOBAL
  const totPemasukan = allPemasukan.reduce((acc, x) => acc + (Number(x.nominal) || 0), 0);
  const totPengeluaran = allPengeluaran.reduce((acc, x) => acc + (Number(x.nominal) || 0), 0);
  const saldoKas = totPemasukan - totPengeluaran;

  // 2. PERSONAL REMINDER (Hanya untuk Kru yang Sedang Login)
  const myCrew = (DB.crew || []).find(c => 
    (ME.ptvId && (c.crew_id === ME.ptvId || c.ptv_id === ME.ptvId)) ||
    (ME.id && String(c.id) === String(ME.id)) ||
    (ME.name && c.name && c.name.toLowerCase() === ME.name.toLowerCase())
  );

  let myUnpaidList = [];
  let myTotalTunggakan = 0;
  let myFirstName = (ME.short || (ME.name ? ME.name.split(' ')[0] : 'Kru'));

  if (myCrew) {
    const myJoinYM = (myCrew.join ? String(myCrew.join).slice(0, 7) : '2026-07');
    validPeriods.forEach(p => {
      if (myJoinYM > p.periode_bulan) return; // Belum join

      const payStatus = getKruPaymentStatus(myCrew, p.periode_bulan);
      if (!payStatus.isPaid) {
        myUnpaidList.push({
          periode_bulan: p.periode_bulan,
          label: fmtPeriodeBulan(p.periode_bulan),
          nominal: payStatus.sisa,
          dibayar: payStatus.dibayar
        });
        myTotalTunggakan += payStatus.sisa;
      }
    });
  }

  // Hitung total piutang kas keseluruhan kru aktif berdasarkan getKruPaymentStatus
  let totPiutangSemuaKru = 0;
  (DB.crew || []).forEach(c => {
    if (!isOperationalCrew(c)) return;
    const cJoinYM = (c.join ? String(c.join).slice(0, 7) : '2026-07');
    validPeriods.forEach(p => {
      if (cJoinYM > p.periode_bulan) return;
      const payStatus = getKruPaymentStatus(c, p.periode_bulan);
      if (!payStatus.isPaid) {
        totPiutangSemuaKru += payStatus.sisa;
      }
    });
  });

  const showTablesNotReadyNotice = (fin.tables_ready === false);

  // Tab Content Builder
  const tabContentHTML = renderFinTabBody(finTab);

  // ----------------------------------------------------
  // PERSONAL REMINDER CARD HTML
  // ----------------------------------------------------
  let personalReminderHTML = '';
  if (myCrew && myUnpaidList.length > 0) {
    personalReminderHTML = `
      <div class="card fin-reminder-card">
        <!-- 1. Header (Badge + Nama + Reminder Singkat) -->
