            <button type="button" class="btn sm" data-act="editPeriodeNominal:${esc(p.periode_bulan)}:${p.nominal}" title="Ubah nominal tarif" style="padding:5px 10px;font-size:11.5px;border-radius:8px;font-weight:700;">
              <i class="fa-solid fa-pen" style="font-size:10px;margin-right:4px;"></i>Edit
            </button>
            ${isAct ? `
              <button type="button" class="btn sm" data-act="hapusPeriodeKas:${esc(p.periode_bulan)}:${hasPayments ? '1' : '0'}" title="${hasPayments ? 'Nonaktifkan periode ini (aman, riwayat tetap ada)' : 'Hapus periode ini'}" style="padding:5px 10px;font-size:11.5px;border-radius:8px;font-weight:700;background:#fef2f2;border:1px solid #fecaca;color:#dc2626;">
                <i class="fa-solid fa-trash-can" style="font-size:10px;margin-right:4px;"></i>Hapus
              </button>
            ` : `
              <button type="button" class="btn sm" data-act="toggleStatusPeriode:${esc(p.periode_bulan)}:aktif" title="Aktifkan kembali periode ini" style="padding:5px 10px;font-size:11.5px;border-radius:8px;font-weight:700;background:#ecfdf5;border:1px solid #a7f3d0;color:#059669;">
                <i class="fa-solid fa-rotate-right" style="font-size:10px;margin-right:4px;"></i>Aktifkan
              </button>
              ${!hasPayments ? `
                <button type="button" class="btn sm" data-act="hapusPeriodeKas:${esc(p.periode_bulan)}:0" title="Hapus permanen" style="padding:5px 8px;font-size:11.5px;border-radius:8px;font-weight:700;background:#fee2e2;border:1px solid #fca5a5;color:#b91c1c;">
                  <i class="fa-solid fa-trash"></i>
                </button>
              ` : ''}
            `}
          </div>
        </td>
      </tr>
    `;
  }).join('');

  openSheet('Pengaturan Tarif & Periode Iuran Kas', `
    <div style="margin-bottom:16px;">
      <div style="font-size:12.5px;color:var(--ink2);line-height:1.5;background:var(--bg-2);padding:11px 14px;border-radius:12px;border:1px solid var(--line-2);">
        <i class="fa-solid fa-circle-info" style="color:var(--ptv-green,#0e4f40);margin-right:6px;"></i>
        Periode kas dimulai resmi dari <b>Juli 2026 (2026-07)</b>. Setiap periode dapat memiliki nominal berbeda. Perubahan tersimpan langsung di Supabase dan otomatis memutakhirkan tagihan kru.
      </div>
    </div>

    <!-- Form Tambah / Simpan Periode Baru -->
    <div style="background:var(--surface);border:1.5px solid var(--line-2);border-radius:14px;padding:14px 16px;margin-bottom:18px;">
      <div style="font-weight:800;font-size:13.5px;color:var(--ink);margin-bottom:10px;display:flex;align-items:center;gap:6px;">
        <i class="fa-solid fa-calendar-plus" style="color:var(--ptv-green,#0e4f40);"></i>Tambah / Konfigurasi Periode Baru
      </div>

      <div class="grid-2">
        <div class="field" style="margin-bottom:12px">
          <label style="font-weight:700;font-size:12.5px;display:block;margin-bottom:5px">Bulan &amp; Tahun Periode *</label>
          <input type="month" id="modal_set_periode" class="input" min="2026-07" value="${iso(new Date()).slice(0,7) >= '2026-07' ? iso(new Date()).slice(0,7) : '2026-07'}" required style="font-size:13px;padding:8px 12px;border-radius:10px;">
        </div>
        <div class="field" style="margin-bottom:12px">
          <label style="font-weight:700;font-size:12.5px;display:block;margin-bottom:5px">Nominal Iuran (Rp) *</label>
          <input type="number" id="modal_set_nominal" class="input" value="25000" min="1000" step="1000" required style="font-size:13.5px;font-weight:750;padding:8px 12px;border-radius:10px;">
        </div>
      </div>

      <div class="field" style="margin-bottom:12px">
        <label style="font-weight:700;font-size:12.5px;display:block;margin-bottom:5px">Keterangan (Opsional)</label>
        <input type="text" id="modal_set_keterangan" class="input" placeholder="Contoh: Iuran Kas Bulan Oktober 2026..." style="font-size:13px;padding:8px 12px;border-radius:10px;">
      </div>

      <div style="text-align:right;">
        <button type="button" class="btn pri sm" data-act="submitPengaturanIuran" style="font-size:12.5px;padding:8px 18px;border-radius:10px;font-weight:750;background:var(--ptv-green,#0e4f40);border:none;">
          <i class="fa-solid fa-save" style="margin-right:6px"></i>Simpan Periode Iuran
        </button>
      </div>
    </div>

    <!-- Tabel Daftar Periode -->
    <div>
      <div style="font-weight:750;font-size:13px;color:var(--ink2);margin-bottom:8px;display:flex;align-items:center;justify-content:space-between;">
        <span>Daftar Periode Iuran (${displayPeriods.length})</span>
        <span style="font-size:11px;color:var(--ink3);font-weight:600;">Periode nonaktif tidak ditagihkan ke kru</span>
      </div>
      <div style="border:1px solid var(--line-2);border-radius:12px;overflow:hidden;background:var(--surface);">
        <table style="width:100%;border-collapse:collapse;font-size:12px;text-align:left;">
          <thead>
            <tr style="background:var(--bg-2);border-bottom:1px solid var(--line-2);color:var(--ink3);font-size:11px;font-weight:700;">
              <th style="padding:9px 12px;">Periode</th>
              <th style="padding:9px 12px;">Tarif</th>
              <th style="padding:9px 12px;">Status Pembayaran</th>
              <th style="padding:9px 12px;text-align:right;">Aksi</th>
            </tr>
          </thead>
          <tbody>
            ${listRowsHTML || `<tr><td colspan="4" style="padding:24px;text-align:center;color:var(--ink3);">Belum ada periode yang terkonfigurasi.</td></tr>`}
          </tbody>
        </table>
      </div>
    </div>
  `, {
    foot: `
      <div style="display:flex;justify-content:flex-end;width:100%">
        <button type="button" class="btn" data-act="closeSheet" style="border-radius:10px;padding:6px 16px;">Tutup</button>
      </div>
    `
  });
}

function submitPengaturanIuran() {
  const periode = ($('#modal_set_periode')?.value || '').trim();
  const nominal = parseInt($('#modal_set_nominal')?.value || 0, 10);
  const keterangan = ($('#modal_set_keterangan')?.value || '').trim();

  if (!periode || periode < '2026-07') {
    toast('Periode harus diisi dan dimulai minimal Juli 2026 (2026-07).', 'alert');
    return;
  }
  if (nominal <= 0) {
    toast('Nominal iuran harus lebih besar dari 0.', 'alert');
    return;
  }

  const submitBtn = document.querySelector('[data-act="submitPengaturanIuran"]');
  let origBtnHtml = '';
  if (submitBtn) {
    origBtnHtml = submitBtn.innerHTML;
    submitBtn.disabled = true;
    submitBtn.style.opacity = '0.75';
    submitBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin" style="margin-right:6px"></i>Menyimpan...';
  }

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_save_kas_periode');
  fd.append('periode_bulan', periode);
  fd.append('nominal', nominal);
  fd.append('keterangan', keterangan);
  fd.append('status', 'aktif');

  fetch(AJAX_URL, { method: 'POST', body: fd })
    .then(r => r.json())
    .then(res => {
      if (res.success && (res.data?.item || res.data?.periode)) {
        const item = res.data.item || res.data.periode;
        if (!DB.keuangan) DB.keuangan = { pemasukan: [], pengeluaran: [], kas_kru: [], periode: [], tables_ready: true };
        
        if (Array.isArray(res.data.all_kas_kru)) {
          DB.keuangan.kas_kru = res.data.all_kas_kru;
        } else {
          (DB.keuangan.kas_kru || []).forEach(k => {
            if (k.periode_bulan === periode) {
              k.tagihan = nominal;
              const dibayar = Number(k.dibayar || 0);
              k.sisa = Math.max(0, nominal - dibayar);
              k.status = (k.sisa === 0 && dibayar >= nominal) ? 'Lunas' : 'Belum Bayar';
            }
          });
        }

        if (Array.isArray(res.data.all_periode)) {
          DB.keuangan.periode = res.data.all_periode;
        } else {
          if (!Array.isArray(DB.keuangan.periode)) DB.keuangan.periode = [];
          const idx = DB.keuangan.periode.findIndex(p => p.periode_bulan === periode);
          if (idx !== -1) {
            DB.keuangan.periode[idx] = item;
          } else {
            DB.keuangan.periode.push(item);
            DB.keuangan.periode.sort((a,b) => a.periode_bulan.localeCompare(b.periode_bulan));
          }
        }

        toast(`Pengaturan tarif iuran ${fmtPeriodeBulan(periode)} (${fmtRupiah(nominal)}) berhasil disimpan.`, 'check');
        render();
        openPengaturanIuranModal();
      } else {
        if (submitBtn) {
          submitBtn.disabled = false;
          submitBtn.style.opacity = '1';
          submitBtn.innerHTML = origBtnHtml;
        }
        toast(res.data?.message || res.message || 'Gagal menyimpan pengaturan iuran.', 'alert');
      }
    })
    .catch(err => {
      if (submitBtn) {
        submitBtn.disabled = false;
        submitBtn.style.opacity = '1';
        submitBtn.innerHTML = origBtnHtml;
      }
      toast('Koneksi gagal: ' + (err?.message || err), 'alert');
    });
}

function hapusPeriodeKas(periodeBulan, hasPayments) {
  if (!isKeuanganAdmin()) {
    toast('Akses terbatas untuk Eksekutif dan Farsya.', 'alert');
    return;
  }
  if (!periodeBulan) return;

  const periodeLabel = fmtPeriodeBulan(periodeBulan);

  if (hasPayments) {
    const confirmMsg = `⚠️ PERINGATAN KEUANGAN:\n\nPeriode ${periodeLabel} sudah memiliki data pembayaran kru.\n\nMenghapus periode dapat memengaruhi riwayat keuangan.\n\nSistem akan MENONAKTIFKAN periode ini agar riwayat transaksi pembayaran tetap aman, namun tidak lagi ditagihkan ke kru aktif.\n\nLanjutkan nonaktifkan periode?`;
    if (!confirm(confirmMsg)) return;
  } else {
    const confirmMsg = `Hapus periode ${periodeLabel}?\n\nPeriode ini belum memiliki transaksi dan akan dihapus secara permanen dari sistem.`;
    if (!confirm(confirmMsg)) return;
  }

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_delete_kas_periode');
  fd.append('periode_bulan', periodeBulan);
  fd.append('force_mode', hasPayments ? 'deactivate' : 'safe');

  fetch(AJAX_URL, { method: 'POST', body: fd })
    .then(r => r.json())
    .then(res => {
      if (res.success) {
        if (!DB.keuangan) DB.keuangan = { periode: [], kas_kru: [] };
        if (!Array.isArray(DB.keuangan.periode)) DB.keuangan.periode = [];

        if (res.data?.mode === 'deactivated' || hasPayments) {
          const p = DB.keuangan.periode.find(x => x.periode_bulan === periodeBulan);
          if (p) {
            p.status = 'nonaktif';
            p.is_active = false;
            if (!p.keterangan || !p.keterangan.includes('[NONAKTIF]')) {
              p.keterangan = '[NONAKTIF] ' + (p.keterangan || '');
            }
          }
          toast(`Periode ${periodeLabel} berhasil dinonaktifkan.`, 'check');
        } else {
          DB.keuangan.periode = DB.keuangan.periode.filter(x => x.periode_bulan !== periodeBulan);
          toast(`Periode ${periodeLabel} berhasil dihapus dari sistem.`, 'check');
        }

        render();
        openPengaturanIuranModal();
      } else {
        toast(res.data?.message || res.message || 'Gagal menghapus periode.', 'alert');
      }
    })
    .catch(err => {
      toast('Koneksi gagal: ' + (err?.message || err), 'alert');
    });
}

function toggleStatusPeriode(periodeBulan, targetStatus) {
  if (!isKeuanganAdmin()) {
    toast('Akses terbatas untuk Eksekutif dan Farsya.', 'alert');
    return;
  }
  if (!periodeBulan) return;

  const fin = DB.keuangan || { periode: [] };
  const p = (fin.periode || []).find(x => x.periode_bulan === periodeBulan);
  const nominal = p ? (p.nominal || 25000) : 25000;
  const ket = p ? (p.keterangan || '').replace('[NONAKTIF]', '').trim() : '';

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_save_kas_periode');
  fd.append('periode_bulan', periodeBulan);
  fd.append('nominal', nominal);
  fd.append('keterangan', ket);
  fd.append('status', targetStatus || 'aktif');

  fetch(AJAX_URL, { method: 'POST', body: fd })
    .then(r => r.json())
    .then(res => {
      if (res.success && res.data) {
        if (p) {
          p.status = targetStatus;
          p.is_active = (targetStatus === 'aktif');
          p.keterangan = ket;
        }
        toast(`Periode ${fmtPeriodeBulan(periodeBulan)} berhasil diaktifkan kembali.`, 'check');
        render();
        openPengaturanIuranModal();
      } else {
        toast(res.data?.message || res.message || 'Gagal mengubah status periode.', 'alert');
      }
    })
    .catch(err => {
      toast('Koneksi gagal: ' + (err?.message || err), 'alert');
    });
}

function openEditPeriodeNominal(periodeBulan, currentNominal) {
  if (!isKeuanganAdmin()) {
    toast('Akses terbatas untuk Eksekutif dan Farsya.', 'alert');
    return;
  }
  if (!periodeBulan) return;

  const periodeLabel = fmtPeriodeBulan(periodeBulan);
  const curVal = currentNominal || 25000;

  openSheet(`Nominal Iuran ${periodeLabel}`, `
    <div style="padding:4px 0 12px;">
      <div style="font-size:13px;color:var(--ink2);margin-bottom:18px;line-height:1.5;">
        Atur tarif iuran kas resmi untuk periode <b>${esc(periodeLabel)}</b>. Nominal baru akan langsung diterapkan ke seluruh tagihan kru dan pembukuan kas.
      </div>

      <div class="field" style="margin-bottom:22px;">
        <label style="font-weight:750;font-size:12.5px;color:var(--ink);display:block;margin-bottom:6px;">
          Nominal Iuran ${esc(periodeLabel)} *
        </label>
        <div style="position:relative;display:flex;align-items:center;">
          <span style="position:absolute;left:14px;font-weight:800;color:var(--ink3);font-size:14px;">Rp</span>
          <input type="number" id="quick_edit_nominal_input" class="input" 
            value="${curVal}" min="1000" step="1000" 
            style="padding-left:42px;font-size:18px;font-weight:850;border-radius:12px;height:46px;color:var(--ink);" 
            required autofocus>
        </div>
        <div style="font-size:11px;color:var(--ink3);margin-top:5px;">
          Contoh: 20000, 25000, atau 40000
        </div>
      </div>

      <div style="display:flex;gap:10px;justify-content:flex-end;">
        <button type="button" class="btn sm" data-act="closeSheet" style="border-radius:10px;padding:9px 18px;font-weight:700;">
          Batal
        </button>
        <button type="button" class="btn pri sm" id="btn_save_quick_nominal" data-act="saveQuickPeriodeNominal:${esc(periodeBulan)}" style="border-radius:10px;padding:9px 24px;font-weight:750;background:var(--ptv-green,#0e4f40);">
          Simpan
        </button>
      </div>
    </div>
  `, {
    then: () => {
      const inp = document.getElementById('quick_edit_nominal_input');
      if (inp) {
        inp.focus();
        inp.select();
        inp.addEventListener('keydown', (e) => {
          if (e.key === 'Enter') {
            e.preventDefault();
            saveQuickPeriodeNominal(periodeBulan);
          }
        });
      }
    }
  });
}

function saveQuickPeriodeNominal(periodeBulan) {
  if (!isKeuanganAdmin()) {
    toast('Akses terbatas untuk Eksekutif dan Farsya.', 'alert');
    return;
  }
  const inp = document.getElementById('quick_edit_nominal_input');
  if (!inp) return;
  const newNom = parseInt(inp.value, 10);
  if (isNaN(newNom) || newNom <= 0) {
    toast('Nominal iuran harus lebih besar dari Rp 0.', 'alert');
    inp.focus();
    return;
  }

  const btn = document.getElementById('btn_save_quick_nominal');
  if (btn) {
    btn.disabled = true;
    btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin" style="margin-right:6px"></i>Menyimpan...';
  }

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_save_kas_periode');
  fd.append('periode_bulan', periodeBulan);
  fd.append('nominal', newNom);
  fd.append('keterangan', `Iuran Kas Kru ${fmtPeriodeBulan(periodeBulan)}`);

  fetch(AJAX_URL, { method: 'POST', body: fd })
    .then(r => r.json())
    .then(res => {
      if (res.success && res.data) {
        if (!DB.keuangan) DB.keuangan = { pemasukan: [], pengeluaran: [], kas_kru: [], periode: [] };
        if (Array.isArray(res.data.all_kas_kru)) {
          DB.keuangan.kas_kru = res.data.all_kas_kru;
        } else {
          (DB.keuangan.kas_kru || []).forEach(k => {
            if (k.periode_bulan === periodeBulan) {
              k.tagihan = newNom;
              const dibayar = Number(k.dibayar || 0);
              k.sisa = Math.max(0, newNom - dibayar);
              k.status = (k.sisa === 0 && dibayar >= newNom) ? 'Lunas' : 'Belum Bayar';
            }
          });
        }

        if (Array.isArray(res.data.all_periode)) {
          DB.keuangan.periode = res.data.all_periode;
        } else {
          if (!Array.isArray(DB.keuangan.periode)) DB.keuangan.periode = [];
          const pIdx = DB.keuangan.periode.findIndex(p => p.periode_bulan === periodeBulan);
          if (pIdx !== -1) {
            DB.keuangan.periode[pIdx].nominal = newNom;
          } else {
            DB.keuangan.periode.push({
              periode_bulan: periodeBulan,
              nominal: newNom,
              keterangan: `Iuran Kas Kru ${fmtPeriodeBulan(periodeBulan)}`
            });
          }
        }

        closeSheet();
        toast(`Nominal iuran ${fmtPeriodeBulan(periodeBulan)} berhasil diubah menjadi ${fmtRupiah(newNom)}.`, 'check');
        render();
      } else {
        if (btn) {
          btn.disabled = false;
          btn.innerHTML = 'Simpan';
        }
        toast(res.data?.message || res.message || 'Gagal menyimpan perubahan nominal.', 'alert');
      }
    })
    .catch(err => {
      if (btn) {
        btn.disabled = false;
        btn.innerHTML = 'Simpan';
      }
      toast('Koneksi gagal: ' + (err?.message || err), 'alert');
    });
}

