        </select>
      </div>
      <div class="field" style="margin-bottom:14px">
        <label style="font-weight:700;font-size:13px;display:block;margin-bottom:6px">Nominal Masuk (Rp) *</label>
        <input type="number" id="modal_pem_nominal" class="input" min="1000" step="1000" placeholder="100000" required style="font-size:13.5px;font-weight:700;padding:8px 12px;border-radius:10px;">
