function submitPemasukan(editId) {
  const sumber = ($('#modal_pem_sumber')?.value || '').trim();
  const kategori = $('#modal_pem_kategori')?.value || 'Donasi';
  const nominal = parseInt($('#modal_pem_nominal')?.value || 0, 10);
  const tanggal = ($('#modal_pem_tanggal')?.value || '').trim();
  const bukti = ($('#modal_pem_bukti')?.value || '').trim();
  const keterangan = ($('#modal_pem_keterangan')?.value || '').trim();

  if (!sumber) { toast('Sumber dana wajib diisi.', 'alert'); return; }
  if (nominal <= 0) { toast('Nominal harus lebih dari 0.', 'alert'); return; }

  const submitBtn = document.querySelector(editId ? `[data-act="submitEditPemasukan:${editId}"]` : '[data-act="submitPemasukan"]');
  let origBtnHtml = '';
  if (submitBtn) {
    origBtnHtml = submitBtn.innerHTML;
    submitBtn.disabled = true;
    submitBtn.style.opacity = '0.75';
    submitBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin" style="margin-right:6px"></i>Menyimpan...';
  }

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_save_pemasukan');
  if (editId) {
    fd.append('id', editId);
  }
  fd.append('sumber', sumber);
  fd.append('kategori', kategori);
  fd.append('nominal', nominal);
  fd.append('tanggal', tanggal);
  fd.append('bukti_url', bukti);
  fd.append('keterangan', keterangan);

  fetch(AJAX_URL, { method: 'POST', body: fd })
    .then(r => r.json())
    .then(res => {
      if (res.success && res.data?.item) {
        if (!DB.keuangan) DB.keuangan = { pemasukan: [], pengeluaran: [], kas_kru: [], tables_ready: true };
        if (editId) {
          const idx = (DB.keuangan.pemasukan || []).findIndex(x => String(x.id) === String(editId));
          if (idx !== -1) {
            DB.keuangan.pemasukan[idx] = Object.assign({}, DB.keuangan.pemasukan[idx], res.data.item);
          } else {
            DB.keuangan.pemasukan.unshift(res.data.item);
          }
        } else {
          DB.keuangan.pemasukan.unshift(res.data.item);
        }
        closeSheet();
        toast(res.data?.message || (editId ? 'Pemasukan berhasil diperbarui.' : 'Pemasukan kas berhasil dicatat di Supabase.'), 'check');
        render();
      } else {
        if (submitBtn) {
          submitBtn.disabled = false;
          submitBtn.style.opacity = '1';
          submitBtn.innerHTML = origBtnHtml;
        }
        toast(res.data?.message || res.message || 'Gagal menyimpan pemasukan.', 'alert');
      }
    })
    .catch(err => {
      if (submitBtn) {
        submitBtn.disabled = false;
        submitBtn.style.opacity = '1';
        submitBtn.innerHTML = origBtnHtml;
      }
      toast('Koneksi gagal atau Supabase error: ' + (err?.message || err), 'alert');
    });
}

