function voidKeuanganTransaction(type, id) {
  if (!isKeuanganAdmin()) {
    toast('Akses terbatas untuk Admin Keuangan.', 'alert');
    return;
  }
  const reason = prompt('Masukkan alasan pembatalan (VOID) transaksi ini:');
  if (reason === null) return;
  if (!reason.trim()) { toast('Alasan pembatalan wajib diisi.', 'alert'); return; }

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_void_keuangan');
  fd.append('type', type);
  fd.append('id', id);
  fd.append('alasan', reason.trim());

  fetch(AJAX_URL, { method: 'POST', body: fd })
    .then(r => r.json())
    .then(res => {
      if (res.success) {
        if (!DB.keuangan) DB.keuangan = { pemasukan: [], pengeluaran: [], kas_kru: [], tables_ready: true };
        if (Array.isArray(res.data?.all_kas_kru)) DB.keuangan.kas_kru = res.data.all_kas_kru;
        if (Array.isArray(res.data?.all_pemasukan)) DB.keuangan.pemasukan = res.data.all_pemasukan;
        if (Array.isArray(res.data?.all_pengeluaran)) DB.keuangan.pengeluaran = res.data.all_pengeluaran;
        
        const list = (type === 'pemasukan') ? DB.keuangan.pemasukan : DB.keuangan.pengeluaran;
        const it = (list || []).find(x => String(x.id) === String(id));
        if (it) it.status = 'void';
        
        toast('Transaksi berhasil dibatalkan (VOID).', 'check');
        render();
      } else {
        toast(res.data?.message || 'Gagal membatalkan transaksi.', 'alert');
      }
    })
    .catch(() => toast('Koneksi gagal.', 'alert'));
}

