function copyKeuanganSql() {
  const sqlNotice = `-- Silakan buka file create_ptv_keuangan.sql di folder tema atau salin DDL dari file tersebut ke SQL Editor Supabase.`;
  navigator.clipboard.writeText(sqlNotice).then(() => {
    toast('Petunjuk disalin ke clipboard! Buka create_ptv_keuangan.sql di folder tema untuk melihat script lengkap.', 'check');
  }).catch(() => {
    toast('Buka file create_ptv_keuangan.sql di folder tema.', 'info');
  });
}

