   PAGE: BROADCAST & PENGUMUMAN
   ============================================================ */
function pgBroadcast(){
  const isExec = ME.role === 'eksekutif';
  return `<div class="page">
    <div>
      ${sectionHd('Pengumuman')}
      ${DB.announcements.length === 0 ? `<div class="empty-state"><div class="empty-ic">${ic.megaphone}</div><div>Belum ada pengumuman.</div><div class="t-sm muted">Buat pengumuman baru untuk semua kru.</div></div>` : ''}
      <div class="stack">${DB.announcements.map(a=>`
        <div class="ann ${a.prio==='penting'?'high':''}">
          <div class="row-b" style="align-items:flex-start">
            <div class="tight" style="flex:1;cursor:pointer" data-ann="${esc(a.id)}"><div class="t-md font-bold">${esc(a.title)}</div>
            <p class="t-sm ink2" style="margin:5px 0 0;line-height:1.5">${esc(a.body)}</p></div>
            <div class="row gap4" style="flex-shrink:0;margin-left:10px">
              ${a.prio==='penting'?chip('Penting','gold'):chip('Normal','')}
              ${isExec ? `<button class="btn sm danger" data-act="deleteAnn:${esc(a.id)}" title="Hapus" style="padding:2px 8px;min-height:28px;font-size:11px">Hapus</button>` : ''}
            </div>
          </div>
          <div class="t-xs muted mt8">${esc(a.by)} · ${relDay(a.date)}</div>
        </div>`).join('')}</div>
      <button class="btn pri mt16" data-act="newAnn">${ic.megaphone}Buat pengumuman</button>
    </div>
  </div>`;
}

/* ============================================================
   PAGE: PROJECT HAUL & HARLAH PPBS — COMING SOON + COUNTDOWN
   ============================================================ */
function pgProjectHaul(){
  const targetDate = new Date('2027-02-01T00:00:00+07:00');
  const now = new Date();
  const diff = targetDate - now;
  const isPast = diff <= 0;
  const isOngoing = isPast && (now - targetDate) < (28 * 24 * 60 * 60 * 1000);

  let daysLeft = 0, hoursLeft = 0, minsLeft = 0, secsLeft = 0;
  if (!isPast) {
    daysLeft = Math.floor(diff / (1000*60*60*24));
    hoursLeft = Math.floor((diff / (1000*60*60)) % 24);
    minsLeft = Math.floor((diff / (1000*60)) % 60);
    secsLeft = Math.floor((diff / 1000) % 60);
  }

  return `<div class="page">
    <div class="haul-coming-wrap">
      <div class="haul-badge"><i class="fa-solid fa-mosque"></i>Pesantren Progresif Bumi Shalawat</div>
      <h1 class="haul-title">Project Haul &amp; Harlah PPBS</h1>
      <p class="haul-subtitle">${isPast ? (isOngoing ? 'Rangkaian Haul &amp; Harlah sedang berlangsung.' : 'Rangkaian Haul &amp; Harlah telah berlangsung.') : 'Coming Soon'}</p>

      ${!isPast ? `
      <div class="haul-countdown" id="haulCountdown">
        <div class="haul-cd-box"><span class="cd-num" id="haulDays">${String(daysLeft).padStart(2,'0')}</span><span class="cd-lbl">Hari</span></div>
        <div class="haul-cd-box"><span class="cd-num" id="haulHours">${String(hoursLeft).padStart(2,'0')}</span><span class="cd-lbl">Jam</span></div>
        <div class="haul-cd-box"><span class="cd-num" id="haulMins">${String(minsLeft).padStart(2,'0')}</span><span class="cd-lbl">Menit</span></div>
        <div class="haul-cd-box"><span class="cd-num" id="haulSecs">${String(secsLeft).padStart(2,'0')}</span><span class="cd-lbl">Detik</span></div>
      </div>` : ''}

      <div class="haul-info-card">
        <p><i class="fa-solid fa-calendar-days" style="margin-right:6px;color:var(--ptv-green,#0e4f40)"></i>Rangkaian acara Haul &amp; Harlah akan berlangsung pada bulan <b>Januari–Februari 2027</b>.</p>
        <p class="hint"><i class="fa-solid fa-circle-info" style="margin-right:4px"></i>Persiapkan diri. Informasi rangkaian acara akan diumumkan secara bertahap.</p>
      </div>
    </div>
  </div>`;
}

/* Haul countdown live ticker — started after render, cleared on nav */
let _haulCountdownTimer = null;
function startHaulCountdown(){
  if(_haulCountdownTimer) clearInterval(_haulCountdownTimer);
  const target = new Date('2027-02-01T00:00:00+07:00').getTime();
  _haulCountdownTimer = setInterval(()=>{
    const now = Date.now();
    const diff = target - now;
    if(diff <= 0){
      clearInterval(_haulCountdownTimer);
      _haulCountdownTimer = null;
      const wrap = document.getElementById('haulCountdown');
      if(wrap) wrap.remove();
      return;
    }
    const d = Math.floor(diff/(1000*60*60*24));
    const h = Math.floor((diff/(1000*60*60))%24);
    const m = Math.floor((diff/(1000*60))%60);
    const s = Math.floor((diff/1000)%60);
    const pad = n => String(n).padStart(2,'0');
    const eD = document.getElementById('haulDays');
    const eH = document.getElementById('haulHours');
    const eM = document.getElementById('haulMins');
    const eS = document.getElementById('haulSecs');
    if(eD) eD.textContent = pad(d);
    if(eH) eH.textContent = pad(h);
    if(eM) eM.textContent = pad(m);
    if(eS) eS.textContent = pad(s);
  }, 1000);
}

