/* ============================================================
   FORMS (quick actions & multi-select loan selector)
   ============================================================ */
const availableItems = ()=>(DB.inventory||[]).filter(x=>x.status==='Tersedia');
const eventOptions = ()=>(DB.events||[]).filter(e=>e.status!=='Selesai');

function field(label,inner,hint){
  return `<div class="field" style="margin-bottom:12px"><label>${label}</label>${inner}${hint?`<span class="hint">${hint}</span>`:''}</div>`;
}
function selectOf(id,opts,ph){
  return `<select class="input" id="${id}">${ph?`<option value="">${ph}</option>`:''}${opts.map(o=>`<option value="${o[0]}">${esc(o[1])}</option>`).join('')}</select>`;
}
const uploadBox = `<button class="upload" data-act="fakeUpload">${ic.photo}<span>Ketuk untuk menambah foto</span></button>`;

function normalizeInventoryCategory(cat) {
  if (!cat) return 'Lainnya';
  let c = String(cat).trim();
  c = c.replace(/\s*\/\s*/g, ' / ');
  const lower = c.toLowerCase();
  if (lower === 'smartphone / tablet' || lower === 'smartphone/tablet' || lower === 'hp / tablet' || lower === 'hp/tablet' || lower === 'tablet / smartphone') {
    return 'Smartphone / Tablet';
  }
  if (lower === 'komputer / laptop' || lower === 'komputer/laptop' || lower === 'laptop / komputer' || lower === 'pc / laptop' || lower === 'laptop') {
    return 'Komputer / Laptop';
  }
  if (lower === 'kamera' || lower === 'camera') return 'Kamera';
  if (lower === 'lensa' || lower === 'lens') return 'Lensa';
  if (lower === 'audio' || lower === 'mic' || lower === 'microphone' || lower === 'sound') return 'Audio';
  if (lower === 'lighting' || lower === 'lampu' || lower === 'lampu / lighting') return 'Lighting';
  if (lower === 'tripod' || lower === 'tripod / rig' || lower === 'tripod/rig' || lower === 'rig / tripod' || lower === 'gimbal / stabilizer') return 'Tripod & Rig';
  if (lower === 'baterai' || lower === 'battery' || lower === 'batere' || lower === 'baterai & power') return 'Baterai & Power';
  if (lower === 'baterai' || lower === 'battery' || lower === 'batere' || lower === 'baterai & power') return 'Baterai & Power';
  if (lower === 'kabel' || lower === 'kabel & adapter' || lower === 'kabel / adapter' || lower === 'kabel/adapter' || lower === 'adapter') return 'Kabel & Adapter';
  if (lower === 'streaming / live' || lower === 'streaming/live' || lower === 'broadcast' || lower === 'streaming') return 'Streaming / Live';
  return c.charAt(0).toUpperCase() + c.slice(1);
}

// Loan multi-select state: Map of "assetId_unitNo" => { key, assetId, unitNo, unitCode, unitName, assetName, assetThumb, invCode }
let loanBasket = new Map();

// Local storage retention (2 days = 172,800,000 ms)
const PTV_LOAN_BASKET_STORAGE_KEY = 'ptv_loan_basket_v2';
const PTV_LOAN_BASKET_TTL_MS = 2 * 24 * 60 * 60 * 1000;

function saveLoanBasketToStorage(){
  try {
    const list = [];
    loanBasket.forEach((item, key) => {
      list.push({
        key: key,
        assetId: String(item.assetId),
        unitNo: Number(item.unitNo),
        unitCode: String(item.unitCode || ''),
        unitName: String(item.unitName || ''),
        assetName: String(item.assetName || ''),
        invCode: String(item.invCode || '')
      });
    });
    localStorage.setItem(PTV_LOAN_BASKET_STORAGE_KEY, JSON.stringify({
      timestamp: Date.now(),
      items: list
    }));
  } catch(e){
    console.warn('Gagal menyimpan daftar pinjaman:', e);
  }
}

function loadLoanBasketFromStorage(){
  try {
    const raw = localStorage.getItem(PTV_LOAN_BASKET_STORAGE_KEY);
    if(!raw) return;
    const data = JSON.parse(raw);
    if(!data || !data.timestamp || !Array.isArray(data.items)) return;

    // Kadaluarsa setelah 2 hari
    if(Date.now() - data.timestamp > PTV_LOAN_BASKET_TTL_MS){
      localStorage.removeItem(PTV_LOAN_BASKET_STORAGE_KEY);
      loanBasket.clear();
      return;
    }

    loanBasket.clear();
    data.items.forEach(it => {
      const asset = itemById(String(it.assetId));
      if(asset){
        const s = getAssetUnitSummary(asset);
        const uO = s.units.find(u => Number(u.unit) === Number(it.unitNo));
        if(uO && uO.status === 'Tersedia'){
          const invCode = asset.code || ('INV-' + String(asset.id).padStart(3,'0'));
          loanBasket.set(it.key, {
            key: it.key,
            assetId: String(asset.id),
            unitNo: Number(it.unitNo),
            unitCode: it.unitCode || uO.code || getUnitBarcode(invCode, it.unitNo),
            unitName: it.unitName || getUnitDisplayName(uO, it.unitNo),
            assetName: asset.name,
            assetThumb: asset,
            invCode: invCode
          });
        }
      }
    });
  } catch(e){
    console.warn('Gagal memuat daftar pinjaman:', e);
  }
}
try { loadLoanBasketFromStorage(); } catch(e){}

function toggleUnitInLoanBasket(assetId, unitNo){
  const it = itemById(String(assetId));
  if(!it) return;
  const s = getAssetUnitSummary(it);
  const uNo = parseInt(unitNo || 1, 10);
  const uO = s.units.find(u => Number(u.unit) === uNo);
  const uDisplayName = getUnitDisplayName(uO, uNo);
  if(!uO || uO.status !== 'Tersedia'){
    toast(`${uDisplayName} sedang tidak tersedia untuk dipinjam.`, 'alert');
    return;
  }
  const invCode = it.code || ('INV-' + String(it.id).padStart(3, '0'));
  const uKey = `${it.id}_${uNo}`;

  if(loanBasket.has(uKey)){
    loanBasket.delete(uKey);
    toast(`${uDisplayName} "${it.name}" dikeluarkan dari daftar pinjaman.`, 'info');
  } else {
    loanBasket.set(uKey, {
      key: uKey,
      assetId: String(it.id),
      unitNo: uNo,
      unitCode: uO.code || getUnitBarcode(invCode, uNo),
      unitName: uDisplayName,
      assetName: it.name,
      assetThumb: it,
      invCode: invCode
    });
    toast(`${uDisplayName} "${it.name}" ditambahkan ke daftar pinjaman.`, 'check');
  }
  haptic(20);
  saveLoanBasketToStorage();
  smartUpdateFilterView('inventaris');
  if(state.route.page === 'alatDetail'){
    render();
  }
}

function renderUnitPickerItemsHTML(it, mode){
  const s = getAssetUnitSummary(it);
  const isDirectLoan = (mode === 'direct_loan');

  return s.units.map(u => {
    const isAvail = (u.status === 'Tersedia');
    const isDamaged = (u.status === 'Rusak');
    const isBorrowed = (u.status === 'Dipinjam');
    const uKey = `${it.id}_${u.unit}`;
    const inBasket = loanBasket.has(uKey);

    let statusBadge = '';
    if(isAvail) statusBadge = `<span class="chip ok" style="font-size:10.5px;font-weight:700;"><i class="fa-solid fa-circle-check" style="font-size:9.5px;margin-right:3px;"></i>Tersedia</span>`;
    else if(isBorrowed) statusBadge = `<span class="chip warn" style="font-size:10.5px;font-weight:700;"><i class="fa-solid fa-user-clock" style="font-size:9.5px;margin-right:3px;"></i>Dipinjam</span>`;
    else if(isDamaged) statusBadge = `<span class="chip dang" style="font-size:10.5px;font-weight:700;"><i class="fa-solid fa-triangle-exclamation" style="font-size:9.5px;margin-right:3px;"></i>Rusak</span>`;
    else statusBadge = `<span class="chip" style="font-size:10.5px;font-weight:700;">${esc(u.status)}</span>`;

    return `
      <div class="unit-picker-item" style="display:flex;align-items:center;justify-content:space-between;padding:12px 14px;border:1.5px solid ${inBasket ? '#3b82f6' : '#e2e8f0'};border-radius:12px;background:${inBasket ? '#eff6ff' : '#ffffff'};transition:all 0.15s ease;gap:12px;">
        <div style="display:flex;align-items:center;gap:12px;min-width:0;flex:1;">
          <div style="width:38px;height:38px;border-radius:10px;background:${isAvail ? '#e0f2fe' : '#f1f5f9'};color:${isAvail ? '#0284c7' : '#64748b'};display:flex;align-items:center;justify-content:center;font-weight:800;font-size:13px;flex-shrink:0;">
            #${u.unit}
          </div>
          <div style="min-width:0;flex:1;">
            <div style="display:flex;align-items:center;gap:6px;margin-bottom:3px;">
              ${renderUnitBranding(u, { size: 'xs' })}
            </div>
            <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">
              <span style="font-weight:750;font-size:13.5px;color:#0f172a;">${esc(getUnitDisplayName(u, u.unit))}</span>
              <span class="chip blue" style="font-size:10.5px;font-weight:700;padding:1px 6px;">${esc(u.code)}</span>
              ${statusBadge}
            </div>
            <div style="font-size:11.5px;color:#64748b;margin-top:2px;display:flex;align-items:center;gap:10px;flex-wrap:wrap;">
              <span>Kondisi: <b style="color:#334155">${esc(u.cond || 'Baik')}</b></span>
              ${isBorrowed && u.borrower ? `<span style="color:#d97706"><i class="fa-solid fa-user" style="font-size:10px;margin-right:2px;"></i>${esc(u.borrower)}</span>` : ''}
            </div>
          </div>
        </div>
        <div style="flex-shrink:0;">
          ${isAvail ? (
            isDirectLoan ? `
              <button type="button" class="btn sm pri" data-act="confirmDirectLoanUnit:${it.id}:${u.unit}" style="font-size:12px;font-weight:700;padding:6px 14px;min-height:34px;border-radius:8px;box-shadow:0 2px 6px rgba(18,115,230,0.25);cursor:pointer;white-space:nowrap;">
                Pinjam Unit Ini <i class="fa-solid fa-arrow-right" style="margin-left:4px;"></i>
              </button>
            ` : `
              <button type="button" class="btn sm ${inBasket ? 'pri' : ''}" data-act="toggleUnitBasket:${it.id}:${u.unit}" style="font-size:12px;font-weight:700;padding:6px 14px;min-height:34px;border-radius:8px;cursor:pointer;white-space:nowrap;${inBasket ? 'background:#1d4ed8;border-color:#1d4ed8;color:#fff;' : 'background:#f8fafc;border:1.5px solid #cbd5e1;color:#1e293b;'}">
                ${inBasket ? '<i class="fa-solid fa-check" style="margin-right:4px;"></i> Terpilih' : '<i class="fa-solid fa-plus" style="margin-right:4px;"></i> Pilih Unit'}
              </button>
            `
          ) : `
            <span style="font-size:11.5px;color:#94a3b8;font-weight:600;padding:4px 8px;background:#f8fafc;border-radius:6px;">Tidak Tersedia</span>
          `}
        </div>
      </div>
    `;
  }).join('');
}

function openUnitPickerModal(assetId, mode = 'basket'){
  const it = itemById(String(assetId));
  if(!it) return;
  const s = getAssetUnitSummary(it);
  const invCode = it.code || ('INV-' + String(it.id).padStart(3, '0'));
  const isDirectLoan = (mode === 'direct_loan');

  if(s.available === 0){
    toast(`Semua unit "${it.name}" sedang tidak tersedia.`, 'alert');
    return;
  }

  // Jika hanya memiliki 1 unit fisik:
  if(s.units.length === 1){
    const onlyUnit = s.units[0];
    if(isDirectLoan){
      openLoanModal(it.id, onlyUnit.unit);
    } else {
      toggleUnitInLoanBasket(it.id, onlyUnit.unit);
    }
    return;
  }

  const modalTitle = isDirectLoan ? 'Pilih Unit untuk Dipinjam' : 'Pilih Unit untuk Daftar Pinjaman';

  const bodyHtml = `
    <div style="display:flex;flex-direction:column;gap:14px;">
      <div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:12px;padding:12px 14px;display:flex;align-items:center;justify-content:space-between;gap:10px;">
        <div>
          <div style="font-weight:800;font-size:14.5px;color:#0f172a;">${esc(it.name)}</div>
          <div style="font-size:12px;color:#64748b;margin-top:2px;">
            ${s.available} dari ${s.total} unit fisik siap dipinjam
          </div>
        </div>
        <span class="chip blue" style="font-size:11.5px;font-weight:750;padding:4px 10px;">${esc(invCode)}</span>
      </div>

      <div style="font-size:12px;font-weight:700;color:#475569;text-transform:uppercase;letter-spacing:0.04em;">
        ${isDirectLoan ? 'Silakan tentukan unit yang ingin kamu pinjam:' : 'Pilih satu atau beberapa unit yang ingin dimasukkan ke daftar pinjaman:'}
      </div>

      <div id="unitPickerListWrap" style="display:flex;flex-direction:column;gap:8px;max-height:380px;overflow-y:auto;padding-right:2px;">
        ${renderUnitPickerItemsHTML(it, mode)}
      </div>
    </div>
  `;

  openSheet(modalTitle, bodyHtml, {
    foot: isDirectLoan ? '' : `
      <div style="display:flex;align-items:center;justify-content:space-between;width:100%;gap:10px;flex-wrap:wrap;">
        <span style="font-size:12.5px;font-weight:700;color:#1e293b;" id="unitPickerBasketCount">
          ${loanBasket.size} unit di daftar pinjaman
        </span>
        <div style="display:flex;align-items:center;gap:8px;">
          <button type="button" class="btn sm" data-act="closeSheet" style="min-height:36px;padding:0 14px;border-radius:8px;font-weight:650;">
            Selesai
          </button>
          <button type="button" class="btn sm pri" data-act="openDaftarPinjamanFromPicker" style="min-height:36px;padding:0 16px;border-radius:8px;font-weight:750;box-shadow:0 2px 8px rgba(18,115,230,0.25);">
            Lihat Daftar Pinjaman <i class="fa-solid fa-arrow-right" style="margin-left:4px;"></i>
          </button>
        </div>
      </div>
    `
  });
}

function openLoanModal(presetAssetId, presetUnit){
  loadLoanBasketFromStorage();
  let loanSearchQuery = '';
  let activeCat = 'Semua';
  const expandedCategories = new Set(); // DEFAULT: ALL COLLAPSED
  const expandedAssets = new Set();     // DEFAULT: ALL COLLAPSED
  let mobileDrawerOpen = false;

  // If preset asset + unit provided, add to basket and expand
  if(presetAssetId && presetUnit){
    const it = itemById(String(presetAssetId));
    if(it){
      const s = getAssetUnitSummary(it);
      const uO = s.units.find(u => Number(u.unit) === Number(presetUnit));
      if(uO && uO.status === 'Tersedia'){
        const invCode = it.code || ('INV-' + String(it.id).padStart(3,'0'));
        const uKey = `${it.id}_${presetUnit}`;
        loanBasket.set(uKey, {
          key: uKey,
          assetId: String(it.id),
          unitNo: Number(presetUnit),
          unitCode: uO.code || getUnitBarcode(invCode, presetUnit),
          unitName: getUnitDisplayName(uO, presetUnit),
          assetName: it.name,
          assetThumb: it,
          invCode: invCode
        });
        const cNorm = normalizeInventoryCategory(it.cat);
        expandedCategories.add(cNorm);
        expandedAssets.add(String(it.id));
        saveLoanBasketToStorage();
      }
    }
  } else if(presetAssetId){
    const it = itemById(String(presetAssetId));
    if(it){
      const cNorm = normalizeInventoryCategory(it.cat);
      expandedCategories.add(cNorm);
      expandedAssets.add(String(it.id));
    }
  }

  // Preserve existing loanBasket: validate each unit is still Tersedia, and auto-expand categories & assets
  let basketMutated = false;
  loanBasket.forEach((item, key) => {
    const it = itemById(String(item.assetId));
    if(!it){
      loanBasket.delete(key);
      basketMutated = true;
      return;
    }
    const s = getAssetUnitSummary(it);
    const uO = s.units.find(u => Number(u.unit) === Number(item.unitNo));
    if(!uO || uO.status !== 'Tersedia'){
      loanBasket.delete(key);
      basketMutated = true;
      return;
    }
    const cNorm = normalizeInventoryCategory(it.cat);
    expandedCategories.add(cNorm);
    expandedAssets.add(String(it.id));
  });
  if(basketMutated) saveLoanBasketToStorage();

  const dateIn = (id,val) => `<input class="input" type="date" id="${id}" value="${val||iso(today)}" style="font-size:12.5px;padding:6px 10px;min-height:36px">`;
  const purposeChips = ['Dokumentasi','Latihan shooting','Konten PTV','Kegiatan asrama','Persiapan acara'];

  // Collect dynamic normalized categories from DB.inventory
  const dbCats = Array.from(new Set((DB.inventory || []).map(x => normalizeInventoryCategory(x.cat)).filter(Boolean)));
  const catOrder = ['Kamera', 'Lensa', 'Tripod & Rig', 'Tripod', 'Baterai & Power', 'Audio', 'Lighting', 'Smartphone / Tablet', 'Komputer / Laptop', 'Kabel & Adapter', 'Streaming / Live', 'Lainnya'];
  dbCats.sort((a,b) => {
    const idxA = catOrder.indexOf(a);
    const idxB = catOrder.indexOf(b);
    return (idxA !== -1 ? idxA : 99) - (idxB !== -1 ? idxB : 99);
  });
  const catList = ['Semua', ...dbCats];

  /* ---- Render Category Filter Chips ---- */
  const renderCategoryChips = () => {
    return catList.map(c => `
      <button type="button" class="fchip ${activeCat === c ? 'on' : ''}" data-loan-cat="${esc(c)}" style="font-size:11.5px;padding:3px 10px;white-space:nowrap;font-weight:600">
        ${esc(c)}
      </button>
    `).join('');
  };

  /* ---- Filter and Group Inventory Items ---- */
  const getFilteredCategories = () => {
    const q = loanSearchQuery.toLowerCase().trim();
    let allItems = (DB.inventory || []).slice();

    // Group items into normalized categories
    const catMap = new Map();
    allItems.forEach(x => {
      const cNorm = normalizeInventoryCategory(x.cat);
      if(!catMap.has(cNorm)) catMap.set(cNorm, []);
      catMap.get(cNorm).push(x);
    });

    // If active category selected (other than 'Semua')
    let resultCategories = [];
    if(activeCat !== 'Semua'){
      if(catMap.has(activeCat)){
        resultCategories = [[activeCat, catMap.get(activeCat)]];
      }
    } else {
      resultCategories = Array.from(catMap.entries());
      resultCategories.sort((a,b) => {
        const idxA = catOrder.indexOf(a[0]);
        const idxB = catOrder.indexOf(b[0]);
        return (idxA !== -1 ? idxA : 99) - (idxB !== -1 ? idxB : 99);
      });
    }

    if(q){
      // Filter items matching query and auto expand
      const filtered = [];
      resultCategories.forEach(([catName, items]) => {
        const matchingItems = items.filter(x => {
          const nameMatch = (x.name || '').toLowerCase().includes(q);
          const codeMatch = (x.code || '').toLowerCase().includes(q);
          const brandMatch = (x.brand || '').toLowerCase().includes(q);
          const modelMatch = (x.model || '').toLowerCase().includes(q);
          
          // Search inside unit identities & unit codes!
          const summary = getAssetUnitSummary(x);
          const unitMatch = summary.units.some(u => 
            (u.name || '').toLowerCase().includes(q) || 
            (u.code || '').toLowerCase().includes(q)
          );

          if(nameMatch || codeMatch || brandMatch || modelMatch || unitMatch){
            expandedAssets.add(String(x.id));
            return true;
          }
          return false;
        });

        if(matchingItems.length > 0){
          expandedCategories.add(catName);
          filtered.push([catName, matchingItems]);
        }
      });
      return filtered;
    }

    return resultCategories;
  };

  /* ---- Render Inventory List with Hierarchical Collapsible Categories & Assets ---- */
  const renderInventoryPicker = () => {
    const categories = getFilteredCategories();
    if(!categories.length){
      return `
        <div style="text-align:center;padding:30px 15px;background:var(--surface);border-radius:var(--r-m);border:1px dashed var(--line-2)">
          <i class="fa-solid fa-box-open" style="font-size:26px;color:var(--muted);opacity:0.6;margin-bottom:8px;display:block"></i>
          <p class="t-sm muted" style="margin:0;font-weight:600">Tidak ada inventaris yang cocok.</p>
          <span class="t-xs muted">Coba kata kunci lain atau pilih filter kategori "Semua".</span>
        </div>
      `;
    }

    const q = loanSearchQuery.toLowerCase().trim();

    return categories.map(([catName, items]) => {
      const isCatExp = expandedCategories.has(catName) || (activeCat !== 'Semua');
      const catCount = items.length;

      // Count total available and selected across this category
      let totalCatAvail = 0;
      let totalCatSelected = 0;
      items.forEach(it => {
        const s = getAssetUnitSummary(it);
        totalCatAvail += s.available;
        s.units.forEach(u => {
          if(loanBasket.has(`${it.id}_${u.unit}`)) totalCatSelected++;
        });
      });
      const hasCatSelected = totalCatSelected > 0;

      const catIconClass = catIcon(catName);
      const catIconSvg = ic[catIconClass] || ic.box;

      return `
        <div class="loan-cat-card ${isCatExp ? 'expanded' : ''} ${hasCatSelected ? 'has-selected' : ''}" data-cat-name="${esc(catName)}">
          <!-- 1. Category Accordion Header -->
          <div class="loan-cat-head" data-toggle-cat="${esc(catName)}">
            <i class="fa-solid ${isCatExp ? 'fa-chevron-down' : 'fa-chevron-right'}" style="font-size:12px;color:var(--ink3);width:14px;flex-shrink:0;transition:transform .15s"></i>
            <span style="display:inline-flex;align-items:center;color:var(--b-600);flex-shrink:0">${catIconSvg}</span>
            <div style="flex:1;min-width:0">
              <span class="loan-cat-title-text">
                ${esc(catName)} <span style="font-size:11px;font-weight:500;color:var(--muted)">(${catCount})</span>
              </span>
            </div>
            <div style="display:flex;align-items:center;gap:6px;flex-shrink:0">
              <span style="font-size:11px;font-weight:550;color:${totalCatAvail > 0 ? 'var(--ok)' : 'var(--warn)'}">
                ${totalCatAvail} tersedia
              </span>
              ${hasCatSelected ? `
                <span class="chip blue" style="font-size:10.5px;font-weight:600;padding:2px 7px;background:#dbeafe;color:#1e40af;border:1px solid #bfdbfe">
                  <i class="fa-solid fa-check" style="margin-right:3px;font-size:9.5px"></i>${totalCatSelected} dipilih
                </span>
              ` : ''}
            </div>
          </div>

          <!-- 2. Category Body (List of Collapsible Asset Cards) -->
          ${isCatExp ? `
            <div class="loan-cat-body">
              ${items.length === 0 ? `
                <div class="t-xs muted" style="padding:10px 14px;text-align:center">Belum ada inventaris pada kategori ini.</div>
              ` : items.map(x => {
                const isAssetExp = expandedAssets.has(String(x.id));
                const summary = getAssetUnitSummary(x);
                const invCode = x.code || ('INV-' + String(x.id).slice(0,5).toUpperCase());
                
                const selectedUnitsThisAsset = summary.units.filter(u => loanBasket.has(`${x.id}_${u.unit}`));
                const selectedCount = selectedUnitsThisAsset.length;
                const hasSelected = selectedCount > 0;

                return `
                  <div class="loan-asset-card ${isAssetExp ? 'expanded' : ''} ${hasSelected ? 'has-selected' : ''}" data-asset-id="${esc(x.id)}">
                    <!-- Inventaris Accordion Header -->
                    <div class="loan-asset-head" data-toggle-asset="${esc(x.id)}">
                      <i class="fa-solid ${isAssetExp ? 'fa-chevron-down' : 'fa-chevron-right'}" style="font-size:11px;color:var(--ink3);width:14px;flex-shrink:0;transition:transform .15s"></i>
                      ${itemThumbHTML(x, 'sm')}
                      <div style="flex:1;min-width:0">
                        <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap">
                          <span style="font-size:13px;font-weight:550;color:var(--ink);line-height:1.25">${esc(x.name)}</span>
                          <span style="font-size:10.5px;color:var(--ink3);font-family:monospace;background:var(--bg-2);padding:1px 5px;border-radius:4px;border:1px solid var(--line-2)">${esc(invCode)}</span>
                        </div>
                        <div style="font-size:11px;color:var(--ink3);margin-top:2px;display:flex;align-items:center;gap:6px;flex-wrap:wrap">
                          <span>${summary.total} Unit</span>
                          <span>&bull;</span>
                          <span style="font-weight:550;color:${summary.available > 0 ? 'var(--ok)' : 'var(--dang)'}">${summary.available} Tersedia</span>
                          ${x.loc ? `<span>&bull;</span><span>${esc(x.loc)}</span>` : ''}
                        </div>
                      </div>
                      <div style="display:flex;align-items:center;gap:6px;flex-shrink:0">
                        ${hasSelected ? `
                          <span class="chip blue" style="font-size:10.5px;font-weight:600;padding:2px 7px;background:#dbeafe;color:#1e40af;border:1px solid #bfdbfe">
                            <i class="fa-solid fa-check" style="margin-right:3px;font-size:9.5px"></i>${selectedCount} Dipilih
                          </span>
                        ` : ''}
                      </div>
                    </div>

                    <!-- 3. Physical Units Checklist (Shown when asset is expanded) -->
                    ${isAssetExp ? `
                      <div class="loan-units-container">
                        ${summary.units.map(u => {
                          const key = `${x.id}_${u.unit}`;
                          const isChecked = loanBasket.has(key);
                          const isAvail = u.status === 'Tersedia';
                          const uName = getUnitDisplayName(u, u.unit);

                          const isMatch = q && ((u.name||'').toLowerCase().includes(q) || (u.code||'').toLowerCase().includes(q));

                          let chipStyle = 'background:#dcfce7;color:#166534;border:1px solid #bbf7d0';
                          let chipIcon = '<i class="fa-regular fa-circle-check" style="margin-right:3px"></i>';
                          if(u.status === 'Dipinjam') {
                            chipStyle = 'background:#e0e7ff;color:#3730a3;border:1px solid #c7d2fe';
                            chipIcon = '<i class="fa-solid fa-user-clock" style="margin-right:3px"></i>';
                          } else if(u.status === 'Rusak') {
                            chipStyle = 'background:#fee2e2;color:#991b1b;border:1px solid #fecaca';
                            chipIcon = '<i class="fa-solid fa-triangle-exclamation" style="margin-right:3px"></i>';
                          } else if(u.status === 'Butuh Servis') {
                            chipStyle = 'background:#fef3c7;color:#92400e;border:1px solid #fde68a';
                            chipIcon = '<i class="fa-solid fa-wrench" style="margin-right:3px"></i>';
                          } else if(u.status === 'Hilang') {
                            chipStyle = 'background:#f1f5f9;color:#475569;border:1px solid #cbd5e1';
                            chipIcon = '<i class="fa-solid fa-circle-question" style="margin-right:3px"></i>';
                          }

                          const unitInputId = `loan_unit_${x.id}_${u.unit}`;
                          return `
                            <label class="loan-unit-item ${isChecked ? 'selected' : ''} ${!isAvail ? 'disabled' : ''} ${isMatch ? 'match-highlight' : ''}" for="${unitInputId}" data-unit-key="${key}" title="${!isAvail ? `Unit tidak dapat dipilih: status ${u.status}` : `Klik untuk memilih ${uName}`}">
                              <input type="checkbox" id="${unitInputId}" class="loan-unit-checkbox" data-loan-unit-toggle="${key}" value="${key}" ${isChecked ? 'checked' : ''} ${!isAvail ? 'disabled' : ''} tabindex="-1">
                              <div class="loan-unit-info">
                                <div style="display:flex;align-items:center;gap:6px;margin-bottom:2px;">
                                  ${renderUnitBranding(u, { size: 'xs' })}
                                </div>
                                <span class="loan-unit-name">${esc(uName)}</span>
                                <span class="loan-unit-code">${esc(u.code)}</span>
                              </div>
                              <span class="chip" style="font-size:10px;padding:2px 7px;font-weight:550;margin-left:auto;flex-shrink:0;${chipStyle}">
                                ${chipIcon}${esc(u.status)}${u.borrower ? ` (${esc(u.borrower)})` : ''}
                              </span>
                            </label>
                          `;
                        }).join('')}
                      </div>
                    ` : ''}
                  </div>
                `;
              }).join('')}
            </div>
          ` : ''}
        </div>
      `;
    }).join('');
  };

  /* ---- Render Form Body inside Selected Panel (Used in both Desktop Panel & Mobile Drawer) ---- */
  const renderFormFields = () => {
    return `
      <div style="border-top:1px solid var(--line-2);padding-top:10px;margin-top:6px">
        <div class="field" style="margin-bottom:9px">
          <label style="font-weight:550;font-size:12px;color:var(--ink);display:flex;align-items:center;gap:4px">
            Keperluan Peminjaman <span style="color:#ef4444">*</span>
          </label>
          <input class="input" id="f_purpose" placeholder="Contoh: Dokumentasi Syamail 2026, Konten PTV..." required style="font-size:12.5px;padding:6px 10px;min-height:36px">
          <div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:5px">
            ${purposeChips.map(p=>`<button type="button" class="fchip" data-loan-preset-purpose="${esc(p)}" style="font-size:10.5px;padding:2px 7px;font-weight:500">${esc(p)}</button>`).join('')}
          </div>
        </div>

        <div class="grid-2" style="gap:8px;margin-bottom:9px">
          ${field('Tanggal Ambil', dateIn('f_out'))}
          ${field('Rencana Kembali', dateIn('f_due', dOff(2)))}
        </div>

        <div class="field" style="margin-bottom:9px">
          ${field('Terkait Acara (Opsional)', selectOf('f_event', eventOptions().map(e=>[e.id,e.name]),'Tidak terkait acara'))}
        </div>

        <div class="field" style="margin-bottom:12px">
          <label style="font-weight:550;font-size:12px;color:var(--ink2)">Catatan Tambahan (Opsional)</label>
          <input class="input" id="f_notes" placeholder="Catatan kondisi, kelengkapan, dll..." style="font-size:12px;padding:5px 9px;min-height:34px">
        </div>

        <button type="button" class="btn block pri" data-act="submitMultiLoan" id="btnSubmitLoan" ${loanBasket.size === 0 ? 'disabled' : ''} style="font-weight:600;font-size:13px;padding:10px 14px;min-height:42px;display:flex;align-items:center;justify-content:center;gap:7px;border-radius:var(--r-m);box-shadow:var(--shadow-s)">
          <i class="fa-solid fa-paper-plane" style="font-size:12px"></i>
          <span>${loanBasket.size > 0 ? `Ajukan Peminjaman (${loanBasket.size} Unit)` : 'Ajukan Peminjaman'}</span>
        </button>
      </div>
    `;
  };

  /* ---- Render Right Column ("Alat yang Dipilih" Panel) ---- */
  const renderSelectedPanel = () => {
    const groupedSelected = new Map();
    loanBasket.forEach(item => {
      if(!groupedSelected.has(item.assetId)) groupedSelected.set(item.assetId, []);
      groupedSelected.get(item.assetId).push(item);
    });

    let selectedListHtml = '';
    if(loanBasket.size === 0){
      selectedListHtml = `
        <div style="padding:20px 14px;text-align:center;border:1.5px dashed var(--line-2);border-radius:var(--r-m);background:var(--bg-2)">
          <i class="fa-solid fa-boxes-stacked" style="font-size:22px;color:var(--muted);opacity:0.5;display:block;margin-bottom:6px"></i>
          <div style="font-size:12.5px;font-weight:550;color:var(--ink)">Belum ada unit dipilih</div>
          <div class="t-xs muted" style="margin-top:2px">Buka kategori dan centang unit fisik di sebelah kiri.</div>
        </div>
      `;
    } else {
      let blocks = '';
      groupedSelected.forEach((units, aid) => {
        const it = itemById(aid);
        blocks += `
          <div class="selected-asset-block">
            <div class="selected-asset-head">
              <i class="fa-solid fa-box" style="font-size:10.5px;color:var(--b-500);margin-right:4px"></i>
              <span>${esc(it?.name || units[0]?.assetName || 'Alat')}</span>
            </div>
            <div style="display:flex;flex-direction:column;gap:3px;padding-left:12px;border-left:2px solid var(--b-200);margin-left:2px">
              ${units.map(u => `
                <div class="selected-unit-tag">
                  <span style="color:var(--b-600);font-size:13px;line-height:1">&bull;</span>
                  <span style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;display:inline-flex;align-items:center;gap:4px;">
                    ${renderUnitBranding({ nama_unit: u.unitName }, { size: 'xs' })}
                    <span>${esc(u.unitName)}</span>
                    <span style="font-size:11px;color:var(--ink3);font-family:monospace;margin-left:3px">(${esc(u.unitCode)})</span>
                  </span>
                  <button type="button" class="btn-remove-unit" data-remove-unit="${esc(u.key)}" title="Hapus unit">&times;</button>
                </div>
              `).join('')}
            </div>
          </div>
        `;
      });
      selectedListHtml = `<div class="selected-items-scroll">${blocks}</div>`;
    }

    return `
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:4px">
        <span style="font-size:12px;font-weight:600;color:var(--b-700)">
          <i class="fa-solid fa-clipboard-check" style="margin-right:5px"></i>Alat yang Dipilih
        </span>
        <div style="display:flex;align-items:center;gap:6px">
          ${loanBasket.size > 0 ? `
            <button type="button" class="btn-clear-basket" data-clear-loan-basket style="font-size:10.5px;color:#ef4444;background:none;border:none;cursor:pointer;padding:2px 4px;font-weight:600;display:inline-flex;align-items:center;gap:3px;" title="Kosongkan Semua Pilihan">
              <i class="fa-solid fa-trash-can" style="font-size:10px"></i>Kosongkan
            </button>
          ` : ''}
          <span class="chip blue" style="font-size:11px;font-weight:600;padding:2px 8px">
            ${loanBasket.size} Unit Dipilih
          </span>
        </div>
      </div>

      ${selectedListHtml}
      ${renderFormFields()}
    `;
  };

  /* ---- Render Mobile Full Screen Panel Content ---- */
  const renderMobileDrawerContent = () => {
    return `
      <div class="loan-mobile-drawer-header">
        <button type="button" class="loan-mobile-back-btn" data-close-mobile-drawer aria-label="Kembali ke Daftar Alat">
          <i class="fa-solid fa-arrow-left" style="font-size:13.5px"></i>
          <span>Pilih Alat</span>
        </button>
        <div style="display:flex;align-items:center;gap:6px">
          ${loanBasket.size > 0 ? `
            <button type="button" class="btn-clear-basket" data-clear-loan-basket style="font-size:10.5px;color:#ef4444;background:none;border:none;cursor:pointer;padding:2px 4px;font-weight:600;display:inline-flex;align-items:center;gap:3px;" title="Kosongkan Semua Pilihan">
              <i class="fa-solid fa-trash-can" style="font-size:10px"></i>Kosongkan
            </button>
          ` : ''}
          <span class="chip blue" style="font-size:11.5px;font-weight:600;padding:3px 9px">
            ${loanBasket.size} Unit Dipilih
          </span>
          <button type="button" class="loan-mobile-close-all-btn" data-act="closeSheet" aria-label="Tutup Peminjaman">
            <i class="fa-solid fa-xmark" style="font-size:17px"></i>
          </button>
        </div>
      </div>
      <div class="loan-mobile-drawer-body">
        ${renderSelectedPanel()}
      </div>
    `;
  };

  const bodyHTML = `
    <div class="loan-picker-modal-root" id="loanPickerModalRoot">
      <div class="loan-picker-container">
        <!-- LEFT COLUMN: Inventory Picker & Hierarchical Accordions -->
        <div class="loan-picker-left">
          <div style="display:flex;align-items:center;gap:8px">
            <div class="searchbar" style="flex:1;margin:0">
              ${ic.search}
              <input id="loanGearSearch" placeholder="Cari nama alat, kode inventaris, identitas unit (Body A, Unit 1)..." autocomplete="off" value="${esc(loanSearchQuery)}" style="font-size:12.5px">
            </div>
            <button type="button" class="btn sm" data-act="scanForLoan" style="padding:4px 10px;min-height:36px;font-size:11.5px;font-weight:600;flex-shrink:0">
              ${ic.scan}Scan QR
            </button>
          </div>

          <!-- Dynamic Category Filter Chips -->
          <div class="loan-cat-chips-bar" id="loanCatChipsWrap">
            ${renderCategoryChips()}
          </div>

          <!-- Inventory Hierarchical Categories and Units Scrollable List -->
          <div class="loan-inventory-scroll" id="loanInventoryScrollWrap">
            ${renderInventoryPicker()}
          </div>
        </div>

        <!-- RIGHT COLUMN: Desktop Selected Items & Loan Form Panel -->
        <div class="loan-picker-right desktop-only-panel" id="loanSelectedPanelWrap">
          ${renderSelectedPanel()}
        </div>
      </div>

      <!-- MOBILE STICKY BOTTOM BAR -->
      <div class="loan-mobile-sticky-bar" id="loanMobileStickyBar" data-open-mobile-drawer>
        <span><i class="fa-solid fa-boxes-stacked" style="margin-right:7px"></i><span>${loanBasket.size} unit dipilih</span></span>
        <span style="display:inline-flex;align-items:center;gap:4px">Lihat &amp; Ajukan <i class="fa-solid fa-arrow-right" style="font-size:11px"></i></span>
      </div>

      <!-- MOBILE FULL BOTTOM SHEET DRAWER -->
      <div class="loan-mobile-drawer-overlay ${mobileDrawerOpen ? 'open' : ''}" id="loanMobileDrawerOverlay">
        <div class="loan-mobile-drawer-content" id="loanMobileDrawerContent">
          ${renderMobileDrawerContent()}
        </div>
      </div>
    </div>
  `;

  openSheet('Peminjaman Alat & Pemilihan Unit Fisik', bodyHTML, {
    wide: true,
    className: 'loan-picker-sheet-modal',
    onClose: () => { smartUpdateFilterView('inventaris'); },
    then: (sheetBody) => {
      const modalRoot      = $('#loanPickerModalRoot', sheetBody) || sheetBody;
      const searchIn       = $('#loanGearSearch', modalRoot);
      const chipsWrap      = $('#loanCatChipsWrap', modalRoot);
      const invScroll      = $('#loanInventoryScrollWrap', modalRoot);
      const rightWrap      = $('#loanSelectedPanelWrap', modalRoot);
      const stickyBar      = $('#loanMobileStickyBar', modalRoot);
      const drawerOverlay  = $('#loanMobileDrawerOverlay', modalRoot);
      const drawerContent  = $('#loanMobileDrawerContent', modalRoot);

      // Save previous purpose & dates when re-rendering
      let savedPurpose = '';
      let savedOut = '';
      let savedDue = '';
      let savedEvent = '';
      let savedNotes = '';

      const captureFormValues = () => {
        const pIn = modalRoot.querySelector('#f_purpose'); if(pIn) savedPurpose = pIn.value;
        const oIn = modalRoot.querySelector('#f_out'); if(oIn) savedOut = oIn.value;
        const dIn = modalRoot.querySelector('#f_due'); if(dIn) savedDue = dIn.value;
        const eIn = modalRoot.querySelector('#f_event'); if(eIn) savedEvent = eIn.value;
        const nIn = modalRoot.querySelector('#f_notes'); if(nIn) savedNotes = nIn.value;
      };

      const restoreFormValues = () => {
        const pIns = modalRoot.querySelectorAll('#f_purpose'); pIns.forEach(p => { if(savedPurpose) p.value = savedPurpose; });
        const oIns = modalRoot.querySelectorAll('#f_out'); oIns.forEach(o => { if(savedOut) o.value = savedOut; });
        const dIns = modalRoot.querySelectorAll('#f_due'); dIns.forEach(d => { if(savedDue) d.value = savedDue; });
        const eIns = modalRoot.querySelectorAll('#f_event'); eIns.forEach(e => { if(savedEvent) e.value = savedEvent; });
        const nIns = modalRoot.querySelectorAll('#f_notes'); nIns.forEach(n => { if(savedNotes) n.value = savedNotes; });
      };

      const refreshAll = () => {
        captureFormValues();
        const savedScroll = invScroll ? invScroll.scrollTop : 0;
        if(chipsWrap) chipsWrap.innerHTML = renderCategoryChips();
        if(invScroll) {
          invScroll.innerHTML = renderInventoryPicker();
          invScroll.scrollTop = savedScroll;
        }
        if(rightWrap) rightWrap.innerHTML = renderSelectedPanel();
        if(drawerContent) drawerContent.innerHTML = renderMobileDrawerContent();
        if(drawerOverlay) drawerOverlay.classList.toggle('open', mobileDrawerOpen);
        if(stickyBar) {
          stickyBar.innerHTML = `
            <span><i class="fa-solid fa-boxes-stacked" style="margin-right:7px"></i><b>${loanBasket.size} unit dipilih</b></span>
            <span style="display:inline-flex;align-items:center;gap:4px">Lihat &amp; Ajukan <i class="fa-solid fa-arrow-right" style="font-size:11px"></i></span>
          `;
        }
        restoreFormValues();
      };

      const refreshSelectionState = () => {
        captureFormValues();
        saveLoanBasketToStorage();
        const savedScroll = invScroll ? invScroll.scrollTop : 0;
        if(rightWrap) rightWrap.innerHTML = renderSelectedPanel();
        if(drawerContent) drawerContent.innerHTML = renderMobileDrawerContent();
        if(invScroll) {
          invScroll.innerHTML = renderInventoryPicker();
          invScroll.scrollTop = savedScroll;
        }
        if(drawerOverlay) drawerOverlay.classList.toggle('open', mobileDrawerOpen);
        if(stickyBar) {
          stickyBar.innerHTML = `
            <span><i class="fa-solid fa-boxes-stacked" style="margin-right:7px"></i><b>${loanBasket.size} unit dipilih</b></span>
            <span style="display:inline-flex;align-items:center;gap:4px">Lihat &amp; Ajukan <i class="fa-solid fa-arrow-right" style="font-size:11px"></i></span>
          `;
        }
        restoreFormValues();
      };

      // Realtime search
      if(searchIn){
        searchIn.addEventListener('input', () => {
          loanSearchQuery = searchIn.value;
          if(invScroll) invScroll.innerHTML = renderInventoryPicker();
        });
      }

      // Event delegation for clicks attached specifically to modalRoot
      modalRoot.addEventListener('click', (ev) => {
        // 0. Close entire sheet
        const closeSheetBtn = ev.target.closest('[data-act="closeSheet"]');
        if(closeSheetBtn){
          closeSheet();
          haptic(4);
          return;
        }

        // 1. Preset purpose chip
        const chip = ev.target.closest('[data-loan-preset-purpose]');
        if(chip){
          const pVal = chip.dataset.loanPresetPurpose;
          const pIns = modalRoot.querySelectorAll('#f_purpose');
          pIns.forEach(pIn => { pIn.value = pVal; pIn.focus(); });
          savedPurpose = pVal;
          haptic(6);
          return;
        }

        // 2. Category filter chip
        const catBtn = ev.target.closest('[data-loan-cat]');
        if(catBtn){
          activeCat = catBtn.dataset.loanCat || 'Semua';
          if(activeCat !== 'Semua'){
            expandedCategories.add(activeCat);
          }
          haptic(6);
          if(chipsWrap) chipsWrap.innerHTML = renderCategoryChips();
          if(invScroll){
            invScroll.scrollTop = 0;
            invScroll.innerHTML = renderInventoryPicker();
          }
          return;
        }

        // 3. Toggle Category Accordion
        const toggleCat = ev.target.closest('[data-toggle-cat]');
        if(toggleCat){
          const cName = toggleCat.dataset.toggleCat;
          if(expandedCategories.has(cName)){
            expandedCategories.delete(cName);
          } else {
            expandedCategories.add(cName);
          }
          haptic(4);
          if(invScroll){
            const savedScroll = invScroll.scrollTop;
            invScroll.innerHTML = renderInventoryPicker();
            invScroll.scrollTop = savedScroll;
          }
          return;
        }

        // 4. Toggle Inventaris / Asset Accordion
        const toggleAsset = ev.target.closest('[data-toggle-asset]');
        if(toggleAsset){
          const aid = String(toggleAsset.dataset.toggleAsset);
          if(expandedAssets.has(aid)){
            expandedAssets.delete(aid);
          } else {
            expandedAssets.add(aid);
          }
          haptic(4);
          if(invScroll){
            const savedScroll = invScroll.scrollTop;
            invScroll.innerHTML = renderInventoryPicker();
            invScroll.scrollTop = savedScroll;
          }
          return;
        }

        // 4.5. Clear all units from basket
        const clearBtn = ev.target.closest('[data-clear-loan-basket]');
        if(clearBtn){
          loanBasket.clear();
          haptic(10);
          refreshSelectionState();
          return;
        }

        // 5. Remove unit from basket
        const rmBtn = ev.target.closest('[data-remove-unit]');
        if(rmBtn){
          const uKey = rmBtn.dataset.removeUnit;
          loanBasket.delete(uKey);
          haptic(6);
          refreshSelectionState();
          return;
        }

        // 6. Toggle unit selection (Entire row is clickable & instant)
        const unitItem = ev.target.closest('[data-unit-key]');
        if(unitItem){
          ev.preventDefault();
          const uKey = unitItem.dataset.unitKey;
          const [aid, uNoStr] = uKey.split('_');
          const uNo = parseInt(uNoStr, 10);
          const it = itemById(aid);
          if(it){
            const s = getAssetUnitSummary(it);
            const uO = s.units.find(u => Number(u.unit) === Number(uNo));
            const uDisplayName = getUnitDisplayName(uO, uNo);
            if(unitItem.classList.contains('disabled') || !uO || uO.status !== 'Tersedia'){
              const uName = uDisplayName;
              const st = uO?.status || 'Tidak Tersedia';
              const borrower = uO?.borrower ? ` oleh ${uO.borrower}` : '';
              toast(`${uName} sedang ${st}${borrower} dan tidak dapat dipilih.`, 'info');
              haptic(2);
              return;
            }
            if(loanBasket.has(uKey)){
              loanBasket.delete(uKey);
            } else {
              const invCode = it.code || ('INV-' + String(it.id).padStart(3,'0'));
              loanBasket.set(uKey, {
                key: uKey,
                assetId: String(it.id),
                unitNo: uNo,
                unitCode: uO.code || getUnitBarcode(invCode, uNo),
                unitName: uDisplayName,
                assetName: it.name,
                assetThumb: it,
                invCode: invCode
              });
              expandedAssets.add(String(it.id));
            }
            haptic(6);
            refreshSelectionState();
          }
          return;
        }

        // 7. Open Mobile Drawer
        const openDrawerBtn = ev.target.closest('[data-open-mobile-drawer]');
        if(openDrawerBtn){
          mobileDrawerOpen = true;
          if(drawerOverlay) drawerOverlay.classList.add('open');
          haptic(6);
          return;
        }

        // 8. Close Mobile Drawer
        const closeDrawerBtn = ev.target.closest('[data-close-mobile-drawer]');
        if(closeDrawerBtn || ev.target === drawerOverlay){
          mobileDrawerOpen = false;
          if(drawerOverlay) drawerOverlay.classList.remove('open');
          haptic(4);
          return;
        }
      });
    }
  });

  // Keep loanActiveSelected pointing to last focused item (backward compat)
  loanActiveSelected = {
    get assetId(){ return presetAssetId || null; },
    get unitNo(){ return presetUnit || null; }
  };
}

let loanActiveSelected = { assetId: null, unitNo: null };

function submitMultiLoan(){
  if(!loanBasket || loanBasket.size === 0){
    toast('Pilih minimal satu unit alat terlebih dahulu.', 'info');
    return;
  }

  const purposeVal = ($('#f_purpose')?.value || '').trim();
  if(!purposeVal){
    toast('Keperluan peminjaman wajib diisi.', 'info');
    $('#f_purpose')?.focus();
    return;
  }

  const outVal   = $('#f_out')?.value  || iso(today);
  const dueVal   = $('#f_due')?.value  || dOff(2);
  const eventVal = $('#f_event')?.value || '';
  const notesVal = ($('#f_notes')?.value || '').trim();
  const tempTxnId = 'TXN-' + Date.now() + '-' + Math.random().toString(36).substring(2,7).toUpperCase();

  const equipmentIds = [];
  const unitsData    = [];
  const qtyMap       = {};

  loanBasket.forEach((v) => {
    if(!equipmentIds.includes(v.assetId)) equipmentIds.push(v.assetId);
    qtyMap[v.assetId] = (qtyMap[v.assetId] || 0) + 1;
    unitsData.push({
      assetId: v.assetId,
      unitNo: v.unitNo,
      unitCode: v.unitCode,
      unitName: v.unitName,
      assetName: v.assetName
    });
  });

  const submitBtn = document.querySelector('[data-act="submitMultiLoan"]') || $('#btn_submit_loan');
  const origBtnText = submitBtn ? submitBtn.innerHTML : '';
  if (submitBtn) {
    submitBtn.disabled = true;
    submitBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin" style="margin-right:6px"></i>Memproses Peminjaman...';
  }

  const firstEntry = unitsData[0];

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_pinjam');
  fd.append('borrower_name', ME.name);
  fd.append('purpose', purposeVal);
  fd.append('item_id', firstEntry?.assetId || '');
  fd.append('alat_id', firstEntry?.assetId || '');
  fd.append('unit_no', String(firstEntry?.unitNo || ''));
  fd.append('unit_code', firstEntry?.unitCode || '');
  fd.append('units', JSON.stringify(unitsData));
  fd.append('equipment_ids', JSON.stringify(equipmentIds));
  fd.append('equipment_quantities', JSON.stringify(qtyMap));
  fd.append('out_date', outVal);
  fd.append('due_date', dueVal);
  fd.append('event_id', eventVal);
  fd.append('notes', notesVal);

  fetch(AJAX_URL, { method: 'POST', body: fd })
    .then(r => r.json())
    .then(res => {
      if(res.success){
        const txnId = res.data?.transaction_id || tempTxnId;
        const loanId = res.data?.loan_id || '';
        loanBasket.forEach((v) => {
          DB.loans.unshift({
            id: loanId || ('loan_' + Date.now() + '_' + v.assetId),
            transaction_id: txnId,
            item: v.assetId,
            unit_no: String(v.unitNo),
            unit_code: v.unitCode,
            unit_name: v.unitName,
            by: ME.name,
            purpose: purposeVal,
            out: outVal,
            due: dueVal,
            back: '',
            event: eventVal,
            notes: notesVal,
            qty: 1
          });
          const it = itemById(v.assetId);
          if(it){ it.holder = ME.name; it.due = dueVal; }
        });
        pushNotif('Peminjaman tercatat', `${loanBasket.size} unit alat (${purposeVal}) atas nama kamu`, 'box', '#peminjaman');
        toast(`${loanBasket.size} unit alat berhasil diajukan.`, 'check');
        loanBasket.clear();
        saveLoanBasketToStorage();
        closeSheet();
        render();
        if (typeof requestSyncScope === 'function') {
          requestSyncScope('loans', true);
          requestSyncScope('inventory', true);
        }
      } else {
        if (submitBtn) {
          submitBtn.disabled = false;
          submitBtn.innerHTML = origBtnText;
        }
        toast(res.data?.message || res.data || 'Gagal mencatat peminjaman di server.', 'alert');
      }
    })
    .catch((err) => {
      if (submitBtn) {
        submitBtn.disabled = false;
        submitBtn.innerHTML = origBtnText;
      }
      toast('Terjadi kendala jaringan saat mencatat peminjaman.', 'alert');
      console.error('[PTV Loans] Submit error:', err);
    });
}

/* ============================================================
   SURAT TUGAS MODAL
   ============================================================ */
let stSelectedCrew = new Set();
let stCrewSearchQuery = '';

function updateStCrewSelectedChips(chipsEl, countEl) {
  if (!chipsEl) return;
  if (stSelectedCrew.size === 0) {
    chipsEl.innerHTML = '<span class="t-xs muted" style="padding:4px 0">Belum ada kru yang dipilih. Cari dan pilih dari daftar di bawah.</span>';
  } else {
    const list = Array.from(stSelectedCrew).map(id => {
      const c = (DB.crew || []).find(x => String(x.id) === String(id));
      if (!c) return '';
      return `
        <span class="ptv-selected-pill ptv-pill-crew">
          ${avatarHTML(c.name, c.photo || c.foto_url || c.foto, 'xs')}
          <b>${esc(c.name)}</b>
          <span class="pill-role">(${esc(c.pos || c.div || 'Kru')})</span>
          <button type="button" class="pill-del-btn" data-st-crew-remove="${esc(c.id)}" aria-label="Hapus">&times;</button>
        </span>
      `;
    }).join('');
    chipsEl.innerHTML = list;
  }
  if (countEl) {
    countEl.textContent = stSelectedCrew.size ? `${stSelectedCrew.size} Kru Dipilih` : 'Pilih Kru';
  }
}

function isOperationalCrew(c) {
  if (!c) return false;
  
  // Status kru HARUS AKTIF persis sesuai data kolom status di Supabase ptv_kru
  const rawStatus = (c.status || '').toLowerCase().trim();
  const isNonaktif = ['nonaktif', 'non-aktif', 'non aktif', 'pasif', 'alumni', 'inactive'].includes(rawStatus);
  if (isNonaktif || rawStatus !== 'aktif') return false;

  const div = (c.div || c.divisi || '').toLowerCase().trim();
  const pos = (c.pos || c.jabatan || '').toLowerCase().trim();
  const role = (c.role || '').toLowerCase().trim();

  // Pengarah, Pembina, Penasihat, Dewan Pendiri/Pengasuh BUKAN kru operasional kas
  if (['pembina', 'pengarah', 'penasihat', 'member', 'non-operasional', 'tamu'].includes(role)) return false;
  if (['pembina', 'pengarah', 'penasihat'].includes(div)) return false;
  if (/pembina|pengarah|penasihat|pendiri|pengasuh/i.test(pos)) return false;

  // Eksekutif aktif dan seluruh Kru aktif SELALU masuk di tabel iuran kas kru!
  return true;
}

function renderStCrewList(listEl) {
  if (!listEl) return;
  const q = (stCrewSearchQuery || '').toLowerCase().trim();

  let crews = (DB.crew || []).filter(c => isOperationalCrew(c));

  // Jika dibuka terkait acara, HANYA tampilkan kru yang terdaftar pada acara tersebut!
  if (_stFromEventId) {
    crews = crews.filter(c => {
      const cid = String(c.id);
      const cname = (c.name || '').toLowerCase().trim();
      return _stEventCrewIds.has(cid) || _stEventCrewNames.some(n => (n || '').toLowerCase().trim() === cname);
    });
  }

  if (q) {
    crews = crews.filter(c => {
      return (c.name || '').toLowerCase().includes(q) ||
             (c.pos || '').toLowerCase().includes(q) ||
             (c.div || '').toLowerCase().includes(q);
    });
  }

  if (crews.length === 0) {
    if (_stFromEventId) {
      listEl.innerHTML = `
        <div style="text-align:center;padding:16px 8px;color:#dc2626;font-size:12px;font-weight:600;">
          <i class="fa-solid fa-user-xmark" style="font-size:22px;display:block;margin-bottom:6px;color:#ef4444;"></i>
          ${_stEventCrewNames.length === 0 ? 'Belum ada kru yang ditugaskan pada acara ini. Silakan atur kru pada acara terlebih dahulu.' : 'Tidak ada kru acara yang sesuai dengan pencarian.'}
        </div>
      `;
    } else {
      listEl.innerHTML = '<p class="t-xs muted" style="text-align:center;padding:12px 0">Tidak ada data kru yang sesuai.</p>';
    }
    return;
  }

  listEl.innerHTML = crews.map(c => {
    const isSelected = stSelectedCrew.has(String(c.id));
    return `
      <div class="row-b" data-st-crew-select="${esc(c.id)}" style="padding:7px 11px;border-radius:var(--r-s);cursor:pointer;background:${isSelected ? '#eff6ff' : 'var(--surface)'};border:1.5px solid ${isSelected ? '#93c5fd' : 'var(--line-2)'};margin-bottom:5px;align-items:center;transition:background 0.15s ease;">
        <div class="row gap8" style="align-items:center;">
          ${avatarHTML(c.name, c.photo || c.foto_url || c.foto, 'sm')}
          <div class="tight">
            <div class="t-sm" style="font-weight:700;color:var(--ink)">${esc(c.name)}</div>
            <div class="t-xs muted">${esc(c.pos || 'Kru')}${c.div ? ' · ' + esc(c.div) : ''}</div>
          </div>
        </div>
        <div style="display:flex;align-items:center;gap:6px">
          ${_stFromEventId ? '<span style="font-size:10px;font-weight:700;color:#1d4ed8;background:#dbeafe;padding:1px 6px;border-radius:4px;">Kru Acara</span>' : ''}
          <span class="chip ${isSelected ? 'ok' : 'muted'}" style="font-size:10.5px;font-weight:700;">${isSelected ? '✓ Ditugaskan' : '+ Pilih'}</span>
        </div>
      </div>
    `;
  }).join('');
}

let _stFromEventId = null;
let _stEventCrewNames = [];
let _stEventCrewIds = new Set();
let _stEventName = '';

function openSuratTugasModal(preset) {
  stSelectedCrew.clear();
  _stEventCrewNames = [];
  _stEventCrewIds = new Set();
  _stEventName = '';

  let ev = null;
  if(preset && typeof preset === 'object' && preset.eventId){
    ev = eventById(preset.eventId);
  } else if(preset && typeof preset === 'string' && eventById(preset)){
    ev = eventById(preset);
  }

  _stFromEventId = ev ? String(ev.id) : null;
  if (ev) {
    _stEventName = ev.name || '';
  }

  if (ev && Array.isArray(ev.crew) && ev.crew.length) {
    _stEventCrewNames = [...ev.crew];
    ev.crew.forEach(name => {
      const c = (DB.crew || []).find(x => (x.name || '').toLowerCase() === String(name).toLowerCase());
      if (c) _stEventCrewIds.add(String(c.id));
    });
  } else if (preset && typeof preset === 'object' && Array.isArray(preset.crewNames) && preset.crewNames.length) {
    _stEventCrewNames = [...preset.crewNames];
    preset.crewNames.forEach(name => {
      const c = (DB.crew || []).find(x => (x.name || '').toLowerCase() === String(name).toLowerCase());
      if (c) _stEventCrewIds.add(String(c.id));
    });
  }

  // JANGAN auto-select semua kru! Biarkan user memilih kru yang ditugaskan secara manual.
  stCrewSearchQuery = '';

  const dateIn = (id,val)=>`<input class="input" type="date" id="${id}" value="${val||iso(today)}">`;
  const defaultEventName = ev ? ev.name : '';
  const defaultSubject = ev ? `Liputan & Dokumentasi: ${ev.name}` : '';
  const defaultStart = ev ? ev.date : iso(today);
  const defaultEnd = ev ? ev.date : iso(today);
  const defaultNote = ev ? `Penugasan operasional untuk acara ${ev.name} di ${ev.loc || 'Studio PTV'}${ev.time ? ' (' + ev.time + ')' : ''}.` : '';

  const bodyHtml = `
    <div style="background:var(--bg-2); border:1px solid var(--line-2); border-radius:12px; padding:10px 14px; margin-bottom:14px; display:flex; align-items:center; justify-content:space-between;">
      <div>
        <div style="font-size:10px; font-weight:800; color:var(--muted); text-transform:uppercase; letter-spacing:0.05em;">Nomor Surat Tugas Resmi</div>
        <div style="font-size:13px; font-weight:700; color:var(--ink); margin-top:2px;">— (Diterbitkan Otomatis Saat Disetujui Eksekutif)</div>
      </div>
      <span class="chip" style="font-size:10px; font-weight:700;">Menunggu ACC</span>
    </div>

    ${ev ? `
    <div style="background:#eff6ff;border:1.5px solid #bfdbfe;border-radius:12px;padding:11px 15px;margin-bottom:14px;display:flex;align-items:flex-start;gap:12px;">
      <span style="width:32px;height:32px;border-radius:8px;background:#dbeafe;color:#1d4ed8;display:inline-flex;align-items:center;justify-content:center;font-size:15px;flex-shrink:0;">
        <i class="fa-solid fa-calendar-check"></i>
      </span>
      <div style="flex:1;min-width:0;">
        <div style="font-size:12.5px;font-weight:800;color:#1e40af;">Penugasan Acara: ${esc(ev.name)} (${fmtDate(ev.date, true)})</div>
        <div style="font-size:11.5px;color:#2563eb;line-height:1.4;margin-top:2px;">
          Daftar kru di bawah telah disaring <b>khusus kru yang terdaftar pada acara ini</b> (${_stEventCrewNames.length} kru). Silakan pilih kru yang akan ditugaskan.
        </div>
      </div>
    </div>` : ''}

    <div class="field" style="margin-bottom:12px">
      <label style="font-weight:650">Terkait Acara (Isian Bebas)</label>
      <input class="input" id="st_event" value="${esc(defaultEventName)}" placeholder="Ketik nama acara (misal: Haflah Akhirussanah 2026 / Wisuda / Liputan Pondok)..." list="stEventDatalist" autocomplete="off">
      <datalist id="stEventDatalist">
        ${(DB.events || []).map(e => `<option value="${esc(e.name)}">`).join('')}
      </datalist>
      <span class="t-xs muted" style="margin-top:4px;display:block">Bebas ketik nama acara apa saja, atau pilih rekomendasi dari agenda kegiatan.</span>
    </div>

    <div class="field" style="margin-bottom:12px">
      <label style="font-weight:650">Perihal / Judul Penugasan <span style="color:#ef4444">*</span></label>
      <input class="input" id="st_subject" value="${esc(defaultSubject)}" placeholder="Contoh: Liputan Siaran Langsung & Dokumentasi Video" required>
    </div>

    <div class="field" style="margin-bottom:12px">
      <div class="row-b" style="margin-bottom:6px">
        <label style="margin:0;font-weight:650">Kru yang Ditugaskan ${_stFromEventId ? '(Kru yang Terdaftar pada Acara Ini)' : '(Basis Data Manajemen Kru)'} <span style="color:#ef4444">*</span></label>
        <span class="chip" id="stCrewCount" style="font-size:11px">Pilih Kru</span>
      </div>
      <div id="stCrewSelectedChips" style="min-height:28px;display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px"></div>
      <div class="searchbar mt8" style="margin-bottom:8px">
        ${ic.search}
        <input id="stCrewSearch" placeholder="${_stFromEventId ? 'Cari nama kru yang bertugas di acara ini…' : 'Cari nama kru, divisi, atau jabatan…'}" autocomplete="off">
      </div>
      <div id="stCrewList" style="max-height:190px;overflow-y:auto;border:1px solid var(--line-2);border-radius:var(--r-m);padding:8px;background:var(--bg-2)"></div>
    </div>

    <div class="grid-2" style="margin-bottom:12px">
      ${field('Tanggal Mulai Tugas', dateIn('st_start', defaultStart))}
      ${field('Tanggal Selesai Tugas', dateIn('st_end', defaultEnd))}
    </div>

    <div class="field">
      <label style="font-weight:650">Catatan & Instruksi Penugasan</label>
      <textarea class="input" id="st_note" placeholder="Instruksi penugasan tambahan, pembagian tugas/jobdesc kru, titik kumpul, perlengkapan yang disiapkan...">${esc(defaultNote)}</textarea>
    </div>
  `;

  const btnLabel = ev ? `${ic.check}Terbitkan Surat Tugas Resmi` : `${ic.send}Ajukan Surat Tugas`;

  openSheet('Buat Surat Tugas Kru', bodyHtml, {
    foot: `<button class="btn block pri" id="btnSubmitSuratTugas" data-act="submitSuratTugas">${btnLabel}</button>`,
    then: (sheetBody) => {
      const chipsEl = $('#stCrewSelectedChips', sheetBody);
      const listEl = $('#stCrewList', sheetBody);
      const countEl = $('#stCrewCount', sheetBody);
      const searchIn = $('#stCrewSearch', sheetBody);

      function updateStValidationState() {
        const btn = $('#btnSubmitSuratTugas', sheetBody) || $('button[data-act="submitSuratTugas"]', sheetBody);
        const isValid = stSelectedCrew.size > 0;
        if (btn) {
          if (!isValid) {
            btn.style.opacity = '0.5';
            btn.style.cursor = 'not-allowed';
            btn.setAttribute('data-disabled-msg', 'Wajib memilih minimal 1 kru yang ditugaskan terlebih dahulu.');
          } else {
            btn.style.opacity = '1';
            btn.style.cursor = 'pointer';
            btn.removeAttribute('data-disabled-msg');
          }
        }
      }

      updateStCrewSelectedChips(chipsEl, countEl);
      renderStCrewList(listEl);
      updateStValidationState();

      if (searchIn) {
        searchIn.addEventListener('input', () => {
          stCrewSearchQuery = searchIn.value;
          renderStCrewList(listEl);
        });
      }

      if (sheetBody._stClickHandler) {
        sheetBody.removeEventListener('click', sheetBody._stClickHandler);
      }
      sheetBody._stClickHandler = (ev) => {
        const itemEl = ev.target.closest('[data-st-crew-select]');
        if (itemEl) {
          ev.stopPropagation();
          const cid = String(itemEl.getAttribute('data-st-crew-select') || itemEl.dataset.stCrewSelect || '');
          if (!cid) return;
          if (stSelectedCrew.has(cid)) {
            stSelectedCrew.delete(cid);
          } else {
            stSelectedCrew.add(cid);
          }
          haptic(8);
          updateStCrewSelectedChips(chipsEl, countEl);
          renderStCrewList(listEl);
          updateStValidationState();
          return;
        }

        const rmBtn = ev.target.closest('[data-st-crew-remove]');
        if (rmBtn) {
          ev.stopPropagation();
          const cid = String(rmBtn.getAttribute('data-st-crew-remove') || rmBtn.dataset.stCrewRemove || '');
          if (!cid) return;
          stSelectedCrew.delete(cid);
          haptic(8);
          updateStCrewSelectedChips(chipsEl, countEl);
          renderStCrewList(listEl);
          updateStValidationState();
          return;
        }
      };
      sheetBody.addEventListener('click', sheetBody._stClickHandler);
    }
  });
}

function submitSuratTugas() {
  const btn = $('#btnSubmitSuratTugas') || $('button[data-act="submitSuratTugas"]');
  if (btn && btn.getAttribute('data-disabled-msg')) {
    toast(btn.getAttribute('data-disabled-msg'), 'alert');
    return;
  }
  const subject = ($('#st_subject')?.value || '').trim();
  if (!subject) {
    toast('Perihal penugasan wajib diisi.', 'info');
    $('#st_subject')?.focus();
    return;
  }
  if (stSelectedCrew.size === 0) {
    toast('Wajib memilih minimal 1 kru yang ditugaskan.', 'alert');
    return;
  }

  const eventName = ($('#st_event')?.value || '').trim();
  const notes = ($('#st_note')?.value || '').trim();
  const startDate = $('#st_start')?.value || iso(today);
  const endDate = $('#st_end')?.value || iso(today);

  const crewDetails = Array.from(stSelectedCrew).map(cid => {
    const c = (DB.crew || []).find(x => String(x.id) === String(cid));
    return {
      nama: c ? c.name : ('Kru #' + cid),
      peran: c ? (c.pos || c.div || 'Kru Pelaksana') : 'Kru Pelaksana',
      catatan: '-'
    };
  });

  const fullSubject = eventName ? `${subject} (${eventName})` : subject;
  const leadCrew = crewDetails[0]?.nama || ME.name;
  const isFromEvent = !!_stFromEventId;
  const activeEventId = _stFromEventId;

  // VERIFIKASI WAJIB: Penerbitan langsung Surat Tugas dari Rundown Acara
  if (isFromEvent && !window._stVerificationToken) {
    if (typeof window.openSuratVerificationSheet === 'function') {
      window.openSuratVerificationSheet({
        type: 'Surat Tugas',
        draftId: String(activeEventId || 'event'),
        title: 'Penerbitan Surat Tugas Resmi: ' + fullSubject,
        onVerified: function(token) {
          window._stVerificationToken = token;
          submitSuratTugas();
        }
      });
      return;
    }
  }

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_submit_doc');
  fd.append('type', 'Surat Tugas');
  fd.append('subject', fullSubject);
  fd.append('event', eventName);
  fd.append('notes', notes);
  fd.append('start_date', startDate);
  fd.append('end_date', endDate);
  fd.append('penanggung_jawab', leadCrew);
  fd.append('crew_ids', Array.from(stSelectedCrew).join(','));
  fd.append('crew_names', JSON.stringify(crewDetails));
  if (isFromEvent) {
    fd.append('from_event', '1');
    fd.append('event_id', activeEventId);
    fd.append('auto_approve', '1');
    if (window._stVerificationToken) {
      fd.append('verification_token', window._stVerificationToken);
      window._stVerificationToken = null;
    }
  }

  const submitBtn = document.querySelector('[data-act="submitSuratTugas"]') || $('#btn_submit_surat_tugas');
  const origBtnHtml = submitBtn ? submitBtn.innerHTML : '';
  if (submitBtn) {
    submitBtn.disabled = true;
    submitBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin" style="margin-right:6px"></i>Memproses...';
  }

  fetch(AJAX_URL, { method: 'POST', body: fd })
    .then(r => r.json())
    .then(res => {
      if (res.success && res.data) {
        const docNo = res.data.no || (isFromEvent ? 'RESMI' : '— (Menunggu Pengesahan)');
        const finalStatus = res.data.status || (isFromEvent ? 'Disetujui' : 'Menunggu');
        const docId = res.data.id || (res.data.record && res.data.record.id);
        DB.docs.unshift({
          id: docId,
          owner: leadCrew,
          date: startDate,
          status: finalStatus,
          event: eventName,
          event_id: activeEventId || '',
          type: 'Surat Tugas',
          no: docNo,
          subject: fullSubject,
          recipients: crewDetails.map(c => c.nama)
        });
        if (isFromEvent) {
          toast(`Surat tugas resmi diterbitkan untuk ${eventName || subject}. Nomor: ${docNo}`, 'check');
        } else {
          pushNotif('Surat Tugas Diajukan', fullSubject + ' · Menunggu Pengesahan', 'doc', '#/perizinan');
          toast('Surat tugas berhasil diajukan, menunggu pengesahan.', 'check');
        }
        closeSheet();
        render();
        if (typeof syncPerizinanLive === 'function') syncPerizinanLive(true);
      } else {
        if (submitBtn) {
          submitBtn.disabled = false;
          submitBtn.innerHTML = origBtnHtml;
        }
        toast(res.data?.message || res.data || 'Gagal mengajukan surat tugas.', 'alert');
      }
    })
    .catch((err) => {
      if (submitBtn) {
        submitBtn.disabled = false;
        submitBtn.innerHTML = origBtnHtml;
      }
      toast('Terjadi kendala jaringan saat mengajukan surat.', 'alert');
      console.error('[PTV Surat Tugas] Submit error:', err);
    });
}

/* ============================================================
   SURAT MEMBAWA BARANG MODAL (CUSTOM MULTI-ALAT & KRU TERLIBAT)
   ============================================================ */
let sbSelectedGear = new Set();
let sbGearSearchQuery = '';
let sbSelectedCrew = new Set();
let sbCrewSearchQuery = '';
let _sbFromEventId = null;
let _sbEventGearDetails = {};
let _sbEventName = '';
let _sbEventCrewNames = [];
let _sbEventCrewIds = new Set();

function getSbGearDetail(gid) {
  const gidStr = String(gid);
  if (!_sbEventGearDetails[gidStr]) {
    const it = itemById(gidStr);
    const s = it ? getAssetUnitSummary(it) : { available: 1, total: 1, units: [] };
    const cand = (s.units && s.units.length > 0) ? s.units.map(u => Number(u.unit)) : [1];
    _sbEventGearDetails[gidStr] = {
      id: gidStr,
      candidateUnits: cand,
      selectedUnits: [],
      qty: 0
    };
  }
  return _sbEventGearDetails[gidStr];
}

function updateSbGearSelectedChips(chipsEl, countEl) {
  if (!chipsEl) return;
  if (sbSelectedGear.size === 0) {
    chipsEl.innerHTML = '<span class="t-xs muted" style="padding:4px 0">Belum ada alat yang dipilih. Silakan pilih alat dan unit fisik di bawah.</span>';
  } else {
    const list = Array.from(sbSelectedGear).map(id => {
      const it = itemById(id);
      if (!it) return '';
      const detail = getSbGearDetail(id);
      let unitBadge = '';
      if (detail && Array.isArray(detail.selectedUnits) && detail.selectedUnits.length) {
        const invCode = it.code || ('INV-' + String(it.id).padStart(3, '0'));
        const unitLabels = detail.selectedUnits.map(uNo => {
          const rawUnits = it.unit_conditions || [];
          const uObj = rawUnits.find(u => Number(u.unit) === Number(uNo));
          const uDisplayName = getUnitDisplayName(uObj, uNo);
          return uDisplayName;
        }).join(', ');
        unitBadge = `<span class="chip blue" style="font-size:10px;padding:2px 7px;font-weight:700;margin-left:4px;">${detail.selectedUnits.length} Unit: ${esc(unitLabels)}</span>`;
      }
      return `
        <span class="ptv-selected-pill ptv-pill-gear" style="display:inline-flex;align-items:center;gap:6px;">
          <b>${esc(it.code || 'INV')}</b>
          <span class="pill-name">${esc(it.name)}</span>
          ${unitBadge}
          <button type="button" class="pill-del-btn" data-sb-gear-remove="${esc(it.id)}" aria-label="Hapus">&times;</button>
        </span>
      `;
    }).join('');
    chipsEl.innerHTML = list;
  }
  if (countEl) {
    countEl.textContent = sbSelectedGear.size ? `${sbSelectedGear.size} Barang Dipilih` : 'Pilih Barang';
  }
}

function renderSbGearList(listEl) {
  if (!listEl) return;
  const q = (sbGearSearchQuery || '').toLowerCase().trim();
  let items = (DB.inventory || []);

  // Jika dibuka dari acara, HANYA tampilkan barang yang terdaftar pada acara tersebut
  if (_sbFromEventId) {
    const eventGearIdSet = new Set(Object.keys(_sbEventGearDetails));
    items = items.filter(it => eventGearIdSet.has(String(it.id)));
  }

  if (q) {
    items = items.filter(it => {
      return (it.name || '').toLowerCase().includes(q) ||
             (it.code || '').toLowerCase().includes(q) ||
             (it.cat || '').toLowerCase().includes(q) ||
             (it.brand || '').toLowerCase().includes(q);
    });
  }
  items = sortInventoryItems(items);

  if (items.length === 0) {
    listEl.innerHTML = '<p class="t-xs muted" style="text-align:center;padding:12px 0">Tidak ada peralatan yang sesuai.</p>';
    return;
  }

  listEl.innerHTML = items.map(it => {
    const gidStr = String(it.id);
    const detail = getSbGearDetail(gidStr);
    const invCode = it.code || ('INV-' + String(it.id).padStart(3, '0'));
    const candidateUnits = detail.candidateUnits || [1];
    const selectedUnits = detail.selectedUnits || [];
    const isSelected = sbSelectedGear.has(gidStr) && (selectedUnits.length > 0);
    const hasMultipleUnits = candidateUnits.length > 1;

    let unitsSelectorHtml = '';
    if (hasMultipleUnits || (it.unit_conditions && it.unit_conditions.length > 1)) {
      unitsSelectorHtml = `
        <div style="margin-top:8px;padding-top:8px;border-top:1px dashed ${isSelected ? '#93c5fd' : 'var(--line-2)'};">
          <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px;flex-wrap:wrap;gap:4px;">
            <span style="font-size:11px;font-weight:750;color:${isSelected ? '#1e40af' : 'var(--ink)'};">
              <i class="fa-solid fa-layer-group" style="margin-right:4px;"></i>Pilih Unit Fisik (${selectedUnits.length} dari ${candidateUnits.length} unit dibawa):
            </span>
            <button type="button" data-sb-gear-toggle-all="${esc(it.id)}" style="font-size:10.5px;font-weight:700;color:#2563eb;background:none;border:none;cursor:pointer;padding:0;">
              ${selectedUnits.length === candidateUnits.length ? 'Batalkan Semua Unit' : 'Pilih Semua Unit'}
            </button>
          </div>
          <div style="display:flex;flex-wrap:wrap;gap:6px;">
            ${candidateUnits.map(uNo => {
              const rawUnits = it.unit_conditions || [];
              const uObj = rawUnits.find(u => Number(u.unit) === Number(uNo));
              const uDisplayName = getUnitDisplayName(uObj, uNo);
              const uBarcode = getUnitBarcode(invCode, uNo);
              const isUnitActive = selectedUnits.includes(Number(uNo));
              return `
                <button type="button"
                  data-sb-unit-toggle="${esc(it.id)}:${uNo}"
                  style="display:inline-flex;align-items:center;gap:6px;padding:5px 9px;border-radius:7px;font-size:11px;font-weight:700;cursor:pointer;border:1.5px solid ${isUnitActive ? '#2563eb' : '#cbd5e1'};background:${isUnitActive ? '#eff6ff' : '#ffffff'};color:${isUnitActive ? '#1e40af' : '#64748b'};transition:all 0.12s ease;">
                  <i class="fa-solid ${isUnitActive ? 'fa-square-check' : 'fa-square'}" style="color:${isUnitActive ? '#2563eb' : '#cbd5e1'};font-size:12px;"></i>
                  <span>${esc(uDisplayName)}</span>
                  <span style="font-size:9.5px;opacity:0.75;font-weight:600;">(${esc(uBarcode)})</span>
                </button>
              `;
            }).join('')}
          </div>
        </div>
      `;
    } else if (candidateUnits.length === 1) {
      const uNo = candidateUnits[0];
      const rawUnits = it.unit_conditions || [];
      const uObj = rawUnits.find(u => Number(u.unit) === Number(uNo));
      const uDisplayName = getUnitDisplayName(uObj, uNo);
      const uBarcode = getUnitBarcode(invCode, uNo);
      unitsSelectorHtml = `
        <div style="margin-top:4px;">
          <span style="display:inline-block;background:#f0fdf4;color:#166534;border:1px solid #bbf7d0;padding:2px 7px;border-radius:6px;font-size:10px;font-weight:700;">
            Unit Fisik: ${esc(uDisplayName)} (${esc(uBarcode)})
          </span>
        </div>
      `;
    }

    return `
      <div style="padding:10px 12px;border-radius:var(--r-m);background:${isSelected ? '#f0fdf4' : 'var(--surface)'};border:1.5px solid ${isSelected ? '#86efac' : 'var(--line-2)'};margin-bottom:8px;transition:all 0.15s ease;">
        <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;">
          <div style="display:flex;align-items:center;gap:10px;flex:1;min-width:0;cursor:pointer;" data-sb-gear-toggle="${esc(it.id)}">
            <div style="width:40px;height:40px;border-radius:8px;background:#f3f4f6;display:grid;place-items:center;overflow:hidden;flex-shrink:0;border:1px solid #e5e7eb;">
              ${it.photo ? `<img src="${esc(it.photo)}" style="width:100%;height:100%;object-fit:cover;">` : `<i class="fa-solid fa-camera text-slate-400"></i>`}
            </div>
            <div class="tight" style="flex:1;min-width:0;">
              <div class="t-sm" style="font-weight:750;color:var(--ink)">${esc(it.name)}</div>
              <div class="t-xs muted"><b>${esc(invCode)}</b> &middot; ${esc(it.cat || 'Alat')} &middot; Kondisi: ${esc(it.cond || 'Baik')}</div>
            </div>
          </div>
          <button type="button" data-sb-gear-toggle="${esc(it.id)}" style="display:inline-flex;align-items:center;gap:5px;padding:5px 10px;border-radius:7px;border:1.5px solid ${isSelected ? '#22c55e' : '#cbd5e1'};background:${isSelected ? '#dcfce7' : '#f8fafc'};color:${isSelected ? '#15803d' : '#64748b'};font-size:11px;font-weight:750;cursor:pointer;flex-shrink:0;transition:all 0.12s ease;">
            <i class="fa-solid ${isSelected ? 'fa-check' : 'fa-plus'}"></i>
            <span>${isSelected ? 'Dibawa' : '+ Bawa Alat'}</span>
          </button>
        </div>
        ${unitsSelectorHtml}
      </div>
    `;
  }).join('');
}

function updateSbCrewSelectedChips(chipsEl, countEl) {
  if (!chipsEl) return;
  if (sbSelectedCrew.size === 0) {
    chipsEl.innerHTML = '<span class="t-xs muted" style="padding:4px 0">Belum ada kru yang dipilih. Silakan pilih minimal 1 kru pembawa di bawah.</span>';
  } else {
    const list = Array.from(sbSelectedCrew).map(id => {
      const c = (DB.crew || []).find(x => String(x.id) === String(id));
      if (!c) return '';
      return `
        <span class="ptv-selected-pill ptv-pill-crew">
          ${avatarHTML(c.name, c.photo || c.foto_url || c.foto, 'xs')}
          <b>${esc(c.name)}</b>
          <span class="pill-role">(${esc(c.pos || c.div || 'Kru')})</span>
          <button type="button" class="pill-del-btn" data-sb-crew-remove="${esc(c.id)}" aria-label="Hapus">&times;</button>
        </span>
      `;
    }).join('');
    chipsEl.innerHTML = list;
  }
  if (countEl) {
    countEl.textContent = sbSelectedCrew.size ? `${sbSelectedCrew.size} Kru Pembawa` : 'Pilih Kru';
  }
}

function renderSbCrewList(listEl) {
  if (!listEl) return;
  const q = (sbCrewSearchQuery || '').toLowerCase().trim();

  let crews = (DB.crew || []).filter(c => isOperationalCrew(c));

  // Jika dibuka dari acara, HANYA tampilkan kru yang bertugas pada acara tersebut!
  if (_sbFromEventId) {
    crews = crews.filter(c => {
      const cid = String(c.id);
      const cname = (c.name || '').toLowerCase().trim();
      return _sbEventCrewIds.has(cid) || _sbEventCrewNames.some(n => (n || '').toLowerCase().trim() === cname);
    });
  }

  if (q) {
    crews = crews.filter(c => {
      return (c.name || '').toLowerCase().includes(q) ||
             (c.pos || '').toLowerCase().includes(q) ||
             (c.div || '').toLowerCase().includes(q);
    });
  }

  if (crews.length === 0) {
    if (_sbFromEventId) {
      listEl.innerHTML = `
        <div style="text-align:center;padding:16px 8px;color:#dc2626;font-size:12px;font-weight:600;">
          <i class="fa-solid fa-user-xmark" style="font-size:22px;display:block;margin-bottom:6px;color:#ef4444;"></i>
          ${_sbEventCrewNames.length === 0 ? 'Belum ada kru yang ditugaskan pada acara ini. Silakan atur kru pada acara terlebih dahulu.' : 'Tidak ada kru acara yang sesuai dengan pencarian.'}
        </div>
      `;
    } else {
      listEl.innerHTML = '<p class="t-xs muted" style="text-align:center;padding:12px 0">Tidak ada data kru yang sesuai.</p>';
    }
    return;
  }

  listEl.innerHTML = crews.map(c => {
    const isSelected = sbSelectedCrew.has(String(c.id));
    return `
      <div class="row-b" data-sb-crew-select="${esc(c.id)}" style="padding:7px 11px;border-radius:var(--r-s);cursor:pointer;background:${isSelected ? '#eff6ff' : 'var(--surface)'};border:1.5px solid ${isSelected ? '#93c5fd' : 'var(--line-2)'};margin-bottom:5px;align-items:center;transition:background 0.15s ease;">
        <div class="row gap8" style="align-items:center;">
          ${avatarHTML(c.name, c.photo || c.foto_url || c.foto, 'xs')}
          <div class="tight">
            <div class="t-sm" style="font-weight:700;color:var(--ink)">${esc(c.name)}</div>
            <div class="t-xs muted">${esc(c.pos || 'Kru')}${c.div ? ' · ' + esc(c.div) : ''}</div>
          </div>
        </div>
        <div style="display:flex;align-items:center;gap:6px;">
          ${_sbFromEventId ? '<span style="font-size:10px;font-weight:700;color:#1d4ed8;background:#dbeafe;padding:1px 6px;border-radius:4px;">Kru Acara</span>' : ''}
          <span class="chip ${isSelected ? 'ok' : 'muted'}" style="font-size:10.5px;font-weight:700;">${isSelected ? '✓ Membawa' : '+ Pilih'}</span>
        </div>
      </div>
    `;
  }).join('');
}

function openSuratBarangModal(preset) {
  sbSelectedGear.clear();
  sbSelectedCrew.clear();
  sbGearSearchQuery = '';
  sbCrewSearchQuery = '';
  _sbEventGearDetails = {};
  _sbEventName = '';
  _sbEventCrewNames = [];
  _sbEventCrewIds = new Set();

  let presetSubject = '';
  let presetStart = iso(today);
  let presetEnd = iso(today);

  if (preset && typeof preset === 'object') {
    _sbFromEventId = preset.eventId ? String(preset.eventId) : null;
    _sbEventName = preset.eventName || '';
    if (preset.gearDetails && typeof preset.gearDetails === 'object') {
      _sbEventGearDetails = { ...preset.gearDetails };
    }
    // Register candidate event crew (do NOT auto-select)
    if (Array.isArray(preset.crewIds)) {
      preset.crewIds.forEach(id => {
        if (id) _sbEventCrewIds.add(String(id));
      });
    }
    if (Array.isArray(preset.crewNames)) {
      _sbEventCrewNames = [...preset.crewNames];
      preset.crewNames.forEach(name => {
        const c = (DB.crew || []).find(x => (x.name || '').toLowerCase() === String(name).toLowerCase());
        if (c) _sbEventCrewIds.add(String(c.id));
      });
    }
    // JANGAN auto-select alat maupun kru! Tetap kosong agar dipilih manual oleh user.
    if (preset.subject) presetSubject = preset.subject;
    if (preset.startDate) presetStart = preset.startDate;
    if (preset.endDate) presetEnd = preset.endDate;
  } else if (preset) {
    _sbFromEventId = null;
    sbSelectedGear.add(String(preset));
    const d = getSbGearDetail(preset);
    if (d && d.candidateUnits.length > 0) {
      d.selectedUnits = [...d.candidateUnits];
      d.qty = d.selectedUnits.length;
    }
  } else {
    _sbFromEventId = null;
  }

  const dateIn = (id,val)=>`<input class="input" type="date" id="${id}" value="${val||iso(today)}">`;

  const eventBannerHtml = _sbFromEventId ? `
    <div style="background:#f0fdf4; border:1.5px solid #86efac; border-radius:12px; padding:11px 15px; margin-bottom:14px; display:flex; align-items:flex-start; gap:12px;">
      <span style="width:32px;height:32px;border-radius:8px;background:#dcfce7;color:#16a34a;display:inline-flex;align-items:center;justify-content:center;font-size:15px;flex-shrink:0;">
        <i class="fa-solid fa-boxes-packing"></i>
      </span>
      <div style="flex:1;min-width:0;">
        <div style="font-size:12.5px; font-weight:800; color:#166534;">Peralatan Sesuai Acara: ${esc(_sbEventName)}</div>
        <div style="font-size:11.5px; color:#15803d; line-height:1.4; margin-top:2px;">
          Peralatan dan kru yang tersedia telah disaring sesuai kegiatan ini. <b>Silakan pilih minimal 1 alat (beserta unitnya) dan 1 kru pembawa</b> di bawah untuk menerbitkan surat izin.
        </div>
      </div>
    </div>
  ` : '';

  const bodyHtml = `
    ${eventBannerHtml}
    <div style="background:var(--bg-2); border:1px solid var(--line-2); border-radius:12px; padding:10px 14px; margin-bottom:14px; display:flex; align-items:center; justify-content:space-between;">
      <div>
        <div style="font-size:10px; font-weight:800; color:var(--muted); text-transform:uppercase; letter-spacing:0.05em;">Nomor Surat Bawa Barang Resmi</div>
        <div style="font-size:13px; font-weight:700; color:var(--ink); margin-top:2px;">— (Diterbitkan Otomatis Saat Disetujui Eksekutif)</div>
      </div>
      <span class="chip" style="font-size:10px; font-weight:700;">Menunggu ACC</span>
    </div>

    <div class="field" style="margin-bottom:12px">
      <div class="row-b" style="margin-bottom:6px">
        <label style="margin:0;font-weight:650">Alat / Barang Inventaris yang Dibawa ${_sbFromEventId ? '(Khusus Acara Ini)' : ''} <span style="color:#ef4444">*</span></label>
        <span class="chip" id="sbGearCount" style="font-size:11px">Pilih Barang</span>
      </div>
      <div id="sbGearSelectedChips" style="min-height:28px;display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px"></div>
      ${_sbFromEventId ? '' : `
        <div class="searchbar mt8" style="margin-bottom:8px">
          ${ic.search}
          <input id="sbGearSearch" placeholder="Cari nama alat, kode inventaris (INV-xxx), merk…" autocomplete="off">
        </div>
      `}
      <div id="sbGearList" style="max-height:220px;overflow-y:auto;border:1px solid var(--line-2);border-radius:var(--r-m);padding:8px;background:var(--bg-2)"></div>
    </div>

    <div class="field" style="margin-bottom:12px">
      <div class="row-b" style="margin-bottom:6px">
        <label style="margin:0;font-weight:650">Kru yang Membawa Barang ${_sbFromEventId ? '(Kru yang Bertugas di Acara Ini)' : '(Basis Data Kru)'} <span style="color:#ef4444">*</span></label>
        <span class="chip" id="sbCrewCount" style="font-size:11px">Pilih Kru</span>
      </div>
      <div id="sbCrewSelectedChips" style="min-height:28px;display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px"></div>
      <div class="searchbar mt8" style="margin-bottom:8px">
        ${ic.search}
        <input id="sbCrewSearch" placeholder="${_sbFromEventId ? 'Cari kru pembawa di acara ini…' : 'Cari nama kru pembawa…'}" autocomplete="off">
      </div>
      <div id="sbCrewList" style="max-height:160px;overflow-y:auto;border:1px solid var(--line-2);border-radius:var(--r-m);padding:8px;background:var(--bg-2)"></div>
    </div>

    <div class="field" style="margin-bottom:12px">
      <label style="font-weight:650">Keperluan Membawa Alat <span style="color:#ef4444">*</span></label>
      <input class="input" id="sb_subject" value="${esc(presetSubject)}" placeholder="Contoh: Dokumentasi & Liputan Eksternal di Area Asrama Pondok" required>
    </div>

    <div class="grid-2" style="margin-bottom:12px">
      ${field('Tanggal Mulai Bawa', dateIn('sb_start', presetStart))}
      ${field('Rencana Kembali / Selesai', dateIn('sb_end', presetEnd))}
    </div>

    <div class="field">
      <label style="font-weight:650">Catatan Tambahan</label>
      <textarea class="input" id="sb_note" placeholder="Catatan kondisi alat saat dibawa, lokasi pemakaian, izin pos keamanan pondok, dll..."></textarea>
    </div>
  `;

  openSheet('Izin Membawa Barang Inventaris', bodyHtml, {
    foot: `<button class="btn block pri" id="btnSubmitSuratBarang" data-act="submitSuratBarang">${ic.send}${_sbFromEventId ? 'Terbitkan Surat Izin Bawa Barang' : 'Ajukan Izin Bawa Barang'}</button>`,
    then: (sheetBody) => {
      const gearChipsEl = $('#sbGearSelectedChips', sheetBody);
      const gearListEl = $('#sbGearList', sheetBody);
      const gearCountEl = $('#sbGearCount', sheetBody);
      const gearSearchIn = $('#sbGearSearch', sheetBody);

      const crewChipsEl = $('#sbCrewSelectedChips', sheetBody);
      const crewListEl = $('#sbCrewList', sheetBody);
      const crewCountEl = $('#sbCrewCount', sheetBody);
      const crewSearchIn = $('#sbCrewSearch', sheetBody);

      function updateSbValidationState() {
        const btn = $('#btnSubmitSuratBarang', sheetBody) || $('button[data-act="submitSuratBarang"]', sheetBody);
        const gearValid = sbSelectedGear.size > 0 && Array.from(sbSelectedGear).some(gid => {
          const d = getSbGearDetail(gid);
          return d && Array.isArray(d.selectedUnits) && d.selectedUnits.length > 0;
        });
        const crewValid = sbSelectedCrew.size > 0;
        const isValid = gearValid && crewValid;

        if (btn) {
          if (!isValid) {
            btn.style.opacity = '0.5';
            btn.style.cursor = 'not-allowed';
            let missing = [];
            if (!gearValid) missing.push('minimal 1 alat & unit');
            if (!crewValid) missing.push('minimal 1 kru pembawa');
            btn.setAttribute('data-disabled-msg', 'Wajib memilih ' + missing.join(' dan ') + ' terlebih dahulu.');
          } else {
            btn.style.opacity = '1';
            btn.style.cursor = 'pointer';
            btn.removeAttribute('data-disabled-msg');
          }
        }
      }

      updateSbGearSelectedChips(gearChipsEl, gearCountEl);
      renderSbGearList(gearListEl);
      updateSbCrewSelectedChips(crewChipsEl, crewCountEl);
      renderSbCrewList(crewListEl);
      updateSbValidationState();

      if (gearSearchIn) {
        gearSearchIn.addEventListener('input', () => {
          sbGearSearchQuery = gearSearchIn.value;
          renderSbGearList(gearListEl);
        });
      }

      if (crewSearchIn) {
        crewSearchIn.addEventListener('input', () => {
          sbCrewSearchQuery = crewSearchIn.value;
          renderSbCrewList(crewListEl);
        });
      }

      // Event delegation for the sheet
      if (sheetBody._sbClickHandler) {
        sheetBody.removeEventListener('click', sheetBody._sbClickHandler);
      }
      sheetBody._sbClickHandler = (ev) => {
        // 1. Toggle individual unit pill
        const unitBtn = ev.target.closest('[data-sb-unit-toggle]');
        if (unitBtn) {
          ev.stopPropagation();
          const attr = unitBtn.getAttribute('data-sb-unit-toggle') || '';
          const parts = attr.split(':');
          const gid = parts[0];
          const uNo = Number(parts[1]);
          if (gid && uNo) {
            const detail = getSbGearDetail(gid);
            const idx = detail.selectedUnits.indexOf(uNo);
            if (idx >= 0) {
              detail.selectedUnits.splice(idx, 1);
            } else {
              detail.selectedUnits.push(uNo);
              detail.selectedUnits.sort((a,b)=>a-b);
            }
            detail.qty = detail.selectedUnits.length;
            if (detail.selectedUnits.length > 0) {
              sbSelectedGear.add(String(gid));
            } else {
              sbSelectedGear.delete(String(gid));
            }
            haptic(8);
            updateSbGearSelectedChips(gearChipsEl, gearCountEl);
            renderSbGearList(gearListEl);
            updateSbValidationState();
          }
          return;
        }

        // 2. Toggle all units of an item
        const toggleAllBtn = ev.target.closest('[data-sb-gear-toggle-all]');
        if (toggleAllBtn) {
          ev.stopPropagation();
          const gid = String(toggleAllBtn.getAttribute('data-sb-gear-toggle-all') || '');
          if (gid) {
            const detail = getSbGearDetail(gid);
            if (detail.selectedUnits.length === detail.candidateUnits.length) {
              detail.selectedUnits = [];
              detail.qty = 0;
              sbSelectedGear.delete(gid);
            } else {
              detail.selectedUnits = [...detail.candidateUnits];
              detail.qty = detail.selectedUnits.length;
              sbSelectedGear.add(gid);
            }
            haptic(8);
            updateSbGearSelectedChips(gearChipsEl, gearCountEl);
            renderSbGearList(gearListEl);
            updateSbValidationState();
          }
          return;
        }

        // 3. Toggle entire gear item
        const gearToggleBtn = ev.target.closest('[data-sb-gear-toggle]');
        if (gearToggleBtn) {
          ev.stopPropagation();
          const gid = String(gearToggleBtn.getAttribute('data-sb-gear-toggle') || '');
          if (gid) {
            const detail = getSbGearDetail(gid);
            if (sbSelectedGear.has(gid)) {
              sbSelectedGear.delete(gid);
              detail.selectedUnits = [];
              detail.qty = 0;
            } else {
              sbSelectedGear.add(gid);
              detail.selectedUnits = [...detail.candidateUnits];
              detail.qty = detail.selectedUnits.length;
            }
            haptic(8);
            updateSbGearSelectedChips(gearChipsEl, gearCountEl);
            renderSbGearList(gearListEl);
            updateSbValidationState();
          }
          return;
        }

        // 4. Remove gear from selected chips
        const rmGearBtn = ev.target.closest('[data-sb-gear-remove]');
        if (rmGearBtn) {
          ev.stopPropagation();
          const gid = String(rmGearBtn.getAttribute('data-sb-gear-remove') || '');
          if (gid) {
            sbSelectedGear.delete(gid);
            const detail = getSbGearDetail(gid);
            detail.selectedUnits = [];
            detail.qty = 0;
            haptic(8);
            updateSbGearSelectedChips(gearChipsEl, gearCountEl);
            renderSbGearList(gearListEl);
            updateSbValidationState();
          }
          return;
        }

        // 5. Toggle crew selection
        const crewEl = ev.target.closest('[data-sb-crew-select]');
        if (crewEl) {
          ev.stopPropagation();
          const cid = String(crewEl.getAttribute('data-sb-crew-select') || '');
          if (cid) {
            if (sbSelectedCrew.has(cid)) {
              sbSelectedCrew.delete(cid);
            } else {
              sbSelectedCrew.add(cid);
            }
            haptic(8);
            updateSbCrewSelectedChips(crewChipsEl, crewCountEl);
            renderSbCrewList(crewListEl);
            updateSbValidationState();
          }
          return;
        }

        // 6. Remove crew from chips
        const rmCrewBtn = ev.target.closest('[data-sb-crew-remove]');
        if (rmCrewBtn) {
          ev.stopPropagation();
          const cid = String(rmCrewBtn.getAttribute('data-sb-crew-remove') || '');
          if (cid) {
            sbSelectedCrew.delete(cid);
            haptic(8);
            updateSbCrewSelectedChips(crewChipsEl, crewCountEl);
            renderSbCrewList(crewListEl);
            updateSbValidationState();
          }
          return;
        }
      };
      sheetBody.addEventListener('click', sheetBody._sbClickHandler);
    }
  });
}

function submitSuratBarang() {
  const btn = $('#btnSubmitSuratBarang') || $('button[data-act="submitSuratBarang"]');
  if (btn && btn.getAttribute('data-disabled-msg')) {
    toast(btn.getAttribute('data-disabled-msg'), 'alert');
    return;
  }
  const subject = ($('#sb_subject')?.value || '').trim();
  if (!subject) {
    toast('Keperluan membawa barang wajib diisi.', 'info');
    $('#sb_subject')?.focus();
    return;
  }
  if (sbSelectedGear.size === 0) {
    toast('Wajib memilih minimal 1 peralatan inventaris yang akan dibawa.', 'alert');
    return;
  }
  const validGearWithUnits = Array.from(sbSelectedGear).filter(gid => {
    const detail = getSbGearDetail(gid);
    return detail && Array.isArray(detail.selectedUnits) && detail.selectedUnits.length > 0;
  });
  if (validGearWithUnits.length === 0) {
    toast('Pilih minimal 1 unit fisik dari peralatan yang dibawa.', 'alert');
    return;
  }
  if (sbSelectedCrew.size === 0) {
    toast('Wajib memilih minimal 1 kru yang membawa barang.', 'alert');
    return;
  }

  const isFromEvent = !!_sbFromEventId;
  const activeEventId = _sbFromEventId;

  // VERIFIKASI WAJIB: Penerbitan langsung Surat Bawa Barang dari Rundown Acara
  if (isFromEvent && !window._sbVerificationToken) {
    if (typeof window.openSuratVerificationSheet === 'function') {
      window.openSuratVerificationSheet({
        type: 'Izin Membawa Barang',
        draftId: String(activeEventId || 'event'),
        title: 'Penerbitan Surat Bawa Barang: ' + subject,
        onVerified: function(token) {
          window._sbVerificationToken = token;
          submitSuratBarang();
        }
      });
      return;
    }
  }

  const notes = ($('#sb_note')?.value || '').trim();
  const startDate = $('#sb_start')?.value || iso(today);
  const endDate = $('#sb_end')?.value || iso(today);

  const gearItems = Array.from(sbSelectedGear).map(gid => {
    const it = itemById(gid);
    const detail = getSbGearDetail ? getSbGearDetail(gid) : (_sbEventGearDetails ? _sbEventGearDetails[String(gid)] : null);
    const units = (detail && Array.isArray(detail.selectedUnits) && detail.selectedUnits.length)
      ? detail.selectedUnits
      : null;

    let unitLabels = [];
    let unitDesc = '';
    if (units && units.length && it) {
      const invCode = it.code || ('INV-' + String(it.id).padStart(3, '0'));
      unitLabels = units.map(uNo => {
        const rawUnits = it.unit_conditions || [];
        const uObj = rawUnits.find(u => Number(u.unit) === Number(uNo));
        const uDisplayName = getUnitDisplayName(uObj, uNo);
        const uBarcode = getUnitBarcode(invCode, uNo);
        return `${uDisplayName} (${uBarcode})`;
      });
      unitDesc = ' · Unit: ' + unitLabels.join(', ');
    }

    return {
      id: gid,
      nama: (it ? `${it.name} [${it.code || 'INV'}]` : ('Alat #' + gid)) + (unitLabels.length ? ` [${unitLabels.join(', ')}]` : ''),
      unit_numbers: units || [],
      unit_labels: unitLabels,
      catatan: (it ? `Kondisi: ${it.cond || 'Baik'} · ${it.cat || 'Inventaris'}` : 'Kondisi Baik') + unitDesc
    };
  });

  const crewNames = Array.from(sbSelectedCrew).map(cid => {
    const c = (DB.crew || []).find(x => String(x.id) === String(cid));
    return c ? c.name : ('Kru #' + cid);
  });
  const pembawaStr = crewNames.join(', ');

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_submit_doc');
  fd.append('type', 'Izin Membawa Barang');
  fd.append('subject', subject);
  fd.append('items', JSON.stringify(gearItems));
  fd.append('item_id', Array.from(sbSelectedGear).join(','));
  fd.append('pembawa', pembawaStr);
  fd.append('crew_ids', Array.from(sbSelectedCrew).join(','));
  fd.append('notes', notes);
  fd.append('start_date', startDate);
  fd.append('end_date', endDate);

  if (isFromEvent) {
    fd.append('from_event', '1');
    fd.append('auto_approve', '1');
    fd.append('event_id', activeEventId);
    if (window._sbVerificationToken) {
      fd.append('verification_token', window._sbVerificationToken);
      window._sbVerificationToken = null;
    }
  }

  const submitBtn = document.querySelector('[data-act="submitSuratBarang"]') || $('#btn_submit_surat_barang');
  const origBtnHtml = submitBtn ? submitBtn.innerHTML : '';
  if (submitBtn) {
    submitBtn.disabled = true;
    submitBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin" style="margin-right:6px"></i>Memproses...';
  }

  fetch(AJAX_URL, { method: 'POST', body: fd })
    .then(r => r.json())
    .then(res => {
      if (res.success && res.data) {
        const docNo = res.data.no || (isFromEvent ? 'RESMI' : '— (Menunggu Pengesahan)');
        const docStatus = res.data.status || (isFromEvent ? 'Disetujui' : 'Menunggu');
        const docId = res.data.id || (res.data.record && res.data.record.id);
        DB.docs.unshift({
          id: docId,
          owner: pembawaStr,
          pembawa: pembawaStr,
          diajukan_oleh: ME.name,
          date: startDate,
          status: docStatus,
          event: activeEventId || '',
          event_id: activeEventId || '',
          type: 'Izin Membawa Barang',
          no: docNo,
          subject: subject,
          recipients: crewNames
        });
        if (docStatus === 'Disetujui') {
          pushNotif('Izin Bawa Barang Resmi', subject + ' · Berlaku Resmi' + (docNo ? ' (' + docNo + ')' : ''), 'box', '#/perizinan');
          toast('Izin bawa barang resmi diterbitkan.', 'check');
        } else {
          pushNotif('Izin Barang Diajukan', subject + ' · Menunggu Pengesahan', 'box', '#/perizinan');
          toast('Izin membawa barang berhasil diajukan, menunggu pengesahan.', 'check');
        }
        closeSheet();
        render();
        if (typeof syncPerizinanLive === 'function') syncPerizinanLive(true);
      } else {
        if (submitBtn) {
          submitBtn.disabled = false;
          submitBtn.innerHTML = origBtnHtml;
        }
        toast(res.data?.message || res.data || 'Gagal mengajukan izin membawa barang.', 'alert');
      }
    })
    .catch((err) => {
      if (submitBtn) {
        submitBtn.disabled = false;
        submitBtn.innerHTML = origBtnHtml;
      }
      toast('Terjadi kendala jaringan saat mengajukan surat.', 'alert');
      console.error('[PTV Surat Barang] Submit error:', err);
    });
}

function openDamageReportModal(presetAssetId, presetUnit){
  let selectedAssetId = presetAssetId ? String(presetAssetId) : (DB.inventory && DB.inventory.length ? String(DB.inventory[0].id) : null);
  let selectedUnitNo = presetUnit ? parseInt(presetUnit, 10) : 1;
  let searchQ = '';

  const renderAssetList = (q = '') => {
    const qLower = q.toLowerCase().trim();
    let items = sortInventoryItems(DB.inventory || []);
    if(qLower){
      items = items.filter(x => (x.name + ' ' + (x.code||'') + ' ' + (x.brand||'') + ' ' + (x.model||'') + ' ' + (x.sn||'') + ' ' + (x.cat||'')).toLowerCase().includes(qLower));
    }
    if(!items.length){
      return `<p class="t-sm muted" style="text-align:center;padding:16px 0">Tidak ada alat yang cocok dengan pencarian.</p>`;
    }
    return items.map(x => {
      const isSel = String(x.id) === String(selectedAssetId);
      const total = Number(x.qty_total || x.qty || 1);
      return `
        <div class="damage-asset-item" data-damage-asset-pick="${esc(x.id)}" style="display:flex;align-items:center;gap:10px;padding:8px 12px;border-radius:var(--r-m);border:1.5px solid ${isSel ? 'var(--b-500)' : 'var(--line)'};background:${isSel ? 'var(--b-050)' : 'var(--surface)'};margin-bottom:6px;cursor:pointer;transition:.15s">
          <div style="width:20px;height:20px;border-radius:6px;border:1.5px solid ${isSel ? 'var(--b-600)' : 'var(--line-2)'};background:${isSel ? 'var(--b-600)' : 'transparent'};color:#fff;display:grid;place-items:center;font-size:11px;flex-shrink:0">
            ${isSel ? '<i class="fa-solid fa-check"></i>' : ''}
          </div>
          ${itemThumbHTML(x)}
          <div style="flex:1;min-width:0">
            <div style="display:flex;align-items:center;gap:6px">
              <span class="t-md trunc" style="font-weight:650">${esc(x.name)}</span>
              <span class="chip blue" style="font-size:10px;padding:1px 6px">${esc(x.code || 'INV')}</span>
            </div>
            <div class="t-xs muted trunc" style="margin-top:2px">
              ${total} unit fisik · ${esc(x.brand || '—')} · Lokasi: ${esc(x.loc || 'Studio')}
            </div>
          </div>
          <div>${chip(x.status)}</div>
        </div>
      `;
    }).join('');
  };

  const renderUnitSelector = () => {
    if(!selectedAssetId) return '';
    const it = itemById(selectedAssetId);
    if(!it) return '';
    const total = Number(it.qty_total || it.qty || 1);
    const invCode = it.code || ('INV-' + String(it.id).padStart(3, '0'));
    const rawUnits = it.unit_conditions || [];
    const units = (rawUnits.length ? rawUnits : Array.from({length: total}, (_, i)=>({unit: i+1, cond: it.cond||'Baik'})));

    return `
      <div class="field mt12" style="background:var(--bg-2);border:1px solid var(--line-2);border-radius:var(--r-m);padding:12px">
        <label style="font-weight:700;display:flex;align-items:center;justify-content:space-between;margin-bottom:8px">
          <span>Pilih Unit Fisik yang Bermasalah</span>
          <span class="chip blue" style="font-size:10px;padding:1px 6px">${total} Unit Terdaftar</span>
        </label>
        <div style="display:grid;grid-template-columns:repeat(auto-fill, minmax(130px, 1fr));gap:8px">
          ${units.map(u => {
            const uNo = Number(u.unit || 1);
            const uCode = getUnitBarcode(invCode, uNo);
            const isUnitSel = uNo === Number(selectedUnitNo);
            const uCond = u.cond || 'Baik';
            const uDisplayName = getUnitDisplayName(u, uNo);
            return `
              <div class="damage-unit-item" data-damage-unit-pick="${uNo}" style="padding:8px 10px;border-radius:var(--r-s);background:${isUnitSel ? 'var(--b-050)' : 'var(--surface)'};border:1.5px solid ${isUnitSel ? 'var(--b-600)' : 'var(--line)'};cursor:pointer;display:flex;align-items:center;justify-content:space-between;gap:6px;transition:.15s">
                <div style="min-width:0;flex:1;">
                  <div style="display:flex;align-items:center;gap:4px;margin-bottom:2px;">
                    ${renderUnitBranding(u, { size: 'xs' })}
                  </div>
                  <div style="font-weight:700;font-size:12px;color:var(--ink)">${esc(uDisplayName)}</div>
                  <div style="font-size:11px;font-weight:600;color:var(--b-600);">${esc(uCode)}</div>
                </div>
                <div style="text-align:right">
                  ${chip(uCond)}
                </div>
              </div>
            `;
          }).join('')}
        </div>
      </div>
    `;
  };

  const renderSelectedBanner = () => {
    if(!selectedAssetId) return '';
    const it = itemById(selectedAssetId);
    if(!it) return '';
    const invCode = it.code || ('INV-' + String(it.id).padStart(3, '0'));
    const uCode = getUnitBarcode(invCode, selectedUnitNo);
    const rawUnits = it.unit_conditions || [];
    const uObj = rawUnits.find(u => Number(u.unit) === Number(selectedUnitNo));
    const uCond = uObj?.cond || it.cond || 'Baik';
    const uDisplayName = getUnitDisplayName(uObj, selectedUnitNo);
    return `
      <div style="display:flex;align-items:center;gap:12px;padding:10px 14px;border-radius:var(--r-m);background:var(--b-050);border:1.5px solid var(--b-400);margin-bottom:12px">
        ${itemThumbHTML(it)}
        <div style="flex:1;min-width:0">
          <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;">
            <div class="t-sm" style="font-weight:750;color:var(--ink)">${esc(it.name)} &mdash; <span style="color:var(--b-700)">${esc(uDisplayName)}</span></div>
            ${renderUnitBranding(uObj || { nama_unit: uDisplayName }, { size: 'xs' })}
          </div>
          <div class="t-xs muted" style="margin-top:2px">Kode Unit: <b>${esc(uCode)}</b> · Induk: <b>${esc(invCode)}</b> · Kondisi: ${chip(uCond)}</div>
        </div>
        <span class="chip blue" style="font-weight:700;font-size:11px">${esc(uDisplayName)}</span>
      </div>
    `;
  };

  openSheet('Lapor Masalah & Kerusakan Alat',
    `<div id="damageSelectedBannerWrap">${renderSelectedBanner()}</div>
     <div class="field" id="damageAssetSelectorSection" style="margin-bottom:12px">
       <label style="font-weight:650">Pilih Alat &amp; Unit Fisik</label>
       <div class="searchbar mb8">${ic.search}<input id="damageAssetSearchIn" placeholder="Cari nama alat, kode (INV-xxx), brand..." autocomplete="off"></div>
       <div id="damageAssetListWrap" style="max-height:180px;overflow-y:auto;border:1px solid var(--line-2);border-radius:var(--r-m);padding:6px;background:var(--bg-2)">
         ${renderAssetList()}
       </div>
       <div id="damageUnitSelectorWrap">${renderUnitSelector()}</div>
     </div>
     ${field('Kendala / Masalah Utama', `<input class="input" id="f_dmg_title" placeholder="Contoh: Layar flickering, autofocus macet, port kendor" required>`)}
     ${field('Keterangan & Kronologi Masalah', `<textarea class="input" id="f_dmg_desc" placeholder="Sudah dicoba apa saja? Sejak kapan mulai bermasalah?"></textarea>`)}
     ${field('Foto Kondisi Fisik (Kamera / Galeri)', renderPhotoUploadWidget('dmg_photo', '', 'Ambil Foto Kerusakan / Pilih dari Galeri', {
       pageContext: 'lapor_kerusakan',
       camLabel: 'Kamera',
       galLabel: 'Galeri / File',
       camIcon: 'fa-solid fa-camera',
       galIcon: 'fa-regular fa-images',
       capture: 'environment'
     }))}`,
    {
      foot: `<button class="btn block dang" data-act="submitDamageReport" style="background:#dc2626;color:#ffffff;border:none;box-shadow:0 2px 6px rgba(220,38,38,0.28);">${ic.send}Kirim Laporan Kerusakan Unit</button>`,
      then: (sheetBody) => {
        bindPhotoUploadWidget(sheetBody, 'dmg_photo');
        const assetSearchIn = $('#damageAssetSearchIn', sheetBody);
        const assetListWrap = $('#damageAssetListWrap', sheetBody);
        const unitWrap = $('#damageUnitSelectorWrap', sheetBody);
        const bannerWrap = $('#damageSelectedBannerWrap', sheetBody);

        const refreshUI = () => {
          if(bannerWrap) bannerWrap.innerHTML = renderSelectedBanner();
          if(assetListWrap) assetListWrap.innerHTML = renderAssetList(assetSearchIn ? assetSearchIn.value : '');
          if(unitWrap) unitWrap.innerHTML = renderUnitSelector();
        };

        if(assetSearchIn){
          assetSearchIn.addEventListener('input', () => {
            if(assetListWrap) assetListWrap.innerHTML = renderAssetList(assetSearchIn.value);
          });
        }

        sheetBody.addEventListener('click', (ev) => {
          const assetPick = ev.target.closest('[data-damage-asset-pick]');
          if(assetPick){
            selectedAssetId = assetPick.dataset.damageAssetPick;
            selectedUnitNo = 1;
            haptic(6);
            refreshUI();
            return;
          }

          const unitPick = ev.target.closest('[data-damage-unit-pick]');
          if(unitPick){
            selectedUnitNo = parseInt(unitPick.dataset.damageUnitPick, 10) || 1;
            haptic(6);
            refreshUI();
            return;
          }
        });
      }
    }
  );

  window._activeDamageSelected = { get assetId(){ return selectedAssetId; }, get unitNo(){ return selectedUnitNo; } };
}

function submitDamageReport(){
  const itId = window._activeDamageSelected?.assetId;
  const unitNo = window._activeDamageSelected?.unitNo || 1;
  const it = itemById(itId);
  if(!it){
    toast('Pilih alat terlebih dahulu.', 'info');
    return;
  }
  const titleVal = ($('#f_dmg_title')?.value || '').trim();
  if(!titleVal){
    toast('Tulis kendala / masalah utama alat.', 'info');
    $('#f_dmg_title')?.focus();
    return;
  }
  const descVal = $('#f_dmg_desc')?.value || '—';
  const photoVal = $('#dmg_photo')?.value || '';
  const invCode = it.code || ('INV-' + String(it.id).padStart(3, '0'));
  const unitCode = getUnitBarcode(invCode, unitNo);
  const rawUnits = it.unit_conditions || [];
  const uObj = rawUnits.find(u => Number(u.unit) === Number(unitNo));
  const uDisplayName = getUnitDisplayName(uObj, unitNo);
  const uId = uObj?.unit_id || uObj?.id || '';

  const tempId = 'tmp_' + Date.now();
  const prevItStatus = it.status;
  const prevItCond = it.cond;

  // Optimistic update
  DB.damages.unshift({
    id: tempId,
    item: it.id,
    unit_no: unitNo,
    unit_code: unitCode,
    unit_name: uDisplayName,
    title: titleVal,
    desc: descVal,
    by: ME.name,
    date: iso(today),
    status: 'Baru',
    photo: photoVal
  });

  // Update specific unit condition if available
  const totalQty = Number(it.qty_total || it.qty || 1);
  if(!Array.isArray(it.unit_conditions) || !it.unit_conditions.length){
    it.unit_conditions = Array.from({length: totalQty}, (_, i)=>({unit: i+1, cond: 'Baik', sn: it.sn ? `${it.sn}-${i+1}` : ''}));
  }
  const uIdx = it.unit_conditions.findIndex(u => Number(u.unit) === Number(unitNo));
  if(uIdx !== -1){
    it.unit_conditions[uIdx].cond = 'Rusak';
  } else {
    it.unit_conditions.push({ unit: Number(unitNo), cond: 'Rusak', sn: '' });
  }

  // Recalculate dynamic status from physical units
  const dmgSummary = getAssetUnitSummary(it);
  it.qty_available = dmgSummary.available;
  it.qty_damaged = dmgSummary.damaged;
  it.status = dmgSummary.masterStatus;

  pushNotif('Laporan kerusakan dibuat', `${it.name} [${uDisplayName}] — ${titleVal}`, 'wrench', '#kerusakan');
  closeSheet();
  render();

  const fd = new FormData();
  fd.append('action', 'ptv_submit_lapor_masalah');
  fd.append('alat_id', it.id);
  fd.append('nama_alat', it.name);
  fd.append('unit_no', unitNo);
  fd.append('unit_code', unitCode);
  fd.append('unit_name', uDisplayName);
  if(uId) fd.append('unit_id', uId);
  fd.append('pelapor_nama', ME.name);
  fd.append('masalah', titleVal);
  fd.append('keterangan', descVal);
  fd.append('foto_url', photoVal);

  fetch(AJAX_URL, { method: 'POST', body: fd })
    .then(r => r.json())
    .then(res => {
      if(res.success && (res.data?.report_id || res.data?.id)){
        const realId = res.data.report_id || res.data.id;
        const idx = DB.damages.findIndex(d => d.id === tempId);
        if(idx !== -1){
          DB.damages[idx].id = realId;
          if(res.data.record?.foto_url) DB.damages[idx].photo = res.data.record.foto_url;
        }
        toast(`Laporan kerusakan ${uDisplayName} (${unitCode}) berhasil disimpan ke database.`, 'check');
      } else {
        DB.damages = DB.damages.filter(d => d.id !== tempId);
        it.status = prevItStatus;
        it.cond = prevItCond;
        toast(res.data?.message || res.data || 'Gagal menyimpan laporan ke database.', 'error');
        render();
      }
    })
    .catch(() => {
      DB.damages = DB.damages.filter(d => d.id !== tempId);
      it.status = prevItStatus;
      it.cond = prevItCond;
      toast('Koneksi gagal. Laporan tidak tersimpan.', 'error');
      render();
    });
}

function openForm(kind, preset, unitPreset){
  if(kind === 'catatan' || kind === 'note'){
    openNewNote(preset);
    return;
  }
  if(kind === 'pinjam'){
    try {
      openLoanModal(preset, unitPreset);
    } catch(e) {
      console.error('openLoanModal error:', e);
      toast('Gagal membuka form pinjam: ' + (e?.message || e), 'alert');
    }
    return;
  }
  if(kind === 'lapor'){
    openDamageReportModal(preset, unitPreset);
    return;
  }
  if(kind === 'izin'){
    if(state.role === 'eksekutif'){
      go('generatorIzin');
    } else {
      go('perizinan');
    }
    return;
  }
  if(kind === 'tugas'){
    openSuratTugasModal();
    return;
  }
  if(kind === 'barang'){
    openSuratBarangModal(preset);
    return;
  }

  const dateIn = (id,val)=>`<input class="input" type="date" id="${id}" value="${val||iso(today)}">`;
  const forms = {
    hilang:{
      title:'Laporkan Barang Hilang',
      body:
        field('Nama Barang', `<input class="input" id="f_name" placeholder="Contoh: Baterai NP-FZ100 / Tutup Lensa" required>`)+
        `<div class="grid-2">${field('Terakhir Terlihat di',`<input class="input" id="f_loc" placeholder="Lokasi terakhir">`)}${field('Tanggal',dateIn('f_date'))}</div>`+
        field('Ciri-Ciri & Identitas', `<textarea class="input" id="f_desc" placeholder="Warna, stiker identitas, kondisi, dll"></textarea>`)+
        field('Foto Referensi (Kamera / Galeri)', renderPhotoUploadWidget('lf_photo', '', 'Ambil Foto / Pilih dari Galeri', {
          pageContext: 'lf_hilang',
          camLabel: 'Foto Barang',
          galLabel: 'Pilih dari Galeri',
          camIcon: 'fa-solid fa-camera',
          galIcon: 'fa-regular fa-images',
          capture: 'environment'
        })),
      submit:'Kirim Laporan Kehilangan',
      done:'Laporan kehilangan tersimpan di database Supabase.'
    },

    temuan:{
      title:'Laporkan Barang Temuan',
      body:
        field('Nama Barang', `<input class="input" id="f_name" placeholder="Contoh: Flashdisk Sandisk 64GB" required>`)+
        `<div class="grid-2">${field('Ditemukan di Lokasi',`<input class="input" id="f_loc" placeholder="Lokasi penemuan">`)}${field('Tanggal',dateIn('f_date'))}</div>`+
        field('Ciri Barang & Lokasi Simpan Saat Ini', `<textarea class="input" id="f_desc" placeholder="Ciri barang dan disimpan di mana saat ini..."></textarea>`)+
        field('Foto Barang Temuan (Kamera / Galeri)', renderPhotoUploadWidget('lf_photo', '', 'Ambil Foto / Pilih dari Galeri', {
          pageContext: 'lf_temuan',
          camLabel: 'Foto Temuan',
          galLabel: 'Pilih dari Galeri',
          camIcon: 'fa-solid fa-camera',
          galIcon: 'fa-regular fa-images',
          capture: 'environment'
        })),
      submit:'Kirim Laporan Temuan',
      done:'Barang temuan tersimpan di database Supabase.'
    }
  };

  const f = forms[kind];
  if(!f) return;

  openSheet(f.title, f.body, {
    foot:`<button class="btn block pri" data-act="submitForm:${kind}">${ic.send}${f.submit}</button>`,
    then:(b)=>{
      bindPhotoUploadWidget(b, 'lf_photo');
    }
  });
}

function submitForm(kind){
  // 1. Izin & Dokumen
  if(kind==='izin' || kind==='tugas' || kind==='barang'){
    const f = {
      izin:{type:'Izin Santri',done:'Pengajuan izin berhasil dikirim.',subject:$('#f_sub')?.value||'Izin santri'},
      tugas:{type:'Surat Tugas',done:'Surat tugas diajukan, menunggu review.',subject:$('#f_sub')?.value||'Surat tugas',event:$('#f_event')?.value||''},
      barang:{type:'Izin Membawa Barang',done:'Izin membawa barang diajukan.',subject:$('#f_sub')?.value||'Izin membawa barang'},
    }[kind];

    if(!f.subject || f.subject.trim()===''){toast('Isi perihalnya dulu.','info');return}

    const fd = new FormData();
    fd.append('action', 'ptv_dashboard_action_submit_doc');
    fd.append('type', f.type);
    fd.append('subject', f.subject);
    fd.append('notes', $('#f_note')?.value || '');
    fd.append('event_id', f.event || '');
    fd.append('start_date', $('#f_start')?.value || iso(today));
    fd.append('end_date', $('#f_end')?.value || iso(today));
    fd.append('crew_id', $('#f_crew')?.value || '');
    fd.append('item_id', $('#f_item')?.value || '');

    const submitBtn = document.querySelector(`[data-act="submitForm:${kind}"]`);
    const origBtnHtml = submitBtn ? submitBtn.innerHTML : '';
    if (submitBtn) {
      submitBtn.disabled = true;
      submitBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin" style="margin-right:6px"></i>Mengirim...';
    }

    fetch(AJAX_URL, { method:'POST', body:fd })
      .then(r=>r.json())
      .then(res=>{
        if (res.success && res.data) {
          const no = res.data.no || '— (Menunggu Pengesahan)';
          const docId = res.data.id || (res.data.record && res.data.record.id);
          DB.docs.unshift({
            id: docId,
            owner: ME.name,
            date: iso(today),
            status: res.data.status || 'Menunggu',
            event: f.event || '',
            type: f.type,
            no: no,
            subject: f.subject
          });
          pushNotif('Pengajuan terkirim', f.type + ' · Menunggu Pengesahan', 'doc', '#dokumen');
          closeSheet();
          toast(f.done, 'check');
          render();
          if (typeof syncPerizinanLive === 'function') syncPerizinanLive(true);
        } else {
          if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerHTML = origBtnHtml;
          }
          toast(res.data?.message || res.data || 'Gagal mengirim pengajuan.', 'alert');
        }
      })
      .catch((err)=>{
        if (submitBtn) {
          submitBtn.disabled = false;
          submitBtn.innerHTML = origBtnHtml;
        }
        toast('Terjadi kendala jaringan saat mengirim pengajuan.', 'alert');
        console.error('[PTV Docs] Submit error:', err);
      });
    return;
  }

  // 2. Pinjam Alat (Single fallback jika dipanggil biasa)
  if(kind==='pinjam'){
    submitMultiLoan();
    return;
  }

  // 3. Lapor Masalah
  if(kind==='lapor'){
    submitDamageReport();
    return;
  }

  // 4. Lost & Found
  if(kind==='hilang' || kind==='temuan'){
    const n = ($('#f_name')?.value || '').trim();
    if(!n){
      toast('Tulis nama barangnya dulu.', 'info');
      return;
    }
    const locVal = ($('#f_loc')?.value || '').trim() || 'Studio PTV';
    const dateVal = $('#f_date')?.value || iso(today);
    const descVal = ($('#f_desc')?.value || '').trim() || '—';
    const photoVal = $('#lf_photo')?.value || '';
    const tipeVal = (kind === 'temuan') ? 'penemuan' : 'kehilangan';

    const submitBtn = document.querySelector(`[data-act="submitForm:${kind}"]`);
    const origBtnHtml = submitBtn ? submitBtn.innerHTML : '';
    if (submitBtn) {
      submitBtn.disabled = true;
      submitBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin" style="margin-right:6px"></i>Menyimpan...';
    }

    const fd = new FormData();
    fd.append('action', 'ptv_submit_lost_found');
    fd.append('tipe', tipeVal);
    fd.append('nama_barang', n);
    fd.append('lokasi', locVal);
    fd.append('tanggal', dateVal);
    fd.append('keterangan', descVal);
    fd.append('foto_url', photoVal);
    fd.append('pelapor_nama', ME.name || 'Kru PTV');
    fd.append('pelapor_kontak', ME.phone || '');

    fetch(AJAX_URL, { method:'POST', body:fd })
      .then(r => r.json())
      .then(res => {
        if(res.success && (res.data?.id || res.data?.record?.id)){
          const realId = res.data.id || res.data.record.id;
          const photoFinal = res.data.record?.foto_url || photoVal;
          const newLost = {
            id: realId,
            kind: (kind === 'temuan' ? 'temuan' : 'hilang'),
            name: n,
            loc: locVal,
            date: dateVal,
            desc: descVal,
            by: ME.name || 'Kru PTV',
            status: (kind === 'temuan' ? 'Ditemukan' : 'Dicari'),
            photo: photoFinal
          };
          DB.lost.unshift(newLost);
          pushNotif('Lost & Found diperbarui', n + ' · ' + (kind === 'temuan' ? 'Ditemukan' : 'Dicari'), 'lost', '#lostfound');
          toast(kind==='temuan' ? 'Barang temuan berhasil disimpan ke Supabase.' : 'Laporan kehilangan berhasil disimpan ke Supabase.', 'check');
          closeSheet();
          render();
          if (typeof requestSyncScope === 'function') requestSyncScope('lost', true);
        } else {
          if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerHTML = origBtnHtml;
          }
          toast(res.data?.message || res.data || 'Gagal menyimpan Lost & Found ke Supabase.', 'error');
        }
      })
      .catch((err) => {
        if (submitBtn) {
          submitBtn.disabled = false;
          submitBtn.innerHTML = origBtnHtml;
        }
        toast('Koneksi gagal. Laporan tidak tersimpan.', 'error');
        console.error('[PTV Lost] Save error:', err);
      });
    return;
  }
}

/**
 * pushNotif: tambah notifikasi ke DB.notifs lokal + persist ke Supabase backend.
 * TIDAK menggunakan fallback user - jika sesi tidak valid, hanya simpan lokal.
 */
function pushNotif(t, s, kind, go) {
  // Tambah ke memori lokal (segera tampil di badge)
  const localId = ID();
  DB.notifs.unshift({ id: localId, t, s, when: 'Baru saja', kind, unread: true, go });

  // Update badge
  const badge = document.getElementById('notif-badge');
  const cnt = unreadCount();
  if (badge) { badge.textContent = cnt > 9 ? '9+' : cnt; badge.style.display = cnt > 0 ? '' : 'none'; }

  // Persist ke backend (fire-and-forget, tanpa memblokir UI)
  if (typeof AJAX_URL !== 'undefined') {
    const fd = new FormData();
    fd.append('action', 'ptv_push_local_notification');
    fd.append('title', t);
    fd.append('message', s);
    fd.append('kind', kind);
    fd.append('go', go || '');
    fd.append('nonce', typeof PTV_NONCE !== 'undefined' ? PTV_NONCE : '');
    fetch(AJAX_URL, { method: 'POST', body: fd, credentials: 'same-origin' }).catch(() => {});
  }
}


