  openSheet('Buat pengumuman',
    field('Judul',`<input class="input" id="an_t" placeholder="Judul pengumuman">`)+
    field('Isi',`<textarea class="input" id="an_b" placeholder="Tulis isi pengumuman"></textarea>`)+
    field('Prioritas',selectOf('an_p',[['normal','Normal'],['penting','Penting']])),
    {foot:`<button class="btn block pri" data-act="saveAnn">${ic.send}Terbitkan</button>`});
}

function openScheduleMeeting(){
  const sDate = calSel || iso(today);
  const hInit = getHijriInfo(sDate);
  const wInit = getWetonInfo(sDate);
  openSheet('Jadwalkan Acara Baru',
    field('Nama Kegiatan / Acara', `<input class="input" id="sm_name" placeholder="Contoh: Liputan Kegiatan / Rapat Koordinasi Tim">`) +
    field('Lokasi', `<input class="input" id="sm_loc" placeholder="Studio / Ruang Rapat / Lapangan" value="Studio Progresif TV">`) +
    `<div class="grid-2">
      ${field('Tanggal', `<input class="input" id="sm_start" type="date" value="${sDate}"><div id="sm_date_badge" style="margin-top:6px;display:flex;gap:6px;flex-wrap:wrap"><span class="cal-badge-hijri" style="font-size:10.5px;padding:2px 7px"><i class="fa-solid fa-moon" style="font-size:9px"></i><span id="sm_hijri_txt">${esc(hInit.full)}</span></span><span class="cal-badge-weton" style="font-size:10.5px;padding:2px 7px"><i class="fa-solid fa-sun" style="font-size:9px"></i><span id="sm_weton_txt">${esc(wInit.full)}</span></span></div>`)}
      ${field('Waktu', `<input class="input" id="sm_time" placeholder="08:00 – 12:00" value="08:00 – 12:00">`)}
    </div>` +
    field('Catatan / Rundown Singkat', `<textarea class="input" id="sm_notes" placeholder="Tuliskan catatan teknis atau agenda acara..."></textarea>`),
    {
      foot:`<button class="btn block pri" data-act="saveMeeting">${ic.check}Jadwalkan Acara</button>`,
      then:(b)=>{
        const dtIn = $('#sm_start', b);
        if(dtIn){
          dtIn.addEventListener('input', ()=>{
            const val = dtIn.value;
            const h = getHijriInfo(val);
            const w = getWetonInfo(val);
            const hEl = $('#sm_hijri_txt', b);
            const wEl = $('#sm_weton_txt', b);
            if(hEl) hEl.textContent = h.full;
            if(wEl) wEl.textContent = w.full;
          });
        }
      }
    }
  );
}

function saveMeeting(){
  const name = ($('#sm_name')?.value||'').trim();
  if(!name){ toast('Isi nama kegiatan dulu ya.','info'); return; }
  const startDate = $('#sm_start')?.value || calSel || iso(today);
  const loc = ($('#sm_loc')?.value||'').trim() || 'Studio PTV';
  const time = ($('#sm_time')?.value||'').trim() || '08:00 – 12:00';
  const notes = $('#sm_notes')?.value || '';

  const tempEvId = ID();
  const newEv = {
    id: tempEvId,
    name,
    date: startDate,
    time,
    loc,
    crew: [ME.name],
    gear: [],
    cat: 'Produksi',
    status: 'Terjadwal',
    notes
  };

  DB.events.unshift(newEv);
  calSel = startDate;

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_save_event');
  fd.append('name', name);
  fd.append('loc', loc);
  fd.append('date', startDate);
  fd.append('time', time);
  fd.append('notes', notes);
  fd.append('status', 'terjadwal');

  closeSheet();

  fetch(AJAX_URL, { method: 'POST', body: fd })
    .then(r => r.json())
    .then(res => {
      if (res.success && (res.data?.event || res.data?.event_id)) {
        const ev = DB.events.find(e => e.id === tempEvId);
        if (ev) {
          if (res.data.event) Object.assign(ev, res.data.event);
          else if (res.data.event_id) ev.id = String(res.data.event_id);
        }
        pushNotif('Kegiatan dijadwalkan', `${name} · ${fmtDate(startDate)}`, 'event', '#acaraDetail:' + (res.data.event_id || tempEvId));
        toast('Acara berhasil disimpan ke jadwal!', 'check');
      } else {
        DB.events = DB.events.filter(e => e.id !== tempEvId);
        toast(res.data?.message || 'Gagal menyimpan acara ke database.', 'error');
      }
      if(state.route.page === 'kalender' && document.getElementById('acaraContent')){
        updateAcaraSubView('kalender');
      } else if(state.route.page === 'acara' && document.getElementById('acaraContent')){
        updateAcaraSubView('acara');
      } else {
        render();
      }
    })
    .catch(err => {
      DB.events = DB.events.filter(e => e.id !== tempEvId);
      toast('Terjadi kendala koneksi. Acara belum tersimpan.', 'error');
      if(state.route.page === 'kalender' && document.getElementById('acaraContent')){
        updateAcaraSubView('kalender');
      } else if(state.route.page === 'acara' && document.getElementById('acaraContent')){
        updateAcaraSubView('acara');
      } else {
        render();
      }
    });

  if(state.route.page === 'kalender' && document.getElementById('acaraContent')){
    updateAcaraSubView('kalender');
  } else if(state.route.page === 'acara' && document.getElementById('acaraContent')){
    updateAcaraSubView('acara');
  } else {
    render();
  }
}

