function getCategoryDropdownItems(){
  return INVENTORY_CATEGORIES.map(cat => {
    const cfg = INVENTORY_CATEGORY_CONFIG[cat] || INVENTORY_CATEGORY_CONFIG['Lainnya'];
    return {
      value: cat,
      label: cat,
      icon: cfg.icon,
      color: cfg.color,
      bg: cfg.bg,
    };
  });
}

function getLocationDropdownItems(locs){
  const items = (locs || []).map(l => {
    let icon = 'fa-solid fa-location-dot';
    let color = '#0284c7';
    let bg = '#e0f2fe';
    const lower = l.toLowerCase();
    if(lower.includes('studio')) { icon = 'fa-solid fa-building'; color = '#2563eb'; bg = '#dbeafe'; }
    else if(lower.includes('kotak') || lower.includes('box')) { icon = 'fa-solid fa-box'; color = '#d97706'; bg = '#fef3c7'; }
    else if(lower.includes('lemari')) { icon = 'fa-solid fa-archive'; color = '#7c3aed'; bg = '#ede9fe'; }
    else if(lower.includes('gudang')) { icon = 'fa-solid fa-warehouse'; color = '#475569'; bg = '#f1f5f9'; }
    return {
      value: l,
      label: l,
      icon,
      color,
      bg
    };
  });
  items.push({
    value: '__NEW__',
    label: '+ Tambah Lokasi Baru…',
    icon: 'fa-solid fa-plus-circle',
    color: '#0284c7',
    bg: '#f0f9ff',
    isSpecial: true
  });
  return items;
}

function getSourceDropdownItems(sources, canManage){
  const items = (sources || []).map(s => {
    let icon = 'fa-solid fa-file-invoice-dollar';
    let color = '#059669';
    let bg = '#d1fae5';
    const lower = s.toLowerCase();
    if(lower.includes('yayasan')) { icon = 'fa-solid fa-landmark'; color = '#2563eb'; bg = '#dbeafe'; }
    else if(lower.includes('donasi')) { icon = 'fa-solid fa-hand-holding-heart'; color = '#db2777'; bg = '#fce7f3'; }
    else if(lower.includes('hibah')) { icon = 'fa-solid fa-award'; color = '#d97706'; bg = '#fef3c7'; }
    else if(lower.includes('kas')) { icon = 'fa-solid fa-wallet'; color = '#0284c7'; bg = '#e0f2fe'; }
    return {
      value: s,
      label: s,
      icon,
      color,
      bg
    };
  });
  if(canManage){
    items.push({
      value: '__NEW_SOURCE__',
      label: '+ Tambah Sumber…',
      icon: 'fa-solid fa-plus-circle',
      color: '#059669',
      bg: '#ecfdf5',
      isSpecial: true
    });
  }
  return items;
}

function getStatusDropdownItems(){
  return Object.keys(INVENTORY_STATUS_CONFIG).map(k => {
    const cfg = INVENTORY_STATUS_CONFIG[k];
    return {
      value: k,
      label: cfg.label,
      desc: cfg.desc,
      icon: cfg.icon,
      color: cfg.color,
      bg: cfg.bg
    };
  });
}

function renderInvCustomDropdown(id, items, selectedVal, placeholder = 'Pilih opsi...'){
  selectedVal = selectedVal || (items[0] ? items[0].value : '');
  const activeItem = items.find(it => it.value === selectedVal) || items[0] || { value: '', label: placeholder, icon: 'fa-solid fa-circle', color: '#64748b', bg: '#f1f5f9' };

  return `
    <div class="inv-custom-dropdown" data-dd-id="${id}">
      <select class="input" id="${id}" style="display:none !important;" tabindex="-1">
        ${items.map(it => `<option value="${esc(it.value)}" ${it.value === selectedVal ? 'selected' : ''}>${esc(it.label || it.value)}</option>`).join('')}
      </select>
      <button type="button" class="inv-dropdown-trigger" aria-haspopup="listbox" aria-expanded="false">
        <div class="inv-dd-val">
          <span class="inv-dd-icon-box" style="background:${activeItem.bg || '#f1f5f9'};color:${activeItem.color || '#64748b'};">
            <i class="${activeItem.icon || 'fa-solid fa-circle'}"></i>
          </span>
          <span class="inv-dd-text">${esc(activeItem.label || activeItem.value)}</span>
        </div>
        <i class="fa-solid fa-chevron-down inv-dd-chevron"></i>
      </button>
      <div class="inv-dropdown-menu" role="listbox">
        ${items.map(it => `
          <div class="inv-dropdown-item ${it.value === selectedVal ? 'is-selected' : ''} ${it.isSpecial ? 'is-special-action' : ''}" 
               data-val="${esc(it.value)}" role="option"
               ${it.isSpecial ? 'style="border-top:1.5px dashed #cbd5e1;margin-top:4px;padding-top:8px;color:#2563eb;font-weight:700;"' : ''}>
            <div class="inv-dd-item-left">
              <span class="inv-dd-item-icon" style="background:${it.bg || '#f1f5f9'};color:${it.color || '#64748b'};">
                <i class="${it.icon || 'fa-solid fa-circle'}"></i>
              </span>
              <div class="inv-dd-item-info">
                <div class="inv-dd-item-title">${esc(it.label || it.value)}</div>
                ${it.desc ? `<div class="inv-dd-item-sub">${esc(it.desc)}</div>` : ''}
              </div>
            </div>
            <span class="inv-dd-item-check" style="${it.value === selectedVal ? 'opacity:1;' : 'opacity:0;'}">
              <i class="fa-solid fa-check"></i>
            </span>
          </div>
        `).join('')}
      </div>
    </div>
  `;
}

