    { value: 'Rusak', label: 'Rusak', desc: 'Alat tidak berfungsi / fisik rusak', icon: 'fa-solid fa-triangle-exclamation', color: '#dc2626', bg: '#fee2e2' },
    { value: 'Hilang', label: 'Hilang', desc: 'Unit tidak diketahui keberadaannya', icon: 'fa-solid fa-circle-xmark', color: '#475569', bg: '#f1f5f9' },
  ];
