}

function updateCustomDropdownUI(dd, val){
  if(!dd) return;
  const select = dd.querySelector('select');
  if(select && select.value !== val) select.value = val;

  dd.querySelectorAll('.inv-dropdown-item').forEach(it => {
    const isSel = it.getAttribute('data-val') === val;
    it.classList.toggle('is-selected', isSel);
    const chk = it.querySelector('.inv-dd-item-check');
    if(chk) chk.style.opacity = isSel ? '1' : '0';
  });

  const selItem = dd.querySelector(`.inv-dropdown-item[data-val="${CSS.escape(val)}"]`);
  if(selItem){
    const title = selItem.querySelector('.inv-dd-item-title')?.textContent || val;
    const iconSpan = selItem.querySelector('.inv-dd-item-icon');
    const triggerText = dd.querySelector('.inv-dd-text');
    const triggerIconBox = dd.querySelector('.inv-dd-icon-box');
    if(triggerText) triggerText.textContent = title;
    if(triggerIconBox && iconSpan){
      triggerIconBox.innerHTML = iconSpan.innerHTML;
      triggerIconBox.style.background = iconSpan.style.background;
      triggerIconBox.style.color = iconSpan.style.color;
    }
  }
}

function updateUnitCondDropdownUI(dd, val){
  if(!dd) return;
  const select = dd.querySelector('.unit-cond-select');
  if(select && select.value !== val) select.value = val;

  const cfg = UNIT_COND_CONFIG[val] || UNIT_COND_CONFIG['Baik'];
  const pill = dd.querySelector('.unit-cond-trigger .unit-cond-val-pill');
  if(pill){
    pill.style.background = cfg.bg;
    pill.style.color = cfg.color;
    pill.innerHTML = `<i class="${cfg.icon}"></i> ${val}`;
  }

  dd.querySelectorAll('.unit-cond-item').forEach(it => {
    const isSel = it.getAttribute('data-val') === val;
    it.classList.toggle('is-selected', isSel);
    const chk = it.querySelector('.inv-dd-item-check');
    if(chk) chk.style.opacity = isSel ? '1' : '0';
  });
}

// Global click event delegation for custom dropdowns
document.addEventListener('click', (e) => {
  const trigger = e.target.closest('.inv-dropdown-trigger, .unit-cond-trigger');
  if(trigger){
    const dd = trigger.closest('.inv-custom-dropdown, .unit-cond-dropdown');
    if(!dd) return;
    const wasOpen = dd.classList.contains('is-open');
    document.querySelectorAll('.inv-custom-dropdown.is-open, .unit-cond-dropdown.is-open').forEach(d => {
      if(d !== dd){
        d.classList.remove('is-open');
        d.classList.remove('dropup');
        const r = d.closest('.unit-cond-row');
        if(r) r.classList.remove('has-open-dropdown');
      }
    });

    if(!wasOpen){
      dd.classList.add('is-open');
      const row = dd.closest('.unit-cond-row');
      if(row) row.classList.add('has-open-dropdown');

      // Smart flip: check available vertical space in sheet or viewport
      const menu = dd.querySelector('.inv-dropdown-menu, .unit-cond-menu');
      if(menu){
        const trgRect = trigger.getBoundingClientRect();
        const mHeight = menu.offsetHeight || 190;
        const sheetBody = dd.closest('.sheet-body');
        let shouldDropup = false;

        if(sheetBody){
          const bodyRect = sheetBody.getBoundingClientRect();
          const spaceBelow = bodyRect.bottom - trgRect.bottom;
          const spaceAbove = trgRect.top - bodyRect.top;
          if(spaceBelow < mHeight + 15 && spaceAbove > spaceBelow){
            shouldDropup = true;
          }
        } else {
          const spaceBelow = window.innerHeight - trgRect.bottom;
          const spaceAbove = trgRect.top;
          if(spaceBelow < mHeight + 15 && spaceAbove > spaceBelow){
            shouldDropup = true;
          }
        }
        dd.classList.toggle('dropup', shouldDropup);
      }
    } else {
      dd.classList.remove('is-open');
      dd.classList.remove('dropup');
      const row = dd.closest('.unit-cond-row');
      if(row) row.classList.remove('has-open-dropdown');
    }
    return;
  }

  const item = e.target.closest('.inv-dropdown-item');
  if(item){
    const dd = item.closest('.inv-custom-dropdown');
    if(!dd) return;
    const val = item.getAttribute('data-val');
    const select = dd.querySelector('select');
    if(select){
      select.value = val;
      select.dispatchEvent(new Event('change', { bubbles: true }));
    }
    updateCustomDropdownUI(dd, val);
    dd.classList.remove('is-open');
    dd.classList.remove('dropup');
    return;
  }

  const unitItem = e.target.closest('.unit-cond-item');
  if(unitItem){
    const dd = unitItem.closest('.unit-cond-dropdown');
    if(!dd) return;
    const val = unitItem.getAttribute('data-val');
    const select = dd.querySelector('.unit-cond-select');
    if(select){
      select.value = val;
      select.dispatchEvent(new Event('change', { bubbles: true }));
    }
    updateUnitCondDropdownUI(dd, val);
    dd.classList.remove('is-open');
    dd.classList.remove('dropup');
    const r = dd.closest('.unit-cond-row');
    if(r) r.classList.remove('has-open-dropdown');
    return;
  }

  if(!e.target.closest('.inv-dropdown-menu, .unit-cond-menu')){
    document.querySelectorAll('.inv-custom-dropdown.is-open, .unit-cond-dropdown.is-open').forEach(d => {
      d.classList.remove('is-open');
      d.classList.remove('dropup');
      const r = d.closest('.unit-cond-row');
      if(r) r.classList.remove('has-open-dropdown');
    });
  }
});

function getInventoryLocations(){
  const base = ['Studio PTV', 'Ruang Kontrol', 'Ruang Podcast', 'Lemari Kamera A1', 'Lemari Audio B2', 'Ruang Server / Technical', 'Gudang Inventaris'];
  const fromInv = (DB.inventory || []).map(x => (x.loc || '').trim()).filter(Boolean);
  const extra = DB.saved_locations || [];
  const set = new Set([...base, ...fromInv, ...extra]);
  return Array.from(set).filter(Boolean);
}

