              newLocIn?.focus();
            } else {
              newLocWrap.style.display = 'none';
            }
          });
        }
        if(sourceSel){
          sourceSel.addEventListener('change', ()=>{
            if(sourceSel.value === '__NEW_SOURCE__'){
              newSourceWrap.style.display = 'block';
              newSourceIn?.focus();
            } else {
              newSourceWrap.style.display = 'none';
            }
          });
        }

        const updateUnitBoxes = () => {
          const q = parseInt(qtyIn?.value || '1', 10);
          condBox.innerHTML = renderUnitConditionInputs(q, [], '');
        };

        if(qtyIn) qtyIn.addEventListener('input', updateUnitBoxes);

        b.addEventListener('click', (ev)=>{
          const btn = ev.target.closest('[data-set-all-units]');
          if(btn){
            const targetVal = btn.dataset.setAllUnits;
            b.querySelectorAll('.unit-cond-dropdown').forEach(dd => updateUnitCondDropdownUI(dd, targetVal));
            haptic(6);
          }
          const addUnitBtn = ev.target.closest('[data-add-unit-row]');
          if(addUnitBtn && qtyIn){
            const curQ = parseInt(qtyIn.value || '1', 10);
            qtyIn.value = curQ + 1;
            updateUnitBoxes();
            haptic(6);
          }
        });

        // Live real-time Supabase sequence sync
        fetch(AJAX_URL + '?action=ptv_dashboard_action_get_next_inv_code')
          .then(r => r.json())
          .then(res => {
            if(res.success && res.data?.next_code){
