        </div>

        <div class="grid-2 mt12">
          ${field('Tanggal Perolehan', `
            <input type="date" class="input" id="v_tanggal_perolehan" value="${esc(v.tanggal_perolehan || '')}" style="width:100%;box-sizing:border-box;">
          `)}

          <div class="field">
            <label>Status Aset</label>
            <select class="input" id="v_status" style="width:100%;box-sizing:border-box;">
              <option value="Aktif"${curStatus === 'Aktif' ? ' selected' : ''}>Aktif</option>
              <option value="Dihapusbukukan"${curStatus === 'Dihapusbukukan' ? ' selected' : ''}>Dihapusbukukan</option>
              <option value="Dihibahkan"${curStatus === 'Dihibahkan' ? ' selected' : ''}>Dihibahkan</option>
              <option value="Rusak Total"${curStatus === 'Rusak Total' ? ' selected' : ''}>Rusak Total</option>
              <option value="Dijual"${curStatus === 'Dijual' ? ' selected' : ''}>Dijual</option>
            </select>
          </div>
        </div>

        <div class="grid-2 mt12">
          <div class="field">
            <label>Sumber Pendanaan</label>
