function openEditCrew(id){
  const c = (DB.crew||[]).find(x=>String(x.id)===String(id));
  if(!c) return;
  const roles = [['kru','Kru'],['administrasi','Administrasi'],['eksekutif','Eksekutif / Koordinator']];

  const oauthStatusHelp = c.oauth_uid
    ? '<span style="color:#10b981;font-weight:600"><i class="fa-solid fa-circle-check"></i> Terhubung</span> — Akun Google aktif terhubung.'
    : (c.oauth_email
        ? '<span style="color:#f59e0b;font-weight:600"><i class="fa-solid fa-clock"></i> Google Terdaftar</span> — Menunggu kru melakukan login Google pertama kali.'
        : '<span style="color:var(--muted)">Belum terhubung. Daftarkan email Google agar kru dapat login dengan akun Google miliknya.</span>');

  openSheet('Edit Data Kru',
    `<div id="new_crew_error" style="display:none;margin-bottom:12px;padding:10px 14px;background:rgba(239,68,68,0.12);border:1px solid rgba(239,68,68,0.3);border-radius:10px;color:#f87171;font-size:12.5px;font-weight:600"></div>` +
    field('Nama Lengkap', `<input class="input" id="cr_name" value="${esc(c.name)}">`) +
    `<div class="grid-2">
      ${field('ID PTV / Nomor Anggota', `<input class="input" id="cr_ptv_id" value="${esc(c.ptvId || '')}" placeholder="PTV-xxx">`)}
      ${field('Username Login', `<input class="input" id="cr_un" value="${esc(c.username || '')}" placeholder="username">`)}
    </div>` +
    buildCrewCategoryField(c.div) +
    `<div class="grid-2">
      ${field('Jabatan / Peran', `<input class="input" id="cr_pos" value="${esc(c.pos)}">`)}
      ${field('Angkatan', `<input class="input" id="cr_angkatan" value="${esc(c.angkatan || '')}" placeholder="Contoh: 10, 11, 12">`)}
    </div>` +
    `<div class="grid-2">
      ${field('NIM / NISN', `<input class="input" id="cr_nim" value="${esc(c.nim || '')}">`)}
      ${field('Jurusan', `<input class="input" id="cr_jurusan" value="${esc(c.jurusan || '')}">`)}
    </div>` +
    `<div class="grid-2">
      ${field('No. WhatsApp', `<input class="input" id="cr_wa" value="${esc(c.phone)}">`)}
      ${field('Status Kru (Operasional)', selectOf('cr_stat', [['Aktif','Aktif (Bisa Ditugaskan)'],['Nonaktif','Nonaktif']]))}
    </div>` +
    `<div class="grid-2">
      ${field('Status Akun Portal', selectOf('cr_stat_akun', [['Aktif','Aktif (Bisa Login)'],['Nonaktif','Nonaktif (Tidak Bisa Login)']]))}
      ${field('Peran / Hak Akses Portal', selectOf('cr_role', roles))}
    </div>` +
    field('Email Google (OAuth SSO)', `
      <input class="input" id="cr_oauth_email" value="${esc(c.oauth_email || '')}" placeholder="contoh: kru@gmail.com" type="email">
      <div style="font-size:11.5px;margin-top:4px">${oauthStatusHelp}</div>
    `) +
    field('Reset Password (Biarkan kosong jika tidak diubah)', `<input class="input" id="cr_pw" placeholder="Password baru" type="password">`) +
    field('Foto Profil Kru (Kamera / Galeri)', renderPhotoUploadWidget('cr_photo', c.photo || c.foto_url || '', 'Ambil Foto / Pilih dari Galeri', {
      pageContext: 'kru_edit',
      camLabel: 'Ambil Foto',
      galLabel: 'Pilih dari Galeri',
      camIcon: 'fa-solid fa-camera',
      galIcon: 'fa-regular fa-image'
    })),
    {
      foot: `<div class="wrap" style="width:100%;display:flex;justify-content:space-between;gap:8px">
        <button class="btn dang" data-act="confirmDeleteCrew:${c.id}"><i class="fa-solid fa-trash"></i> Hapus Permanen</button>
        <button class="btn pri" id="btn_save_new_crew" data-act="saveEditCrew:${c.id}">${ic.check}Simpan Perubahan</button>
      </div>`,
      wide: true,
      then: (b)=>{
        bindPhotoUploadWidget(b, 'cr_photo');
        const sSel = $('#cr_stat', b); if(sSel) sSel.value = c.status;
        const aSel = $('#cr_stat_akun', b); if(aSel) aSel.value = c.accountStatus || (c.username ? 'Aktif' : 'Nonaktif');
        const rSel = $('#cr_role', b); if(rSel) rSel.value = c.role||'kru';
      }
    }
  );
}

function saveCrew(isEdit, id){
  const name = ($('#cr_name')?.value||'').trim();
  if(!name){ toast('Nama kru tidak boleh kosong.','info'); return; }
  const username = ($('#cr_un')?.value||'').trim().toLowerCase();
  const password = $('#cr_pw')?.value || '';
  const role = $('#cr_role')?.value || 'kru';
  const ptvId = ($('#cr_ptv_id')?.value||'').trim().toUpperCase();
  const angkatan = ($('#cr_angkatan')?.value||'').trim();
  const nim = ($('#cr_nim')?.value||'').trim();
  const jurusan = ($('#cr_jurusan')?.value||'').trim();
  const oauthEmail = ($('#cr_oauth_email')?.value||'').trim().toLowerCase();

  // Ambil divisi: jika kategori bukan kru, pakai nilai kategori langsung
  const kategori = $('#cr_kategori')?.value || 'kru';
  let div = $('#cr_div')?.value || 'Technical';
  if(kategori==='pengarah') div = 'Pengarah';
  else if(kategori==='pembina') div = 'Pembina';
  const pos = ($('#cr_pos')?.value||'').trim() || 'Kru';
  let phone = ($('#cr_wa')?.value||'').replace(/[^0-9]/g,'');
  if(phone.startsWith('08')) phone = '628'+phone.substring(2);
  const status = $('#cr_stat')?.value || 'Aktif';
  const statusAkun = $('#cr_stat_akun')?.value || (username ? 'Aktif' : 'Nonaktif');
  const photo = ($('#cr_photo')?.value||'').trim();

  const errBox = $('#new_crew_error');
  if (errBox) errBox.style.display = 'none';

  const btn = $('#btn_save_new_crew') || (isEdit ? $(`[data-act="saveEditCrew:${id}"]`) : $('[data-act="saveNewCrew"]'));
  if(btn){ btn.disabled = true; btn.innerHTML = '<span>Menyimpan data...</span>'; }

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_save_crew');
  fd.append('name', name);
  fd.append('role', role);
  fd.append('div', div);
  fd.append('pos', pos);
  fd.append('phone', phone);
  fd.append('status', status);
  fd.append('status_akun', statusAkun);
  fd.append('photo', photo);
  if(ptvId) fd.append('ptvId', ptvId);
  if(username) fd.append('username', username);
  if(password) fd.append('password', password);
  if(angkatan) fd.append('angkatan', angkatan);
  if(nim) fd.append('nim', nim);
  if(jurusan) fd.append('jurusan', jurusan);
  if(oauthEmail) fd.append('oauth_email', oauthEmail);
  else if(isEdit) fd.append('oauth_email', '');

  if(isEdit && id){
    fd.append('id', id);
  }

  fetch(AJAX_URL, { method:'POST', body:fd })
    .then(r=>r.json())
    .then(res=>{
      if(res.success){
        closeSheet();
        toast(isEdit ? 'Data kru berhasil diperbarui.' : 'Data kru berhasil dibuat.', 'check');
        if(res.data?.crew){
          const crData = res.data.crew;
          if(isEdit && id){
            const c = (DB.crew||[]).find(x=>String(x.id)===String(id));
            if(c) Object.assign(c, crData);
          } else {
            DB.crew.push(crData);
          }
        }
        render();
      } else {
        const msg = res.data?.message || res.data || 'Gagal menyimpan data ke database.';
        toast(msg, 'danger');
        if(errBox){
          errBox.textContent = msg;
          errBox.style.display = 'block';
          errBox.scrollIntoView({ behavior:'smooth', block:'nearest' });
        }
      }
    })
    .catch(()=>{
      toast('Gagal menghubungi server.', 'danger');
      if(errBox){
        errBox.textContent = 'Gagal menghubungi server. Silakan periksa koneksi Anda.';
        errBox.style.display = 'block';
      }
    })
    .finally(()=>{
      if(btn){
        btn.disabled = false;
        btn.innerHTML = ic.check + (isEdit ? 'Simpan Perubahan' : 'Daftarkan Kru Baru');
      }
    });
}

function promptGoogleEmail(id){
  const c = (DB.crew||[]).find(x=>String(x.id)===String(id));
  if(!c) return;
  const currentEmail = c.oauth_email || '';

  openSheet(currentEmail ? 'Ubah Email Google Kru' : 'Hubungkan Email Google Kru', `
    <div id="google_email_error" style="display:none;margin-bottom:12px;padding:10px 14px;background:rgba(239,68,68,0.12);border:1px solid rgba(239,68,68,0.3);border-radius:10px;color:#f87171;font-size:12.5px;font-weight:600"></div>
    <div class="card pad" style="margin-bottom:14px;border:1px solid var(--line-2)">
      <div class="row gap8">
        ${avatarHTML(c.name, c.photo || c.foto_url || c.foto, 'sm')}
        <div class="tight">
          <b style="font-size:13.5px">${esc(c.name)}</b>
          <div style="font-size:11.5px;color:var(--muted)">${esc(c.ptvId || '')} &bull; ${esc(c.pos || 'Kru')}</div>
        </div>
      </div>
    </div>
    <div class="field">
      <label class="label">Alamat Email Google (Gmail / Workspace)</label>
      <input class="input" id="inp_google_email" type="email" value="${esc(currentEmail)}" placeholder="nama.kru@gmail.com" required>
      <div style="font-size:11.5px;color:var(--muted);margin-top:6px;line-height:1.45">
        <i class="fa-brands fa-google" style="color:#4285F4"></i> Masukkan email akun Google kru ini. Setelah disimpan, kru dapat login langsung ke akun ini menggunakan tombol <b>Login dengan Google</b>.
      </div>
    </div>
  `, {
    foot: `
      <div style="display:flex;gap:8px;width:100%">
        <button class="btn block pri" id="btn_save_google_email" data-act="submitGoogleEmail:${c.id}">
          <i class="fa-brands fa-google"></i> Simpan Email Google
        </button>
      </div>
    `,
    wide: false
  });
}

function submitGoogleEmail(id){
  const c = (DB.crew||[]).find(x=>String(x.id)===String(id));
  if(!c) return;
  const email = ($('#inp_google_email')?.value || '').trim().toLowerCase();
  const errBox = $('#google_email_error');
  if (errBox) errBox.style.display = 'none';

  if (!email) {
    if (errBox) { errBox.textContent = 'Alamat email Google tidak boleh kosong.'; errBox.style.display = 'block'; }
    return;
  }
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    if (errBox) { errBox.textContent = 'Format email Google tidak valid.'; errBox.style.display = 'block'; }
    return;
  }

  const btn = $('#btn_save_google_email');
  if(btn){ btn.disabled = true; btn.innerHTML = '<span>Menyimpan...</span>'; }

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_save_crew_oauth_email');
  fd.append('id', id);
  fd.append('oauth_email', email);

  fetch(AJAX_URL, { method:'POST', body:fd })
    .then(r=>r.json())
    .then(res=>{
      if(res.success){
        c.oauth_email = res.data.oauth_email;
        c.oauth_provider = res.data.oauth_provider || 'google';
        closeSheet();
        toast('Email Google berhasil ditautkan ke kru.', 'check');
        render();
        setTimeout(() => openCrew(id), 250);
      } else {
        const msg = res.data?.message || res.data || 'Gagal menyimpan email Google.';
        if (errBox) {
          errBox.textContent = msg;
          errBox.style.display = 'block';
        } else {
          toast(msg, 'danger');
        }
        if(btn){ btn.disabled = false; btn.innerHTML = '<i class="fa-brands fa-google"></i> Simpan Email Google'; }
      }
    })
    .catch(err=>{
      if (errBox) { errBox.textContent = 'Terjadi kesalahan jaringan: ' + err.message; errBox.style.display = 'block'; }
      if(btn){ btn.disabled = false; btn.innerHTML = '<i class="fa-brands fa-google"></i> Simpan Email Google'; }
    });
}

function unlinkGoogleEmail(id){
  const c = (DB.crew||[]).find(x=>String(x.id)===String(id));
  if(!c) return;

  if (!confirm(`Hapus email Google (${c.oauth_email}) dari data kru ${c.name}? Kru tidak akan bisa login via Google sampai email didaftarkan ulang.`)) {
    return;
  }

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_save_crew_oauth_email');
  fd.append('id', id);
  fd.append('unlink', '1');

  fetch(AJAX_URL, { method:'POST', body:fd })
    .then(r=>r.json())
    .then(res=>{
      if(res.success){
        c.oauth_email = '';
        c.oauth_provider = '';
        c.oauth_uid = '';
        closeSheet();
        toast('Email Google berhasil dihapus dari data kru.', 'check');
        render();
        setTimeout(() => openCrew(id), 250);
      } else {
        toast(res.data?.message || 'Gagal menghapus tautan Google.', 'danger');
      }
    })
    .catch(err=>toast('Kesalahan: ' + err.message, 'danger'));
}

function savePassword(){
  const oldPass = ($('#set_old_pass')?.value || '').trim();
  const newPass = ($('#set_new_pass')?.value || '').trim();
  const cnfPass = ($('#set_cnf_pass')?.value || '').trim();
  const errBox  = $('#set_pass_error');
  const succBox = $('#set_pass_success');
  if (errBox) errBox.style.display = 'none';
  if (succBox) succBox.style.display = 'none';

  if (!oldPass) {
    toast('Password saat ini wajib diisi.', 'alert');
    if (errBox) { errBox.textContent = 'Password saat ini wajib diisi.'; errBox.style.display = 'block'; }
    return;
  }
  if (!newPass || newPass.length < 6) {
    toast('Password baru minimal 6 karakter.', 'alert');
    if (errBox) { errBox.textContent = 'Password baru minimal 6 karakter.'; errBox.style.display = 'block'; }
    return;
  }
  if (newPass !== cnfPass) {
    toast('Konfirmasi password baru tidak cocok.', 'alert');
    if (errBox) { errBox.textContent = 'Konfirmasi password baru tidak cocok.'; errBox.style.display = 'block'; }
    return;
  }

  const btn = $('#btn_save_pass');
  if (btn) { btn.disabled = true; btn.innerHTML = '<span>Menyimpan...</span>'; }

  const fd = new FormData();
  fd.append('action', 'ptv_change_password');
  fd.append('pass_lama', oldPass);
  fd.append('pass_baru', newPass);
  fd.append('pass_konfirm', cnfPass);

  fetch(AJAX_URL, { method: 'POST', body: fd })
    .then(r => r.json())
    .then(res => {
      if (res.success) {
        toast('Password berhasil diperbarui!', 'check');
        if (errBox) errBox.style.display = 'none';
        if ($('#set_old_pass')) $('#set_old_pass').value = '';
        if ($('#set_new_pass')) $('#set_new_pass').value = '';
        if ($('#set_cnf_pass')) $('#set_cnf_pass').value = '';
        if (succBox) {
          succBox.textContent = 'Password akun berhasil diubah. Gunakan password baru untuk login berikutnya.';
          succBox.style.display = 'block';
        }
      } else {
        const msg = res.data?.message || res.data || 'Gagal mengubah password.';
        toast(msg, 'danger');
        if (errBox) {
          errBox.textContent = msg;
          errBox.style.display = 'block';
        }
      }
    })
    .catch(() => {
      toast('Gagal menghubungi server.', 'danger');
    })
    .finally(() => {
      if (btn) { btn.disabled = false; btn.innerHTML = ic.check + 'Simpan Password Baru'; }
    });
}

function toggleCrewStatus(id){
  const c = (DB.crew||[]).find(x=>String(x.id)===String(id));
  if(!c) return;
  const newStatus = c.status === 'Aktif' ? 'Nonaktif' : 'Aktif';

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_manage_crew');
  fd.append('crew_id', id);
  fd.append('type', 'status');
  fd.append('value', newStatus.toLowerCase());
  fetch(AJAX_URL, { method:'POST', body:fd })
    .then(r => r.json())
    .then(res => {
      if(res.success){
        c.status = newStatus;
        closeSheet();
        toast(`Status kru diubah ke: ${newStatus}`, 'check');
        render();
        if (typeof requestSyncScope === 'function') requestSyncScope('crew', true);
      } else {
        toast(res.data?.message || res.data || 'Gagal mengubah status kru.', 'alert');
      }
    })
    .catch((err) => {
      toast('Gagal menghubungi server.', 'alert');
      console.error('[PTV Crew] Toggle status error:', err);
    });
}

function activateCrewAccount(id){
  const c = (DB.crew||[]).find(x=>String(x.id)===String(id));
  if(!c) return;
  if(c.username){ toast('Akun sudah aktif: @'+c.username, 'info'); return; }
  if(!confirm(`Aktifkan akun portal untuk "${c.name}"?\n\nSistem akan membuat username, password default, dan ID PTV secara otomatis.`)) return;

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_activate_crew_account');
  fd.append('crew_id', id);
  fetch(AJAX_URL, { method:'POST', body:fd })
    .then(r=>r.json())
    .then(res=>{
      if(res.success && res.data){
        c.username = res.data.username;
        c.ptvId    = res.data.ptvId;
        c.status   = 'Aktif';
        closeSheet();
        render();
        const info = `Akun berhasil dibuat!\n\nID PTV   : ${res.data.ptvId}\nUsername : ${res.data.username}\nPassword : ${res.data.password_default}\n\nSilakan catat dan bagikan ke kru yang bersangkutan.`;
        alert(info);
      } else {
        toast(res.data?.message || 'Gagal mengaktifkan akun.', 'alert');
      }
    }).catch(()=>toast('Gagal menghubungi server.','alert'));
}

function confirmDeleteCrew(id){
  const c = (DB.crew||[]).find(x=>String(x.id)===String(id));
  if(!c) return;
  if(!confirm(`Yakin ingin MENGHAPUS PERMANEN data kru "${c.name}" (${c.ptvId || 'Tanpa ID'}) dari database?\n\nData yang dihapus dari Supabase tidak dapat dikembalikan lagi.`)) return;

  if (typeof window.ptvMarkDeleting === 'function') window.ptvMarkDeleting('crew', id);

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_delete_crew');
  fd.append('id', id);
  fetch(AJAX_URL, { method:'POST', body:fd })
    .then(r => r.json())
    .then(res => {
      if(res.success){
        if (typeof window.ptvMarkDeleted === 'function') window.ptvMarkDeleted('crew', id);
        DB.crew = (DB.crew || []).filter(x => String(x.id) !== String(id));
        closeSheet();
        toast('Data kru berhasil dihapus permanen dari database.', 'check');
        render();
        if (typeof requestSyncScope === 'function') requestSyncScope('crew', true);
      } else {
        toast(res.data?.message || res.data || 'Gagal menghapus data kru di database.', 'alert');
      }
    })
    .catch((err)=>{
      toast('Gagal menghubungi server.', 'alert');
      console.error('[PTV Crew] Delete error:', err);
    });
}

// ── 3. ACARA / AGENDA (ptv_acara) ───────────────────────────
function openNewEvent(presetDate){
  const defaultDate = presetDate || (calSel !== iso(today) ? calSel : iso(today));
  openSheet('Tambah Acara Liputan Baru',
    field('Nama Kegiatan / Acara', `<input class="input" id="ev_new_name" placeholder="Contoh: Haflah Akhirussanah / Liputan Khusus" required autocomplete="off">`) +
    field('Lokasi', `<input class="input" id="ev_new_loc" placeholder="Contoh: Lapangan Utama / Studio PTV" value="Studio PTV">`) +
    `<div class="grid-2">
      ${field('Tanggal Acara', `<input class="input" id="ev_new_date" type="date" value="${defaultDate}">`)}
      ${field('Waktu', `<input class="input" id="ev_new_time" placeholder="Contoh: 08:00 – Selesai" value="08:00 – Selesai">`)}
    </div>` +
    field('Catatan / Keterangan', `<textarea class="input" id="ev_new_notes" rows="3" placeholder="Rundown atau catatan khusus kegiatan..."></textarea>`),
    {
      foot:`<button class="btn block pri" data-act="saveNewEvent">${ic.check}Simpan Acara</button>`
    }
  );
}

function saveNewEvent(){
  const name = ($('#ev_new_name')?.value || '').trim();
  if(!name){ toast('Nama kegiatan tidak boleh kosong.', 'alert'); return; }
  const loc = ($('#ev_new_loc')?.value || '').trim() || 'Studio PTV';
  const date = $('#ev_new_date')?.value || iso(today);
  const time = ($('#ev_new_time')?.value || '').trim() || '08:00 – Selesai';
  const notes = $('#ev_new_notes')?.value || '';

  const submitBtn = document.querySelector('[data-act="saveNewEvent"]');
  const origBtnHtml = submitBtn ? submitBtn.innerHTML : '';
  if (submitBtn) {
    submitBtn.disabled = true;
    submitBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin" style="margin-right:6px"></i>Menyimpan...';
  }

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_save_event');
  fd.append('name', name);
  fd.append('loc', loc);
  fd.append('date', date);
  fd.append('time', time);
  fd.append('notes', notes);
  fd.append('status', 'terjadwal');
  fetch(AJAX_URL, { method: 'POST', body: fd })
    .then(r => r.json())
    .then(res => {
      if(res.success && res.data?.event){
        const savedEvent = res.data.event;
        const idx = (DB.events||[]).findIndex(x => String(x.id) === String(savedEvent.id));
        if (idx !== -1) {
          DB.events[idx] = savedEvent;
        } else {
          DB.events.unshift(savedEvent);
        }
        closeSheet();
        toast('Acara baru berhasil dijadwalkan.', 'check');
        render();
        if (typeof requestSyncScope === 'function') requestSyncScope('events', true);
      } else {
        if (submitBtn) {
          submitBtn.disabled = false;
          submitBtn.innerHTML = origBtnHtml;
        }
        toast(res.data?.message || res.data || 'Gagal menyimpan acara.', 'alert');
      }
    })
    .catch((err)=>{
      if (submitBtn) {
        submitBtn.disabled = false;
        submitBtn.innerHTML = origBtnHtml;
      }
      toast('Terjadi kendala jaringan saat menyimpan acara.', 'alert');
      console.error('[PTV Events] Save error:', err);
    });
}

