function cancelEditEvent(id){
  closeSheet();
}

function saveEditEvent(id){
  const e = (DB.events||[]).find(x=>String(x.id)===String(id));
  if(!e) return;
  const isExec = ['eksekutif','executive'].includes(normRole(state.role || ME.role));
  const isAdmin = ['administrasi','admin'].includes(normRole(state.role || ME.role));
  if(!isExec && !isAdmin){
    toast('Hanya Eksekutif dan Administrasi yang berwenang mengedit acara.', 'alert');
    return;
  }

  const name = ($('#edit_ev_name')?.value || '').trim();
  if(!name){ toast('Nama kegiatan tidak boleh kosong.', 'alert'); return; }
  const loc = ($('#edit_ev_loc')?.value || '').trim() || 'Studio PTV';
  const date = $('#edit_ev_date')?.value || e.date;
  const time = ($('#edit_ev_time')?.value || '').trim() || '08:00 – Selesai';
  const notes = $('#edit_ev_notes')?.value || '';
  const status = ($('#edit_ev_status')?.value || e.status || 'Mendatang');

  const oldState = { ...e };
  e.name = name;
  e.loc = loc;
  e.date = date;
  e.time = time;
  e.notes = notes;
  e.status = status;

  const submitBtn = document.querySelector(`[data-act="saveEditEvent:${id}"]`) || document.querySelector('[data-act^="saveEditEvent"]');
  const origBtnHtml = submitBtn ? submitBtn.innerHTML : '';
  if (submitBtn) {
    submitBtn.disabled = true;
    submitBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin" style="margin-right:6px"></i>Menyimpan...';
  }

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_save_event');
  fd.append('id', id);
  fd.append('name', name);
  fd.append('loc', loc);
  fd.append('date', date);
  fd.append('time', time);
  fd.append('notes', notes);
  fd.append('status', (status || 'terjadwal').toLowerCase());
  if(Array.isArray(e.crew)) fd.append('crew', JSON.stringify(e.crew));
  if(Array.isArray(e.gear)) fd.append('gear', JSON.stringify(e.gear));
  if(Array.isArray(e.rundown)) fd.append('rundown', JSON.stringify(e.rundown));

  fetch(AJAX_URL, { method:'POST', body:fd })
    .then(r => r.json())
    .then(res => {
      if (res.success && res.data?.event) {
        Object.assign(e, res.data.event);
        closeSheet();
        toast('Perubahan acara berhasil disimpan.', 'check');
        render();
        if (typeof requestSyncScope === 'function') requestSyncScope('events', true);
      } else {
        if (submitBtn) {
          submitBtn.disabled = false;
          submitBtn.innerHTML = origBtnHtml;
        }
        toast(res.data?.message || 'Gagal memperbarui data acara.', 'alert');
      }
    })
    .catch((err) => {
      if (submitBtn) {
        submitBtn.disabled = false;
        submitBtn.innerHTML = origBtnHtml;
      }
      toast('Terjadi kendala koneksi saat menyimpan acara.', 'alert');
      console.error('[PTV Events] Edit error:', err);
    });
}

function saveInlineEditEvent(id){
  saveEditEvent(id);
