function openEditEventRundown(eventId, targetItemId){
  const e = eventById(eventId);
  if(!e) return;
  const canEdit = ['eksekutif','administrasi','executive','admin'].includes(normRole(state.role || ME.role));
  if(!canEdit){
    toast('Hanya Eksekutif dan Administrasi yang berwenang mengedit rundown.', 'alert');
    return;
  }
  const rdList = Array.isArray(e.rundown) ? e.rundown : [];
  const curItem = rdList.find(x => String(x.id) === String(targetItemId)) || rdList[parseInt(targetItemId, 10)];
  if(!curItem) return;

  const curJam = formatRundownJam(curItem.jam_mulai || curItem.start_time || curItem.time || '19.00');
  const curKegiatan = curItem.kegiatan || curItem.pekerjaan || curItem.title || curItem.judul || '';

  openSheet('Edit Rundown Acara',
    `<div class="field mb12">
      <label style="font-weight:700;font-size:13px;color:var(--ink,#0f172a);">Jam <span style="color:#ef4444">*</span></label>
      <input class="input" id="rd_form_jam" value="${esc(curJam)}" placeholder="Contoh: 19.00 atau 19:00" style="font-weight:750;font-size:15px;" autofocus>
      <div style="font-size:11px;color:var(--ink3,#64748b);margin-top:4px">Format waktu, contoh: 19.00 atau 19.15</div>
    </div>
    <div class="field mb12">
      <label style="font-weight:700;font-size:13px;color:var(--ink,#0f172a);">Kegiatan <span style="color:#ef4444">*</span></label>
      <input class="input" id="rd_form_kegiatan" value="${esc(curKegiatan)}" placeholder="Contoh: Pembukaan, Pembacaan Shalawat..." style="font-weight:650;font-size:14px;">
      <div style="font-size:11px;color:var(--ink3,#64748b);margin-top:4px">Tuliskan nama sesi atau kegiatan.</div>
    </div>
    <div style="min-height:10px;"></div>`,
    {
      foot: `<div class="row gap8" style="width:100%">
        <button class="btn" style="flex:1" data-act="closeSheet">Batal</button>
        <button class="btn pri" id="btnSubmitAddRundown" data-act="saveEventRundownItem:${e.id}:${esc(curItem.id)}" style="flex:2;background:linear-gradient(135deg, #1d4ed8 0%, #2563eb 100%);box-shadow:0 2px 8px rgba(37,99,235,0.25);">
          <i class="fa-solid fa-floppy-disk" style="margin-right:6px"></i>Simpan
        </button>
      </div>`
    }
  );
}

function saveEventRundownItem(eventId, targetItemId){
  const e = eventById(eventId);
  if(!e) return;
  const rawJamVal = ($('#rd_form_jam')?.value || '').trim();
  const kegiatanVal = ($('#rd_form_kegiatan')?.value || '').trim();

  if(!rawJamVal){
    toast('Jam kegiatan wajib diisi.', 'alert');
    return;
  }
  if(!kegiatanVal){
    toast('Nama kegiatan wajib diisi.', 'alert');
    return;
  }

  // Normalisasi jam: dukung format 19.00 atau 19:00
  let normJam = rawJamVal.replace('.', ':');
  const mJam = normJam.match(/^(\d{1,2}):(\d{2})/);
  if (mJam) {
    normJam = `${String(mJam[1]).padStart(2, '0')}:${mJam[2]}`;
  }

  let defaultEventDate = '';
  if (e.date) {
    const dObj = new Date(e.date.includes('T') ? e.date : e.date + 'T00:00:00');
    if (!isNaN(dObj.getTime())) defaultEventDate = e.date.slice(0, 10);
  }
  if (!defaultEventDate && e.tanggal_mulai) defaultEventDate = String(e.tanggal_mulai).slice(0, 10);
  if (!defaultEventDate) {
    const now = new Date();
    defaultEventDate = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
  }

  const oldRundown = Array.isArray(e.rundown) ? [...e.rundown] : [];
  let updatedRundown = [...oldRundown];

  const nowIso = new Date().toISOString();
  const isEditing = targetItemId && targetItemId !== 'new' && targetItemId !== '-1';
  let targetIdx = isEditing ? updatedRundown.findIndex(x => String(x.id) === String(targetItemId)) : -1;
  if(isEditing && targetIdx === -1 && !isNaN(parseInt(targetItemId, 10))){
    targetIdx = parseInt(targetItemId, 10);
  }

  const existingItem = (targetIdx >= 0 && targetIdx < updatedRundown.length) ? updatedRundown[targetIdx] : null;
  const finalItemId = existingItem?.id || ((typeof crypto !== 'undefined' && crypto.randomUUID) ? crypto.randomUUID() : 'rd_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6));

  const startAt = `${defaultEventDate} ${normJam}`;

  const itemPayload = {
    id: finalItemId,
    acara_id: e.id,
    kegiatan: kegiatanVal,
    pekerjaan: kegiatanVal,
    title: kegiatanVal,
    tanggal_mulai: defaultEventDate,
    tanggal_selesai: defaultEventDate,
    jam_mulai: normJam,
    jam_selesai: '',
    start_time: normJam,
    time: normJam,
    start_at: startAt,
    tenggat: defaultEventDate,
    status: existingItem?.status || 'BELUM',
    created_at: existingItem?.created_at || nowIso,
    updated_at: nowIso
  };

  if(targetIdx >= 0 && targetIdx < updatedRundown.length){
    updatedRundown[targetIdx] = { ...updatedRundown[targetIdx], ...itemPayload };
  } else {
    updatedRundown.push(itemPayload);
  }

  // Urutkan item rundown strictly berdasarkan waktu/jam: 19.00 -> 19.15 -> 19.30 -> 20.00
  updatedRundown.sort((a, b) => {
    const keyA = parseRundownSortKey(a);
    const keyB = parseRundownSortKey(b);
    return keyA.localeCompare(keyB);
  });

  // Re-index urutan berurutan (1, 2, 3...)
  updatedRundown.forEach((it, i) => {
    it.urutan = i + 1;
  });

  const submitBtn = document.getElementById('btnSubmitAddRundown');
  const origBtnHtml = submitBtn ? submitBtn.innerHTML : '';
  if (submitBtn) {
    submitBtn.disabled = true;
    submitBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin" style="margin-right:6px"></i>Menyimpan...';
  }

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_save_event_rundown');
  fd.append('id', eventId);
  fd.append('rundown', JSON.stringify(updatedRundown));
  fd.append('nonce', typeof PTV_NONCE !== 'undefined' ? PTV_NONCE : '');

  fetch(AJAX_URL, { method: 'POST', body: fd, credentials: 'same-origin' })
    .then(r => r.json().catch(err => {
      throw new Error('Format respon server tidak valid (' + err.message + ')');
    }))
    .then(res => {
      if(res.success){
        if(Array.isArray(res.data?.rundown)){
          e.rundown = res.data.rundown;
        } else {
          e.rundown = updatedRundown;
        }
        closeSheet();
        toast(isEditing ? 'Rundown berhasil diperbarui.' : 'Rundown baru berhasil ditambahkan.', 'check');
        render();
      } else {
        const errMsg = res.data?.message || res.data || 'Gagal menyimpan rundown ke database.';
        console.error('[RUNDOWN INSERT ERROR]', errMsg);
        console.error('[RUNDOWN PAYLOAD]', updatedRundown);
        toast(errMsg, 'alert');
        if(submitBtn) {
          submitBtn.disabled = false;
          submitBtn.innerHTML = origBtnHtml;
        }
      }
    })
    .catch(err => {
      console.error('[RUNDOWN INSERT ERROR]', err);
      console.error('[RUNDOWN PAYLOAD]', updatedRundown);
      toast(err.message || 'Gagal menyimpan rundown.', 'alert');
      if(submitBtn) {
        submitBtn.disabled = false;
        submitBtn.innerHTML = origBtnHtml;
      }
    });
}

function deleteEventRundownItem(eventId, targetItemId){
  const e = eventById(eventId);
  if(!e) return;
  const canEdit = ['eksekutif','administrasi','executive','admin'].includes(normRole(state.role || ME.role));
  if(!canEdit){
    toast('Hanya Eksekutif dan Administrasi yang berwenang menghapus rundown.', 'alert');
    return;
  }
  const oldRundown = Array.isArray(e.rundown) ? [...e.rundown] : [];
  const itemToDelete = oldRundown.find(x => String(x.id) === String(targetItemId)) || oldRundown[parseInt(targetItemId, 10)];
  if(!itemToDelete) return;

  const itemTitle = itemToDelete.kegiatan || itemToDelete.pekerjaan || itemToDelete.title || 'kegiatan ini';
  if (!confirm(`Hapus "${itemTitle}" dari rundown acara ini?`)) return;

  const updatedRundown = oldRundown.filter(x => String(x.id) !== String(itemToDelete.id));
  updatedRundown.forEach((it, i) => {
    it.urutan = i + 1;
  });

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_save_event_rundown');
  fd.append('id', eventId);
  fd.append('rundown', JSON.stringify(updatedRundown));
  fd.append('nonce', typeof PTV_NONCE !== 'undefined' ? PTV_NONCE : '');

  // Optimistic UI update
  e.rundown = updatedRundown;
  render();

  fetch(AJAX_URL, { method: 'POST', body: fd, credentials: 'same-origin' })
    .then(r => r.json().catch(err => {
      throw new Error('Respon server tidak valid (' + err.message + ')');
    }))
    .then(res => {
      if(res.success){
        if(Array.isArray(res.data?.rundown)){
          e.rundown = res.data.rundown;
        }
        toast('Rundown berhasil dihapus.', 'check');
      } else {
        e.rundown = oldRundown;
        const errMsg = res.data?.message || res.data || 'Gagal menghapus rundown di Supabase.';
        console.error('[RUNDOWN DELETE ERROR]', errMsg);
        toast(errMsg, 'alert');
        render();
      }
    })
    .catch(err => {
      console.error('[RUNDOWN DELETE ERROR]', err);
      e.rundown = oldRundown;
      toast(err.message || 'Gagal menghapus rundown.', 'alert');
      render();
    });
}

function moveEventRundownItem(eventId, fromIdx, toIdx){
  const e = eventById(eventId);
  if(!e) return;
  const oldRundown = Array.isArray(e.rundown) ? [...e.rundown] : [];
  if(fromIdx < 0 || fromIdx >= oldRundown.length || toIdx < 0 || toIdx >= oldRundown.length) return;

  const updatedRundown = [...oldRundown];
  const item = updatedRundown.splice(fromIdx, 1)[0];
  updatedRundown.splice(toIdx, 0, item);

  // Normalisasi urutan berurutan (1, 2, 3...)
  updatedRundown.forEach((it, i) => {
    it.urutan = i + 1;
  });

  e.rundown = updatedRundown;

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_save_event_rundown');
  fd.append('id', eventId);
  fd.append('rundown', JSON.stringify(updatedRundown));
  fd.append('nonce', typeof PTV_NONCE !== 'undefined' ? PTV_NONCE : '');

  fetch(AJAX_URL, { method: 'POST', body: fd, credentials: 'same-origin' })
    .then(r => r.json())
    .then(res => {
      if(!res.success){
        e.rundown = oldRundown;
        toast('Gagal memperbarui urutan rundown.', 'error');
      }
      render();
    })
    .catch(() => {
      e.rundown = oldRundown;
      render();
    });

  haptic(4);
  render();
}

function openChangeEventStatus(id){
  const e = (DB.events||[]).find(x=>String(x.id)===String(id));
  if(!e) return;
  const statusList = [
    ['Terjadwal', 'Akan Datang / Terjadwal'],
    ['Batal', 'Dibatalkan']
  ];

  openSheet('Ubah Status Kegiatan',
    field('Pilih Status', selectOf('ev_st_sel', statusList)) +
    `<p class="t-xs muted mt12">Status acara akan disinkronkan secara real-time ke sistem kalender kru.</p>`,
    {
      foot:`<button class="btn block pri" data-act="saveEventStatus:${e.id}">${ic.check}Terapkan Status</button>`,
      then:(b)=>{
        const s = $('#ev_st_sel', b);
        if(s) s.value = e.status === 'Batal' ? 'Batal' : 'Terjadwal';
      }
    }
  );
}

function saveEventStatus(id){
  const e = (DB.events||[]).find(x=>String(x.id)===String(id));
  if(!e) return;
  const st = $('#ev_st_sel')?.value || 'Terjadwal';
  const oldSt = e.status;
  e.status = (st === 'Terjadwal') ? 'Mendatang' : st;

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_update_event_status');
  fd.append('id', id);
  fd.append('status', st.toLowerCase());

  closeSheet();

  fetch(AJAX_URL, { method:'POST', body:fd })
    .then(r => r.json())
    .then(res => {
      if (res.success) {
        toast('Status acara diperbarui: ' + e.status, 'check');
      } else {
        e.status = oldSt;
        toast(res.data?.message || 'Gagal memperbarui status acara.', 'error');
      }
      render();
    })
    .catch(() => {
      e.status = oldSt;
      toast('Terjadi kendala koneksi.', 'error');
      render();
    });

  render();
}

function confirmDeleteEvent(id){
  const e = (DB.events||[]).find(x=>String(x.id)===String(id));
  if(!e) return;
  if(!confirm(`Hapus kegiatan "${e.name}" dari jadwal?`)) return;

  const deletedEv = e;
  DB.events = DB.events.filter(x => String(x.id) !== String(id));
  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_delete_event');
  fd.append('id', id);

  closeSheet();

  fetch(AJAX_URL, { method:'POST', body:fd })
    .then(r => r.json())
    .then(res => {
      if (res.success) {
        toast('Acara telah dihapus dari database.', 'check');
      } else {
        DB.events.push(deletedEv);
        toast(res.data?.message || 'Gagal menghapus acara.', 'error');
      }
      go('acara');
    })
    .catch(() => {
      DB.events.push(deletedEv);
      toast('Terjadi kendala koneksi.', 'error');
      go('acara');
    });

  go('acara');
}

// ── 4. KEUANGAN (ptv_keuangan) ──────────────────────────────
function openNewFinance(){
  const types = [['Kuitansi','Kuitansi'],['Quotation','Quotation'],['Invoice','Invoice']];
  const statuses = [['Menunggu','Menunggu Pembayaran'],['Lunas','Lunas']];

  openSheet('Catat Transaksi Keuangan',
    field('Jenis Transaksi', selectOf('fn_type', types)) +
    field('Klien / Penyelenggara', `<input class="input" id="fn_client" placeholder="Contoh: Panitia Haflah / Yayasan">`) +
    `<div class="grid-2">
      ${field('Nominal (Rp)', `<input class="input" id="fn_amount" placeholder="Contoh: 2500000" type="number">`)}
      ${field('Tanggal', `<input class="input" id="fn_date" type="date" value="${iso(today)}">`)}
    </div>` +
    `<div class="grid-2">
      ${field('Nomor Dokumen (Opsional)', `<input class="input" id="fn_no" placeholder="Otomatis jika kosong">`)}
      ${field('Status Pembayaran', selectOf('fn_status', statuses))}
    </div>` +
    field('Catatan / Keterangan', `<textarea class="input" id="fn_notes" placeholder="Rincian pembayaran atau jasa produksi..."></textarea>`),
    {foot:`<button class="btn block pri" data-act="saveNewFinance">${ic.check}Simpan Transaksi</button>`}
  );
}

function openFinanceDetail(id){
  const f = (DB.finance||[]).find(x=>String(x.id)===String(id));
  if(!f) return;

  openSheet('Detail Transaksi Keuangan',`
    <div class="row-b" style="align-items:flex-start">
      <div class="tight">
        <div class="t-lg">${esc(f.client)}</div>
        <div class="t-sm muted num">${esc(f.no)} · ${esc(f.type)}</div>
      </div>
      ${chip(f.status)}
    </div>
    <div class="card pad mt12">
      <div class="kv"><span>Total Nominal</span><b class="num t-md">${rupiah(f.amount)}</b></div>
      <div class="kv"><span>Tanggal Transaksi</span><b>${fmtDate(f.date, true)}</b></div>
      <div class="kv"><span>Status</span><b>${esc(f.status)}</b></div>
      ${f.notes ? `<div class="kv"><span>Catatan</span><b>${esc(f.notes)}</b></div>` : ''}
    </div>`,
    {
      foot:`<div class="wrap" style="width:100%">
        <button class="btn pri" data-act="toggleFinanceStatus:${f.id}">${f.status==='Lunas'?'Tandai Menunggu':'Tandai Lunas'}</button>
        <button class="btn dang" data-act="confirmDeleteFinance:${f.id}">${ic.trash}Hapus</button>
      </div>`
    }
  );
}

function saveFinance(){
  const client = ($('#fn_client')?.value||'').trim();
  if(!client){ toast('Nama klien wajib diisi.','info'); return; }
  const type = $('#fn_type')?.value || 'Kuitansi';
  const amount = parseInt($('#fn_amount')?.value || '0', 10);
  const date = $('#fn_date')?.value || iso(today);
  const no = ($('#fn_no')?.value||'').trim() || ('PTV/' + (type==='Quotation'?'QT':'KW') + '/' + Math.floor(100 + Math.random()*900));
  const status = $('#fn_status')?.value || 'Menunggu';
  const notes = $('#fn_notes')?.value || '';

  const newFin = { id: 'f' + Math.floor(1000 + Math.random()*9000), no, type, client, amount, date, status, notes };
  DB.finance.unshift(newFin);

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_save_finance');
  fd.append('type', type);
  fd.append('client', client);
  fd.append('amount', amount);
  fd.append('date', date);
  fd.append('no', no);
  fd.append('status', status);
  fd.append('notes', notes);

  fetch(AJAX_URL, { method:'POST', body:fd })
    .then(r=>r.json())
    .then(res=>{
      if(res.success && res.data?.finance){
        Object.assign(newFin, res.data.finance);
      }
    }).catch(()=>{});

  closeSheet();
  toast('Transaksi keuangan berhasil dicatat.', 'check');
  render();
}

function toggleFinanceStatus(id){
  const f = (DB.finance||[]).find(x=>String(x.id)===String(id));
  if(!f) return;
  const newSt = f.status === 'Lunas' ? 'Menunggu' : 'Lunas';
  f.status = newSt;

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_update_finance_status');
  fd.append('id', id);
  fd.append('status', newSt);
  fetch(AJAX_URL, { method:'POST', body:fd }).catch(()=>{});

  closeSheet();
  toast(`Status transaksi diubah: ${newSt}`, 'check');
  render();
}

function confirmDeleteFinance(id){
  const f = (DB.finance||[]).find(x=>String(x.id)===String(id));
  if(!f) return;
  if(!confirm(`Hapus catatan transaksi ${f.no} (${f.client})?`)) return;

  DB.finance = DB.finance.filter(x => String(x.id) !== String(id));
  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_delete_finance');
  fd.append('id', id);
  fetch(AJAX_URL, { method:'POST', body:fd }).catch(()=>{});

  closeSheet();
  toast('Catatan transaksi dihapus.');
  render();
}

// ── 5. JADWAL KONTEN (ptv_konten) ───────────────────────────
function openNewContent(){
  const platforms = ['Instagram','YouTube','TikTok','Website','Facebook'].map(p=>[p,p]);
  const statuses = [['Draft','Draft Ide'],['Dijadwalkan','Dijadwalkan'],['Terbit','Sudah Terbit']];

  openSheet('Tambah Jadwal Konten',
    field('Judul Konten / Liputan', `<input class="input" id="ct_title" placeholder="Contoh: Highlight Acara Milad / Podcast Kru">`) +
    `<div class="grid-2">
      ${field('Platform Penayangan', selectOf('ct_plat', platforms))}
      ${field('Tanggal Tayang', `<input class="input" id="ct_date" type="date" value="${iso(today)}">`)}
    </div>` +
    field('Status Konten', selectOf('ct_stat', statuses)) +
    field('Catatan Produksi', `<textarea class="input" id="ct_notes" placeholder="Ide caption, format reel/landscape, PIC editor..."></textarea>`),
    {foot:`<button class="btn block pri" data-act="saveNewContent">${ic.check}Jadwalkan Konten</button>`}
  );
}

function openContentDetail(id){
  const p = (DB.contents||[]).find(x=>String(x.id)===String(id));
  if(!p) return;

  openSheet('Detail Jadwal Konten',`
    <div class="row-b" style="align-items:flex-start">
      <div class="tight">
        <div class="t-lg">${esc(p.title)}</div>
        <div class="t-sm muted">${esc(p.platform)} · ${fmtDate(p.date)}</div>
      </div>
      ${chip(p.status)}
    </div>
    <div class="card pad mt12">
      <div class="kv"><span>Platform</span><b>${esc(p.platform)}</b></div>
      <div class="kv"><span>Tanggal Tayang</span><b>${fmtDate(p.date, true)}</b></div>
      <div class="kv"><span>Status</span><b>${esc(p.status)}</b></div>
      ${p.notes ? `<div class="kv"><span>Catatan</span><b>${esc(p.notes)}</b></div>` : ''}
    </div>`,
    {
      foot:`<div class="wrap" style="width:100%">
        <button class="btn pri" data-act="cycleContentStatus:${p.id}">${p.status==='Terbit'?'Ubah ke Draft':'Tandai Terbit'}</button>
        <button class="btn dang" data-act="confirmDeleteContent:${p.id}">${ic.trash}Hapus</button>
      </div>`
    }
  );
}

function saveContent(){
  const title = ($('#ct_title')?.value||'').trim();
  if(!title){ toast('Judul konten wajib diisi.','info'); return; }
  const platform = $('#ct_plat')?.value || 'Instagram';
  const date = $('#ct_date')?.value || iso(today);
  const status = $('#ct_stat')?.value || 'Draft';
  const notes = $('#ct_notes')?.value || '';

  const newCt = { id: 'p' + Math.floor(1000 + Math.random()*9000), title, platform, date, status, notes };
  DB.contents.unshift(newCt);

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_save_content');
  fd.append('title', title);
  fd.append('platform', platform);
  fd.append('date', date);
  fd.append('status', status);
  fd.append('notes', notes);

  fetch(AJAX_URL, { method:'POST', body:fd })
    .then(r=>r.json())
    .then(res=>{
      if(res.success && res.data?.content){
        Object.assign(newCt, res.data.content);
      }
    }).catch(()=>{});

  closeSheet();
  toast('Konten baru berhasil dijadwalkan.', 'check');
  render();
}

function cycleContentStatus(id){
  const p = (DB.contents||[]).find(x=>String(x.id)===String(id));
  if(!p) return;
  const nextSt = p.status === 'Terbit' ? 'Draft' : 'Terbit';
  p.status = nextSt;

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_update_content_status');
  fd.append('id', id);
  fd.append('status', nextSt);
  fetch(AJAX_URL, { method:'POST', body:fd }).catch(()=>{});

  closeSheet();
  toast(`Status konten diubah: ${nextSt}`, 'check');
  render();
}

function confirmDeleteContent(id){
  const p = (DB.contents||[]).find(x=>String(x.id)===String(id));
  if(!p) return;
  if(!confirm(`Hapus jadwal konten "${p.title}"?`)) return;

  DB.contents = DB.contents.filter(x => String(x.id) !== String(id));
  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_delete_content');
  fd.append('id', id);
  fetch(AJAX_URL, { method:'POST', body:fd }).catch(()=>{});

  closeSheet();
  toast('Jadwal konten dihapus.');
  render();
}

/* ============================================================
   CONTENT PLANNER (SUPABASE ptv_content_planner)
   ============================================================ */

function getRecurrenceLabel(rec) {
  if (!rec) return '';
  const type = normalizePlannerRecurrenceType(rec.type || '');
  if (!type || type === 'sekali_tayang') return '';
  const r = rec.rule || {};
  switch (type) {
    case 'setiap_bulan':
      return `Setiap bulan (Tgl ${r.day || 15})`;
    case 'tanggal_masehi_tahunan':
      return `Berulang tiap ${r.day || ''} ${MONTHS[(Number(r.month)||1)-1] || ''} (Tahunan)`;
    case 'bulan_masehi':
      return `Sepanjang bulan ${MONTHS[(Number(r.month)||1)-1] || ''}`;
    case 'tanggal_hijriah':
      return `Berulang tiap ${r.day || ''} ${r.month || ''} H (Tahunan)`;
    case 'bulan_hijriah':
      return `Sepanjang bulan ${r.month || ''} H (Tanggal belum ditentukan)`;
    case 'bagian_bulan_hijriah': {
      const segLabels = { awal: 'Awal', pertengahan: 'Pertengahan', akhir: 'Akhir', menjelang: 'Menjelang' };
      const s = segLabels[(r.segment || 'awal').toLowerCase()] || 'Awal';
      return `${s} ${r.month || ''} H (Periode)`;
    }
    case 'hari_mingguan':
      return `Tiap ${r.dayOfWeek || 'hari'}`;
    case 'hari_weton':
      return `Tiap ${r.dayOfWeek || ''} ${r.pasaran || ''}`.trim();
    case 'minggu_ke_n':
      return `Minggu ke-${r.nth || 1} tiap bulan (${r.dayOfWeek || 'Minggu'})`;
    case 'hari_ke_n':
      return `${r.dayOfWeek || ''} ke-${r.nth || 1} tiap bulan`;
    case 'custom_periode':
      return `Periode Momentum Khusus`;
    default:
      return getPlannerRecurrenceLabel(type);
  }
}

function updatePlannerPreviewBox(container) {
  const root = container || document;
  const rawSelType = root.querySelector('#cp_recurrence_type')?.value || 'sekali_tayang';
  const selType = normalizePlannerRecurrenceType(rawSelType);
  const textEl = root.querySelector('#cp_preview_text');
  if (!textEl) return;

  let txt = '';
  switch (selType) {
    case 'sekali_tayang': {
      const d = root.querySelector('#cp_tanggal_mulai')?.value;
      txt = d ? `● Tanggal Pasti: ${d}` : '● Tanggal Pasti: Silakan pilih tanggal pelaksanaan';
      break;
    }
    case 'tanggal_hijriah': {
      const day = root.querySelector('#cp_rec_h_day')?.value || '9';
      const m = root.querySelector('#cp_rec_h_month')?.value || 'Muharram';
      txt = `● ${day} ${m} H — Tanggal Pasti (Setiap Tahun Hijriyah)`;
      break;
    }
    case 'bulan_hijriah': {
      const m = root.querySelector('#cp_rec_h_month')?.value || 'Rabiul Akhir';
      txt = `○ Sepanjang ${m} — Tanggal Belum Ditentukan (Tampil di semua bulan kalender yang beririsan)`;
      break;
    }
    case 'bagian_bulan_hijriah': {
      const segVal = root.querySelector('#cp_rec_segment')?.value || 'awal';
      const segLabels = { awal: 'Awal Bulan (1–10)', pertengahan: 'Pertengahan Bulan (11–20)', akhir: 'Akhir Bulan (21–Akhir)', menjelang: 'Menjelang Akhir (25–Akhir)' };
      const m = root.querySelector('#cp_rec_h_month')?.value || 'Ramadhan';
      txt = `◐ ${segLabels[segVal] || 'Bagian'} ${m} — Momentum Periode`;
      break;
    }
    case 'tanggal_masehi_tahunan': {
      const day = root.querySelector('#cp_rec_day')?.value || '17';
      const mIdx = Number(root.querySelector('#cp_rec_month')?.value || '1');
      txt = `● Tiap ${day} ${MONTHS[mIdx-1] || ''} (Tahunan Masehi)`;
      break;
    }
    case 'bulan_masehi': {
      const mIdx = Number(root.querySelector('#cp_rec_month')?.value || '1');
      txt = `○ Sepanjang bulan ${MONTHS[mIdx-1] || ''} (Tanggal Belum Ditentukan)`;
      break;
    }
    case 'setiap_bulan': {
      const day = root.querySelector('#cp_rec_day')?.value || '15';
      txt = `● Setiap tanggal ${day} setiap bulan`;
      break;
    }
    case 'hari_mingguan': {
      const dow = root.querySelector('#cp_rec_dow')?.value || 'Kamis';
      txt = `● Setiap hari ${dow} mingguan`;
      break;
    }
    case 'hari_weton': {
      const dow = root.querySelector('#cp_rec_dow')?.value || 'Kamis';
      const pas = root.querySelector('#cp_rec_pasaran')?.value || 'Legi';
      txt = `● Setiap ${dow} ${pas} (Siklus Weton 35 Hari Sekali)`;
      break;
    }
    case 'minggu_ke_n': {
      const nth = root.querySelector('#cp_rec_nth')?.value || '1';
      const dow = root.querySelector('#cp_rec_dow')?.value || 'Minggu';
      txt = `● Minggu ke-${nth} (${dow}) setiap bulan`;
      break;
    }
    case 'hari_ke_n': {
      const nth = root.querySelector('#cp_rec_nth')?.value || '1';
      const dow = root.querySelector('#cp_rec_dow')?.value || 'Selasa';
      txt = `● ${dow} ke-${nth} setiap bulan`;
      break;
    }
    case 'custom_periode': {
      txt = `○ Rentang Periode / Momentum Khusus`;
      break;
    }
    default:
      txt = getPlannerRecurrenceLabel(selType);
  }
  textEl.textContent = txt;
}

function renderPlannerRecurrenceInputs(type, rule, defaultDate) {
  rule = rule || {};
  const HIJRI_LIST = HIJRI_MONTHS;
  const DOW_LIST = ['Senin','Selasa','Rabu','Kamis','Jumat','Sabtu','Minggu'];
  let inputsHtml = '';
  const normType = normalizePlannerRecurrenceType(type);

  switch(normType) {
    case 'setiap_bulan': {
      const curSetiapBulanDay = rule.day || (defaultDate ? parseInt(defaultDate.split('-')[2], 10) : 15);
      inputsHtml = `
        <div class="field" style="margin-bottom:10px">
          <label style="font-weight:600;font-size:12.5px">Tanggal Setiap Bulan (1–31)</label>
          <input class="input" type="number" id="cp_rec_day" min="1" max="31" value="${curSetiapBulanDay}" required>
          <span class="hint">Berulang rutin 1 KALI setiap bulan pada tanggal yang dipilih.</span>
        </div>`;
      break;
    }
    case 'tanggal_masehi_tahunan': {
      const curDay = rule.day || (defaultDate ? parseInt(defaultDate.split('-')[2], 10) : 1);
      const curMonth = Number(rule.month || (defaultDate ? parseInt(defaultDate.split('-')[1], 10) : 1));
      inputsHtml = `
        <div class="grid-2">
          <div class="field" style="margin-bottom:10px">
            <label style="font-weight:600;font-size:12.5px">Tanggal (1–31)</label>
            <input class="input" type="number" id="cp_rec_day" min="1" max="31" value="${curDay}" required>
          </div>
          <div class="field" style="margin-bottom:10px">
            <label style="font-weight:600;font-size:12.5px">Bulan Masehi</label>
            <select class="input" id="cp_rec_month">
              ${MONTHS.map((m,i)=>`<option value="${i+1}" ${curMonth===(i+1)?'selected':''}>${m}</option>`).join('')}
            </select>
          </div>
        </div>
        <span class="hint" style="display:block;margin-top:-4px;margin-bottom:10px;">Berulang otomatis setiap tahun pada tanggal &amp; bulan Masehi yang sama (Tanggal Pasti).</span>`;
      break;
    }
    case 'bulan_masehi': {
      const curMonth = Number(rule.month || (defaultDate ? parseInt(defaultDate.split('-')[1], 10) : 1));
      inputsHtml = `
        <div class="field" style="margin-bottom:10px">
          <label style="font-weight:600;font-size:12.5px">Pilih Bulan Masehi</label>
          <select class="input" id="cp_rec_month">
            ${MONTHS.map((m,i)=>`<option value="${i+1}" ${curMonth===(i+1)?'selected':''}>${m}</option>`).join('')}
          </select>
          <span class="hint">Aktif sebagai momentum sepanjang bulan yang dipilih setiap tahunnya (Tanggal belum ditentukan).</span>
        </div>`;
      break;
    }
    case 'tanggal_hijriah': {
      const curHDay = rule.day || 1;
      const curHMonth = normalizeHijriMonth(rule.month || 'Muharram');
      inputsHtml = `
        <div class="grid-2">
          <div class="field" style="margin-bottom:10px">
            <label style="font-weight:600;font-size:12.5px">Tanggal Hijriah (1–30)</label>
            <input class="input" type="number" id="cp_rec_h_day" min="1" max="30" value="${curHDay}" required>
          </div>
          <div class="field" style="margin-bottom:10px">
            <label style="font-weight:600;font-size:12.5px">Bulan Hijriah</label>
            <select class="input" id="cp_rec_h_month">
              ${HIJRI_LIST.map(m=>`<option value="${m}" ${normalizeHijriMonth(m)===curHMonth?'selected':''}>${m}</option>`).join('')}
            </select>
          </div>
        </div>
        <span class="hint" style="display:block;margin-top:-4px;margin-bottom:10px;">Tanggal Pasti: Kalender PTV akan mencocokkan konversi kalender Hijriah otomatis (misal: 9 Muharram, 12 Rabiul Awal).</span>`;
      break;
    }
    case 'bulan_hijriah': {
      const curHMonth = normalizeHijriMonth(rule.month || 'Rabiul Akhir');
      inputsHtml = `
        <div class="field" style="margin-bottom:10px">
          <label style="font-weight:600;font-size:12.5px">Pilih Bulan Hijriah</label>
          <select class="input" id="cp_rec_h_month">
            ${HIJRI_LIST.map(m=>`<option value="${m}" ${normalizeHijriMonth(m)===curHMonth?'selected':''}>${m}</option>`).join('')}
          </select>
          <div style="margin-top:8px;padding:9px 12px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:10px;font-size:12px;color:#1e40af;line-height:1.4;">
            <i class="fa-solid fa-circle-info" style="margin-right:5px;"></i><b>Tanggal belum ditentukan:</b> Event ini aktif sepanjang bulan Hijriah yang dipilih. Tidak akan dipaksa menjadi tanggal 1 dan tetap muncul pada seluruh bulan kalender Masehi yang beririsan.
          </div>
        </div>`;
      break;
    }
    case 'bagian_bulan_hijriah': {
      const curSeg = (rule.segment || 'awal').toLowerCase();
      const curHMonth = normalizeHijriMonth(rule.month || 'Ramadhan');
      inputsHtml = `
        <div class="grid-2">
          <div class="field" style="margin-bottom:10px">
            <label style="font-weight:600;font-size:12.5px">Bagian Bulan</label>
            <select class="input" id="cp_rec_segment">
              <option value="awal" ${curSeg==='awal'?'selected':''}>Awal Bulan (Tgl 1–10)</option>
              <option value="pertengahan" ${curSeg==='pertengahan'?'selected':''}>Pertengahan Bulan (Tgl 11–20)</option>
              <option value="akhir" ${curSeg==='akhir'?'selected':''}>Akhir Bulan (Tgl 21–Akhir)</option>
              <option value="menjelang" ${curSeg==='menjelang'?'selected':''}>Menjelang Akhir (Tgl 25–Akhir)</option>
            </select>
          </div>
          <div class="field" style="margin-bottom:10px">
            <label style="font-weight:600;font-size:12.5px">Bulan Hijriah</label>
            <select class="input" id="cp_rec_h_month">
              ${HIJRI_LIST.map(m=>`<option value="${m}" ${normalizeHijriMonth(m)===curHMonth?'selected':''}>${m}</option>`).join('')}
            </select>
          </div>
        </div>
        <span class="hint" style="display:block;margin-top:-4px;margin-bottom:10px;">Cocok untuk persiapan momentum seperti Awal Ramadhan, Menjelang Idul Fitri, dsb.</span>`;
      break;
    }
    case 'hari_mingguan': {
      const curDow = rule.dayOfWeek || 'Kamis';
      inputsHtml = `
        <div class="field" style="margin-bottom:10px">
          <label style="font-weight:600;font-size:12.5px">Pilih Hari Mingguan</label>
          <select class="input" id="cp_rec_dow">
            ${DOW_LIST.map(d=>`<option value="${d}" ${d.toLowerCase()===curDow.toLowerCase()?'selected':''}>${d}</option>`).join('')}
          </select>
          <span class="hint">Berulang rutin setiap pekan pada hari yang ditentukan (misal: Setiap Kamis).</span>
        </div>`;
      break;
    }
    case 'hari_weton': {
      const curDow = rule.dayOfWeek || 'Kamis';
      const curPasaran = rule.pasaran || 'Legi';
      inputsHtml = `
        <div class="grid-2">
          <div class="field" style="margin-bottom:10px">
            <label style="font-weight:600;font-size:12.5px">Hari</label>
            <select class="input" id="cp_rec_dow">
              ${DOW_LIST.map(d=>`<option value="${d}" ${d.toLowerCase()===curDow.toLowerCase()?'selected':''}>${d}</option>`).join('')}
            </select>
          </div>
          <div class="field" style="margin-bottom:10px">
            <label style="font-weight:600;font-size:12.5px">Pasaran Jawa (Weton)</label>
            <select class="input" id="cp_rec_pasaran">
              ${['Legi','Pahing','Pon','Wage','Kliwon'].map(p=>`<option value="${p}" ${p.toLowerCase()===curPasaran.toLowerCase()?'selected':''}>${p}</option>`).join('')}
            </select>
          </div>
        </div>
        <span class="hint" style="display:block;margin-top:-4px;margin-bottom:10px;">Mengikuti siklus weton 35 hari sekali (misal: Kamis Legi, Jumat Kliwon).</span>`;
      break;
    }
    case 'minggu_ke_n': {
      inputsHtml = `
        <div class="grid-2">
          <div class="field" style="margin-bottom:10px">
            <label style="font-weight:600;font-size:12.5px">Urutan Minggu</label>
            <select class="input" id="cp_rec_nth">
              <option value="1" ${rule.nth==1?'selected':''}>Minggu ke-1</option>
              <option value="2" ${rule.nth==2?'selected':''}>Minggu ke-2</option>
              <option value="3" ${rule.nth==3?'selected':''}>Minggu ke-3</option>
              <option value="4" ${rule.nth==4?'selected':''}>Minggu ke-4</option>
            </select>
          </div>
          <div class="field" style="margin-bottom:10px">
            <label style="font-weight:600;font-size:12.5px">Hari</label>
            <select class="input" id="cp_rec_dow">
              ${['Minggu', ...DOW_LIST.slice(0, 6)].map(d=>`<option value="${d}" ${(rule.dayOfWeek||'Minggu').toLowerCase()===d.toLowerCase()?'selected':''}>${d}</option>`).join('')}
            </select>
          </div>
        </div>
        <span class="hint" style="display:block;margin-top:-4px;margin-bottom:10px;">Contoh: Minggu pertama setiap bulan.</span>`;
      break;
    }
    case 'hari_ke_n': {
      inputsHtml = `
        <div class="grid-2">
          <div class="field" style="margin-bottom:10px">
            <label style="font-weight:600;font-size:12.5px">Urutan Kemunculan</label>
            <select class="input" id="cp_rec_nth">
              <option value="1" ${rule.nth==1?'selected':''}>Pertama (ke-1)</option>
              <option value="2" ${rule.nth==2?'selected':''}>Kedua (ke-2)</option>
              <option value="3" ${rule.nth==3?'selected':''}>Ketiga (ke-3)</option>
              <option value="4" ${rule.nth==4?'selected':''}>Keempat (ke-4)</option>
            </select>
          </div>
          <div class="field" style="margin-bottom:10px">
            <label style="font-weight:600;font-size:12.5px">Hari</label>
            <select class="input" id="cp_rec_dow">
              ${DOW_LIST.map(d=>`<option value="${d}" ${(rule.dayOfWeek||'Selasa').toLowerCase()===d.toLowerCase()?'selected':''}>${d}</option>`).join('')}
            </select>
          </div>
        </div>
        <span class="hint" style="display:block;margin-top:-4px;margin-bottom:10px;">Contoh: Selasa pertama setiap bulan.</span>`;
      break;
    }
    case 'custom_periode': {
      inputsHtml = `
        <div class="grid-2">
          <div class="field" style="margin-bottom:10px">
            <label style="font-weight:600;font-size:12.5px">Bulan Hijriah Acuan (Opsional)</label>
            <select class="input" id="cp_rec_h_month">
              <option value="">— Tidak pakai —</option>
              ${HIJRI_LIST.map(m=>`<option value="${m}" ${normalizeHijriMonth(m)===normalizeHijriMonth(rule.monthHijri||'')?'selected':''}>${m}</option>`).join('')}
            </select>
          </div>
          <div class="field" style="margin-bottom:10px">
            <label style="font-weight:600;font-size:12.5px">Bulan Masehi Acuan (Opsional)</label>
            <select class="input" id="cp_rec_month">
              <option value="">— Tidak pakai —</option>
              ${MONTHS.map((m,i)=>`<option value="${i+1}" ${Number(rule.monthMasehi||0)===(i+1)?'selected':''}>${m}</option>`).join('')}
            </select>
          </div>
        </div>
        <div class="grid-2">
          <div class="field" style="margin-bottom:10px">
            <label style="font-weight:600;font-size:12.5px">Tanggal Mulai (Opsional)</label>
            <input class="input" type="date" id="cp_rec_start" value="${rule.start || defaultDate || ''}">
          </div>
          <div class="field" style="margin-bottom:10px">
            <label style="font-weight:600;font-size:12.5px">Tanggal Selesai (Opsional)</label>
            <input class="input" type="date" id="cp_rec_end" value="${rule.end || ''}">
          </div>
        </div>`;
      break;
    }
    case 'sekali_tayang':
    default:
      inputsHtml = `
        <div class="field" style="margin-bottom:10px">
          <label style="font-weight:600;font-size:12.5px">Tanggal Pelaksanaan Spesifik</label>
          <input class="input" type="date" id="cp_tanggal_mulai" value="${defaultDate || ''}" required>
          <span class="hint">Tanggal Pasti: Hanya berlaku pada satu tanggal tertentu (tidak berulang).</span>
        </div>`;
      break;
  }

  return `
    ${inputsHtml}
    <div id="cp_preview_box" style="margin-top:10px;padding:9px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:10px;display:flex;align-items:center;gap:8px;">
      <i class="fa-regular fa-clock" style="color:#64748b;font-size:13px;flex-shrink:0;"></i>
      <span id="cp_preview_text" style="font-size:12px;font-weight:600;color:#334155;line-height:1.4;"></span>
    </div>
  `;
}

function openPlannerDetail(id){
  const p = (DB.content_planner||[]).find(x=>String(x.id)===String(id));
  if(!p) return;

  const rawDaftar = normalizeContentList(p.daftar_konten);
  const refUrls = (p.referensi_url || '').split(/[\n,]+/).map(u=>u.trim()).filter(Boolean);
  const rec = getPlannerRecurrence(p);
  const recLabel = getRecurrenceLabel(rec);

  // Detail semantic date representation
  let dateBadgeHtml = '';
  let noticeExplanationHtml = '';

  if (rec.precision === 'MONTH' || (p.bulan_hijriah && !p.tanggal_hijriah && !p.tanggal_mulai)) {
    const mName = p.bulan_hijriah || 'Bulan Hijriah';
    dateBadgeHtml = `
      <span class="chip" style="font-size:11px;padding:2px 8px;background:#f5f3ff;color:#6d28d9;border:1px solid #ddd6fe;font-weight:700;">○ Sepanjang ${esc(mName)} H</span>
      <span class="chip" style="font-size:11px;padding:2px 8px;background:#fffbeb;color:#b45309;border:1px solid #fde68a;font-weight:700;">○ Tanggal Belum Ditentukan</span>
    `;
    noticeExplanationHtml = `
      <div style="padding:12px 14px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:12px;display:flex;align-items:flex-start;gap:10px;margin-top:14px;">
        <i class="fa-solid fa-circle-info" style="color:#2563eb;font-size:15px;margin-top:2px;flex-shrink:0;"></i>
        <div style="font-size:12.5px;color:#1e40af;line-height:1.45;">
          Event ini dijadwalkan pada bulan <b>${esc(mName)}</b>. Tanggal pelaksanaan belum ditentukan dan akan tampil pada setiap bulan kalender Masehi yang beririsan.
        </div>
      </div>
    `;
  } else if (rec.precision === 'MONTH_SEGMENT') {
    const segMap = { awal: 'Awal', pertengahan: 'Pertengahan', akhir: 'Akhir', menjelang: 'Menjelang' };
    const seg = segMap[(rec.rule?.segment || 'awal').toLowerCase()] || 'Awal';
    const mName = p.bulan_hijriah || rec.rule?.month || 'Bulan Hijriah';
    dateBadgeHtml = `
      <span class="chip" style="font-size:11px;padding:2px 8px;background:#f5f3ff;color:#6d28d9;border:1px solid #ddd6fe;font-weight:700;">◐ ${esc(seg)} ${esc(mName)} H</span>
      <span class="chip" style="font-size:11px;padding:2px 8px;background:#e0e7ff;color:#4338ca;border:1px solid #c7d2fe;font-weight:700;">Periode Bagian Bulan</span>
    `;
    noticeExplanationHtml = `
      <div style="padding:12px 14px;background:#f5f3ff;border:1px solid #ddd6fe;border-radius:12px;display:flex;align-items:flex-start;gap:10px;margin-top:14px;">
        <i class="fa-solid fa-layer-group" style="color:#7c3aed;font-size:15px;margin-top:2px;flex-shrink:0;"></i>
        <div style="font-size:12.5px;color:#5b21b6;line-height:1.45;">
          Event ini dijadwalkan pada periode <b>${esc(seg)} ${esc(mName)}</b>.
        </div>
      </div>
    `;
  } else {
    // Exact Date
    let dateStr = '';
    if (p.tanggal_mulai) {
      const dObj = new Date(p.tanggal_mulai.includes('T') ? p.tanggal_mulai : p.tanggal_mulai + 'T00:00:00');
      dateStr = isNaN(dObj) ? p.tanggal_mulai : `${dObj.getDate()} ${MONTHS[dObj.getMonth()]} ${dObj.getFullYear()}`;
    }
    if (p.bulan_hijriah && p.tanggal_hijriah) {
      dateStr += (dateStr ? ' · ' : '') + `${p.tanggal_hijriah} ${p.bulan_hijriah} H`;
    }
    if (!dateStr) dateStr = 'Tanggal Pasti Terjadwal';
    dateBadgeHtml = `
      <span class="chip" style="font-size:11px;padding:2px 8px;background:#ecfdf5;color:#047857;border:1px solid #a7f3d0;font-weight:700;">● ${esc(dateStr)}</span>
      <span class="chip" style="font-size:11px;padding:2px 8px;background:#f0fdf4;color:#166534;border:1px solid #bbf7d0;font-weight:700;">● Tanggal Pasti</span>
    `;
  }

  const canManage = (state.role === 'eksekutif' || state.role === 'administrasi' || ME.role === 'eksekutif' || ME.role === 'administrasi');

  openSheet('Detail Content Planner',`
    <div class="row-b" style="align-items:flex-start;gap:12px;">
      <div class="tight" style="flex:1;">
        <div class="t-lg" style="font-weight:800;color:var(--ink);">${esc(p.judul_momentum)}</div>
        <div style="display:flex;align-items:center;flex-wrap:wrap;gap:6px;margin-top:6px;">
          <span class="chip" style="font-size:11px;padding:2px 8px;background:#eef2ff;color:#4f46e5;border:1px solid #c7d2fe;font-weight:700;">${esc(getPlannerCategoryLabel(p.kategori))}</span>
          ${p.subkategori ? `<span class="chip" style="font-size:11px;padding:2px 8px;">${esc(p.subkategori)}</span>` : ''}
          ${dateBadgeHtml}
          ${recLabel ? `<span class="chip" style="font-size:11px;padding:2px 8px;background:#f8fafc;color:#475569;border:1px solid #cbd5e1;font-weight:700;"><i class="fa-solid fa-repeat" style="margin-right:4px;"></i>${esc(recLabel)}</span>` : ''}
        </div>
        ${noticeExplanationHtml}
      </div>
    </div>

    <!-- Rincian Ide / Kebutuhan Konten -->
    <div class="sec" style="margin-top:16px;">
      ${sectionHd('Daftar Ide / Format Konten (' + rawDaftar.length + ')')}
      ${rawDaftar.length ? `
        <div class="list" style="gap:8px;">
          ${rawDaftar.map((item, idx) => `
            <div class="li" style="padding:10px 14px;background:var(--bg);border-radius:12px;border:1px solid var(--line);">
              <span style="display:inline-flex;align-items:center;justify-content:center;width:22px;height:22px;border-radius:6px;background:#ede9fe;color:#7c3aed;font-size:11px;font-weight:700;flex-shrink:0;">${idx+1}</span>
              <span class="li-body" style="margin-left:6px;">
                <span class="li-t" style="font-size:13.5px;font-weight:600;color:var(--ink);white-space:normal;line-height:1.4;">${esc(item)}</span>
              </span>
            </div>
          `).join('')}
        </div>
      ` : `<p class="t-sm muted" style="margin:0;">Belum ada item rincian konten.</p>`}
    </div>

    <!-- Deskripsi, Doa & Panduan -->
    ${p.deskripsi ? `
      <div class="sec" style="margin-top:16px;">
        ${sectionHd('Catatan, Doa & Panduan')}
        <div class="card pad" style="background:var(--bg);border:1px solid var(--line);border-radius:14px;">
          <p class="t-sm ink2" style="margin:0;white-space:pre-wrap;line-height:1.6;font-family:inherit;">${esc(p.deskripsi.replace(/<!-- PTV_RECURRENCE:[\s\S]*?-->/g, '').trim())}</p>
        </div>
      </div>
    ` : ''}

    <!-- Referensi & Link Contoh -->
    ${refUrls.length ? `
      <div class="sec" style="margin-top:16px;">
        ${sectionHd('Referensi Publikasi & Inspirasi')}
        <div style="display:flex;flex-direction:column;gap:8px;">
          ${refUrls.map(u => {
            const isIG = u.includes('instagram.com');
            const isTT = u.includes('tiktok.com');
            const isDrive = u.includes('drive.google.com') || u.includes('s.id');
            const icClass = isIG ? 'fa-brands fa-instagram' : (isTT ? 'fa-brands fa-tiktok' : (isDrive ? 'fa-brands fa-google-drive' : 'fa-solid fa-link'));
            const badgeColor = isIG ? '#e1306c' : (isTT ? '#000000' : (isDrive ? '#0f9d58' : '#6366f1'));
            return `
              <a href="${esc(u)}" target="_blank" rel="noopener noreferrer" class="btn" style="display:flex;align-items:center;justify-content:flex-start;gap:10px;padding:10px 14px;background:var(--bg);border:1px solid var(--line);border-radius:12px;text-decoration:none;">
                <i class="${icClass}" style="color:${badgeColor};font-size:16px;flex-shrink:0;"></i>
                <span class="trunc" style="font-size:12.5px;font-weight:600;color:var(--ink);flex:1;">${esc(u)}</span>
                <i class="fa-solid fa-arrow-up-right-from-square" style="font-size:12px;color:var(--muted);flex-shrink:0;"></i>
              </a>
            `;
          }).join('')}
        </div>
      </div>
    ` : ''}
  `, {
    foot: canManage ? `<div class="wrap" style="width:100%;display:flex;gap:8px;">
      <button class="btn" data-act="openEditPlanner:${p.id}"><i class="fa-solid fa-pen-to-square"></i>Edit Planner</button>
      <button class="btn dang" data-act="confirmDeletePlanner:${p.id}">${ic.trash}Hapus</button>
    </div>` : ''
  });
}

function openNewPlanner(presetDate){
  const defaultDate = presetDate || (calSel !== iso(today) ? calSel : '');

  openSheet('Tambah Momentum Content Planner',
    field('Judul Momentum / Acara', `<input class="input" id="cp_judul" placeholder="Contoh: Haul Solo / Haul Ploso / Semarak Ramadhan" required autocomplete="off">`) +
    `<div class="grid-2">
      ${field('Kategori', renderPlannerCategorySelect('cp_kategori', 'Event Hijriyah'))}
      ${field('Subkategori / Label', `<input class="input" id="cp_subkategori" placeholder="Contoh: Rabiul Akhir / Haul / Ramadhan">`)}
    </div>` +
    `<div class="card pad" style="background:var(--bg-2);border:1px solid var(--line-2);border-radius:var(--r-m);margin-bottom:12px;">
      ${field('Pola Waktu / Pengulangan Konten', renderPlannerRecurrenceSelect('cp_recurrence_type', 'sekali_tayang'))}
      <div id="cp_rec_container">
        ${renderPlannerRecurrenceInputs('sekali_tayang', {}, defaultDate)}
      </div>
    </div>` +
    field('Daftar Ide / Format Konten (1 baris per item)', `<textarea class="input" id="cp_daftar_konten" rows="4" placeholder="Contoh:\nFeed Ucapan Selamat\nStory Live Streaming\nReels Cuplikan Mauidhoh"></textarea>`) +
    field('Catatan / Panduan / Teks Doa', `<textarea class="input" id="cp_deskripsi" rows="3" placeholder="Teks doa, biografi, rundown, atau amalan khusus..."></textarea>`) +
    field('Referensi URL / Link Contoh (Pisahkan dengan baris baru)', `<textarea class="input" id="cp_referensi_url" rows="2" placeholder="https://instagram.com/p/..."></textarea>`),
    {
      foot:`<button class="btn block pri" data-act="saveNewPlanner" style="background:#6366f1;color:#fff;border:none;">${ic.check}Simpan ke Supabase</button>`,
      then:(sheetBody)=>{
        const sel = $('#cp_recurrence_type', sheetBody);
        const box = $('#cp_rec_container', sheetBody);
        const attachInputsListener = () => {
          updatePlannerPreviewBox(sheetBody);
          box.querySelectorAll('input, select').forEach(el => {
            el.addEventListener('input', () => updatePlannerPreviewBox(sheetBody));
            el.addEventListener('change', () => updatePlannerPreviewBox(sheetBody));
          });
        };
        if(sel && box){
          sel.addEventListener('change', ()=>{
            box.innerHTML = renderPlannerRecurrenceInputs(sel.value, {}, defaultDate);
            attachInputsListener();
          });
          attachInputsListener();
        }
      }
    }
  );
}

function openEditPlanner(id){
  const p = (DB.content_planner||[]).find(x=>String(x.id)===String(id));
  if(!p) return;

  const rawDaftar = normalizeContentList(p.daftar_konten);
  const rec = getPlannerRecurrence(p);
  const currentRecType = normalizePlannerRecurrenceType(rec.type || (p.tanggal_mulai ? 'sekali_tayang' : (p.bulan_hijriah && p.tanggal_hijriah ? 'tanggal_hijriah' : (p.bulan_hijriah ? 'bulan_hijriah' : 'sekali_tayang'))));

  openSheet('Edit Momentum Content Planner',
    field('Judul Momentum / Acara', `<input class="input" id="cp_judul" value="${esc(p.judul_momentum)}" required autocomplete="off">`) +
    `<div class="grid-2">
      ${field('Kategori', renderPlannerCategorySelect('cp_kategori', p.kategori || 'Event Hijriyah'))}
      ${field('Subkategori / Label', `<input class="input" id="cp_subkategori" value="${esc(p.subkategori||'')}">`)}
    </div>` +
    `<div class="card pad" style="background:var(--bg-2);border:1px solid var(--line-2);border-radius:var(--r-m);margin-bottom:12px;">
      ${field('Pola Waktu / Pengulangan Konten', renderPlannerRecurrenceSelect('cp_recurrence_type', currentRecType))}
      <div id="cp_rec_container">
        ${renderPlannerRecurrenceInputs(currentRecType, rec.rule || {}, p.tanggal_mulai || '')}
      </div>
    </div>` +
    field('Daftar Ide / Format Konten (1 baris per item)', `<textarea class="input" id="cp_daftar_konten" rows="4">${esc(rawDaftar.join('\n'))}</textarea>`) +
    field('Catatan / Panduan / Teks Doa', `<textarea class="input" id="cp_deskripsi" rows="3">${esc(p.deskripsi ? p.deskripsi.replace(/<!-- PTV_RECURRENCE:[\s\S]*?-->/g, '').trim() : '')}</textarea>`) +
    field('Referensi URL / Link Contoh (Pisahkan dengan baris baru)', `<textarea class="input" id="cp_referensi_url" rows="2">${esc(p.referensi_url||'')}</textarea>`),
    {
      foot:`<button class="btn block pri" data-act="saveEditPlanner:${p.id}" style="background:#6366f1;color:#fff;border:none;">${ic.check}Perbarui di Supabase</button>`,
      then:(sheetBody)=>{
        const sel = $('#cp_recurrence_type', sheetBody);
        const box = $('#cp_rec_container', sheetBody);
        const attachInputsListener = () => {
          updatePlannerPreviewBox(sheetBody);
          box.querySelectorAll('input, select').forEach(el => {
            el.addEventListener('input', () => updatePlannerPreviewBox(sheetBody));
            el.addEventListener('change', () => updatePlannerPreviewBox(sheetBody));
          });
        };
        if(sel && box){
          sel.addEventListener('change', ()=>{
            box.innerHTML = renderPlannerRecurrenceInputs(sel.value, rec.rule || {}, p.tanggal_mulai || '');
            attachInputsListener();
          });
          attachInputsListener();
        }
      }
    }
  );
}

function savePlanner(isEdit, id){
  const judul = ($('#cp_judul')?.value||'').trim();
  if(!judul){ toast('Judul momentum wajib diisi.','info'); return; }
  const rawKategori = $('#cp_kategori')?.value || 'Event Hijriyah';
  const kategori = normalizePlannerCategory(rawKategori);
  let subkategori = ($('#cp_subkategori')?.value||'').trim();
  const rawRecType = $('#cp_recurrence_type')?.value || 'sekali_tayang';
  const recurrence_type = normalizePlannerRecurrenceType(rawRecType);
  let recurrence_rule = {};

  let tanggal_mulai = '';
  let bulan_hijriah = '';
  let tanggal_hijriah = '';

  if (recurrence_type === 'setiap_bulan' || recurrence_type === 'bulanan') {
    const selDay = Math.min(31, Math.max(1, Number($('#cp_rec_day')?.value || 15)));
    recurrence_rule = { day: selDay, repeat: 'every_month' };
  } else if (recurrence_type === 'tanggal_masehi_tahunan' || recurrence_type === 'tanggal_masehi') {
    const dVal = Math.min(31, Math.max(1, Number($('#cp_rec_day')?.value || 1)));
    const mVal = Number($('#cp_rec_month')?.value || 1);
    recurrence_rule = { day: dVal, month: mVal, repeat: 'every_year' };
    const curYear = new Date().getFullYear();
    tanggal_mulai = `${curYear}-${String(mVal).padStart(2,'0')}-${String(dVal).padStart(2,'0')}`;
  } else if (recurrence_type === 'bulan_masehi') {
    const mVal = Number($('#cp_rec_month')?.value || 1);
    recurrence_rule = { month: mVal };
    // Tanggal pelaksanaan belum ditentukan
  } else if (recurrence_type === 'tanggal_hijriah') {
    const hDay = Math.min(30, Math.max(1, Number($('#cp_rec_h_day')?.value || 1)));
    const hMonth = $('#cp_rec_h_month')?.value || 'Muharram';
    recurrence_rule = { day: hDay, month: hMonth };
    bulan_hijriah = hMonth;
    tanggal_hijriah = String(hDay);
    if (!subkategori) subkategori = hMonth;
  } else if (recurrence_type === 'bulan_hijriah') {
    const hMonth = $('#cp_rec_h_month')?.value || 'Rabiul Akhir';
    recurrence_rule = { month: hMonth };
    bulan_hijriah = hMonth;
    tanggal_hijriah = ''; // PENTING: NULL, JANGAN PERNAH 1!
    if (!subkategori) subkategori = hMonth;
  } else if (recurrence_type === 'bagian_bulan_hijriah' || recurrence_type === 'month_segment') {
    const seg = $('#cp_rec_segment')?.value || 'awal';
    const hMonth = $('#cp_rec_h_month')?.value || 'Ramadhan';
    const segLabels = { awal: 'Awal', pertengahan: 'Pertengahan', akhir: 'Akhir', menjelang: 'Menjelang' };
    recurrence_rule = { segment: seg, month: hMonth, segmentLabel: `${segLabels[seg] || 'Awal'} ${hMonth}` };
    bulan_hijriah = hMonth;
    tanggal_hijriah = ''; // NULL
    if (!subkategori) subkategori = `${segLabels[seg] || 'Awal'} ${hMonth}`;
  } else if (recurrence_type === 'hari_mingguan') {
    recurrence_rule = { dayOfWeek: $('#cp_rec_dow')?.value || 'Kamis' };
  } else if (recurrence_type === 'hari_weton' || recurrence_type === 'hari_pasaran') {
    recurrence_rule = {
      dayOfWeek: $('#cp_rec_dow')?.value || 'Kamis',
      pasaran: $('#cp_rec_pasaran')?.value || 'Legi'
    };
  } else if (recurrence_type === 'minggu_ke_n') {
    recurrence_rule = {
      nth: Number($('#cp_rec_nth')?.value || 1),
      dayOfWeek: $('#cp_rec_dow')?.value || 'Minggu'
    };
  } else if (recurrence_type === 'hari_ke_n') {
    recurrence_rule = {
      nth: Number($('#cp_rec_nth')?.value || 1),
      dayOfWeek: $('#cp_rec_dow')?.value || 'Selasa'
    };
  } else if (recurrence_type === 'custom_periode') {
    recurrence_rule = {
      monthHijri: $('#cp_rec_h_month')?.value || '',
      monthMasehi: $('#cp_rec_month')?.value || '',
      start: $('#cp_rec_start')?.value || '',
      end: $('#cp_rec_end')?.value || ''
    };
    if (recurrence_rule.monthHijri) bulan_hijriah = recurrence_rule.monthHijri;
    if (recurrence_rule.start) tanggal_mulai = recurrence_rule.start;
  } else {
    // Sekali tayang / none: tanggal pelaksanaan spesifik
    tanggal_mulai = ($('#cp_tanggal_mulai')?.value || '').trim();
    if (!tanggal_mulai) {
      toast('Silakan pilih tanggal pelaksanaan spesifik.', 'info');
      return;
    }
  }

  let rawDeskripsi = ($('#cp_deskripsi')?.value||'').trim();
  rawDeskripsi = rawDeskripsi.replace(/<!-- PTV_RECURRENCE:[\s\S]*?-->/g, '').trim();
  let finalDeskripsi = rawDeskripsi;
  if (recurrence_type !== 'sekali_tayang' && recurrence_type !== 'none') {
    finalDeskripsi += (finalDeskripsi ? '\n\n' : '') + `<!-- PTV_RECURRENCE: ${JSON.stringify({ type: recurrence_type, rule: recurrence_rule })} -->`;
  }

  const rawListText = ($('#cp_daftar_konten')?.value||'').trim();
  const daftar_konten = rawListText ? rawListText.split('\n').map(s=>s.trim()).filter(Boolean) : [];
  const referensi_url = ($('#cp_referensi_url')?.value||'').trim();

  // Submit button loading state
  const submitBtn = document.querySelector(`[data-act="${isEdit ? 'saveEditPlanner:' + id : 'saveNewPlanner'}"]`) || document.querySelector('.sheet-foot button.pri');
  let origPlannerBtnHtml = '';
  if(submitBtn){
    origPlannerBtnHtml = submitBtn.innerHTML;
    submitBtn.disabled = true;
    submitBtn.style.opacity = '0.75';
    submitBtn.style.cursor = 'not-allowed';
    submitBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin" style="margin-right:8px;font-size:14px;"></i><span>Menyimpan ke Supabase...</span>';
  }

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_save_planner');
  if (isEdit && id) fd.append('id', id);
  fd.append('judul_momentum', judul);
  fd.append('kategori', kategori);
  fd.append('subkategori', subkategori);
  fd.append('tanggal_mulai', tanggal_mulai);
  fd.append('bulan_hijriah', bulan_hijriah);
  fd.append('tanggal_hijriah', tanggal_hijriah);
  fd.append('deskripsi', finalDeskripsi);
  fd.append('daftar_konten', JSON.stringify(daftar_konten));
  fd.append('referensi_url', referensi_url);
  fd.append('recurrence_type', recurrence_type);
  fd.append('recurrence_rule', JSON.stringify(recurrence_rule));

  fetch(AJAX_URL, { method:'POST', body:fd })
    .then(r=>r.json())
    .then(res=>{
      if(res.success && res.data?.planner){
        const real = res.data.planner;
        const isMonthLevel = (recurrence_type === 'bulan_hijriah' || recurrence_type === 'bulan_masehi');
        const isMonthSegment = (recurrence_type === 'bagian_bulan_hijriah' || recurrence_type === 'month_segment');
        const isCustom = (recurrence_type === 'custom_periode' && !tanggal_mulai);
        const parsedPrecision = isMonthLevel ? 'MONTH' : (isMonthSegment ? 'MONTH_SEGMENT' : (isCustom ? 'CUSTOM_PERIOD' : 'EXACT'));
        const parsedRec = { type: recurrence_type, rule: recurrence_rule, precision: parsedPrecision };
        if(isEdit && id){
          const it = (DB.content_planner || []).find(x => String(x.id) === String(id));
          if(it) Object.assign(it, real, { recurrence_type, recurrence_rule, _recParsed: parsedRec });
        } else {
          if(!DB.content_planner) DB.content_planner = [];
          DB.content_planner.unshift(Object.assign(real, { recurrence_type, recurrence_rule, _recParsed: parsedRec }));
        }
        closeSheet();
        toast(isEdit ? 'Momentum planner diperbarui di Supabase.' : 'Momentum baru tersimpan di Supabase.', 'check');
        if(state.route.page==='kalender' && document.getElementById('acaraContent')){
          updateAcaraSubView('kalender');
        } else {
          render();
        }
      } else {
        if(submitBtn){
          submitBtn.disabled = false;
          submitBtn.style.opacity = '1';
          submitBtn.style.cursor = 'pointer';
          submitBtn.innerHTML = origPlannerBtnHtml;
        }
        toast(res.data?.message || 'Gagal menyimpan data Content Planner.', 'danger');
      }
    })
    .catch(err=>{
      console.error('[savePlanner] Error:', err);
      if(submitBtn){
        submitBtn.disabled = false;
        submitBtn.style.opacity = '1';
        submitBtn.style.cursor = 'pointer';
        submitBtn.innerHTML = origPlannerBtnHtml;
      }
      toast('Terjadi kesalahan jaringan saat menyimpan data.', 'danger');
    });
}

function confirmDeletePlanner(id){
  const p = (DB.content_planner||[]).find(x=>String(x.id)===String(id));
  if(!p) return;
  if(!confirm(`Hapus permanen momentum planner "${p.judul_momentum}" dari Supabase?`)) return;

  DB.content_planner = DB.content_planner.filter(x => String(x.id) !== String(id));
  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_delete_planner');
  fd.append('id', id);
  fetch(AJAX_URL, { method:'POST', body:fd }).catch(()=>{});

  closeSheet();
  toast('Momentum planner berhasil dihapus dari Supabase.', 'check');
  if(state.route.page==='kalender' && document.getElementById('acaraContent')){
    updateAcaraSubView('kalender');
  } else {
    render();
  }
}

function seedPlannerMaster(){
  if (!confirm('Jalankan proses seed master data PDF ke Supabase (public.ptv_content_planner)?\n\nProses ini aman (idempotent) dan tidak akan menimpa data yang sudah Anda edit.')) return;
  toast('Sedang melakukan seed data ke Supabase...', 'info');

  const fd = new FormData();
  fd.append('action', 'ptv_dashboard_action_seed_planner');
  fetch(AJAX_URL, { method: 'POST', body: fd })
    .then(r => r.json())
    .then(res => {
      if (res.success && res.data) {
        if (Array.isArray(res.data.planner_list)) {
          DB.content_planner = res.data.planner_list;
        }
        toast(`Seed berhasil: ${res.data.inserted} momentum baru dimasukkan, ${res.data.skipped} dilewati (Total Supabase: ${res.data.verified_count}).`, 'check');
        if(state.route.page==='kalender' && document.getElementById('acaraContent')){
          updateAcaraSubView('kalender');
        } else {
          render();
        }
      } else {
        const msg = res.data?.message || res.data || 'Gagal melakukan seed ke Supabase.';
        toast(msg, 'error');
        alert('Gagal Seed ke Supabase:\n\n' + msg);
      }
    })
    .catch(err => {
      toast('Koneksi gagal saat melakukan seed.', 'error');
    });
}

/* ============================================================
   PAGE: GENERATOR SURAT IZIN RESMI (EKSEKUTIF)
