      <!-- Filters & Search -->
      <div class="flex flex-col lg:flex-row justify-between gap-4" style="display:flex; flex-direction:column; gap:16px;">
        <!-- Angkatan Chips -->
        <div id="izinAlphabetBar" class="flex overflow-x-auto gap-2.5 pb-2 hide-scrollbar" style="display:flex; overflow-x:auto; gap:10px; padding-bottom:8px;">
          <!-- Rendered by JS -->
        </div>

        <div class="flex flex-col sm:flex-row items-center justify-between gap-4 w-full" style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:16px;">
          <div class="relative w-full sm:w-64" style="position:relative; flex:1; min-width:240px; max-width:400px;">
            <i class="fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm" style="position:absolute; left:12px; top:50%; transform:translateY(-50%); color:#94a3b8; font-size:14px;"></i>
            <input type="text" id="izinSearchInput" oninput="izinFilterGrid()" class="w-full pl-9 pr-8 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-primary transition-all" style="width:100%; padding:10px 32px 10px 36px; background:#f8fafc; border:1px solid #e2e8f0; border-radius:12px; font-size:14px;" placeholder="Cari santri...">
            <button id="izinSearchClearBtn" onclick="izinClearSearch()" style="display:none; position:absolute; right:12px; top:50%; transform:translateY(-50%); border:none; background:transparent; color:#94a3b8; cursor:pointer; font-size:14px;">
              <i class="fa-solid fa-xmark"></i>
            </button>
          </div>
          <div class="flex items-center gap-4 shrink-0" style="display:flex; align-items:center; gap:16px;">
            <label class="inline-flex items-center gap-2 text-sm font-bold text-slate-700 cursor-pointer" style="display:inline-flex; align-items:center; gap:8px; font-size:14px; font-weight:700; color:#334155; cursor:pointer; user-select:none;">
              <input type="checkbox" id="izinCheckAll" class="w-4 h-4 accent-[#1e478f] rounded cursor-pointer" style="width:18px; height:18px; accent-color:#1e478f; cursor:pointer;">
