/* ── Push Notification Settings UI Helpers ── */
function isKeyMatching(sub, targetBytes) {
  if (!sub || !sub.options || !sub.options.applicationServerKey || !targetBytes) return false;
  const rawSubKey = new Uint8Array(sub.options.applicationServerKey);
  if (rawSubKey.byteLength !== targetBytes.byteLength) return false;
  for (let i = 0; i < rawSubKey.byteLength; i++) {
    if (rawSubKey[i] !== targetBytes[i]) return false;
  }
  return true;
}

async function syncPushSettingsUI() {
  const lbl = document.getElementById('push-status-label');
  const btn = document.getElementById('push-toggle-btn');
  if (!lbl || !btn) return;

  if (typeof PTVNotificationManager === 'undefined') {
    lbl.textContent = 'Memuat modul notifikasi...';
    return;
  }

  const state = PTVNotificationManager.getNotificationPermissionState();

  if (state === 'insecure_http') {
    lbl.innerHTML = '<span style="color:#d97706;font-weight:600"><i class="fa-solid fa-lock-open" style="font-size:11px;margin-right:4px;"></i>Koneksi HTTP (Perlu HTTPS)</span>';
    btn.innerHTML = `<button type="button" class="btn btn-sm btn-ghost" data-act="openInsecureModal" style="color:#d97706;border:1px solid #fde68a;font-size:11.5px;font-weight:650;padding:4px 10px;">Info HTTPS</button>`;
    return;
  }

  if (state === 'ios_safari_browser') {
    lbl.innerHTML = '<span style="color:#2563eb;font-weight:600"><i class="fa-brands fa-apple" style="font-size:11px;margin-right:4px;"></i>Khusus Safari iPhone/iPad</span>';
    btn.innerHTML = `<button type="button" class="btn btn-sm btn-ghost" data-act="openIOSModal" style="color:#2563eb;border:1px solid #bfdbfe;font-size:11.5px;font-weight:650;padding:4px 10px;">Petunjuk iOS</button>`;
    return;
  }

  if (state === 'unsupported') {
    lbl.textContent = 'Notifikasi Push tidak didukung browser ini.';
    btn.innerHTML = '<span class="chip error" style="font-size:11px">Tidak Didukung</span>';
    return;
  }

  if (state === 'denied') {
    lbl.innerHTML = '<span style="color:#dc2626;font-weight:600"><i class="fa-solid fa-bell-slash" style="font-size:11px;margin-right:4px;"></i>Izin notifikasi diblokir</span>';
    btn.innerHTML = `<button type="button" class="btn btn-sm btn-ghost" data-act="openDeniedModal" style="color:#dc2626;border:1px solid #fecaca;font-size:11.5px;font-weight:650;padding:4px 10px;">Buka Blokir</button>`;
    return;
  }

  if (state === 'granted') {
    try {
      const sub = await PTVNotificationManager.getSubscription();
      if (sub) {
        lbl.innerHTML = '<span style="color:#10b981;font-weight:600">● Notifikasi push aktif di perangkat ini</span>';
        btn.innerHTML = `
          <div style="display:flex;gap:6px;align-items:center">
            <button type="button" class="btn btn-sm" style="background:#f1f5f9;color:#334155;border:1px solid #cbd5e1;font-weight:600;font-size:11.5px;padding:4px 10px" data-act="testPush">
              <i class="fa-solid fa-paper-plane" style="font-size:10px;margin-right:4px"></i>Tes Push
            </button>
            <button type="button" class="btn btn-sm" style="background:#f8fafc;color:#475569;border:1px solid #cbd5e1;font-weight:600;font-size:11.5px;padding:4px 8px" data-act="testDirect" title="Uji notifikasi browser langsung tanpa backend">
              <i class="fa-solid fa-bell" style="font-size:10px;margin-right:4px"></i>Tes Direct
            </button>
            <button type="button" class="btn btn-sm" style="background:#fee2e2;color:#dc2626;border:1px solid #fca5a5;font-weight:600;font-size:11.5px;padding:4px 10px" data-act="disablePush">
              Matikan
            </button>
          </div>`;
        return;
      }
    } catch (_) {}
    lbl.textContent = 'Izin terpasang, belum berlangganan push.';
    btn.innerHTML = '<button type="button" class="btn btn-sm btn-p" style="font-weight:600;font-size:12px;padding:4px 12px" data-act="enablePush">Aktifkan</button>';
    return;
  }

  // state === 'default'
  lbl.textContent = 'Belum diaktifkan.';
  btn.innerHTML = '<button type="button" class="btn btn-sm btn-p" style="font-weight:600;font-size:12px;padding:4px 12px" data-act="enablePush">Aktifkan</button>';
}

async function enablePushNotifications() {
  if (typeof PTVNotificationManager === 'undefined') {
    toast('Modul notifikasi belum siap.', 'alert');
    return;
  }

  toast('Menghubungkan notifikasi...', 'bell');
  try {
    const res = await PTVNotificationManager.subscribe();
    if (res.success) {
      toast('Notifikasi push berhasil diaktifkan!', 'check');
      const promptBanner = document.getElementById('notifPushPromptBanner');
      if (promptBanner) promptBanner.remove();
      const instaBanner = document.getElementById('ptvInstaPushPrompt');
      if (instaBanner) instaBanner.remove();
      console.info('[PTV Push] Push notification berhasil diaktifkan oleh pengguna.');
    } else {
      if (res.state === 'denied') {
        PTVNotificationManager.showDeniedModal();
      } else if (res.state === 'ios_safari_browser') {
        PTVNotificationManager.showIOSModal();
      } else if (res.state === 'insecure_http') {
        PTVNotificationManager.showInsecureModal();
      } else {
        toast(res.message || 'Gagal mengaktifkan notifikasi.', 'alert');
      }
    }
  } catch (err) {
    console.error('[PTV Push] Gagal mengaktifkan push:', err);
    toast('Gagal: ' + (err.message || 'Terjadi kesalahan'), 'alert');
  }

  syncPushSettingsUI();
}

async function disablePushNotifications() {
  if (typeof PTVNotificationManager === 'undefined') return;
  toast('Mematikan notifikasi push...', 'bell');
  try {
    await PTVNotificationManager.unsubscribe();
    toast('Notifikasi push telah dimatikan.');
  } catch (err) {
    console.error('[PTV Push] Gagal mematikan push:', err);
    toast('Gagal mematikan push: ' + err.message, 'alert');
  }
  syncPushSettingsUI();
}

async function testPushNotification() {
  if (typeof PTVNotificationManager === 'undefined') {
    toast('Modul notifikasi belum siap.', 'alert');
    return;
  }
  toast('Mengirim notifikasi push uji coba...', 'bell');
  try {
    await PTVNotificationManager.sendTestPush();
    toast('Notifikasi push terkirim! Cek notifikasi di layar kamu.', 'check');
  } catch (err) {
    toast('Gagal mengirim push: ' + err.message, 'alert');
  }
}

async function testDirectNotification() {
  if (typeof PTVNotificationManager === 'undefined') {
    toast('Modul notifikasi belum siap.', 'alert');
    return;
  }
  toast('Menguji notifikasi browser langsung...', 'bell');
  try {
    await PTVNotificationManager.testDirectNotification();
    toast('Notifikasi direct dikirim ke OS!', 'check');
  } catch (err) {
    toast('Gagal direct notification: ' + err.message, 'alert');
  }
}
window.testDirectNotification = testDirectNotification;
window.testPushNotification = testPushNotification;
