/* ── Centralized Supabase Realtime Engine: WebSocket + Watchdog + Auto Reconnect + Scoped Resync (Zero Polling) ── */
(function setupPTVRealtimeEngine() {

  // 1. Global Realtime State & Health Metrics
  window.PTV_REALTIME_STATE = window.PTV_REALTIME_STATE || {
    status: 'disconnected', // 'connected' | 'connecting' | 'reconnecting' | 'disconnected' | 'offline' | 'error'
    browserOnline: typeof navigator !== 'undefined' ? (typeof navigator.onLine === 'boolean' ? navigator.onLine : true) : true,
    websocketConnected: false,
    subscribed: false,
    reconnectAttempts: 0,
    lastConnectedAt: null,
    lastDisconnectedAt: null,
    lastSuccessfulSyncAt: null,
    lastEventAt: null,
    lastError: null,
  };

  // 1b. Session Tombstone Registry & Stale Request Sequence Tracker
  // Mencegah race condition DELETE vs asynchronous background fetch
  window._deletingIds = window._deletingIds || new Set();
  window._deletedIds = window._deletedIds || new Set();
  window._syncRequestVersions = window._syncRequestVersions || {};
  const _processedNotifKeys = new Set();

  window.ptvMarkDeleting = function(id) {
    if (!id) return;
    window._deletingIds.add(String(id));
  };
  window.ptvMarkDeleted = function(id) {
    if (!id) return;
    const s = String(id);
    window._deletingIds.delete(s);
    window._deletedIds.add(s);
  };
  window.ptvUnmarkDeleting = function(id) {
    if (!id) return;
    window._deletingIds.delete(String(id));
  };
  window.ptvFilterTombstones = function(items) {
    if (!Array.isArray(items)) return items;
    if ((!window._deletedIds || window._deletedIds.size === 0) && (!window._deletingIds || window._deletingIds.size === 0)) return items;
    return items.filter(it => {
      if (!it) return false;
      const id = String(it.id || '');
      if (!id) return true;
      return !window._deletedIds.has(id) && !window._deletingIds.has(id);
    });
  };

  const _syncDebounceTimers = {};
  const _inFlightSync = {};
  const _pendingResync = {};
  let _reconnectTimer = null;
  let _watchdogTimer = null;
  let _indicatorHideTimer = null;
  window._pendingRenderScopes = window._pendingRenderScopes || {};

  // 2. Subtle Connection Indicator Helper
  function updateConnectionIndicator(prevStatus, newStatus) {
    if (typeof document === 'undefined') return;
    let el = document.getElementById('ptvConnectionIndicator');
    if (!el && document.body) {
      el = document.createElement('div');
      el.id = 'ptvConnectionIndicator';
      el.style.cssText = 'position:fixed;bottom:calc(env(safe-area-inset-bottom, 0px) + 68px);left:50%;transform:translateX(-50%) translateY(20px);z-index:9995;display:flex;align-items:center;gap:7px;padding:6px 14px;border-radius:9999px;font-size:12px;font-weight:600;letter-spacing:0.2px;box-shadow:0 6px 20px rgba(0,0,0,0.22);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);pointer-events:none;opacity:0;transition:opacity 0.28s ease, transform 0.28s cubic-bezier(0.2, 0.9, 0.4, 1.1);font-family:inherit;';
      document.body.appendChild(el);
    }
    if (!el) return;

    if (_indicatorHideTimer) {
      clearTimeout(_indicatorHideTimer);
      _indicatorHideTimer = null;
    }

    if (newStatus === 'connected') {
      if (['offline', 'reconnecting', 'connecting', 'error', 'disconnected'].includes(prevStatus)) {
        el.style.background = 'rgba(16, 185, 129, 0.92)';
        el.style.color = '#ffffff';
        el.style.border = '1px solid rgba(255, 255, 255, 0.25)';
        el.innerHTML = '<span style="width:7px;height:7px;border-radius:50%;background:#ffffff;display:inline-block;box-shadow:0 0 6px rgba(255,255,255,0.8);"></span><span>Terhubung</span>';
        el.style.opacity = '1';
        el.style.transform = 'translateX(-50%) translateY(0)';

        _indicatorHideTimer = setTimeout(() => {
          el.style.opacity = '0';
          el.style.transform = 'translateX(-50%) translateY(20px)';
        }, 2400);
      } else {
        el.style.opacity = '0';
        el.style.transform = 'translateX(-50%) translateY(20px)';
      }
    } else if (newStatus === 'reconnecting' || newStatus === 'connecting') {
      el.style.background = 'rgba(217, 119, 6, 0.92)';
      el.style.color = '#ffffff';
      el.style.border = '1px solid rgba(255, 255, 255, 0.25)';
      el.innerHTML = '<span style="width:7px;height:7px;border-radius:50%;background:#ffffff;display:inline-block;animation:pulse 1.2s infinite ease-in-out;"></span><span>Menghubungkan kembali...</span>';
      el.style.opacity = '1';
      el.style.transform = 'translateX(-50%) translateY(0)';
    } else if (newStatus === 'offline') {
      el.style.background = 'rgba(239, 68, 68, 0.92)';
      el.style.color = '#ffffff';
      el.style.border = '1px solid rgba(255, 255, 255, 0.25)';
      el.innerHTML = '<span style="width:7px;height:7px;border-radius:50%;background:#ffffff;display:inline-block;"></span><span>Tidak ada koneksi</span>';
      el.style.opacity = '1';
      el.style.transform = 'translateX(-50%) translateY(0)';
    } else if (newStatus === 'error') {
      el.style.background = 'rgba(239, 68, 68, 0.92)';
      el.style.color = '#ffffff';
      el.style.border = '1px solid rgba(255, 255, 255, 0.25)';
      el.innerHTML = '<span style="width:7px;height:7px;border-radius:50%;background:#ffffff;display:inline-block;"></span><span>Koneksi terputus</span>';
      el.style.opacity = '1';
      el.style.transform = 'translateX(-50%) translateY(0)';
    } else {
      el.style.opacity = '0';
      el.style.transform = 'translateX(-50%) translateY(20px)';
    }
  }

  // 3. Centralized Status Setter
  function setRealtimeStatus(newStatus, detail = '') {
    const prevState = window.PTV_REALTIME_STATE.status;
    window.PTV_REALTIME_STATE.status = newStatus;
    window.PTV_REALTIME_STATE.browserOnline = typeof navigator !== 'undefined' ? (typeof navigator.onLine === 'boolean' ? navigator.onLine : true) : true;

    if (newStatus === 'connected') {
      window.PTV_REALTIME_STATE.websocketConnected = true;
      window.PTV_REALTIME_STATE.subscribed = true;
      window.PTV_REALTIME_STATE.reconnectAttempts = 0;
      window.PTV_REALTIME_STATE.lastConnectedAt = new Date().toISOString();
      window.PTV_REALTIME_STATE.lastError = null;
    } else if (newStatus === 'offline') {
      window.PTV_REALTIME_STATE.websocketConnected = false;
      window.PTV_REALTIME_STATE.subscribed = false;
      window.PTV_REALTIME_STATE.lastDisconnectedAt = new Date().toISOString();
    } else if (newStatus === 'disconnected' || newStatus === 'error') {
      window.PTV_REALTIME_STATE.websocketConnected = false;
      window.PTV_REALTIME_STATE.subscribed = false;
      window.PTV_REALTIME_STATE.lastDisconnectedAt = new Date().toISOString();
    } else if (newStatus === 'reconnecting' || newStatus === 'connecting') {
      window.PTV_REALTIME_STATE.subscribed = false;
    }

    if (detail) {
      window.PTV_REALTIME_STATE.lastError = detail;
    }

    if (prevState !== newStatus) {
      if (newStatus === 'offline') console.warn('[PTV Realtime] Browser offline');
      else if (newStatus === 'reconnecting') console.info(`[PTV Realtime] Reconnecting (attempt #${window.PTV_REALTIME_STATE.reconnectAttempts})...`);
      else if (newStatus === 'connecting') console.info('[PTV Realtime] Connecting to Supabase Realtime...');
      else if (newStatus === 'connected') console.info('[PTV Realtime] Connection restored. Engine READY.');
      else if (newStatus === 'error') console.warn('[PTV Realtime] Connection error:', detail);
    }

    try {
      window.dispatchEvent(new CustomEvent('ptv:realtime-state-change', {
        detail: Object.assign({}, window.PTV_REALTIME_STATE, { prevStatus: prevState })
      }));
    } catch (_) {}

    updateConnectionIndicator(prevState, newStatus);
    if (typeof updateScopeBadges === 'function') {
      updateScopeBadges();
    }
  }

  // 4. In-App Notifications Synchronizer
  async function syncInAppNotifications() {
    try {
      if (typeof AJAX_URL === 'undefined') return;
      const fd = new FormData();
      fd.append('action', 'ptv_get_notifications');
      fd.append('nonce', typeof PTV_NONCE !== 'undefined' ? PTV_NONCE : '');
      const r = await fetch(AJAX_URL, { method: 'POST', body: fd, credentials: 'same-origin' });
      const j = await r.json();
      if (j && j.success && Array.isArray(j.data)) {
        DB.notifs = window.ptvFilterTombstones(j.data);
        const count = typeof unreadCount === 'function' ? unreadCount() : (DB.notifs || []).filter(n => n.unread).length;
        const badge = document.getElementById('notif-badge');
        if (badge) {
          badge.textContent = count > 9 ? '9+' : (count > 0 ? count : '');
          badge.style.display = count > 0 ? '' : 'none';
        }
        const notifDot = document.getElementById('notifDot');
        if (notifDot) {
          notifDot.textContent = count > 9 ? '9+' : count;
          notifDot.style.display = count ? 'grid' : 'none';
        }
      }
    } catch (_) {}
  }
  syncInAppNotifications();
  window.ptvSyncInAppNotifs = syncInAppNotifications;

  // 5. Shared Supabase Client Singleton
  function getSharedSupabaseClient() {
    if (window._ptvSbClient) return window._ptvSbClient;

    if (typeof window.PTVNotificationManager !== 'undefined' && typeof window.PTVNotificationManager.getSupabaseClient === 'function') {
      const c = window.PTVNotificationManager.getSupabaseClient();
      if (c) {
        window._ptvSbClient = c;
        return c;
      }
    }

    if (typeof window.supabase !== 'undefined' && typeof window.PTV_SUPABASE !== 'undefined' && window.PTV_SUPABASE.url && window.PTV_SUPABASE.anonKey) {
      try {
        window._ptvSbClient = window.supabase.createClient(window.PTV_SUPABASE.url, window.PTV_SUPABASE.anonKey);
        return window._ptvSbClient;
      } catch (e) {
        console.warn('[PTV Realtime] Gagal membuat Supabase client:', e);
        return null;
      }
    }
    return null;
  }

  // 6. Editor Safety Checker
  function isUserTyping() {
    const el = document.activeElement;
    if (!el) return false;
    const tag = (el.tagName || '').toUpperCase();
    return tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || !!el.isContentEditable || !!el.closest('.note-editor, .rich-editor, [contenteditable="true"]');
  }

  // 7. Scoped Page Impact Resolver
  function isPageAffectedByScope(page, scope) {
    if (scope === 'all') return true;
    switch (scope) {
      case 'docs':
        return ['dokumen', 'perizinan', 'arsip', 'beranda'].includes(page);
      case 'inventory':
        return ['inventaris', 'alatDetail', 'peminjaman', 'beranda'].includes(page);
      case 'loans':
        return ['peminjaman', 'inventaris', 'alatDetail', 'beranda'].includes(page);
      case 'events':
        return ['acara', 'acaraDetail', 'kalender', 'beranda'].includes(page);
      case 'damages':
        return ['kerusakan', 'inventaris', 'alatDetail', 'beranda'].includes(page);
      case 'announcements':
        return ['broadcast', 'beranda'].includes(page);
      case 'lost':
        return ['lostFound', 'beranda'].includes(page);
      case 'notes':
        return ['catatan', 'notes', 'beranda'].includes(page);
      case 'crew':
        return ['tim', 'profil', 'beranda'].includes(page);
      case 'finance':
        return ['keuangan', 'kas', 'beranda'].includes(page);
      default:
        return false;
    }
  }

  // 8. Safe Partial Rerender — Scoped In-Place Component Patching (Zero Full Page Reload)
  function safeRerenderForScopes(scopes) {
    const curPage = (typeof state !== 'undefined' && state.route) ? state.route.page : '';
    
    // In-place scoped DOM patching: does NOT touch #view outer shell, sidebar, or global headers
    if (typeof smartUpdateScopedView === 'function') {
      smartUpdateScopedView(curPage, scopes);
    } else if (typeof smartUpdateFilterView === 'function') {
      smartUpdateFilterView(curPage);
    } else if (typeof updateActionBadges === 'function') {
      updateActionBadges();
    }

    if (scopes.includes('docs') && window._currentOpenDocId && typeof openDoc === 'function') {
      const sheet = document.getElementById('sheet');
      if (sheet && sheet.classList.contains('on')) {
        const found = (DB.docs || []).find(d => String(d.id) === String(window._currentOpenDocId));
        if (found) {
          const sheetBody = document.getElementById('sheetBody');
          const bodyScrollY = sheetBody ? sheetBody.scrollTop : 0;
          openDoc(window._currentOpenDocId);
          if (sheetBody && bodyScrollY > 0) {
            requestAnimationFrame(() => {
              sheetBody.scrollTop = bodyScrollY;
            });
          }
        }
      }
    }

    if (scopes.includes('damages') && window._currentOpenDamageId && typeof openDamage === 'function') {
      const sheet = document.getElementById('sheet');
      if (sheet && sheet.classList.contains('on')) {
        const found = (DB.damages || []).find(d => String(d.id) === String(window._currentOpenDamageId));
        if (found) {
          const sheetBody = document.getElementById('sheetBody');
          const bodyScrollY = sheetBody ? sheetBody.scrollTop : 0;
          openDamage(window._currentOpenDamageId);
          if (sheetBody && bodyScrollY > 0) {
            requestAnimationFrame(() => {
              sheetBody.scrollTop = bodyScrollY;
            });
          }
        }
      }
    }
  }

  // 9. Apply Scoped Data to in-memory DB with Tombstone Guard
  function applyScopedData(scope, newDB) {
    if (!newDB || typeof newDB !== 'object') return;
    let hasChanges = false;

    if (scope === 'docs' && Array.isArray(newDB.docs)) {
      const cleanDocs = window.ptvFilterTombstones(newDB.docs);
      if (JSON.stringify(DB.docs) !== JSON.stringify(cleanDocs)) {
        DB.docs = cleanDocs;
        hasChanges = true;
      }
    } else if (scope === 'inventory' || scope === 'loans' || scope === 'damages') {
      if (Array.isArray(newDB.inventory)) {
        const cleanInv = window.ptvFilterTombstones(newDB.inventory);
        if (JSON.stringify(DB.inventory) !== JSON.stringify(cleanInv)) {
          DB.inventory = cleanInv;
          hasChanges = true;
        }
      }
      if (Array.isArray(newDB.loans)) {
        const cleanLoans = window.ptvFilterTombstones(newDB.loans);
        if (JSON.stringify(DB.loans) !== JSON.stringify(cleanLoans)) {
          DB.loans = cleanLoans;
          hasChanges = true;
        }
      }
      if (Array.isArray(newDB.damages)) {
        const cleanDamages = window.ptvFilterTombstones(newDB.damages);
        if (JSON.stringify(DB.damages) !== JSON.stringify(cleanDamages)) {
          DB.damages = cleanDamages;
          hasChanges = true;
        }
      }
      if (Array.isArray(newDB.inventory_values)) DB.inventory_values = window.ptvFilterTombstones(newDB.inventory_values);
      if (Array.isArray(newDB.inventory_sources)) DB.inventory_sources = window.ptvFilterTombstones(newDB.inventory_sources);
    } else if (scope === 'events' && Array.isArray(newDB.events)) {
      const cleanEvents = window.ptvFilterTombstones(newDB.events);
      if (JSON.stringify(DB.events) !== JSON.stringify(cleanEvents)) {
        DB.events = cleanEvents;
        hasChanges = true;
      }
    } else if (scope === 'announcements' && Array.isArray(newDB.announcements)) {
      const cleanAnn = window.ptvFilterTombstones(newDB.announcements);
      if (JSON.stringify(DB.announcements) !== JSON.stringify(cleanAnn)) {
        DB.announcements = cleanAnn;
        hasChanges = true;
      }
    } else if (scope === 'lost' && Array.isArray(newDB.lost)) {
      const cleanLost = window.ptvFilterTombstones(newDB.lost);
      if (JSON.stringify(DB.lost) !== JSON.stringify(cleanLost)) {
        DB.lost = cleanLost;
        hasChanges = true;
      }
    } else if (scope === 'notes' && Array.isArray(newDB.notes)) {
      const rawClean = window.ptvFilterTombstones(newDB.notes);
      const seenIds = new Set();
      const cleanNotes = [];
      for (const item of rawClean) {
        const iid = String(item && item.id ? item.id : '');
        if (iid && !seenIds.has(iid)) {
          seenIds.add(iid);
          cleanNotes.push(item);
        }
      }
      console.log('[NOTE SYNC] fresh count:', cleanNotes.length);
      if (JSON.stringify(DB.notes) !== JSON.stringify(cleanNotes)) {
        DB.notes = cleanNotes;
        hasChanges = true;
      }
    } else if (scope === 'all') {
      Object.keys(newDB).forEach(k => {
        let cleanVal = Array.isArray(newDB[k]) ? window.ptvFilterTombstones(newDB[k]) : newDB[k];
        if (k === 'notes' && Array.isArray(cleanVal)) {
          const seenIds = new Set();
          const cleanNotes = [];
          for (const item of cleanVal) {
            const iid = String(item && item.id ? item.id : '');
            if (iid && !seenIds.has(iid)) {
              seenIds.add(iid);
              cleanNotes.push(item);
            }
          }
          cleanVal = cleanNotes;
        }
        if (JSON.stringify(DB[k]) !== JSON.stringify(cleanVal)) {
          DB[k] = cleanVal;
          hasChanges = true;
        }
      });
    }

    console.log('[PTV Realtime][APPLY]', `scope=${scope}`, `changed=${hasChanges}`);
    if (!hasChanges) return;

    if (typeof sanitizeDB === 'function') {
      try { sanitizeDB(DB); } catch (_) {}
    }

    if (isUserTyping()) {
      window._pendingRenderScopes[scope] = true;
      const el = document.activeElement;
      if (el && !el._ptvRealtimeBlurAttached) {
        el._ptvRealtimeBlurAttached = true;
        el.addEventListener('blur', () => {
          el._ptvRealtimeBlurAttached = false;
          setTimeout(() => {
            if (!isUserTyping() && window._pendingRenderScopes) {
              const pendingScopes = Object.keys(window._pendingRenderScopes);
              window._pendingRenderScopes = {};
              if (pendingScopes.length > 0) {
                safeRerenderForScopes(pendingScopes);
              }
            }
          }, 120);
        }, { once: true });
      }
    } else {
      safeRerenderForScopes([scope]);
    }
  }

  // 10. Scoped Sync Debouncer & Dispatcher with Sequence Versioning (Anti-Stale Response)
  function requestSyncScope(scope, forceImmediate = false) {
    if (!scope) scope = 'docs';
    console.info('[REALTIME] sync requested (scope: ' + scope + ')');
    if (_syncDebounceTimers[scope]) {
      clearTimeout(_syncDebounceTimers[scope]);
    }

    const delay = forceImmediate ? 40 : 350;
    _syncDebounceTimers[scope] = setTimeout(() => {
      delete _syncDebounceTimers[scope];
      executeSync(scope);
    }, delay);
  }

  function executeSync(scope) {
    if (_inFlightSync[scope]) {
      _pendingResync[scope] = true;
      return;
    }
    _inFlightSync[scope] = true;
    console.log('[PTV Realtime][SYNC]', `scope=${scope}`);

    // Sequence versioning: discard any response that arrives out of order
    _syncRequestVersions[scope] = (_syncRequestVersions[scope] || 0) + 1;
    const reqVersion = _syncRequestVersions[scope];

    // Track section-level syncing state
    if (window.PTV_SCOPES_STATE && window.PTV_SCOPES_STATE[scope]) {
      window.PTV_SCOPES_STATE[scope].isRefreshing = true;
      window.PTV_SCOPES_STATE[scope].error = null;
    }
    if (typeof updateScopeBadges === 'function') {
      updateScopeBadges([scope]);
    }

    if (typeof AJAX_URL === 'undefined') {
      _inFlightSync[scope] = false;
      if (window.PTV_SCOPES_STATE && window.PTV_SCOPES_STATE[scope]) {
        window.PTV_SCOPES_STATE[scope].isRefreshing = false;
      }
      return;
    }

    const url = AJAX_URL + '?action=ptv_dashboard_get_live_data&scope=' + encodeURIComponent(scope);
    fetch(url)
      .then(r => r.json())
      .then(res => {
        _inFlightSync[scope] = false;
        if (reqVersion !== _syncRequestVersions[scope]) {
          console.info(`[PTV Realtime] Mengabaikan respons basi untuk ${scope} (v${reqVersion} < v${_syncRequestVersions[scope]})`);
          return;
        }
        const recCount = (res.data && res.data.DB && res.data.DB[scope] && Array.isArray(res.data.DB[scope])) ? res.data.DB[scope].length : (res.data && res.data.DB ? Object.keys(res.data.DB).length : 0);
        console.log('[PTV Realtime][SYNC RESPONSE]', `scope=${scope}`, `records=${recCount}`);

        if (window.PTV_SCOPES_STATE && window.PTV_SCOPES_STATE[scope]) {
          window.PTV_SCOPES_STATE[scope].isRefreshing = false;
          window.PTV_SCOPES_STATE[scope].hasData = true;
          window.PTV_SCOPES_STATE[scope].isInitialLoading = false;
          window.PTV_SCOPES_STATE[scope].error = null;
          window.PTV_SCOPES_STATE[scope].lastUpdated = new Date().toISOString();
        }
        if (res && res.success && res.data && res.data.DB) {
          applyScopedData(scope, res.data.DB);
          window.PTV_REALTIME_STATE.lastSuccessfulSyncAt = new Date().toISOString();
        }
        if (typeof updateScopeBadges === 'function') {
          updateScopeBadges([scope]);
        }
        if (_pendingResync[scope]) {
          delete _pendingResync[scope];
          requestSyncScope(scope, false);
        }
      })
      .catch(() => {
        _inFlightSync[scope] = false;
        if (reqVersion !== _syncRequestVersions[scope]) return;
        if (window.PTV_SCOPES_STATE && window.PTV_SCOPES_STATE[scope]) {
          window.PTV_SCOPES_STATE[scope].isRefreshing = false;
          window.PTV_SCOPES_STATE[scope].error = 'Menunggu koneksi...';
        }
        if (typeof updateScopeBadges === 'function') {
          updateScopeBadges([scope]);
        }
        if (_pendingResync[scope]) {
          delete _pendingResync[scope];
        }
      });
  }

  window.ptvRequestSyncScope = requestSyncScope;

  // 11. Quiet Active Page Sync
  function syncActivePageQuietly(forceImmediate = false) {
    if (typeof state !== 'undefined' && state.route) {
      const p = state.route.page;
      if (['perizinan', 'dokumen', 'arsip'].includes(p)) requestSyncScope('docs', forceImmediate);
      else if (['inventaris', 'alatDetail'].includes(p)) requestSyncScope('inventory', forceImmediate);
      else if (p === 'peminjaman') requestSyncScope('loans', forceImmediate);
      else if (['acara', 'acaraDetail', 'kalender'].includes(p)) requestSyncScope('events', forceImmediate);
      else if (p === 'kerusakan') requestSyncScope('damages', forceImmediate);
      else if (p === 'broadcast') requestSyncScope('announcements', forceImmediate);
      else if (p === 'lostFound') requestSyncScope('lost', forceImmediate);
      else if (p === 'catatan') requestSyncScope('notes', forceImmediate);
      else if (p === 'beranda') requestSyncScope('docs', forceImmediate);
    }
  }

  // 12. Realtime Notification Dispatcher & Smooth In-Place Prepend
  function dispatchRealtimeNotification(row) {
    if (!row) return;
    const notifId = String(row.id || ('rt_' + Date.now() + '_' + Math.random().toString(36).slice(2, 6)));
    const dedupeKey = String(row.dedupe_key || (row.entity_type ? `${row.entity_type}:${row.entity_id || ''}:${row.title || row.t || ''}` : notifId));

    if (_processedNotifKeys.has(dedupeKey)) return;
    _processedNotifKeys.add(dedupeKey);
    if (_processedNotifKeys.size > 500) {
      const firstK = _processedNotifKeys.values().next().value;
      _processedNotifKeys.delete(firstK);
    }

    if (Array.isArray(DB.notifs) && DB.notifs.some(n => String(n.id) === notifId)) return;

    const title = row.title || row.t || 'Pemberitahuan PTV';
    const message = row.message || row.s || '';
    const actionUrl = row.action_url || row.go || '';
    const formatted = {
      id: notifId,
      t: title,
      s: message,
      type: row.type || 'system',
      kind: row.icon || row.kind || 'bell',
      entity_type: row.entity_type || '',
      entity_id: row.entity_id || '',
      go: actionUrl,
      unread: true,
      is_protected: !!row.is_protected,
      when: 'Baru saja',
      created_at: row.created_at || new Date().toISOString(),
    };

    DB.notifs = [formatted, ...(DB.notifs || [])];

    // Update notification badges immediately
    const count = typeof unreadCount === 'function' ? unreadCount() : (DB.notifs || []).filter(n => n.unread).length;
    const badge = document.getElementById('notif-badge');
    if (badge) {
      badge.textContent = count > 9 ? '9+' : (count > 0 ? count : '');
      badge.style.display = count > 0 ? '' : 'none';
    }
    const notifDot = document.getElementById('notifDot');
    if (notifDot) {
      notifDot.textContent = count > 9 ? '9+' : count;
      notifDot.style.display = count ? 'grid' : 'none';
    }

    // In-place smooth prepend to sheet #notifListContainer if open (smooth, without closing or resetting scroll)
    const listEl = document.getElementById('notifListContainer');
    if (listEl) {
      const emptyEl = listEl.querySelector('.empty');
      if (emptyEl) emptyEl.remove();
      if (typeof renderNotifItemsHTML === 'function') {
        const tempWrap = document.createElement('div');
        tempWrap.innerHTML = renderNotifItemsHTML([formatted]);
        const newCard = tempWrap.firstElementChild;
        if (newCard) {
          newCard.style.animation = 'fadeIn 0.35s ease';
          listEl.insertBefore(newCard, listEl.firstChild);
        }
      }
    }

    // Toast alert & sound
    if (typeof toast === 'function') {
      toast(`${title}: ${message}`, 'bell');
    }
    if (typeof haptic === 'function') {
      haptic(8);
    }

    // Native device push / OS notification
    if (typeof window.PTVNotificationManager !== 'undefined' && typeof window.PTVNotificationManager.showDeviceNotification === 'function') {
      window.PTVNotificationManager.showDeviceNotification(title, message, actionUrl, 'ptv-' + notifId);
    }
  }
  window.ptvDispatchRealtimeNotif = dispatchRealtimeNotification;

  // 12b. Central Realtime Table Event Pipeline: One Event -> Scoped Data Sync + Specific Remote Notification
  function handleRealtimeTableChange(table, scope, payload) {
    window.PTV_REALTIME_STATE.lastEventAt = new Date().toISOString();
    const eventType = payload.eventType || '';
    const recId = (payload.new && (payload.new.id || payload.new.uuid)) || (payload.old && (payload.old.id || payload.old.uuid)) || (payload.id || '');
    console.log('[PTV Realtime][RAW]', `table=${table}`, `event=${eventType}`, `id=${recId}`);

    // Handle DELETE event: Remove record immediately and patch UI in-place (ZERO full-page reload)
    if (eventType === 'DELETE') {
      const delId = payload.old ? (payload.old.id || payload.old.uuid) : (payload.id || null);
      if (delId) {
        window.ptvMarkDeleted(delId);
        if (scope === 'docs' && Array.isArray(DB.docs)) {
          DB.docs = DB.docs.filter(x => String(x.id) !== String(delId));
        } else if (scope === 'inventory' && Array.isArray(DB.inventory)) {
          DB.inventory = DB.inventory.filter(x => String(x.id) !== String(delId));
        } else if (scope === 'loans' && Array.isArray(DB.loans)) {
          DB.loans = DB.loans.filter(x => String(x.id) !== String(delId));
        } else if (scope === 'damages' && Array.isArray(DB.damages)) {
          DB.damages = DB.damages.filter(x => String(x.id) !== String(delId));
        } else if (scope === 'events' && Array.isArray(DB.events)) {
          DB.events = DB.events.filter(x => String(x.id) !== String(delId));
        } else if (scope === 'announcements' && Array.isArray(DB.announcements)) {
          DB.announcements = DB.announcements.filter(x => String(x.id) !== String(delId));
        } else if (scope === 'lost' && Array.isArray(DB.lost)) {
          DB.lost = DB.lost.filter(x => String(x.id) !== String(delId));
        } else if (scope === 'notes' && Array.isArray(DB.notes)) {
          DB.notes = DB.notes.filter(x => String(x.id) !== String(delId));
        } else if (scope === 'notifs' && Array.isArray(DB.notifs)) {
          DB.notifs = DB.notifs.filter(x => String(x.id) !== String(delId));
          const count = typeof unreadCount === 'function' ? unreadCount() : (DB.notifs || []).filter(n => n.unread).length;
          const badge = document.getElementById('notif-badge');
          if (badge) { badge.textContent = count > 9 ? '9+' : (count > 0 ? count : ''); badge.style.display = count > 0 ? '' : 'none'; }
        }
        console.log('[PTV Realtime][APPLY]', `scope=${scope}`, 'changed=true', 'action=DELETE_IN_PLACE');
        safeRerenderForScopes([scope]);
      }
    }

    const newRow = payload.new;
    if (newRow && newRow.id && window._deletedIds && window._deletedIds.has(String(newRow.id))) {
      return;
    }

    // Resolusi Identitas Pengirim (Sender / Client Identification)
    const incomingClientId = String(payload.client_id || (newRow && newRow.client_id) || '');
    const incomingActorId = String(payload.actor_id || (newRow && (newRow.actor_id || newRow.created_by)) || '');
    const actorName = String(payload.actor_name || (newRow && (newRow.actor_name || newRow.created_by_name || newRow.pelapor_nama || newRow.nama_peminjam)) || 'Kru PTV');

    const isSameClient = !!(incomingClientId && window.PTV_CLIENT_ID && incomingClientId === window.PTV_CLIENT_ID);
    const isRecentLocal = !!(recId && window._recentLocalMutations && window._recentLocalMutations.has(String(recId)));
    const isSelfAction = isSameClient || isRecentLocal;

    // Log Diagnostik Wajib (Requirement #10)
    console.info('[REALTIME NOTIFICATION]', {
      event_received: `${table}:${eventType}`,
      actor_id: incomingActorId,
      actor_name: actorName,
      client_id: incomingClientId,
      current_client_id: window.PTV_CLIENT_ID,
      entity: `${table}:${recId}`,
      action: eventType,
      decision: isSelfAction ? 'SUPPRESS' : 'NOTIFY'
    });

    // Anti-duplicate deduplication key
    const dedupeBase = `${table}:${eventType}:${recId}`;
    if (_processedNotifKeys.has(dedupeBase)) {
      console.info('[REALTIME NOTIFICATION] Duplicate suppressed:', dedupeBase);
      requestSyncScope(scope);
      return;
    }

    // JIKA AKSI DARI DIRI SENDIRI (SELF ACTION):
    // Data tetap disinkronkan, tetapi PUSH NOTIFIKASI / TOAST / CHIME WAJIB DITEKAN (SUPPRESSED)
    if (isSelfAction) {
      _processedNotifKeys.add(dedupeBase);
      if (recId) _processedNotifKeys.add(`${table}:${recId}`);
      requestSyncScope(scope);
      return;
    }

    // JIKA AKSI DARI REMOTE CLIENT (CLIENT LAIN / USER LAIN / DEVICE LAIN):
    // Tandai dedupe key agar postgres_changes/broadcast duplikat tidak memicu notifikasi ganda
    _processedNotifKeys.add(dedupeBase);
    if (recId) _processedNotifKeys.add(`${table}:${recId}`);

    // Table-specific notifications & sync dispatch
    if (table === 'ptv_notifications') {
      if (eventType === 'INSERT' && newRow) {
        const myId = (typeof BOOT_ME !== 'undefined' && BOOT_ME) ? (BOOT_ME.id || BOOT_ME.sb_id || '') : '';
        const mySbId = (typeof BOOT_ME !== 'undefined' && BOOT_ME) ? (BOOT_ME.sb_id || '') : '';
        const targetCrewId = newRow.recipient_crew_id || '';
        if (!targetCrewId || targetCrewId === myId || (mySbId && targetCrewId === mySbId)) {
          dispatchRealtimeNotification(newRow);
        }
      }
      return;
    }

    if (table === 'ptv_peminjaman') {
      if (eventType === 'INSERT' && newRow) {
        const borrower = newRow.nama_peminjam || newRow.peminjam || actorName || 'Kru';
        const purpose = newRow.keperluan ? (' (' + newRow.keperluan + ')') : '';
        dispatchRealtimeNotification({
          id: 'loan_' + newRow.id,
          dedupe_key: dedupeBase,
          title: 'Peminjaman Baru',
          message: `${borrower} meminjam peralatan${purpose}`,
          type: 'loan',
          icon: 'box-archive',
          action_url: '#pgPeminjaman',
          entity_type: 'ptv_peminjaman',
          entity_id: newRow.id,
        });
      } else if (eventType === 'UPDATE' && newRow) {
        const borrower = newRow.nama_peminjam || newRow.peminjam || 'Kru';
        const st = newRow.status || 'Diperbarui';
        dispatchRealtimeNotification({
          id: 'loan_status_' + newRow.id + '_' + st,
          dedupe_key: dedupeBase,
          title: 'Status Peminjaman',
          message: `${actorName} memperbarui status peminjaman ${borrower}: "${st}"`,
          type: 'loan',
          icon: 'box-archive',
          action_url: '#pgPeminjaman',
          entity_type: 'ptv_peminjaman',
          entity_id: newRow.id,
        });
      }
      requestSyncScope('loans');
      requestSyncScope('inventory');
      return;
    }

    if (table === 'ptv_acara') {
      const evTitle = (newRow && newRow.judul) || payload.judul || 'Acara PTV';
      if (eventType === 'INSERT' && newRow) {
        dispatchRealtimeNotification({
          id: 'ev_' + (newRow.id || recId),
          dedupe_key: dedupeBase,
          title: 'Acara Baru Ditambahkan',
          message: `${actorName} menambahkan acara baru: ${evTitle}`,
          type: 'event',
          icon: 'calendar-day',
          action_url: '#pgAcara',
          entity_type: 'ptv_acara',
          entity_id: newRow.id || recId,
        });
      } else if (eventType === 'UPDATE') {
        dispatchRealtimeNotification({
          id: 'ev_upd_' + recId,
          dedupe_key: dedupeBase,
          title: 'Acara Diperbarui',
          message: `${actorName} memperbarui acara: ${evTitle}`,
          type: 'event',
          icon: 'calendar-day',
          action_url: '#pgAcara',
          entity_type: 'ptv_acara',
          entity_id: recId,
        });
      }
      requestSyncScope('events');
      return;
    }

    if (table === 'ptv_catatan') {
      const incomingNote = newRow || (payload && payload.id ? payload : null);
      const incId = String((incomingNote && (incomingNote.id || incomingNote.uuid)) || recId || '');
      if (!incId) return;

      if (!DB.notes) DB.notes = [];

      // Check if this ID already exists in DB.notes
      const alreadyExists = DB.notes.some(n => String(n.id) === incId);
      if (alreadyExists) {
        console.info('[NOTE DEDUPE] id already exists → SKIP', incId);
        const eIdx = DB.notes.findIndex(n => String(n.id) === incId);
        if (eIdx !== -1 && incomingNote) {
          DB.notes[eIdx] = Object.assign({}, DB.notes[eIdx], incomingNote);
        }
      } else {
        if (eventType === 'INSERT') {
          console.info('[NOTE REALTIME INSERT] id:', incId);
          if (incomingNote) {
            DB.notes.unshift(incomingNote);
            safeRerenderForScopes(['notes']);
          }
        }
      }

      if (eventType === 'UPDATE') {
        const uIdx = DB.notes.findIndex(n => String(n.id) === incId);
        if (uIdx !== -1 && incomingNote) {
          DB.notes[uIdx] = Object.assign({}, DB.notes[uIdx], incomingNote);
          safeRerenderForScopes(['notes']);
        }
      }

      // Strict deduplication by ID canonical
      const seenN = new Set();
      DB.notes = DB.notes.filter(n => {
        const nid = String(n && n.id ? n.id : '');
        if (!nid || seenN.has(nid)) return false;
        seenN.add(nid);
        return true;
      });

      if ((eventType === 'INSERT' || eventType === 'UPDATE') && incomingNote) {
        const noteTitle = incomingNote.judul || 'Catatan Baru';
        const isMeeting = (incomingNote.tipe === 'meeting_minutes' || (Array.isArray(incomingNote.tags) && incomingNote.tags.includes('notulensi')));
        dispatchRealtimeNotification({
          id: 'note_' + incId + '_' + eventType,
          dedupe_key: dedupeBase,
          title: isMeeting ? 'Notulensi Rapat' : 'Catatan Tim',
          message: `${actorName} ${eventType === 'UPDATE' ? 'memperbarui' : 'menambahkan'} ${isMeeting ? 'notulensi' : 'catatan'}: ${noteTitle}`,
          type: 'note',
          icon: 'note-sticky',
          action_url: '#pgCatatan',
          entity_type: 'ptv_catatan',
          entity_id: incId,
        });
      }
      requestSyncScope('notes', false);
      return;
    }

    if (table === 'ptv_inventaris' || table === 'ptv_inventaris_unit') {
      const toolName = (newRow && (newRow.nama || newRow.nama_alat)) || payload.nama || 'Peralatan';
      if (eventType === 'INSERT' && newRow) {
        dispatchRealtimeNotification({
          id: 'inv_' + (newRow.id || recId),
          dedupe_key: dedupeBase,
          title: 'Inventaris Baru',
          message: `${actorName} menambahkan peralatan baru: ${toolName}`,
          type: 'inventory',
          icon: 'box',
          action_url: '#pgInventaris',
          entity_type: table,
          entity_id: newRow.id || recId,
        });
      } else if (eventType === 'UPDATE') {
        dispatchRealtimeNotification({
          id: 'inv_upd_' + recId,
          dedupe_key: dedupeBase,
          title: 'Inventaris Diperbarui',
          message: `${actorName} memperbarui peralatan: ${toolName}`,
          type: 'inventory',
          icon: 'box',
          action_url: '#pgInventaris',
          entity_type: table,
          entity_id: recId,
        });
      }
      requestSyncScope('inventory');
      return;
    }

    if (table === 'ptv_lapor_masalah') {
      if (eventType === 'INSERT' && newRow) {
        const toolName = newRow.nama_alat || 'Alat';
        const issue = newRow.masalah || 'Kendala dilaporkan';
        dispatchRealtimeNotification({
          id: 'dmg_' + newRow.id,
          dedupe_key: dedupeBase,
          title: 'Laporan Kerusakan Baru',
          message: `${actorName} melaporkan kendala ${toolName}: ${issue}`,
          type: 'damage',
          icon: 'triangle-exclamation',
          action_url: '#pgKerusakan',
          entity_type: 'ptv_lapor_masalah',
          entity_id: newRow.id,
        });
      } else if (eventType === 'UPDATE' && newRow) {
        const toolName = newRow.nama_alat || 'Alat';
        dispatchRealtimeNotification({
          id: 'dmg_upd_' + newRow.id,
          dedupe_key: dedupeBase,
          title: 'Status Kerusakan Diperbarui',
          message: `${actorName} memperbarui status kendala ${toolName}: "${newRow.status || 'Diperbarui'}"`,
          type: 'damage',
          icon: 'triangle-exclamation',
          action_url: '#pgKerusakan',
          entity_type: 'ptv_lapor_masalah',
          entity_id: newRow.id,
        });
      }
      requestSyncScope('damages');
      requestSyncScope('inventory');
      return;
    }

    if (table === 'ptv_surat_izin' || table === 'ptv_surat_tugas' || table === 'ptv_surat_barang') {
      if (eventType === 'UPDATE' && newRow && payload.old && newRow.status !== payload.old.status) {
        const docName = newRow.nomor_surat || newRow.nama_kegiatan || newRow.keperluan || 'Dokumen';
        dispatchRealtimeNotification({
          id: 'doc_' + newRow.id + '_' + newRow.status,
          dedupe_key: dedupeBase,
          title: 'Status Dokumen: ' + (newRow.status || 'Diperbarui'),
          message: `${actorName} memperbarui status ${docName} menjadi "${newRow.status || ''}"`,
          type: 'doc',
          icon: 'file-signature',
          action_url: '#pgPerizinan',
          entity_type: table,
          entity_id: newRow.id,
        });
      }
      requestSyncScope('docs');
      return;
    }

    if (table === 'ptv_pengumuman') {
      if (eventType === 'INSERT' && newRow) {
        dispatchRealtimeNotification({
          id: 'ann_' + newRow.id,
          dedupe_key: dedupeBase,
          title: 'Pengumuman: ' + (newRow.judul || 'Baru'),
          message: (newRow.konten || '').slice(0, 100),
          type: 'announcement',
          icon: 'bullhorn',
          action_url: '#pgBroadcast',
          entity_type: 'ptv_pengumuman',
          entity_id: newRow.id,
        });
      }
      requestSyncScope('announcements');
      return;
    }

    if (table === 'ptv_lost_found') {
      if (eventType === 'INSERT' && newRow) {
        dispatchRealtimeNotification({
          id: 'lost_' + newRow.id,
          dedupe_key: dedupeBase,
          title: 'Lost & Found: ' + (newRow.nama_barang || 'Barang Baru'),
          message: `${actorName} melaporkan barang: ${newRow.nama_barang || ''} (${newRow.lokasi || 'Studio'})`,
          type: 'lost',
          icon: 'box-open',
          action_url: '#pgLostFound',
          entity_type: 'ptv_lost_found',
          entity_id: newRow.id,
        });
      } else if (eventType === 'UPDATE' && newRow) {
        dispatchRealtimeNotification({
          id: 'lost_upd_' + newRow.id,
          dedupe_key: dedupeBase,
          title: 'Status Lost & Found',
          message: `${actorName} memperbarui status barang: ${newRow.nama_barang || ''} (${newRow.status || 'Diperbarui'})`,
          type: 'lost',
          icon: 'box-open',
          action_url: '#pgLostFound',
          entity_type: 'ptv_lost_found',
          entity_id: newRow.id,
        });
      }
      requestSyncScope('lost');
      return;
    }

    // Default fallback for any other registered tables
    requestSyncScope(scope);
  }

  // 13. Channel Subscription Engine: Single Unified WebSocket Channel
  function setupRealtimeChannels() {
    if (typeof navigator !== 'undefined' && navigator.onLine === false) {
      setRealtimeStatus('offline', 'Cannot subscribe channels while browser is offline');
      return false;
    }

    const sbClient = getSharedSupabaseClient();
    if (!sbClient) {
      setRealtimeStatus('error', 'Supabase credentials or client not available');
      return false;
    }

    // Clean up old channels cleanly to prevent duplicate subscriptions
    if (window._ptvRealtimeSyncChannel) {
      try { sbClient.removeChannel(window._ptvRealtimeSyncChannel); } catch (_) {}
      window._ptvRealtimeSyncChannel = null;
    }
    if (window._ptvNotifChannel) {
      try { sbClient.removeChannel(window._ptvNotifChannel); } catch (_) {}
      window._ptvNotifChannel = null;
    }

    try {
      const syncChannel = sbClient.channel('ptv_dashboard_realtime_sync');

      // Register listeners across core operational tables & notifications on ONE unified pipeline
      syncChannel
        .on('broadcast', { event: 'table_change' }, (bPayload) => {
          const p = bPayload.payload || bPayload;
          if (p && p.table && p.scope) {
            handleRealtimeTableChange(p.table, p.scope, {
              eventType: p.eventType || 'UPDATE',
              new: p.new || { id: p.id, ...p },
              old: p.old || { id: p.id },
              client_id: p.client_id || '',
              actor_id: p.actor_id || '',
              actor_name: p.actor_name || '',
              id: p.id || '',
              scope: p.scope,
              table: p.table,
              source: 'broadcast',
              ...p
            });
          }
        })
        .on('postgres_changes', { event: '*', schema: 'public', table: 'ptv_notifications' }, (payload) => handleRealtimeTableChange('ptv_notifications', 'notifs', payload))
        .on('postgres_changes', { event: '*', schema: 'public', table: 'ptv_surat_tugas' }, (payload) => handleRealtimeTableChange('ptv_surat_tugas', 'docs', payload))
        .on('postgres_changes', { event: '*', schema: 'public', table: 'ptv_surat_barang' }, (payload) => handleRealtimeTableChange('ptv_surat_barang', 'docs', payload))
        .on('postgres_changes', { event: '*', schema: 'public', table: 'ptv_surat_izin' }, (payload) => handleRealtimeTableChange('ptv_surat_izin', 'docs', payload))
        .on('postgres_changes', { event: '*', schema: 'public', table: 'ptv_inventaris' }, (payload) => handleRealtimeTableChange('ptv_inventaris', 'inventory', payload))
        .on('postgres_changes', { event: '*', schema: 'public', table: 'ptv_inventaris_unit' }, (payload) => handleRealtimeTableChange('ptv_inventaris_unit', 'inventory', payload))
        .on('postgres_changes', { event: '*', schema: 'public', table: 'ptv_nilai_inventaris' }, (payload) => handleRealtimeTableChange('ptv_nilai_inventaris', 'inventory', payload))
        .on('postgres_changes', { event: '*', schema: 'public', table: 'ptv_peminjaman' }, (payload) => handleRealtimeTableChange('ptv_peminjaman', 'loans', payload))
        .on('postgres_changes', { event: '*', schema: 'public', table: 'ptv_acara' }, (payload) => handleRealtimeTableChange('ptv_acara', 'events', payload))
        .on('postgres_changes', { event: '*', schema: 'public', table: 'ptv_acara_rundown' }, (payload) => handleRealtimeTableChange('ptv_acara_rundown', 'events', payload))
        .on('postgres_changes', { event: '*', schema: 'public', table: 'ptv_lapor_masalah' }, (payload) => handleRealtimeTableChange('ptv_lapor_masalah', 'damages', payload))
        .on('postgres_changes', { event: '*', schema: 'public', table: 'ptv_pengumuman' }, (payload) => handleRealtimeTableChange('ptv_pengumuman', 'announcements', payload))
        .on('postgres_changes', { event: '*', schema: 'public', table: 'ptv_lost_found' }, (payload) => handleRealtimeTableChange('ptv_lost_found', 'lost', payload))
        .on('postgres_changes', { event: '*', schema: 'public', table: 'ptv_catatan' }, (payload) => handleRealtimeTableChange('ptv_catatan', 'notes', payload))
        .subscribe((status, err) => {
          if (status === 'SUBSCRIBED') {
            console.info('[PTV Realtime] SUBSCRIBED: WebSocket channel ptv_dashboard_realtime_sync active.');
            console.info('[REALTIME] websocket connected');
            window.PTV_REALTIME_STATE.websocketConnected = true;
            window.PTV_REALTIME_STATE.subscribed = true;
            window.PTV_REALTIME_STATE.reconnectAttempts = 0;

            // Trigger post-reconnect resync to catch any events missed during disconnect
            PTVRealtimeManager.resyncAfterReconnect();
          } else if (status === 'CHANNEL_ERROR' || status === 'TIMED_OUT' || status === 'CLOSED') {
            console.warn(`[PTV Realtime] Subscription status: ${status}`, err || '');
            window.PTV_REALTIME_STATE.websocketConnected = false;
            window.PTV_REALTIME_STATE.subscribed = false;
            window.PTV_REALTIME_STATE.lastDisconnectedAt = new Date().toISOString();

            if (typeof navigator !== 'undefined' && navigator.onLine === false) {
              setRealtimeStatus('offline', 'Browser offline');
            } else {
              PTVRealtimeManager.scheduleReconnect(status, false);
            }
          }
        });

      window._ptvRealtimeSyncChannel = syncChannel;
      return true;
    } catch (e) {
      console.warn('[PTV Realtime] Error during channel setup:', e);
      setRealtimeStatus('error', e.message || 'Setup error');
      return false;
    }
  }

  // 14. Centralized PTVRealtimeManager Object
  const PTVRealtimeManager = {
    getState: function () {
      return Object.assign({}, window.PTV_REALTIME_STATE);
    },

    init: function () {
      console.info('[REALTIME] init started');
      // Guard against duplicate channel creation if already subscribed
      const syncChannel = window._ptvRealtimeSyncChannel;
      if (syncChannel && (syncChannel.state === 'joined' || syncChannel.state === 'joining') && window.PTV_REALTIME_STATE.subscribed) {
        return;
      }

      this.scheduleReconnect('init', true);
      this.startWatchdog();
    },

    scheduleReconnect: function (reason = 'auto', forceImmediate = false) {
      if (typeof navigator !== 'undefined' && navigator.onLine === false) {
        setRealtimeStatus('offline', 'Cannot reconnect while offline');
        return;
      }

      if (_reconnectTimer) {
        clearTimeout(_reconnectTimer);
        _reconnectTimer = null;
      }

      const attempts = window.PTV_REALTIME_STATE.reconnectAttempts || 0;
      // Exponential backoff: 1s, 2s, 4s, 8s, 16s, max 30s
      const delay = forceImmediate ? 60 : Math.min(1000 * Math.pow(2, attempts), 30000);
      const isInitialBoot = !window.PTV_REALTIME_STATE.lastConnectedAt && attempts === 0;

      setRealtimeStatus(isInitialBoot ? 'connecting' : 'reconnecting', reason);
      if (!isInitialBoot) {
        console.info('[REALTIME] reconnecting');
      }

      _reconnectTimer = setTimeout(() => {
        _reconnectTimer = null;
        if (typeof navigator !== 'undefined' && navigator.onLine === false) {
          setRealtimeStatus('offline', 'Network went offline before reconnect executed');
          return;
        }
        window.PTV_REALTIME_STATE.reconnectAttempts = attempts + 1;
        setupRealtimeChannels();
      }, delay);
    },

    resyncAfterReconnect: function () {
      console.info('[PTV Realtime] Resync dispatched after subscription confirmation...');

      // 1. Resync active page scope immediately
      syncActivePageQuietly(true);

      // 2. Resync related critical scopes
      const curPage = (typeof state !== 'undefined' && state.route) ? state.route.page : 'beranda';
      if (['peminjaman', 'inventaris', 'alatDetail'].includes(curPage)) {
        requestSyncScope('loans', true);
        requestSyncScope('inventory', true);
      } else if (['perizinan', 'dokumen', 'arsip'].includes(curPage)) {
        requestSyncScope('docs', true);
      } else if (['acara', 'acaraDetail', 'kalender'].includes(curPage)) {
        requestSyncScope('events', true);
      } else if (curPage === 'kerusakan') {
        requestSyncScope('damages', true);
        requestSyncScope('inventory', true);
      } else if (curPage === 'broadcast') {
        requestSyncScope('announcements', true);
      } else if (curPage === 'lostFound') {
        requestSyncScope('lost', true);
      } else if (curPage === 'catatan') {
        requestSyncScope('notes', true);
      } else if (curPage === 'beranda') {
        requestSyncScope('docs', true);
        requestSyncScope('inventory', true);
        requestSyncScope('events', true);
        requestSyncScope('announcements', true);
      }

      // 3. Resync notifications
      syncInAppNotifications();

      // 4. Mark status connected
      setRealtimeStatus('connected', 'Resync dispatched successfully');
    },

    startWatchdog: function () {
      if (_watchdogTimer) clearInterval(_watchdogTimer);
      // Watchdog checks connection state every 8s. ZERO DATA POLLING.
      _watchdogTimer = setInterval(() => {
        this.checkHealth();
      }, 8000);
    },

    stopWatchdog: function () {
      if (_watchdogTimer) {
        clearInterval(_watchdogTimer);
        _watchdogTimer = null;
      }
    },

    checkHealth: function () {
      const isOnline = (typeof navigator !== 'undefined' && typeof navigator.onLine === 'boolean') ? navigator.onLine : true;

      // Network level check
      if (!isOnline) {
        if (window.PTV_REALTIME_STATE.status !== 'offline') {
          this.handleOffline();
        }
        return; // Zero fetching while offline
      }

      // Browser came back online from previous offline status
      if (isOnline && window.PTV_REALTIME_STATE.status === 'offline') {
        this.handleOnline();
        return;
      }

      // Supabase channel level check
      const syncChannel = window._ptvRealtimeSyncChannel;
      const isChannelJoined = syncChannel && (syncChannel.state === 'joined' || syncChannel.state === 'joining');
      const isSubscribed = window.PTV_REALTIME_STATE.subscribed && isChannelJoined;

      if (!isSubscribed) {
        if (window.PTV_REALTIME_STATE.status !== 'reconnecting' && window.PTV_REALTIME_STATE.status !== 'connecting') {
          console.warn('[PTV Realtime] Watchdog detected inactive subscription. Reconnecting...');
          this.scheduleReconnect('watchdog_reconnect', false);
        }
      }
      // If healthy: do nothing! No data fetching, no console spam.
    },

    handleOffline: function () {
      if (_reconnectTimer) {
        clearTimeout(_reconnectTimer);
        _reconnectTimer = null;
      }
      setRealtimeStatus('offline', 'Browser network disconnected');
    },

    handleOnline: function () {
      window.PTV_REALTIME_STATE.browserOnline = true;
      window.PTV_REALTIME_STATE.reconnectAttempts = 0;
      setRealtimeStatus('reconnecting', 'Browser network restored');
      this.scheduleReconnect('browser_online_event', true);
    },

    handleVisibilityChange: function () {
      if (typeof document !== 'undefined' && document.hidden) return;

      const isOnline = (typeof navigator !== 'undefined' && typeof navigator.onLine === 'boolean') ? navigator.onLine : true;
      if (!isOnline) {
        setRealtimeStatus('offline', 'Tab visible but network offline');
        return;
      }

      const syncChannel = window._ptvRealtimeSyncChannel;
      const isHealthy = syncChannel && (syncChannel.state === 'joined' || syncChannel.state === 'joining') && window.PTV_REALTIME_STATE.subscribed;

      if (!isHealthy) {
        console.info('[PTV Realtime] Tab active with disconnected channel. Reconnecting...');
        this.scheduleReconnect('tab_focus_reconnect', true);
      } else {
        syncActivePageQuietly();
      }
    }
  };

  window.PTVRealtimeManager = PTVRealtimeManager;
  window.initSupabaseRealtime = function () {
    PTVRealtimeManager.init();
  };

  // 15. DOM & Browser Event Bindings
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => PTVRealtimeManager.init());
  } else {
    PTVRealtimeManager.init();
  }

  window.addEventListener('online', () => PTVRealtimeManager.handleOnline());
  window.addEventListener('offline', () => PTVRealtimeManager.handleOffline());

  document.addEventListener('visibilitychange', () => PTVRealtimeManager.handleVisibilityChange());
  window.addEventListener('focus', () => PTVRealtimeManager.handleVisibilityChange());
})();

/* ── Gestur scroll horizontal melalui trackpad, wheel, mouse & 1 jari (touch / drag) ── */
(function setupHorizontalGestures(){
  const TARGET_SELECTOR = '#invCatTrack, .prod-unit-cards-scroll, [data-horizontal-scroll]';

  // 1. Wheel & Trackpad (2 jari atau mouse wheel)
  window.addEventListener('wheel', (e) => {
    const track = e.target.closest(TARGET_SELECTOR);
    if (!track) return;
    const maxScroll = track.scrollWidth - track.clientWidth;
    if (maxScroll <= 0) return;

    // Trackpad horizontal swipe native: biarkan browser menangani secara native
    if (Math.abs(e.deltaX) > Math.abs(e.deltaY)) {
      return;
    }

    // Trackpad gerakan vertikal atau mouse wheel: konversi ke pergeseran horizontal yang mulus
    if (Math.abs(e.deltaY) > 0 && !e.shiftKey) {
      const prev = track.scrollLeft;
      track.scrollLeft += e.deltaY;
      if (track.scrollLeft !== prev) {
        e.preventDefault();
      }
    }
  }, { passive: false });

  // 2. Mouse & 1-Jari Trackpad Drag-to-Scroll
  let activeTrack = null, isDragging = false, startX = 0, scrollLeft = 0, hasMoved = false;

  window.addEventListener('mousedown', (e) => {
    const track = e.target.closest(TARGET_SELECTOR);
    if (!track) return;
    if (e.target.closest('button, .btn, a, input, textarea, select, [data-act], [data-quick], [role="button"]')) return;

    activeTrack = track;
    isDragging = true;
    hasMoved = false;
    startX = e.pageX;
    scrollLeft = track.scrollLeft;
    track.classList.add('is-dragging');
  });

  window.addEventListener('mousemove', (e) => {
    if (!isDragging || !activeTrack) return;
    const walk = (e.pageX - startX) * 1.35;
    if (Math.abs(walk) > 4) {
      hasMoved = true;
      e.preventDefault();
    }
    if (hasMoved) {
      activeTrack.scrollLeft = scrollLeft - walk;
    }
  }, { passive: false });

  const stopDrag = () => {
    if (isDragging && activeTrack) {
      activeTrack.classList.remove('is-dragging');
    }
    isDragging = false;
    setTimeout(() => {
      hasMoved = false;
      activeTrack = null;
    }, 60);
  };

  window.addEventListener('mouseup', stopDrag);
  window.addEventListener('mouseleave', stopDrag);

  // Mencegah trigger tombol/link saat pengguna sedang menggeser/dragging
  window.addEventListener('click', (e) => {
    if (e.target.closest('button, .btn, a, input, textarea, select, [data-act], [data-quick], [role="button"]')) {
      return; // Jangan blokir klik tombol interaktif
    }
    if (hasMoved && e.target.closest(TARGET_SELECTOR)) {
      e.stopPropagation();
      e.preventDefault();
      hasMoved = false;
    }
  }, true);

  // 3. 1-Jari Touchscreen Swipe Safety (layar sentuh / HP / iPad / tablet)
  let touchStartX = 0, touchMoved = false;
  window.addEventListener('touchstart', (e) => {
    const track = e.target.closest(TARGET_SELECTOR);
    if (track && e.touches.length === 1) {
      if (e.target.closest('button, .btn, a, input, textarea, select, [data-act], [data-quick], [role="button"]')) return;
      touchStartX = e.touches[0].pageX;
      touchMoved = false;
    }
  }, { passive: true });

  window.addEventListener('touchmove', (e) => {
    const track = e.target.closest(TARGET_SELECTOR);
    if (track && e.touches.length === 1) {
      if (Math.abs(e.touches[0].pageX - touchStartX) > 6) {
        touchMoved = true;
      }
    }
  }, { passive: true });

  window.addEventListener('touchend', (e) => {
    if (touchMoved && e.target.closest(TARGET_SELECTOR + ' button, ' + TARGET_SELECTOR + ' a')) {
      e.stopPropagation();
      setTimeout(() => { touchMoved = false; }, 80);
    } else {
      setTimeout(() => { touchMoved = false; }, 80);
    }
  }, true);
})();

})();

</script>
